/* 해설 콘텐츠 라이브러리 (자동 시드: forms_bank 992개념). dx/fix/cite는 저작용 빈칸. */
window.INTERP_CONTENT={"CH1-001": {"name": "원소·원자·분자 정의", "course": "ch1", "unit": "Ⅰ-1", "tier": "C", "mis": ["성질 단위는 분자이다.", "원소는 입자가 아니라 성분이다.", "성분의 종류는 원소이다."], "dx": "원소(성분)·원자(입자)·분자(성질 단위)의 층위를 뭉뚱그린 경우다. 이 구분이 흔들리면 화학식 읽기와 몰 계산까지 전부 헛디딘다.", "fix": "원소(종류)·원자(낱개 입자)·분자(둘 이상 원자가 결합한 성질 단위)를 세 칸으로 분리해 외운다. 물(H₂O)로 '원소 2종·원자 3개·분자 1개'를 직접 세어 층위를 굳혀라.", "cite": ""}, "CH1-002": {"name": "분자 종류", "course": "ch1", "unit": "Ⅰ-1", "tier": "A", "mis": ["H와 Cl 원자 2개이다.", "산소 원자 2개이다.", "원자 2개이다.", "질소 원자 2개이다.", "원자 하나로 존재한다.", "원자 3개이다."], "dx": "분자식에서 원자의 종류와 개수를 읽어내지 못한 경우다(HCl은 H·Cl 각 1개). 화학식 해석이 안 되면 몰질량·양적관계가 모두 막힌다.", "fix": "분자식은 '원소 기호 = 종류, 첨자 = 개수'로 분해해 읽는다. HCl·H₂O·CO₂를 종류와 개수로 적어 보며 첨자가 없으면 1개임을 확인하라.", "cite": ""}, "CH1-003": {"name": "원소 수 세기", "course": "ch1", "unit": "Ⅰ-1", "tier": "C", "mis": ["H와 O 두 종류이다.", "원자 수 5와 혼동하면 안 된다.", "N과 H 두 종류이다."], "dx": "화학식에서 원소(종류) 수와 원자(개수) 수를 같은 것으로 본 경우다. 종류와 개수를 섞으면 조성·실험식 계산이 어긋난다.", "fix": "'원소 수 = 서로 다른 기호의 가짓수, 원자 수 = 첨자까지 더한 낱개 수'로 두 셈을 분리한다. H₂SO₄로 원소 3종·원자 7개를 따로 세어 구분하라.", "cite": ""}, "CH1-004": {"name": "원자 수 세기", "course": "ch1", "unit": "Ⅰ-1", "tier": "B", "mis": ["6 + 12 + 6 = 24개이다.", "H 2 + O 1 = 3개이다.", "N 1 + H 3 = 4개이다.", "C 1 + O 2 = 3개이다."], "dx": "첨자와 계수를 빠뜨리고 원자 수를 센 경우다. 이 셈이 흔들리면 질량 보존·양적관계가 무너진다.", "fix": "원자 수는 '계수 × 각 첨자'를 빠짐없이 곱해 센다. 2H₂O에서 H 4개·O 2개처럼 계수와 첨자를 둘 다 반영해 직접 세어 보라.", "cite": ""}, "CH1-005": {"name": "화학식 종류", "course": "ch1", "unit": "Ⅰ-1", "tier": "C", "mis": ["결합선 표현은 구조식이다.", "이온 결합 물질은 실험식으로 나타낸다.", "분자식은 실제 개수이다."], "dx": "분자식·실험식·구조식·시성식의 쓰임을 구분 못 한 경우다. 이온 물질을 분자식으로 쓰려 하면 화학식 자체가 틀어진다.", "fix": "분자식(실제 원자 수)·실험식(가장 간단한 정수비)·구조식(결합)·시성식(작용기)의 쓰임을 한 줄씩 정리한다. 이온 물질은 분자가 없어 실험식으로 쓴다는 규칙을 NaCl로 확인하라.", "cite": ""}, "CH1-006": {"name": "실험식 도출", "course": "ch1", "unit": "Ⅰ-1", "tier": "C", "mis": ["H₂O는 이미 가장 간단한 비이다.", "가장 간단한 비로 줄여야 한다.", "6:12:6을 1:2:1로 줄인다."], "dx": "실험식이 원자 수의 가장 간단한 정수비라는 점을 놓친 경우다. 약분 개념이 없으면 조성 분석에서 분자식을 못 잡는다.", "fix": "실험식은 원자 수비를 최대공약수로 약분한 가장 간단한 정수비다. C₆H₁₂O₆를 CH₂O로 줄이는 약분을 직접 해 보며 분자식과의 차이를 확인하라.", "cite": ""}, "CH1-007": {"name": "원자 구조", "course": "ch1", "unit": "Ⅰ-1", "tier": "C", "mis": ["양성자 때문에 (+)이다.", "전자는 음전하이다.", "전자가 넓은 공간에 분포한다."], "dx": "원자를 (+)핵과 (−)전자가 균형 잡힌 중성 입자로 보지 못한 경우다. 이 그림이 약하면 이온 형성·전기적 성질 전체가 흔들린다.", "fix": "원자를 '가운데 (+)핵, 둘레 (−)전자, 둘이 같아 전체 중성'으로 그린다. 양성자 수와 전자 수를 맞춰 중성을 확인하고, 전자가 빠지면 이온이 됨을 이어 짚어라.", "cite": ""}, "CH1-008": {"name": "입자 질량비", "course": "ch1", "unit": "Ⅰ-1", "tier": "C", "mis": ["전자가 매우 가볍다.", "약 1840분의 1이다.", "전자 질량은 무시할 수준이다."], "dx": "전자가 핵자보다 약 1840배 가볍다는 질량 차를 놓친 경우다. 그래서 원자 질량이 사실상 핵에 몰려 있다는 다음 개념이 약해진다.", "fix": "'양성자≈중성자, 전자는 약 1840배 가벼움'을 기준으로 삼는다. 그래서 원자 질량이 사실상 핵에 다 몰린다는 결론까지 한 문장으로 이어 적어라.", "cite": ""}, "CH1-009": {"name": "입자 전하비", "course": "ch1", "unit": "Ⅰ-1", "tier": "C", "mis": ["중성자는 0이다.", "중성이다.", "부호만 반대이고 크기는 같다."], "dx": "양성자 +1·전자 −1·중성자 0이라는 전하 배분을 놓친 경우다. 전하의 기준이 흔들리면 이온·핵전하 해석이 어긋난다.", "fix": "세 입자 전하를 '양성자 +1, 전자 −1, 중성자 0'으로 못 박는다. 이 값으로 중성 원자의 전하 합이 0이 됨을 직접 확인하라.", "cite": ""}, "CH1-010": {"name": "원자 중성", "course": "ch1", "unit": "Ⅰ-1", "tier": "C", "mis": ["중성자 수는 다를 수 있다.", "중성자는 전하가 없다.", "전하 균형이 깨진다."], "dx": "원자가 양성자 수 = 전자 수라서 중성이라는 균형을 놓친 경우다. 이 균형이 깨질 때가 곧 이온이라는 다음 개념과 직결된다.", "fix": "중성의 조건은 '양성자 수 = 전자 수'임을 기준으로 삼는다. 이 균형이 깨져 전자가 줄거나 늘면 이온이 됨을, 전자 수만 바꿔 직접 확인하라.", "cite": ""}, "CH1-011": {"name": "원자핵 구성", "course": "ch1", "unit": "Ⅰ-1", "tier": "C", "mis": ["전자는 핵 바깥에 있다.", "전자 질량은 무시한다."], "dx": "핵(양성자·중성자)과 핵 바깥 전자라는 공간 배치를 놓친 경우다. 핵의 위치를 잘못 잡으면 원자번호·질량수 정의가 흔들린다.", "fix": "'핵 안에 양성자·중성자, 핵 밖에 전자'라는 공간 배치를 그림으로 고정한다. 이 위치에서 원자번호(양성자 수)와 질량수(양성자+중성자)를 직접 읽어 보라.", "cite": ""}, "CH1-012": {"name": "옥텟규칙", "course": "ch1", "unit": "Ⅰ-1", "tier": "B", "mis": ["원자 상태로는 옥텟이 아니다.", "옥텟을 만족한다.", "옥텟 규칙이 일반적이다."], "dx": "옥텟 규칙이 원자 혼자가 아니라 결합한 뒤의 안정 상태 기준이라는 점을 놓친 경우다. 이걸 놓치면 결합이 왜 일어나는지 설명이 막힌다.", "fix": "옥텟은 '원자가 결합으로 최외각 8개(수소는 2개)를 채워 안정해지는 것'으로 이해한다. 결합이 일어나는 이유가 이 안정화임을 NaCl·H₂O로 확인하라.", "cite": ""}, "CH1-013": {"name": "루이스 전자점식", "course": "ch1", "unit": "Ⅰ-1", "tier": "A", "mis": ["원자가 전자가 6개이다.", "안쪽 껍질은 표시하지 않는다.", "양성자 수가 아니다.", "원자가 전자가 2개이다.", "원자가 전자가 5개이다."], "dx": "루이스 전자점식이 원자가 전자만 그린다(안쪽 껍질 제외)는 점을 놓친 경우다. 점 수를 잘못 세면 결합 수·분자 구조가 어긋난다.", "fix": "전자점식은 '안쪽 껍질 빼고 최외각(원자가) 전자만' 점으로 그린다. 2주기 원소의 원자가 전자 수를 세어 점을 찍어 보며 결합 손 수를 확인하라.", "cite": ""}, "CH1-014": {"name": "주기율표 기초", "course": "ch1", "unit": "Ⅰ-1", "tier": "C", "mis": ["족은 원자가 전자 수와 관련된다.", "같은 주기는 전자껍질 수가 같다.", "원자 번호 기준이다."], "dx": "족(원자가 전자 수)과 주기(전자껍질 수)의 의미를 뒤섞은 경우다. 이 두 축이 흔들리면 주기성·결합 예측의 토대가 무너진다.", "fix": "'세로 족 = 원자가 전자 수, 가로 주기 = 전자껍질 수' 두 축을 분리해 외운다. 임의 원소의 위치에서 두 값을 읽어 보며 축을 구분하라.", "cite": ""}, "CH1-015": {"name": "족 판정", "course": "ch1", "unit": "Ⅰ-1", "tier": "C", "mis": ["현대 주기율표에서 16족이다.", "17족은 할로젠이다.", "원자가 전자가 2개이다."], "dx": "전자 배치(원자가 전자 수)로 족을 읽어내는 게 흔들린 경우다. 족을 못 잡으면 반응성·이온 전하 예측이 어긋난다.", "fix": "족은 전자 배치의 최외각 전자 수로 판정한다. 전자 배치를 쓰고 원자가 전자 수를 세어 족을 매겨 보며, 그 수로 이온 전하를 예측하라.", "cite": ""}, "CH1-016": {"name": "이온형성 방향", "course": "ch1", "unit": "Ⅰ-1", "tier": "B", "mis": ["전자를 얻어야 음이온이다.", "금속은 전자를 내놓는다.", "전자를 얻는다.", "방향이 서로 반대이다."], "dx": "금속은 잃어 양이온, 비금속은 얻어 음이온이라는 방향을 놓친 경우다. 방향을 뒤집으면 이온식·결합 판정이 전부 틀어진다.", "fix": "'금속 = 전자 잃어 양이온, 비금속 = 전자 얻어 음이온' 방향을 못 박는다. Na⁺·Cl⁻처럼 대표 원소로 방향과 전하를 직접 적어 굳혀라.", "cite": ""}, "CH1-017": {"name": "이온 전하", "course": "ch1", "unit": "Ⅰ-1", "tier": "B", "mis": ["전자 2개를 잃는다.", "전자 2개를 얻는다.", "전자 1개를 얻는다.", "전자 3개를 잃는다."], "dx": "잃거나 얻은 전자 수가 곧 이온 전하라는 점을 놓친 경우다. 전하 크기를 못 잡으면 이온 화합물의 화학식이 어긋난다.", "fix": "이온 전하는 '잃거나 얻은 전자 수'와 같다. Mg는 2개 잃어 Mg²⁺, O는 2개 얻어 O²⁻처럼 전자 수와 전하를 맞춰 적어 보라.", "cite": ""}, "CH1-018": {"name": "결합 기초", "course": "ch1", "unit": "Ⅰ-1", "tier": "A", "mis": ["금속결합이다.", "비금속끼리는 공유결합이다.", "비금속 H와 Cl의 결합이다.", "이온결합이다.", "전자쌍을 공유한다."], "dx": "금속+비금속(이온)·비금속끼리(공유)·금속끼리(금속)라는 결합 분류를 놓친 경우다. 결합 종류를 못 가리면 물질의 성질 예측이 막힌다.", "fix": "결합을 '금속+비금속 = 이온, 비금속+비금속 = 공유, 금속+금속 = 금속'으로 분류한다. 예시 물질을 종류별로 하나씩 적어 보며 구성 원소로 결합을 가려라.", "cite": ""}, "CH1-019": {"name": "물질 분류", "course": "ch1", "unit": "Ⅰ-1", "tier": "C", "mis": ["여러 성분이 섞여 있다.", "여러 원소가 결합한다.", "단일 원소이다."], "dx": "순물질(홑원소·화합물)과 혼합물의 갈래를 놓친 경우다. 분류 틀이 약하면 일정 성분비·끓는점 같은 성질 해석이 흔들린다.", "fix": "물질을 '순물질(홑원소·화합물) 대 혼합물'로 가른다. 산소·물·공기를 각 칸에 넣어 보며 분류 틀을 굳혀라.", "cite": ""}, "CH1-020": {"name": "순물질·혼합물 경계", "course": "ch1", "unit": "Ⅰ-1", "tier": "B", "mis": ["화학결합이 없으면 혼합물이다.", "설탕과 물이 섞여 있다.", "혼합물은 비율에 따라 변한다.", "화학결합 없이 섞인 것이다."], "dx": "화학결합이 있으면 화합물, 단지 섞이면 혼합물이라는 경계를 놓친 경우다. 이 선이 흐리면 화합물의 일정 조성을 설명 못 한다.", "fix": "'화학결합으로 묶이면 화합물, 그냥 섞이면 혼합물'을 경계로 삼는다. 물(화합물)과 소금물(혼합물)을 비교하며 결합 유무로 가려라.", "cite": ""}, "CH1-021": {"name": "물질 분류 판정", "course": "ch1", "unit": "Ⅰ-1", "tier": "A", "mis": ["한 종류 원소로 이루어진다.", "탄소 한 종류이다.", "여러 기체가 섞여 있다.", "화학결합 없이 섞인 것이다.", "두 종류 원소가 결합했다."], "dx": "한 종류 원소면 홑원소, 여러 원소 결합이면 화합물이라는 판정을 놓친 경우다. 판정이 흔들리면 화학식·조성 해석이 어긋난다.", "fix": "'한 종류 원소 = 홑원소, 여러 원소 결합 = 화합물'로 판정한다. 화학식을 보고 원소 가짓수로 홑원소·화합물을 직접 가려 보라.", "cite": ""}, "CH1-022": {"name": "물리·화학변화", "course": "ch1", "unit": "Ⅰ-1", "tier": "B", "mis": ["새로운 물질이 생긴다.", "H₂O 그대로 상태만 변한다.", "재·기체 등 새 물질이 생긴다."], "dx": "상태만 변하는 물리 변화와 새 물질이 생기는 화학 변화를 구분 못 한 경우다. 이 구분이 약하면 반응식·질량 보존 단원이 흔들린다.", "fix": "'새 물질이 생기면 화학 변화, 상태·모양만 바뀌면 물리 변화'를 기준으로 삼는다. 얼음이 녹음(물리)과 나무가 탐(화학)을 비교해 가려라.", "cite": ""}, "CH1-023": {"name": "물리·화학적 성질", "course": "ch1", "unit": "Ⅰ-1", "tier": "C", "mis": ["화학반응성과 관련된다.", "화학반응을 동반한다.", "연소라는 화학변화이다."], "dx": "반응 없이 관찰하는 물리적 성질과 반응성인 화학적 성질을 뒤섞은 경우다. 성질의 갈래가 흐리면 반응 예측의 기준이 무너진다.", "fix": "'반응 없이 관찰하면 물리적 성질, 반응성을 보면 화학적 성질'로 가른다. 색·끓는점(물리)과 가연성·반응성(화학)을 분류해 보라.", "cite": ""}, "CH1-024": {"name": "분자 판정", "course": "ch1", "unit": "Ⅰ-1", "tier": "A", "mis": ["이온결합 물질이다.", "공유결합 분자이다."], "dx": "공유결합 물질만 분자이고 이온결합 물질은 분자가 아니라는 구분을 놓친 경우다. 이 선이 흐리면 분자식·실험식 표기가 어긋난다.", "fix": "'공유결합 물질만 분자, 이온결합 물질은 분자 아님'을 기준으로 삼는다. CO₂(분자)와 NaCl(이온, 실험식)을 비교해 표기 방식을 확인하라.", "cite": ""}, "CH1-025": {"name": "물질 상태", "course": "ch1", "unit": "Ⅰ-1", "tier": "C", "mis": ["끓는점 위는 기체이다.", "고체는 형태가 고정된다.", "두 점 사이는 액체이다."], "dx": "녹는점·끓는점을 경계로 온도에 따른 상태를 판정하는 게 흔들린 경우다. 상태 판정이 약하면 기체 법칙·상태 변화 단원이 흔들린다.", "fix": "녹는점·끓는점을 경계로 '그보다 낮으면 고체, 사이면 액체, 높으면 기체'로 판정한다. 한 물질의 두 점과 주어진 온도를 비교해 상태를 정해 보라.", "cite": ""}, "CH1-026": {"name": "불의 이용", "course": "ch1", "unit": "Ⅰ-2", "tier": "C", "mis": ["조리·제련·난방을 가능하게 했다.", "흙을 구워 만든다.", "광석에서 금속을 얻으려면 고온이 필요하다."], "dx": "불(연소)이 조리·난방·제련을 열어 문명을 바꿨다는 맥락을 놓친 경우다. 고온 제련이라는 고리가 약하면 금속 사용 시기 논리로 이어지지 못한다.", "fix": "불을 '조리·난방을 넘어 고온 제련을 가능케 해 금속 시대를 연 열쇠'로 자리매김한다. 불에서 고온, 제련, 금속 사용으로 이어지는 고리를 한 줄로 적어라.", "cite": ""}, "CH1-027": {"name": "금속 반응성·사용시기", "course": "ch1", "unit": "Ⅰ-2", "tier": "A", "mis": ["제련이 쉬운 금속이 먼저 쓰였다.", "제련이 어렵다.", "제련이 쉽기 때문이다.", "구리가 철보다 먼저 쓰였다.", "철이 더 반응성이 크다.", "분리하기 어렵다."], "dx": "반응성이 작아 제련이 쉬운 금속이 먼저 쓰였다는 인과를 놓친 경우다. 반응성↔제련 난이도의 연결이 약하면 사용 시기 순서를 못 잡는다.", "fix": "'반응성이 작은 금속일수록 제련이 쉬워 먼저 쓰였다'는 인과를 기준으로 삼는다. 구리·철·알루미늄을 반응성 순으로 늘어놓고 사용 시기와 맞춰 보라.", "cite": ""}, "CH1-028": {"name": "금속 사용시기", "course": "ch1", "unit": "Ⅰ-2", "tier": "C", "mis": ["철이 반응성이 더 크다.", "구리가 철보다 먼저 쓰였다.", "반응성이 커서 제련이 어렵다."], "dx": "구리가 철보다 반응성이 작아 먼저 쓰였다는 순서를 놓친 경우다. 반응성 비교가 흔들리면 금속 활용사 전체가 뒤집힌다.", "fix": "'구리는 철보다 반응성이 작아 더 일찍 쓰였다'는 순서를 외운다. 청동기에서 철기로 가는 순서를 반응성 비교로 설명해 보라.", "cite": ""}, "CH1-029": {"name": "지각 구성원소", "course": "ch1", "unit": "Ⅰ-2", "tier": "A", "mis": ["1위는 산소이다.", "2위는 규소이다.", "철은 4위이다.", "알루미늄은 3위이다.", "산소가 1위, 규소가 2위이다."], "dx": "지각 구성 1위 산소·2위 규소라는 순위를 놓친 경우다. 지각과 인체의 구성 원소 비교가 흔들린다.", "fix": "지각 구성은 '1위 산소, 2위 규소'로 못 박는다. 인체 구성(산소 1위)과 나란히 두고 지각·인체의 상위 원소를 비교해 외워라.", "cite": ""}, "CH1-030": {"name": "인체 구성원소", "course": "ch1", "unit": "Ⅰ-2", "tier": "A", "mis": ["개수비 1위는 수소이다.", "질량비 1위는 산소이다.", "탄소는 2위이다.", "수소는 개수비 1위이다."], "dx": "인체 구성이 질량비로는 산소, 개수비로는 수소가 1위라는 기준 차이를 놓친 경우다. 질량비와 개수비를 섞으면 순위 자체가 어긋난다.", "fix": "인체 구성은 '질량비 1위 산소, 개수비 1위 수소'로 기준을 나눠 외운다. 같은 대상도 질량 기준이냐 개수 기준이냐로 순위가 갈림을 확인하라.", "cite": ""}, "CH1-031": {"name": "질소", "course": "ch1", "unit": "Ⅰ-2", "tier": "C", "mis": ["단백질·DNA를 구성한다.", "질소가 약 78%이다.", "염기에 질소가 들어 있다."], "dx": "질소가 공기의 약 78%이자 단백질·DNA 구성 원소라는 점을 놓친 경우다. 질소 고정·하버보슈로 이어지는 맥락이 약해진다.", "fix": "질소를 '공기의 약 78%이자 단백질·DNA의 필수 구성 원소'로 기억한다. 공기 질소는 안정해 쓰기 어렵다는 점을 다음 개념(질소 고정)으로 이어라.", "cite": ""}, "CH1-032": {"name": "질소 안정성", "course": "ch1", "unit": "Ⅰ-2", "tier": "A", "mis": ["삼중결합으로 안정하다.", "삼중결합 때문이다.", "질소 고정이 필요하다.", "결합 에너지가 크다.", "질소가 안정하기 때문이다."], "dx": "질소 분자(N₂)의 삼중결합이 강해 반응성이 작다는 점을 놓친 경우다. 이걸 놓치면 왜 질소 고정에 큰 에너지가 드는지 설명이 막힌다.", "fix": "질소 분자의 반응성이 작은 이유를 'N₂의 강한 삼중결합'으로 못 박는다. 그래서 질소 고정에 큰 에너지가 든다는 결론까지 한 문장으로 이어 적어라.", "cite": ""}, "CH1-033": {"name": "하버보슈", "course": "ch1", "unit": "Ⅰ-2", "tier": "A", "mis": ["N과 H로 이루어진다.", "원료는 질소와 수소이다.", "비료 생산을 가능하게 했다.", "질소를 공급한다.", "질소의 삼중결합을 끊어야 한다."], "dx": "하버-보슈가 질소(N₂)와 수소(H₂)로 암모니아를 합성한다는 점을 놓친 경우다. 원료를 잘못 잡으면 비료·질소 순환 맥락이 흔들린다.", "fix": "하버-보슈의 원료와 산물을 'N₂ + H₂에서 NH₃'로 못 박는다. 반응식 N₂ + 3H₂ → 2NH₃를 직접 써 보며 원료를 확인하라.", "cite": ""}, "CH1-034": {"name": "원자량 정의", "course": "ch1", "unit": "Ⅰ-3", "tier": "B", "mis": ["절대 질량이 아니라 비이다.", "실제 질량이 아니다.", "기준은 탄소-12이다.", "비라서 단위가 없다."], "dx": "원자량을 절대 질량으로 본 경우다. ¹²C 기준의 상대 비라는 점이 흔들리면 평균 원자량·몰 계산이 어긋난다.", "fix": "원자량을 '¹²C를 12로 둔 상대적 질량 비'로 정의한다. 절대 질량(g)이 아니라 비라는 점을, 평균 원자량 계산에 앞서 한 번 적어 확인하라.", "cite": ""}, "CH1-035": {"name": "원자량 단위", "course": "ch1", "unit": "Ⅰ-3", "tier": "C", "mis": ["상대적 비이다.", "원자량은 무단위이다."], "dx": "원자량이 상대 비라 단위가 없다는 점을 놓친 경우다. 단위 감각이 흐리면 몰질량(g/mol)과 헷갈린다.", "fix": "'원자량은 상대 비라 단위가 없고, 몰질량은 g/mol'로 둘을 갈라 외운다. 같은 수치라도 단위가 붙는지로 원자량과 몰질량을 구분하라.", "cite": ""}, "CH1-036": {"name": "평균 원자량", "course": "ch1", "unit": "Ⅰ-3", "tier": "C", "mis": ["가중 평균이기 때문이다.", "한 동위원소만 보는 것이 아니다.", "비율로 가중한다."], "dx": "평균 원자량을 단순 평균으로 본 경우다. 존재비로 가중한다는 점이 약하면 동위원소 문제에서 값이 어긋난다.", "fix": "평균 원자량은 '각 동위원소 질량 × 존재비'의 합(가중 평균)으로 구한다. 염소(³⁵Cl 75%, ³⁷Cl 25%)로 35.5가 나오는 계산을 직접 해 보라.", "cite": ""}, "CH1-037": {"name": "동위원소", "course": "ch1", "unit": "Ⅰ-3", "tier": "B", "mis": ["전자 배치가 같다.", "같은 원소이기 때문이다.", "양성자수가 같다.", "양성자수는 같다."], "dx": "동위원소가 양성자 수는 같고 중성자 수만 달라 화학적 성질이 같다는 점을 놓친 경우다. 이 틀이 약하면 평균 원자량·질량수 계산이 흔들린다.", "fix": "동위원소를 '양성자 수 같음(같은 원소·같은 성질), 중성자 수만 다름(질량만 다름)'으로 두 축에 정리한다. 수소의 ¹H·²H·³H로 두 축을 확인하라.", "cite": ""}, "CH1-038": {"name": "분자량·화학식량", "course": "ch1", "unit": "Ⅰ-3", "tier": "B", "mis": ["곱이 아니라 합이다.", "1×2 + 16 = 18이다.", "원자 수가 아니라 원자량의 합이다.", "분자가 없기 때문이다."], "dx": "분자량을 원자량의 곱으로 오인한 경우다. 합이라는 점이 흔들리면 몰질량·양적관계가 전부 어긋난다.", "fix": "분자량은 '구성 원자 원자량의 합'임을 못 박는다. H₂O를 1×2 + 16 = 18로, 곱이 아니라 합으로 계산해 굳혀라.", "cite": ""}, "CH1-039": {"name": "몰 정의", "course": "ch1", "unit": "Ⅰ-3", "tier": "A", "mis": ["1몰의 절반이다.", "1몰의 2배이다.", "아보가드로수만큼이다.", "아보가드로수로 일정하다.", "지수가 23이다."], "dx": "1몰이 입자 6.02×10²³개라는 기준 수를 놓친 경우다. 몰의 정의가 흔들리면 입자 수·질량·부피 환산이 모두 막힌다.", "fix": "'1몰 = 입자 6.02×10²³개'를 기준 수로 못 박는다. 이 수가 입자 수·질량·부피 환산의 공통 다리임을, 한 물질로 세 환산을 이어 적어 확인하라.", "cite": ""}, "CH1-040": {"name": "몰질량", "course": "ch1", "unit": "Ⅰ-3", "tier": "A", "mis": ["12 + 32 = 44이다.", "14 + 3 = 17이다.", "16×2 = 32이다.", "2 + 16 = 18이다.", "화학식량이 물질마다 다르다."], "dx": "몰질량(g/mol)이 분자량·화학식량과 수치가 같다는 다리를 놓친 경우다. 이 연결이 약하면 질량↔몰 환산이 막힌다.", "fix": "'몰질량(g/mol) = 분자량과 같은 수치'라는 다리를 못 박는다. H₂O 분자량 18이 곧 몰질량 18 g/mol임을 확인하고 질량과 몰을 환산하라.", "cite": ""}, "CH1-041": {"name": "기체 몰부피", "course": "ch1", "unit": "Ⅰ-3", "tier": "A", "mis": ["아보가드로 법칙 때문이다.", "22.4의 2배이다.", "종류와 무관하다.", "22.4의 절반이다.", "1몰은 22.4 L이다.", "무게와 무관하다."], "dx": "표준 상태 기체 1몰이 종류와 무관하게 22.4 L라는 점을 놓친 경우다. 이 상수가 흔들리면 기체 양적관계가 전부 어긋난다.", "fix": "'표준 상태(0°C, 1기압) 기체 1몰 = 종류 무관 22.4 L'를 상수로 못 박는다. 부피를 22.4로 나눠 몰을 구하는 환산을 직접 해 보라.", "cite": ""}, "CH1-042": {"name": "아보가드로 법칙", "course": "ch1", "unit": "Ⅰ-3", "tier": "C", "mis": ["분자량이 다르면 질량이 다르다.", "무게와 무관하다.", "기체의 부피-분자 수 관계이다."], "dx": "같은 온도·압력·부피에 같은 분자 수가 든다(질량 무관)는 법칙을 놓친 경우다. 이 원리가 약하면 부피비=몰비라는 양적관계의 토대가 무너진다.", "fix": "'같은 온도·압력·부피면 분자 수가 같다(질량 무관)'를 기준으로 삼는다. 그래서 기체의 부피비 = 몰비임을, 반응식 계수로 확인하라.", "cite": ""}, "CH1-043": {"name": "질량 계산", "course": "ch1", "unit": "Ⅰ-3", "tier": "A", "mis": ["12 + 4 = 16이다.", "14 + 3 = 17이다.", "32 × 0.5 = 16이다.", "32 × 2 = 64이다.", "44 × 0.5 = 22이다.", "44 × 2 = 88이다."], "dx": "몰질량을 구성 원자량의 합으로 구하는 게 흔들린 경우다. 몰질량을 못 잡으면 질량↔몰 환산이 전부 막힌다.", "fix": "몰질량은 '화학식 속 원자량을 모두 더해' 구한다. CO₂를 12 + 16×2 = 44 g/mol로 직접 계산해 질량↔몰 환산의 기준을 세워라.", "cite": ""}, "CH1-044": {"name": "몰-입자수", "course": "ch1", "unit": "Ⅰ-3", "tier": "A", "mis": ["분자당 수소 2개이다.", "분자당 산소 2개이다.", "분자당 산소 1개이다.", "분자당 수소 3개이다."], "dx": "1몰 분자 속 원자 수를 분자식 첨자로 환산하는 게 흔들린 경우다. 첨자 환산이 약하면 원자 단위 입자 수 계산이 어긋난다.", "fix": "'분자 1몰 속 특정 원자 몰수 = 1몰 × 그 원자의 첨자'로 환산한다. H₂O 1몰에 H 2몰·O 1몰처럼 첨자를 곱해 원자 몰수를 구하라.", "cite": ""}, "CH1-045": {"name": "몰 환산", "course": "ch1", "unit": "Ⅰ-3", "tier": "C", "mis": ["9 / 18 = 0.5몰이다.", "나눗셈이다.", "18 / 18 = 1몰이다."], "dx": "몰수 = 질량 ÷ 몰질량이라는 환산을 놓친 경우다. 이 식이 흔들리면 모든 정량 문제의 출발점이 막힌다.", "fix": "'몰수 = 질량 ÷ 몰질량'을 정량 문제의 출발 식으로 못 박는다. 질량과 몰질량을 넣어 몰수를 구하는 환산을 반복해 손에 익혀라.", "cite": ""}, "CH1-046": {"name": "기체 몰 환산", "course": "ch1", "unit": "Ⅰ-3", "tier": "B", "mis": ["11.2 / 22.4 = 0.5몰이다.", "5.6 / 22.4 = 0.25몰이다.", "22.4 / 22.4 = 1몰이다.", "나눗셈이다."], "dx": "기체 몰수 = 부피 ÷ 22.4 L(표준 상태)라는 환산을 놓친 경우다. 부피↔몰 다리가 약하면 기체 양적관계가 막힌다.", "fix": "'기체 몰수 = 부피 ÷ 22.4 L(표준 상태)'를 부피↔몰 다리로 못 박는다. 주어진 부피를 22.4로 나눠 몰수를 구해 보라.", "cite": ""}, "CH1-047": {"name": "몰 비교", "course": "ch1", "unit": "Ⅰ-3", "tier": "B", "mis": ["H₂의 분자량이 작다.", "CO₂의 분자량이 크다.", "몰수 = 질량 / 분자량이다.", "질량 = 몰수 × 분자량이다."], "dx": "같은 질량이면 분자량이 작은 기체가 몰수가 많다는 반비례를 놓친 경우다. 질량과 몰수를 혼동하면 입자 수 비교가 어긋난다.", "fix": "'같은 질량이면 분자량이 작을수록 몰수 많음(반비례)'을 기준으로 삼는다. 같은 1 g의 H₂와 O₂ 몰수를 비교해 반비례를 확인하라.", "cite": ""}, "CH1-048": {"name": "원자-분자 몰", "course": "ch1", "unit": "Ⅰ-3", "tier": "C", "mis": ["분자당 수소 2개이다.", "분자당 산소 2개이다.", "C 1 + O 2 = 3개이다."], "dx": "분자 1몰 속 특정 원자의 몰수를 첨자로 환산하는 게 흔들린 경우다. 이 환산이 약하면 원자 수준 양적관계가 막힌다.", "fix": "'분자 몰수 × 첨자 = 그 원자 몰수'로 환산한다. CO₂ 2몰에 O가 4몰임을 첨자로 계산해 원자 수준 양적관계를 굳혀라.", "cite": ""}, "CH1-049": {"name": "밀도-분자량", "course": "ch1", "unit": "Ⅰ-3", "tier": "C", "mis": ["나눗셈이 아니라 곱셈이다.", "무거운 기체가 밀도가 크다.", "분자량이 클수록 밀도가 크다."], "dx": "같은 조건에서 기체 밀도가 분자량에 비례한다는 점을 놓친 경우다. 이 비례가 흔들리면 분자량 측정·기체 비교가 어긋난다.", "fix": "'같은 온도·압력에서 기체 밀도 ∝ 분자량'을 기준으로 삼는다. 밀도가 큰 기체가 분자량이 큼을, 두 기체 밀도 비교로 확인하라.", "cite": ""}, "CH1-050": {"name": "기체 분자수-압력", "course": "ch1", "unit": "Ⅰ-3", "tier": "C", "mis": ["압력이 분자 수에 비례한다.", "압력이 높을수록 분자 수가 많다.", "비례 관계이다."], "dx": "같은 온도·부피에서 압력이 분자 수(몰수)에 비례한다는 점을 놓친 경우다. 이 비례가 약하면 분압·기체 평형 해석이 흔들린다.", "fix": "'같은 온도·부피에서 압력 ∝ 분자 수(몰수)'를 기준으로 삼는다. 기체를 더 넣어 몰수가 늘면 압력이 비례해 오름을 분압 해석으로 이어라.", "cite": ""}, "CH1-051": {"name": "입자수-질량", "course": "ch1", "unit": "Ⅰ-3", "tier": "C", "mis": ["1몰이므로 18 g이다.", "O₂ 1몰이 32 g이다.", "아보가드로수가 1몰이다."], "dx": "몰수·몰질량으로 입자 수와 질량을 잇는 게 흔들린 경우다. 이 다리가 약하면 정량 계산이 중간에서 끊긴다.", "fix": "'질량을 몰질량으로 나눠 몰수를, 몰수에 6.02×10²³을 곱해 입자 수를 잇는' 두 다리를 순서대로 둔다. 한 물질로 질량에서 입자 수까지 끊김 없이 환산해 보라.", "cite": ""}, "CH1-052": {"name": "실험식-분자식", "course": "ch1", "unit": "Ⅰ-3", "tier": "C", "mis": ["포도당과 아세트산은 실험식이 같지만 분자식이 다르다.", "정수배가 1이 아닐 수 있다.", "분자식이 다를 수 있다."], "dx": "실험식이 같아도 분자식이 정수배만큼 다를 수 있다(포도당·아세트산)는 점을 놓친 경우다. 이걸 놓치면 조성 분석에서 분자식을 못 확정한다.", "fix": "'같은 실험식이라도 분자식은 정수배만큼 다를 수 있다'를 기준으로 삼는다. 포도당(C₆H₁₂O₆)과 아세트산(C₂H₄O₂)이 같은 실험식 CH₂O임을 확인하라.", "cite": ""}, "CH1-053": {"name": "몰-부피", "course": "ch1", "unit": "Ⅰ-3", "tier": "C", "mis": ["11.2 / 22.4 = 0.5몰이다.", "1몰은 22.4 L이다.", "22.4 × 2 = 44.8 L이다."], "dx": "기체 몰수와 부피를 22.4 L로 잇는 환산이 흔들린 경우다. 부피↔몰 다리가 약하면 기체 양적관계가 막힌다.", "fix": "'기체 부피 ↔ 몰수'를 22.4 L로 잇는 환산을 못 박는다. 몰수에 22.4를 곱해 부피를, 부피를 22.4로 나눠 몰수를 구해 양방향을 익혀라.", "cite": ""}, "CH1-054": {"name": "화학반응식 형식", "course": "ch1", "unit": "Ⅰ-4", "tier": "C", "mis": ["왼쪽은 반응물이다.", "방향성이 있다.", "화학식으로 표현한다."], "dx": "화학반응식을 '왼쪽 반응물 → 오른쪽 생성물'이라는 방향 있는 문장으로 읽지 못한 경우다. 이 문법이 안 잡히면 계수·양적관계 같은 정량 해석이 시작부터 어긋난다.", "fix": "반응식을 '왼쪽 반응물에서 오른쪽 생성물로 가는 방향 있는 문장'으로 읽는다. 화살표 양쪽을 가려 반응물과 생성물을 직접 표시해 보며 문법을 잡아라.", "cite": ""}, "CH1-055": {"name": "화학반응식 계수", "course": "ch1", "unit": "Ⅰ-4", "tier": "C", "mis": ["정수비가 원칙이다.", "1은 쓰지 않는다.", "종류가 아니라 몰비이다."], "dx": "반응식 계수를 단순한 개수표로 보고, 그것이 가장 간단한 정수 몰비라는 의미를 놓친 경우다. 계수를 몰비로 읽지 못하면 이후 양적관계 계산이 통째로 막힌다.", "fix": "계수를 '개수표가 아니라 가장 간단한 정수 몰비'로 읽는다. 2H₂ + O₂ → 2H₂O에서 2:1:2를 몰비로 소리 내어 읽으며 양적관계의 출발로 삼아라.", "cite": ""}, "CH1-056": {"name": "질량 보존", "course": "ch1", "unit": "Ⅰ-4", "tier": "A", "mis": ["재배열만 일어난다.", "질량이 보존된다.", "원자는 변하지 않는다.", "빠져나간 기체도 포함해야 한다.", "원자가 보존된다."], "dx": "반응에서 질량이 생기거나 사라진다고 본 경우다(빠져나간 기체를 빼먹는 게 전형). 반응은 원자의 재배열일 뿐이라는 보존 감각이 없으면 양적관계의 출발 전제가 무너진다.", "fix": "반응을 '원자가 사라지지 않고 재배열될 뿐'으로 못 박는다. 빠져나간 기체까지 포함한 닫힌 계로 반응 전후 질량을 맞춰 보며 보존을 확인하라.", "cite": ""}, "CH1-057": {"name": "질량 보존 법칙", "course": "ch1", "unit": "Ⅰ-4", "tier": "C", "mis": ["원자가 보존된다.", "기체 생성물을 더해야 한다.", "총질량이 유지된다."], "dx": "반응 전후 원자의 종류·수가 그대로라 총질량이 같다는 법칙을, 기체로 빠진 생성물까지 닫힌 계로 셈해야 성립한다는 점에서 놓친 경우다. 이 닫힌 계 감각이 약하면 질량 균형 문제가 어긋난다.", "fix": "'원자의 종류·수가 그대로라 닫힌 계의 총질량이 같다'를 기준으로 삼는다. 기체가 빠지는 반응을 밀폐 용기로 두고 전후 질량을 비교해 법칙을 확인하라.", "cite": ""}, "CH1-058": {"name": "일정 성분비 법칙", "course": "ch1", "unit": "Ⅰ-4", "tier": "C", "mis": ["혼합물은 비율이 가변적이다.", "조성이 일정하다.", "부피가 아니라 질량비이다."], "dx": "한 화합물의 성분 질량비가 늘 일정하다는 점을, 혼합물의 가변 비율과 뒤섞어 놓친 경우다. 이 구분이 흔들리면 화합물과 혼합물을 가르는 기준, 나아가 화학식 결정이 어긋난다.", "fix": "'한 화합물의 성분 질량비는 늘 일정, 혼합물은 자유'로 둘을 갈라 둔다. 물의 H:O = 1:8과 소금물의 자유로운 비를 비교해 구분하라.", "cite": ""}, "CH1-059": {"name": "일정 성분비 적용", "course": "ch1", "unit": "Ⅰ-4", "tier": "B", "mis": ["산소가 8배 무겁다.", "산소가 더 무겁다."], "dx": "일정한 질량비(물에서 수소:산소 = 1:8)로 성분량을 역산하는 적용이 흔들린 경우다. 이 계산이 약하면 조성 분석·화학식 도출에서 막힌다.", "fix": "일정한 질량비(물 수소:산소 = 1:8)로 성분량을 역산한다. 산소 16 g과 결합하는 수소가 2 g임을 비례로 직접 구해 조성 분석에 써라.", "cite": ""}, "CH1-060": {"name": "배수 비례 법칙", "course": "ch1", "unit": "Ⅰ-4", "tier": "C", "mis": ["여러 화합물이 필요하다.", "간단한 정수비이다.", "배수 비례는 여러 화합물을 비교한다."], "dx": "같은 두 원소가 만든 여러 화합물을 '비교'할 때 한 원소 고정량에 결합한 다른 원소 질량이 간단한 정수비가 된다는 법칙을 놓친 경우다. '여러 화합물 비교'라는 전제를 놓치면 원자설의 정량적 근거를 못 읽는다.", "fix": "배수 비례는 '같은 두 원소가 만든 여러 화합물을 비교할 때' 성립함을 전제로 못 박는다. 한 원소를 고정량으로 두고 다른 원소 질량이 정수비가 되는지 두 화합물로 확인하라.", "cite": ""}, "CH1-061": {"name": "배수 비례 적용", "course": "ch1", "unit": "Ⅰ-4", "tier": "C", "mis": ["산소가 1개 대 2개이다.", "CO₂의 산소가 더 많다.", "간단한 1:2이다."], "dx": "CO와 CO₂에서 탄소 같은 양당 산소가 1:2라는 배수 비례 적용이 흔들린 경우다. 화합물 쌍을 직접 비교하는 셈이 약하면 배수 비례 문제가 어긋난다.", "fix": "화합물 쌍을 직접 비교해 배수 비례를 적용한다. 탄소 같은 양당 CO와 CO₂의 산소가 1:2임을 계산해 정수비를 확인하라.", "cite": ""}, "CH1-062": {"name": "기체 반응 법칙", "course": "ch1", "unit": "Ⅰ-4", "tier": "C", "mis": ["질량이 아니라 부피비이다.", "조건이 일정해야 한다.", "간단한 정수비이다."], "dx": "같은 온도·압력에서 반응하는 기체 부피가 간단한 정수비라는 점을, 질량비와 혼동하거나 조건 일정 전제를 빼먹어 놓친 경우다. 이 법칙이 약하면 아보가드로 법칙·분자설로 이어지는 고리가 끊긴다.", "fix": "'같은 온도·압력에서 반응 기체의 부피가 간단한 정수비'임을 못 박는다(질량비 아님). 수소·산소·수증기 부피가 2:1:2임을 확인하며 아보가드로 법칙으로 이어라.", "cite": ""}, "CH1-063": {"name": "계수비-분자수", "course": "ch1", "unit": "Ⅰ-4", "tier": "B", "mis": ["질량비가 아니라 분자 수 비이다.", "분자 단위의 비이다.", "계수가 분자 수를 나타낸다.", "계수가 2:1:2이다."], "dx": "계수비를 질량의 비로 받아들이고, 그것이 실은 분자(입자) 수의 비라는 점을 놓친 경우다. 계수=분자 수라는 기준이 흔들리면 몰비·부피비 해석이 함께 무너진다.", "fix": "계수비를 '질량이 아니라 분자(입자) 수의 비'로 못 박는다. 2H₂ + O₂에서 분자 수 2:1을 세어 보며 몰비·부피비의 토대로 삼아라.", "cite": ""}, "CH1-064": {"name": "계수비-질량비", "course": "ch1", "unit": "Ⅰ-4", "tier": "A", "mis": ["질량은 분자량에 따라 다르다.", "질량비가 아니다.", "분자량을 곱해야 한다.", "분자량을 곱해야 질량비가 된다.", "질량 = 몰수 × 분자량이다."], "dx": "계수비를 그대로 질량비로 쓴 경우다. 물질마다 분자량이 달라 (몰수 × 분자량)을 거쳐야 질량비가 되는데 그 단계를 건너뛴 것이다. 이 한 단계를 빠뜨리면 질량 기반 양적관계·수율 계산이 전부 틀어진다.", "fix": "계수비 = 몰비임을 먼저 못 박고, 질량을 물으면 반드시 몰수에 분자량을 곱하는 한 단계를 끼운다. 계수에서 몰, 몰에서 질량으로 잇는 3단 환산을 한 반응으로 직접 써 보라.", "cite": ""}, "CH1-065": {"name": "계수비-부피비", "course": "ch1", "unit": "Ⅰ-4", "tier": "B", "mis": ["질량비가 아니다.", "아보가드로 법칙은 기체에 적용된다.", "분자 수 비와 같다.", "기체에만 적용된다."], "dx": "계수비가 부피비와 같아지는 건 기체에 한정된다(아보가드로 법칙)는 단서를 놓친 경우다. 적용 범위를 기체로 제한하지 못하면 액체·고체가 섞인 반응에서 부피비를 잘못 쓴다.", "fix": "'계수비 = 부피비'는 기체에만 적용됨(아보가드로 법칙)을 단서로 못 박는다. 액체·고체가 낀 반응에선 부피비를 쓰지 않음을 예로 가려라.", "cite": ""}, "CH1-066": {"name": "양적관계 부피", "course": "ch1", "unit": "Ⅰ-4", "tier": "B", "mis": ["계수비가 2:1이다.", "계수비가 2:1:2이다.", "계수비가 1:3이다."], "dx": "기체 반응에서 계수비를 그대로 부피비로 옮겨 부피를 구하는 적용이 흔들린 경우다. 이 환산이 약하면 기체 양적관계 문제에서 답이 어긋난다.", "fix": "기체 반응은 '계수비를 그대로 부피비로' 옮겨 부피를 구한다. 주어진 기체 부피에 계수비를 적용해 다른 기체 부피를 직접 구해 보라.", "cite": ""}, "CH1-067": {"name": "양적관계 몰", "course": "ch1", "unit": "Ⅰ-4", "tier": "B", "mis": ["계수비 1:2이다.", "계수비 2:2이다.", "계수비 3:2이다."], "dx": "계수비를 몰비로 옮겨 반응·생성 몰수를 구하는 적용이 흔들린 경우다. 가장 기본인 몰 환산이 약하면 질량·부피 양적관계가 줄줄이 막힌다.", "fix": "계수비를 몰비로 옮겨 반응·생성 몰수를 구한다. 한 물질의 몰수에 계수비를 곱해 짝 물질의 몰수를 구하는 환산을 반복해 익혀라.", "cite": ""}, "CH1-068": {"name": "한계 반응물", "course": "ch1", "unit": "Ⅰ-4", "tier": "A", "mis": ["한계 반응물이 상한을 정한다.", "양이 많고 적음만으로 정해지지 않는다.", "먼저 소모되는 쪽이다.", "먼저 소모되는 쪽이 상한이다.", "반응할 상대가 없다.", "질량만으로 정해지지 않는다."], "dx": "단순히 양이 적은 쪽을 한계 반응물로 본 경우다. 계수로 나눈 '반응에 쓸 수 있는 몫'을 비교해야 누가 먼저 동나는지 정해진다. 이 비교를 건너뛰면 생성물 최대량·수율 계산이 엉뚱한 기준에서 출발한다.", "fix": "한계 반응물은 '각 반응물의 몰수를 계수로 나눈 몫이 가장 작은 쪽'으로 정한다. 양이 많아도 몫이 작으면 먼저 동남을, 계수가 다른 예제로 확인하라.", "cite": ""}, "CH1-069": {"name": "몰비-계수비", "course": "ch1", "unit": "Ⅰ-4", "tier": "C", "mis": ["질량비가 아니다.", "계수가 몰비를 나타낸다.", "계수 = 몰비이다."], "dx": "계수가 곧 반응 몰비라는 점을 질량비와 헷갈려 놓친 경우다. 계수=몰비라는 출발점이 흔들리면 모든 양적관계가 첫 단추부터 어긋난다.", "fix": "'계수가 곧 반응 몰비'임을 첫 단추로 못 박는다(질량비 아님). 반응식 계수를 그대로 몰비로 읽어 양적관계의 출발점을 세워라.", "cite": ""}, "CH1-070": {"name": "계수 맞추기", "course": "ch1", "unit": "Ⅰ-4", "tier": "A", "mis": ["산소 계수가 2여야 한다.", "물의 계수가 2여야 한다.", "수소 계수가 3이어야 한다.", "화학식을 바꾸면 다른 물질이 된다.", "질량 보존을 만족해야 한다."], "dx": "계수가 아니라 화학식(첨자)을 바꿔 맞추려 한 경우다. 첨자를 바꾸면 다른 물질이 되므로, 원자 종류별 수가 양변에 같도록 계수만 조정해야 한다. 균형을 못 맞추면 그 뒤 모든 양적관계가 틀린 식 위에 세워진다.", "fix": "균형은 '첨자(화학식)는 건드리지 말고 계수만 조정'해 맞춘다. 원자 종류별 수를 양변에 적어 같아지도록 계수만 바꾸는 연습을 하라.", "cite": ""}, "CH1-071": {"name": "양적관계 질량", "course": "ch1", "unit": "Ⅰ-4", "tier": "C", "mis": ["CO₂ 1몰은 44 g이다.", "산소가 더해져 44 g이 된다.", "산소 분자 O₂ 1몰은 32 g이다."], "dx": "계수비로 몰을 구한 뒤 몰질량을 곱해 질량으로 옮기는 마지막 환산이 흔들린 경우다. 몰에서 질량으로 가는 다리가 약하면 질량 양적관계의 결론이 어긋난다.", "fix": "계수비로 몰을 구한 뒤 '몰 × 몰질량'으로 질량으로 옮긴다. 마지막 환산에서 몰질량을 곱하는 단계를 빠뜨리지 않도록 끝까지 적어라.", "cite": ""}, "CH1-072": {"name": "계수 규칙", "course": "ch1", "unit": "Ⅰ-4", "tier": "C", "mis": ["참여하는 물질만 쓴다.", "입자 수는 음수가 될 수 없다.", "정수비가 원칙이다."], "dx": "반응에 참여하는 물질만, 그리고 계수는 양의 정수로 쓴다는 규칙을 놓친 경우다. 식 작성 규칙이 흐리면 균형·양적관계의 전제가 흔들린다.", "fix": "식 작성은 '반응에 참여하는 물질만, 계수는 양의 정수로'를 규칙으로 둔다. 규칙에 맞는지 점검하며 반응식을 써 균형의 전제를 갖춰라.", "cite": ""}, "CH1-073": {"name": "분자설 도입", "course": "ch1", "unit": "Ⅰ-4", "tier": "C", "mis": ["원자설만으로는 부족했다.", "부피비를 설명하는 데 쓰였다.", "모순이 아니라 보완이다."], "dx": "분자설을 원자설과 충돌하는 것으로 본 경우다. 원자설만으로 설명 못 한 기체 부피비를 메우려 분자 개념이 보태진 것이다. 이 보완 관계를 놓치면 부피비=분자 수 비라는 결론의 뿌리를 못 짚는다.", "fix": "분자설을 '원자설과 충돌이 아니라, 설명 못 한 기체 부피비를 메우려 보탠 보완'으로 본다. 부피비 = 분자 수 비라는 결론이 분자 개념에서 나옴을 짚어라.", "cite": ""}, "CH1-074": {"name": "일정 성분비 범위", "course": "ch1", "unit": "Ⅰ-4", "tier": "B", "mis": ["혼합물은 비율이 가변적이다.", "혼합물에는 적용되지 않는다.", "섞는 비율에 따라 달라진다.", "여러 기체가 섞인 혼합물이다."], "dx": "일정 성분비 법칙을 비율이 자유로운 혼합물에까지 적용한 경우다. 법칙의 적용 범위를 화합물로 좁히지 못하면 혼합물 문제에서 엉뚱한 일정 비를 가정하게 된다.", "fix": "일정 성분비는 '비율이 정해진 화합물에만' 적용함을 못 박는다. 혼합물은 비가 자유로워 이 법칙을 가정하면 안 됨을 예로 가려라.", "cite": ""}, "CH1-075": {"name": "양적관계 몰수변화", "course": "ch1", "unit": "Ⅰ-4", "tier": "C", "mis": ["4몰이 2몰이 된다.", "증가·감소·일정이 모두 가능하다."], "dx": "반응 전후 기체 총 몰수가 늘 일정하다고 본 경우다. 양변 계수 합을 비교하면 늘 수도, 줄 수도, 같을 수도 있다. 이 감각이 없으면 반응에 따른 압력·부피 변화 해석이 어긋난다.", "fix": "반응 전후 기체 몰수는 '양변 계수 합을 비교'해 늘 수도, 줄 수도, 같을 수도 있음을 본다. 계수 합 변화로 압력·부피 변화를 예측해 보라.", "cite": ""}, "CH1-076": {"name": "부피비-몰비", "course": "ch1", "unit": "Ⅰ-4", "tier": "C", "mis": ["질량비가 아니다.", "부피 ∝ 몰수이다.", "몰수가 부피를 정한다."], "dx": "기체 부피비를 질량비로 본 경우다. 부피는 몰수에 비례(부피 ∝ 몰수)하므로 부피비가 곧 몰비다. 이 비례를 놓치면 기체 양적관계에서 질량과 부피를 섞어 쓴다.", "fix": "'기체 부피는 몰수에 비례하므로 부피비 = 몰비'임을 못 박는다(질량비 아님). 부피비를 곧장 몰비로 읽어 기체 양적관계에 써라.", "cite": ""}, "CH1-223": {"name": "양적관계", "course": "ch1", "unit": "Ⅰ-4", "tier": "C", "mis": ["부피비 = 분자 수 비이다.", "아보가드로 법칙 때문이다.", "계수가 몰비를 준다."], "dx": "기체 반응에서 부피비가 곧 분자 수 비라는 점(아보가드로 법칙)을 놓친 경우다. 계수가 주는 몰비와 부피비를 잇지 못하면 기체 양적관계 문제가 막힌다.", "fix": "기체 반응은 '부피비 = 분자 수 비(아보가드로 법칙)'로 못 박는다. 계수의 몰비와 부피비를 이어 기체 양적관계를 풀어라.", "cite": ""}, "CH1-077": {"name": "원자 구성", "course": "ch1", "unit": "Ⅱ-1", "tier": "C", "mis": ["전자는 핵 바깥에 있다.", "핵 안에는 양성자·중성자만 있다.", "전자도 포함된다."], "dx": "원자를 핵(양성자·중성자)만으로 떠올리고 핵 바깥 전자를 구성에서 빠뜨린 경우다. 전자를 빼면 원자의 전기적 중성도, 이온이 왜 전자만으로 생기는지도 설명할 수 없다.", "fix": "원자를 '핵(양성자·중성자) + 핵 바깥 전자'로, 전자를 빼지 않고 그린다. 전자가 있어야 중성이 성립하고 전자만 드나들어 이온이 됨을 이어 짚어라.", "cite": ""}, "CH1-078": {"name": "입자 전하", "course": "ch1", "unit": "Ⅱ-1", "tier": "B", "mis": ["부호가 반대이다.", "중성이다.", "음전하 입자이다.", "양성자 +, 전자 -이다."], "dx": "세 입자의 전하를 양성자 +1·전자 −1(크기 같고 부호 반대)·중성자 0으로 못 박지 못한 경우다. 전하의 기준값이 흐리면 원자의 중성 조건과 이온 전하 계산이 흔들린다.", "fix": "세 입자 전하를 '양성자 +1, 전자 −1(크기 같고 부호 반대), 중성자 0'으로 못 박는다. 이 값으로 중성 조건과 이온 전하를 직접 셈하라.", "cite": ""}, "CH1-079": {"name": "원자번호", "course": "ch1", "unit": "Ⅱ-1", "tier": "A", "mis": ["중성자가 아니라 양성자이다.", "질량수는 양성자 + 중성자이다.", "합은 질량수이다.", "양성자 수는 불변이다.", "양성자 수가 같기 때문이다.", "질량은 질량수가 나타낸다."], "dx": "원자번호를 양성자 수가 아닌 다른 수로 잡거나 질량수와 뒤섞은 경우다. 양성자 수가 곧 원소의 정체성이라는 이 한 줄이 흔들리면 주기율표 위치부터 그 뒤 화학 전부가 어긋난다.", "fix": "원자번호를 '양성자 수, 곧 원소의 정체성'으로 못 박는다(질량수와 구분). 양성자 수가 바뀌면 다른 원소가 됨을, 주기율표 위치와 맞춰 확인하라.", "cite": ""}, "CH1-080": {"name": "원소 결정", "course": "ch1", "unit": "Ⅱ-1", "tier": "C", "mis": ["중성자가 아니라 양성자이다.", "동위원소이다.", "이온도 같은 원소이다."], "dx": "무엇이 원소 종류를 정하는지에서 양성자 수가 아니라 중성자·전자를 떠올린 경우다. 양성자 수가 정체성이라는 점을 놓치면 동위원소와 이온이 왜 여전히 같은 원소인지 이해하지 못한다.", "fix": "'원소 종류를 정하는 건 오직 양성자 수'임을 기준으로 삼는다. 그래서 중성자·전자가 달라도(동위원소·이온) 같은 원소임을 짚어라.", "cite": ""}, "CH1-081": {"name": "질량수", "course": "ch1", "unit": "Ⅱ-1", "tier": "A", "mis": ["전자가 아니라 중성자이다.", "양성자도 더해야 한다.", "중성자도 더해야 한다.", "전자 질량은 무시한다.", "전자는 제외한다.", "중성자만큼 차이가 난다."], "dx": "질량수를 양성자와 중성자의 합으로 보지 못한 경우다(전자를 끼워 넣거나 한쪽을 빠뜨리는 게 전형). 전자 질량은 무시할 만하다는 감각까지 잡혀야 중성자 수 계산·동위원소 구분으로 이어진다.", "fix": "질량수를 '양성자 수 + 중성자 수'로 못 박는다(전자 질량은 무시). 질량수에서 원자번호를 빼 중성자 수를 구하는 역산을 직접 해 보라.", "cite": ""}, "CH1-082": {"name": "원자 표기", "course": "ch1", "unit": "Ⅱ-1", "tier": "C", "mis": ["위아래가 바뀌었다.", "중성자 수가 아니다."], "dx": "원소 기호 표기에서 왼쪽 위 질량수와 왼쪽 아래 원자번호의 자리를 바꿔 읽은 경우다. 표기를 거꾸로 읽으면 양성자·중성자 수를 통째로 잘못 뽑아낸다.", "fix": "원소 기호 표기를 '왼쪽 위 = 질량수, 왼쪽 아래 = 원자번호'로 자리를 고정한다. 한 핵종을 적고 두 수에서 양성자·중성자 수를 뽑아 보라.", "cite": ""}, "CH1-083": {"name": "전자수", "course": "ch1", "unit": "Ⅱ-1", "tier": "C", "mis": ["중성자가 아니라 양성자이다.", "전자를 잃었다.", "전자를 얻었다."], "dx": "중성 원자의 전자 수가 양성자 수와 같다는 점을, 중성자 수 등과 헷갈려 놓친 경우다. 이 등식이 흔들리면 전자 배치의 출발 전자 수부터 어긋난다.", "fix": "'중성 원자는 전자 수 = 양성자 수'를 등식으로 못 박는다. 원자번호로 전자 수를 잡아 전자 배치의 출발점으로 삼아라.", "cite": ""}, "CH1-084": {"name": "질량수 계산", "course": "ch1", "unit": "Ⅱ-1", "tier": "C", "mis": ["차가 아니라 합이다.", "23 - 11 = 12이다.", "합이다."], "dx": "질량수 = 양성자 + 중성자라는 관계를 뒤집어 중성자 수를 합으로 구한 경우다. 중성자 수 = 질량수 − 원자번호라는 역산이 안 잡히면 동위원소 비교가 어긋난다.", "fix": "'중성자 수 = 질량수 − 원자번호'로 역산한다. 질량수와 원자번호를 넣어 중성자 수를 구하고 동위원소를 비교해 보라.", "cite": ""}, "CH1-085": {"name": "동위원소", "course": "ch1", "unit": "Ⅱ-1", "tier": "A", "mis": ["전자 배치가 같다.", "같은 원소이다.", "중성자 수가 다르다.", "양성자 수가 같다.", "질량수가 다르기 때문이다.", "양성자 수가 같기 때문이다."], "dx": "동위원소를 양성자가 다른(즉 다른 원소인) 것으로 본 경우다. 양성자 수가 같아 화학적 성질이 같고 중성자 수만 달라 질량이 다른 것이라는 두 축을 잡아야, 평균 원자량과 동위원소 분리 불가의 이유가 풀린다.", "fix": "동위원소를 '양성자 같아 성질 같음, 중성자만 달라 질량 다름' 두 축으로 잡는다. 이 두 축으로 평균 원자량과 분리 불가의 이유를 설명해 보라.", "cite": ""}, "CH1-086": {"name": "입자 질량", "course": "ch1", "unit": "Ⅱ-1", "tier": "B", "mis": ["두 핵자 질량이 비슷하다.", "약 1840분의 1이다.", "전자가 훨씬 가볍다.", "전자가 매우 가볍다."], "dx": "양성자·중성자는 질량이 비슷하고 전자는 약 1840분의 1로 훨씬 가볍다는 비를 놓친 경우다. 이 질량 차가 안 잡히면 원자 질량이 사실상 핵에 몰려 있다는 다음 개념이 흔들린다.", "fix": "'양성자≈중성자, 전자는 약 1840분의 1로 가벼움'을 기준으로 삼는다. 그래서 질량이 핵에 몰린다는 다음 개념까지 이어 적어라.", "cite": ""}, "CH1-087": {"name": "원자 질량 분포", "course": "ch1", "unit": "Ⅱ-1", "tier": "B", "mis": ["전자 질량은 매우 작다.", "전자 질량은 무시 수준이다.", "핵자가 질량을 정한다.", "전자 질량이 매우 작다."], "dx": "원자 질량이 핵(양성자·중성자)에 거의 다 몰려 있고 전자 몫은 무시할 만하다는 점을 놓친 경우다. 이걸 놓치면 질량수가 곧 원자 질량을 대표한다는 셈이 흔들린다.", "fix": "'원자 질량은 핵에 거의 다, 전자 몫은 무시'로 못 박는다. 그래서 질량수가 곧 원자 질량을 대표함을 한 문장으로 이어라.", "cite": ""}, "CH1-088": {"name": "원자핵 크기", "course": "ch1", "unit": "Ⅱ-1", "tier": "B", "mis": ["핵은 매우 작다.", "핵은 극히 일부이다.", "핵은 작은 점과 같다."], "dx": "원자핵이 부피로는 극히 작은 점이면서 질량 대부분을 차지한다는 두 사실을 함께 잡지 못한 경우다. 이 대비가 약하면 원자가 대부분 빈 공간이라는 러더퍼드 결론을 이해하지 못한다.", "fix": "핵을 '부피로는 극히 작은 점이면서 질량은 대부분'이라는 두 사실로 함께 잡는다. 그래서 원자가 대부분 빈 공간이라는 러더퍼드 결론으로 이어라.", "cite": ""}, "CH1-089": {"name": "동위원소 정의", "course": "ch1", "unit": "Ⅱ-1", "tier": "C", "mis": ["양성자 수가 같다.", "중성자 수가 다르다.", "반대로 설명되었다."], "dx": "동위원소의 정의를 거꾸로(양성자 다르고 중성자 같음) 잡은 경우다. '양성자 같고 중성자 다름'이라는 방향을 바로잡지 못하면 동위원소 판정 전체가 뒤집힌다.", "fix": "동위원소 정의의 방향을 '양성자 같음, 중성자 다름'으로 바로잡는다. 거꾸로 잡지 않도록 두 축을 적어 판정에 써라.", "cite": ""}, "CH1-090": {"name": "평균 원자량", "course": "ch1", "unit": "Ⅱ-1", "tier": "C", "mis": ["한 동위원소만 보는 것이 아니다.", "가중 평균이기 때문이다.", "비율로 가중한다."], "dx": "평균 원자량을 동위원소 질량의 단순 평균으로 본 경우다. 존재비로 가중한다는 점을 놓치면 실제 원자량 값이 어긋나 몰 계산까지 틀어진다.", "fix": "평균 원자량은 '동위원소 질량 × 존재비의 합(가중 평균)'으로 구한다. 단순 평균이 아님을, 존재비가 다른 예로 직접 계산해 확인하라.", "cite": ""}, "CH1-091": {"name": "동위원소 전자", "course": "ch1", "unit": "Ⅱ-1", "tier": "C", "mis": ["전자 수가 같다.", "양성자 수가 같다."], "dx": "동위원소끼리 전자 수·전자 배치가 다를 거라 본 경우다. 양성자 수가 같으니 전자 수도 같고, 그래서 화학적 성질이 같다는 연결을 놓치면 동위원소의 핵심을 못 짚는다.", "fix": "'동위원소는 양성자 수가 같아 전자 수·배치도 같다'를 못 박는다. 그래서 화학적 성질이 같다는 결론까지 이어 짚어라.", "cite": ""}, "CH1-092": {"name": "핵전하", "course": "ch1", "unit": "Ⅱ-1", "tier": "C", "mis": ["중성자는 전하가 없다.", "양성자 때문이다.", "핵에는 전자가 없다."], "dx": "핵의 (+)전하가 양성자에서만 나오고 중성자는 전하가 없다는 점을 놓친 경우다. 핵전하의 출처가 흐리면 유효핵전하·핵과 전자의 인력 해석이 흔들린다.", "fix": "핵의 (+)전하가 '양성자에서만 나오고 중성자는 0'임을 못 박는다. 핵전하 = 양성자 수임을 유효핵전하 해석의 출발로 삼아라.", "cite": ""}, "CH1-093": {"name": "동위원소 판정", "course": "ch1", "unit": "Ⅱ-1", "tier": "C", "mis": ["둘 다 산소이다.", "양성자 수가 같다.", "질량수가 다르기 때문이다."], "dx": "두 원자가 동위원소인지 가릴 때 양성자 수가 같은지를 기준 삼지 못한 경우다. 질량수가 달라도 양성자 수가 같으면 같은 원소라는 판정이 흔들리면 분류가 어긋난다.", "fix": "두 원자가 동위원소인지는 '양성자 수가 같은지'로 가린다. 질량수가 달라도 양성자 수가 같으면 같은 원소임을 판정 기준으로 써라.", "cite": ""}, "CH1-094": {"name": "동위원소 vs 동중원소", "course": "ch1", "unit": "Ⅱ-1", "tier": "C", "mis": ["동위원소는 원자번호가 같다.", "양성자 수가 같다.", "같은 원소의 동위원소이다."], "dx": "같은 양성자 수의 동위원소와 같은 질량수의 동중원소를 뒤섞은 경우다. 무엇이 같은지(원자번호냐 질량수냐)를 가르지 못하면 핵종 분류가 헝클어진다.", "fix": "'동위원소 = 원자번호 같음, 동중원소 = 질량수 같음'으로 무엇이 같은지를 가른다. 두 핵종을 두고 어느 수가 같은지 따져 분류하라.", "cite": ""}, "CH1-095": {"name": "이온 형성", "course": "ch1", "unit": "Ⅱ-1", "tier": "C", "mis": ["(+)전하가 더 많아진다.", "(-)전하가 더 많아진다.", "전자만 잃거나 얻는다."], "dx": "전자를 잃으면 양이온, 얻으면 음이온이 된다는 방향을 놓친 경우다(전자만 드나든다는 점이 핵심). 이 방향이 흔들리면 이온식·결합·산화수가 줄줄이 어긋난다.", "fix": "'전자를 잃으면 양이온, 얻으면 음이온(드나드는 건 전자뿐)'을 못 박는다. 양성자는 그대로임을 이온식·산화수의 출발로 삼아라.", "cite": ""}, "CH1-096": {"name": "이온 전자수", "course": "ch1", "unit": "Ⅱ-1", "tier": "C", "mis": ["전자를 잃었다.", "전자 2개를 얻었다."], "dx": "이온의 전자 수를 (양성자 수 − 전하)로 셈하는 게 흔들린 경우다. 전하만큼 전자가 줄거나 는다는 셈이 약하면 이온의 전자 배치를 잘못 잡는다.", "fix": "이온의 전자 수를 '양성자 수 − 전하'로 셈한다. 전하만큼 전자가 줄거나 늚을, 양이온·음이온 예로 직접 계산하라.", "cite": ""}, "CH1-097": {"name": "이온 양성자수", "course": "ch1", "unit": "Ⅱ-1", "tier": "A", "mis": ["전자만 변한다.", "양성자는 변하지 않는다.", "양성자 수가 같다.", "전자만 잃었다.", "양성자 수가 불변이다."], "dx": "이온이 되면 양성자 수도 변한다고 본 경우다. 드나드는 건 전자뿐이고 양성자 수는 그대로라 원소 정체성이 유지된다는 점을 놓치면, 이온이 여전히 같은 원소라는 사실부터 어긋난다.", "fix": "'이온이 돼도 양성자 수는 그대로, 전자만 드나든다'를 못 박는다. 그래서 이온이 여전히 같은 원소임을, 전자 수만 바꿔 확인하라.", "cite": ""}, "CH1-098": {"name": "수소 동위원소", "course": "ch1", "unit": "Ⅱ-1", "tier": "C", "mis": ["모두 수소이다.", "질량수가 다르기 때문이다.", "양성자 수가 같다."], "dx": "수소의 ¹H·²H·³H를 질량수가 달라 서로 다른 원소로 본 경우다. 양성자 수가 모두 1이라 다 수소라는 점을 놓치면 동위원소 개념의 가장 기본 예가 무너진다.", "fix": "수소의 ¹H·²H·³H가 '양성자 수가 모두 1이라 다 수소'임을 못 박는다. 질량수만 다르고 같은 원소임을 동위원소의 기본 예로 새겨라.", "cite": ""}, "CH1-099": {"name": "원자모형 변천", "course": "ch1", "unit": "Ⅱ-2", "tier": "C", "mis": ["돌턴이 가장 먼저이다.", "돌턴은 전자를 몰랐다."], "dx": "원자모형의 발전 순서(돌턴·톰슨·러더퍼드·보어·현대)나 각 모형이 무엇을 몰랐는지를 헷갈린 경우다. 돌턴은 전자조차 몰랐다는 식의 '각 단계가 무엇을 더 밝혔나'가 안 잡히면 모형이 왜 바뀌었는지 설명하지 못한다.", "fix": "원자모형을 '돌턴(전자 모름)·톰슨(전자 발견)·러더퍼드(핵 발견)·보어(준위)·현대(확률)' 순으로, 각 단계가 무엇을 더 밝혔는지로 외운다. 모형마다 한 줄로 '새로 밝힌 것'을 적어 변천의 인과를 잡아라.", "cite": ""}, "CH1-100": {"name": "전자 발견", "course": "ch1", "unit": "Ⅱ-2", "tier": "A", "mis": ["음극선 실험으로 전자를 찾았다.", "러더퍼드는 원자핵을 발견했다.", "원자핵은 러더퍼드가 발견했다.", "전자가 (-)전하이다.", "원자가 분해 가능함을 보였다."], "dx": "전자 발견을 톰슨의 음극선 실험에 연결하지 못하고 러더퍼드와 뒤바꾼 경우다. 누가 무엇을 발견했는지가 흔들리면 원자모형 변천의 인과가 통째로 헝클어진다.", "fix": "'전자 발견 = 톰슨의 음극선 실험'으로 못 박는다(러더퍼드 아님). 누가 무엇을 발견했는지 표로 정리해 톰슨(전자)·러더퍼드(핵)를 갈라라.", "cite": ""}, "CH1-101": {"name": "음극선 성질", "course": "ch1", "unit": "Ⅱ-2", "tier": "C", "mis": ["전자가 (-)전하이다.", "전자의 흐름이다.", "(-)전하라 (+)극에 끌린다."], "dx": "음극선이 (−)전하를 띤 전자의 흐름이라 (+)극 쪽으로 휜다는 점을 놓친 경우다. 음극선의 정체가 흐리면 전자의 전하·질량을 밝힌 실험의 의미를 못 읽는다.", "fix": "음극선을 '(−)전하를 띤 전자의 흐름이라 (+)극 쪽으로 휜다'로 못 박는다. 휘는 방향으로 전자가 음전하임을 읽어 내는 논리를 따라가 보라.", "cite": ""}, "CH1-102": {"name": "톰슨 모형", "course": "ch1", "unit": "Ⅱ-2", "tier": "C", "mis": ["톰슨 모형엔 핵이 없다.", "핵은 러더퍼드가 발견했다.", "핵 개념이 없다."], "dx": "톰슨 모형을 (+)바탕에 전자가 박힌 형태로 보지 못하고 핵이 있다고 본 경우다. 톰슨 모형엔 핵이 없다는 점을 놓치면 러더퍼드가 무엇을 새로 밝혔는지 대비가 사라진다.", "fix": "톰슨 모형을 '(+)바탕에 전자가 박힌, 핵이 없는 형태'로 못 박는다. 핵이 없다는 점을 러더퍼드 모형과 나란히 두고 대비하라.", "cite": ""}, "CH1-103": {"name": "원자핵 발견", "course": "ch1", "unit": "Ⅱ-2", "tier": "A", "mis": ["톰슨은 전자를 발견했다.", "전자는 톰슨이 발견했다.", "음극선은 전자 발견 실험이다.", "핵은 양전하이다.", "핵은 매우 작다.", "전자는 음극선 실험으로 밝혔다."], "dx": "원자핵 발견을 러더퍼드의 알파 입자 산란이 아니라 톰슨에 연결한 경우다. 발견의 주인을 바꾸면 음극선(전자)·산란(핵)이라는 두 실험의 역할이 뒤섞인다.", "fix": "'원자핵 발견 = 러더퍼드의 알파 입자 산란'으로 못 박는다(톰슨 아님). 음극선(전자)과 산란(핵) 두 실험의 주인과 결과를 갈라 정리하라.", "cite": ""}, "CH1-104": {"name": "알파 산란 결과", "course": "ch1", "unit": "Ⅱ-2", "tier": "C", "mis": ["원자 내부가 빈 공간이다.", "극히 일부만 되튀었다.", "핵에 부딪힌 경우만 크게 휜다."], "dx": "알파 입자 대부분이 그대로 통과하고 극히 일부만 크게 튕긴 관찰을 '원자 내부가 대부분 빈 공간'으로 잇지 못한 경우다. 결과와 해석의 연결이 약하면 핵의 존재라는 결론에 도달하지 못한다.", "fix": "'알파 입자 대부분 통과 = 원자 내부가 대부분 빈 공간'으로 관찰과 해석을 잇는다. 극히 일부만 튕긴다는 관찰까지 더해 핵의 존재로 이어라.", "cite": ""}, "CH1-105": {"name": "알파 산란 해석", "course": "ch1", "unit": "Ⅱ-2", "tier": "C", "mis": ["대부분 통과했다.", "전자는 가벼워 영향이 작다.", "(+)핵이 알파 입자를 밀어낸다."], "dx": "소수의 큰 산란이 작고 무거운 (+)핵이 알파 입자를 밀어낸 결과라는 해석을 놓친 경우다. 가벼운 전자로는 큰 산란을 못 만든다는 점까지 잡아야 핵의 성질이 드러난다.", "fix": "'소수의 큰 산란 = 작고 무거운 (+)핵이 알파 입자를 밀어낸 것'으로 해석한다. 가벼운 전자로는 큰 산란이 안 됨을 더해 핵의 성질을 끌어내라.", "cite": ""}, "CH1-106": {"name": "핵의 존재", "course": "ch1", "unit": "Ⅱ-2", "tier": "C", "mis": ["전자는 가볍다.", "양성자 때문이다.", "전자 질량은 매우 작다."], "dx": "질량과 (+)전하가 작은 핵에 몰려 있다는 결론을 놓친 경우다. 이 결론이 약하면 원자 질량이 핵에 집중된다는 앞 단원 사실과 모형이 연결되지 않는다.", "fix": "'질량과 (+)전하가 작은 핵에 집중'됨을 결론으로 못 박는다. 이를 앞서 본 '원자 질량은 핵에 몰림'과 이어 모형과 사실을 맞춰라.", "cite": ""}, "CH1-107": {"name": "보어 모형", "course": "ch1", "unit": "Ⅱ-2", "tier": "C", "mis": ["에너지가 양자화되어 있다.", "궤도를 돈다.", "다전자 원자엔 한계가 있다."], "dx": "보어 모형에서 전자가 정해진 에너지 준위(궤도)에만 있다는 양자화를 놓친 경우다. 이 핵심이 흔들리면 선 스펙트럼 설명도, 다전자 원자에서의 한계도 따라오지 못한다.", "fix": "보어 모형을 '전자가 정해진 에너지 준위에만 있다(양자화)'로 못 박는다. 이 핵심에서 선 스펙트럼 설명과 다전자 한계가 따라옴을 짚어라.", "cite": ""}, "CH1-108": {"name": "전자껍질 순서", "course": "ch1", "unit": "Ⅱ-2", "tier": "C", "mis": ["K가 가장 안쪽이다.", "K가 핵에 가장 가깝다."], "dx": "전자껍질이 K(가장 안쪽)·L·M 순이고 K가 핵에 가장 가깝다는 순서를 놓친 경우다. 껍질 순서가 흔들리면 에너지 준위 비교와 전자 배치 순서가 어긋난다.", "fix": "전자껍질을 'K(가장 안쪽)·L·M 순, K가 핵에 가장 가깝다'로 못 박는다. 안쪽일수록 에너지가 낮음을 순서와 맞춰 전자 배치에 써라.", "cite": ""}, "CH1-109": {"name": "에너지 준위", "course": "ch1", "unit": "Ⅱ-2", "tier": "B", "mis": ["바깥일수록 에너지가 높다.", "K가 더 안쪽이다.", "안쪽일수록 에너지가 낮다."], "dx": "바깥 껍질일수록 에너지 준위가 높다는 방향을 뒤집은 경우다. 안쪽이 낮고 바깥이 높다는 순서가 흔들리면 전자 전이의 흡수·방출 방향과 쌓음 순서가 어긋난다.", "fix": "'바깥 껍질일수록 에너지 준위가 높다(안쪽이 낮음)'로 방향을 못 박는다. 이 순서로 전이의 흡수·방출 방향과 쌓음 순서를 잡아라.", "cite": ""}, "CH1-110": {"name": "에너지 양자화", "course": "ch1", "unit": "Ⅱ-2", "tier": "A", "mis": ["정해진 값만 가진다.", "양자화되어 있다.", "중간값은 불가능하다.", "허용된 준위만 존재한다.", "특정 에너지만 방출한다.", "불연속적이라는 뜻이다."], "dx": "전자 에너지가 연속이라 중간값도 가질 수 있다고 본 경우다. 허용된 준위만 존재한다는 양자화를 놓치면 선 스펙트럼이 왜 특정 파장만 나오는지 설명할 수 없다.", "fix": "전자 에너지를 '연속이 아니라 허용된 준위만 가짐(중간값 없음)'으로 못 박는다. 그래서 선 스펙트럼이 특정 파장만 내는 까닭을 이어 짚어라.", "cite": ""}, "CH1-111": {"name": "바닥상태", "course": "ch1", "unit": "Ⅱ-2", "tier": "C", "mis": ["가장 낮은 준위이다.", "에너지가 가장 낮다.", "에너지가 더 낮다."], "dx": "바닥상태가 전자가 가장 낮은 준위에 있는 가장 안정한 상태라는 점을 놓친 경우다. 기준인 바닥상태가 흐리면 들뜬상태와의 대비, 바닥상태 전자 배치가 흔들린다.", "fix": "바닥상태를 '전자가 가장 낮은 준위에 있는 가장 안정한 상태'로 못 박는다. 이 기준에서 들뜬상태와의 대비, 바닥상태 배치를 잡아라.", "cite": ""}, "CH1-112": {"name": "전자 전이", "course": "ch1", "unit": "Ⅱ-2", "tier": "A", "mis": ["떨어질 때는 방출이다.", "올라갈 때는 흡수이다.", "차이만큼 주고받는다."], "dx": "전자가 올라갈 때 흡수, 내려올 때 방출이라는 방향을 뒤바꾼 경우다. 주고받는 에너지가 두 준위 차와 같다는 점까지 잡아야 스펙트럼선의 위치를 해석할 수 있다.", "fix": "'올라갈 때 흡수, 내려올 때 방출, 주고받는 에너지 = 두 준위 차'로 못 박는다. 준위 차를 계산해 스펙트럼선 위치로 잇는 연습을 하라.", "cite": ""}, "CH1-113": {"name": "선 스펙트럼", "course": "ch1", "unit": "Ⅱ-2", "tier": "C", "mis": ["특정 파장만 방출된다.", "양자화 때문이다.", "선 스펙트럼이다."], "dx": "전이 에너지가 양자화돼 특정 파장만 나타나는 게 선 스펙트럼이라는 연결을 놓친 경우다. 양자화와 선 스펙트럼의 고리가 약하면 스펙트럼이 준위의 증거라는 해석이 안 선다.", "fix": "선 스펙트럼을 '전이 에너지가 양자화돼 특정 파장만 나타나는 것'으로 잇는다. 양자화가 선 스펙트럼을 만든다는 고리를 한 줄로 적어라.", "cite": ""}, "CH1-114": {"name": "스펙트럼 해석", "course": "ch1", "unit": "Ⅱ-2", "tier": "C", "mis": ["불연속 준위 때문이다.", "위치가 아니라 에너지이다.", "전자는 핵에 박혀 있지 않다."], "dx": "선 스펙트럼을 불연속 에너지 준위의 증거로 읽지 못한 경우다. 스펙트럼선의 의미가 위치가 아니라 에너지 차라는 점을 놓치면 보어 모형의 근거를 못 짚는다.", "fix": "선 스펙트럼을 '불연속 에너지 준위의 증거'로 읽는다. 스펙트럼선이 위치가 아니라 에너지 차를 뜻함을 보어 모형의 근거로 삼아라.", "cite": ""}, "CH1-115": {"name": "연속 스펙트럼", "course": "ch1", "unit": "Ⅱ-2", "tier": "A", "mis": ["모든 파장이 섞여 있다.", "무지개처럼 이어진다.", "끊김이 없다.", "모든 파장이 연속이다.", "수소는 선 스펙트럼이다."], "dx": "연속 스펙트럼이 모든 파장이 끊김 없이 이어진(무지개) 빛이라는 점을 놓치고 선 스펙트럼과 뒤섞은 경우다. 두 스펙트럼을 못 가르면 수소가 왜 선 스펙트럼을 내는지 의미가 사라진다.", "fix": "연속 스펙트럼을 '모든 파장이 끊김 없이 이어진(무지개) 빛'으로 선 스펙트럼과 갈라 둔다. 수소가 선 스펙트럼을 냄과 대비해 의미를 잡아라.", "cite": ""}, "CH1-116": {"name": "스펙트럼선 의미", "course": "ch1", "unit": "Ⅱ-2", "tier": "C", "mis": ["질량이 아니라 에너지 차이이다.", "전이에 따라 다르다.", "전이 에너지가 위치를 정한다."], "dx": "스펙트럼선의 위치가 전이 전후 준위의 에너지 차를 나타낸다는 점을 놓친 경우다. 위치를 질량 등으로 오해하면 스펙트럼의 정량적 의미를 못 읽는다.", "fix": "스펙트럼선의 위치를 '전이 전후 준위의 에너지 차'로 읽는다. 위치를 질량 등으로 오해하지 않도록 에너지 차로만 해석하라.", "cite": ""}, "CH1-117": {"name": "보어 모형 성공", "course": "ch1", "unit": "Ⅱ-2", "tier": "C", "mis": ["양자화로 설명한다.", "선 스펙트럼이 대상이다.", "다전자 원자엔 한계가 있다."], "dx": "보어 모형이 수소 선 스펙트럼을 에너지 양자화로 설명한 성과를 놓친 경우다. 무엇을 성공시켰는지가 흐리면 다전자 원자에서의 한계와 대비가 서지 않는다.", "fix": "보어 모형의 성과를 '수소 선 스펙트럼을 에너지 양자화로 설명'으로 못 박는다. 무엇을 성공시켰는지를 다전자 한계와 대비해 두라.", "cite": ""}, "CH1-118": {"name": "보어 모형 한계", "course": "ch1", "unit": "Ⅱ-2", "tier": "C", "mis": ["수소에만 잘 맞는다.", "전자가 둘 이상이면 부정확하다.", "다전자 원자엔 한계가 있다."], "dx": "보어 모형이 전자가 둘 이상인 원자에는 잘 맞지 않는다는 한계를 놓친 경우다. 이 한계가 안 잡히면 왜 현대 모형으로 넘어갔는지 동기를 못 짚는다.", "fix": "보어 모형의 한계를 '전자가 둘 이상인 원자엔 잘 안 맞음'으로 못 박는다. 이 한계가 현대 모형으로 넘어간 동기임을 짚어라.", "cite": ""}, "CH1-119": {"name": "현대 모형", "course": "ch1", "unit": "Ⅱ-2", "tier": "C", "mis": ["위치를 정확히 알 수 없다.", "정해진 궤도는 보어 모형이다.", "불확정성 원리 때문이다."], "dx": "현대 모형이 전자 위치를 확률로 다뤄 정해진 궤도가 없다는 점(보어와의 차이)을 놓친 경우다. 이 차이가 흐리면 다음 단원의 오비탈 개념이 보어식 궤도와 섞인다.", "fix": "현대 모형을 '전자 위치를 확률로 다뤄 정해진 궤도가 없다(보어와 차이)'로 못 박는다. 이 차이를 다음 단원 오비탈과 보어식 궤도가 안 섞이게 새겨라.", "cite": ""}, "CH1-120": {"name": "오비탈", "course": "ch1", "unit": "Ⅱ-2-d", "tier": "B", "mis": ["궤도 개념은 보어 모형이다.", "정확한 점이 아니다.", "확률적 개념이다.", "위치가 고정되지 않는다."], "dx": "오비탈을 보어식 정해진 궤도로 보고, 전자가 발견될 확률 분포(영역)라는 점을 놓친 경우다. 궤도와 오비탈을 섞으면 전자가 점이 아니라 구름처럼 퍼진다는 그림이 무너진다.", "fix": "오비탈을 '전자가 발견될 확률이 높은 영역(정해진 궤도 아님)'으로 못 박는다. 전자가 점이 아니라 구름처럼 퍼짐을 보어식 궤도와 대비하라.", "cite": ""}, "CH1-121": {"name": "불확정성", "course": "ch1", "unit": "Ⅱ-2-d", "tier": "C", "mis": ["불확정성 원리 때문이다.", "동시 측정에 한계가 있다."], "dx": "불확정성 원리로 전자의 위치와 운동량을 동시에 정확히 알 수 없다는 점을 놓친 경우다. 이 원리가 약하면 왜 오비탈을 확률로만 다루는지 근거가 사라진다.", "fix": "불확정성 원리를 '전자의 위치와 운동량을 동시에 정확히 알 수 없음'으로 못 박는다. 그래서 오비탈을 확률로만 다룬다는 근거로 삼아라.", "cite": ""}, "CH1-122": {"name": "오비탈 종류", "course": "ch1", "unit": "Ⅱ-2-d", "tier": "C", "mis": ["모양이 종류마다 다르다.", "구형이다.", "아령 형태이다."], "dx": "s·p·d·f 오비탈이 모양이 서로 다르다(s는 구형, p는 아령)는 점을 놓친 경우다. 오비탈 모양 감각이 없으면 전자 배치와 결합의 방향성을 이해하기 어렵다.", "fix": "오비탈을 's는 구형, p는 아령'처럼 모양으로 구분한다. s·p·d·f의 모양 차이를 전자 배치·결합의 방향성과 이어 두라.", "cite": ""}, "CH1-123": {"name": "전이 에너지", "course": "ch1", "unit": "Ⅱ-2-d", "tier": "C", "mis": ["차이만큼 주고받는다.", "에너지와 파장은 반비례한다.", "준위 차이에 따라 다르다."], "dx": "전이 때 두 준위의 에너지 차만큼 빛을 주고받고 에너지와 파장이 반비례한다는 점을 놓친 경우다. 이 관계가 약하면 스펙트럼선과 에너지·파장을 잇는 계산이 어긋난다.", "fix": "'전이 때 두 준위 차만큼 빛을 주고받고, 에너지와 파장은 반비례'로 못 박는다. 준위 차에서 파장을 구하는 계산으로 스펙트럼선과 이어라.", "cite": ""}, "CH1-124": {"name": "부껍질", "course": "ch1", "unit": "Ⅱ-2-d", "tier": "C", "mis": ["s < p < d < f로 갈린다.", "주껍질 내부의 구분이다.", "세부 준위로 나뉜다."], "dx": "주껍질이 s·p·d·f 부껍질로 갈리고 에너지가 s<p<d<f라는 점을 놓친 경우다. 부껍질 구분이 약하면 전자가 어느 순서로 채워지는지(쌓음)를 잡지 못한다.", "fix": "주껍질이 's·p·d·f 부껍질로 갈리고 에너지가 s<p<d<f'임을 못 박는다. 이 순서를 전자가 채워지는 쌓음 순서의 바탕으로 삼아라.", "cite": ""}, "CH1-125": {"name": "주양자수", "course": "ch1", "unit": "Ⅱ-2-d", "tier": "C", "mis": ["0은 될 수 없다.", "바깥 껍질일수록 에너지가 높다.", "모양이 아니라 껍질 번호이다."], "dx": "주양자수 n을 0도 될 수 있다고 보거나 모양을 정하는 수로 오해한 경우다. n이 1 이상의 껍질 번호이고 클수록 에너지가 높다는 점이 흔들리면 준위 구조가 어긋난다.", "fix": "주양자수 n을 '1 이상의 껍질 번호이고 클수록 에너지가 높음'으로 못 박는다(0 불가, 모양 정하는 수 아님). n으로 준위 구조를 잡아라.", "cite": ""}, "CH1-126": {"name": "바닥·들뜬상태", "course": "ch1", "unit": "Ⅱ-2-d", "tier": "C", "mis": ["흡수하면 들뜬상태로 올라간다.", "에너지가 더 낮다.", "가장 낮은 준위이다."], "dx": "에너지를 흡수하면 들뜬상태로 올라가고 들뜬상태가 바닥상태보다 에너지가 높다는 점을 놓친 경우다. 흡수·방출과 높낮이가 흔들리면 전이와 전자 배치 해석이 어긋난다.", "fix": "'에너지를 흡수하면 들뜬상태로 올라가고 들뜬상태가 바닥상태보다 높다'를 못 박는다. 흡수·방출과 높낮이를 전이·배치 해석에 써라.", "cite": ""}, "CH1-127": {"name": "오비탈 전자수", "course": "ch1", "unit": "Ⅱ-3", "tier": "A", "mis": ["파울리 배타원리 때문이다.", "2개로 제한된다.", "한 오비탈은 2개이다.", "스핀 반대인 2개까지이다.", "6개는 p 부껍질 전체이다."], "dx": "한 오비탈에 전자가 스핀 반대인 최대 2개만 들어간다는 점을 놓친 경우다(6개는 오비탈이 아니라 p 부껍질 전체). 오비탈 정원이 흔들리면 전자 배치의 칸 수가 통째로 어긋난다.", "fix": "'한 오비탈엔 스핀 반대인 전자 최대 2개'를 못 박는다(6개는 오비탈 아니라 p 부껍질 전체). 오비탈 칸마다 2개씩 채워 배치의 칸 수를 맞춰라.", "cite": ""}, "CH1-128": {"name": "오비탈 수", "course": "ch1", "unit": "Ⅱ-3", "tier": "C", "mis": ["s는 1개, p는 3개이다.", "d 부껍질은 5개이다.", "p 부껍질은 3개이다."], "dx": "부껍질별 오비탈 수가 s 1·p 3·d 5·f 7개라는 점을 놓친 경우다. 오비탈 수가 흔들리면 부껍질 최대 전자 수(오비탈 수 × 2)가 따라서 어긋난다.", "fix": "부껍질별 오비탈 수를 's 1, p 3, d 5, f 7'로 못 박는다. 이 수에 2를 곱해 부껍질 최대 전자 수가 나옴을 이어 셈하라.", "cite": ""}, "CH1-129": {"name": "부껍질 전자수", "course": "ch1", "unit": "Ⅱ-3", "tier": "A", "mis": ["오비탈 1개 × 2개이다.", "오비탈 3개 × 2개이다.", "오비탈 5개 × 2개이다.", "오비탈 7개 × 2개이다."], "dx": "부껍질 최대 전자 수를 (오비탈 수 × 2)로 셈하지 못한 경우다. s 2·p 6·d 10이라는 정원이 흔들리면 전자 배치에서 어디까지 채울지를 잘못 잡는다.", "fix": "부껍질 최대 전자 수를 '오비탈 수 × 2 = s 2, p 6, d 10'으로 못 박는다. 이 정원으로 전자 배치에서 어디까지 채울지 잡아라.", "cite": ""}, "CH1-130": {"name": "껍질 최대 전자수", "course": "ch1", "unit": "Ⅱ-3", "tier": "A", "mis": ["2 × 3² = 18이다.", "2 × 2² = 8이다.", "2 × 1² = 2이다.", "2 × 4² = 32이다.", "2, 8, 18, 32로 다르다."], "dx": "n번째 껍질 최대 전자 수가 2n²(2·8·18·32)이라는 점을 놓친 경우다. 이 공식이 약하면 주기율표의 주기 길이가 왜 그렇게 되는지 설명하지 못한다.", "fix": "n번째 껍질 최대 전자 수를 '2n² = 2, 8, 18, 32'로 못 박는다. 이 값이 주기율표의 주기 길이를 정함을 이어 짚어라.", "cite": ""}, "CH1-131": {"name": "쌓음 원리", "course": "ch1", "unit": "Ⅱ-3", "tier": "C", "mis": ["낮은 것부터이다.", "안쪽부터 채운다.", "순서가 정해져 있다."], "dx": "전자가 에너지가 낮은 오비탈부터 차례로 채워진다는 쌓음 원리를 놓친 경우다(안쪽부터가 아니라 에너지 순). 이 순서가 흔들리면 전자 배치 자체가 어긋난다.", "fix": "쌓음 원리를 '에너지가 낮은 오비탈부터 차례로 채움(안쪽 순이 아니라 에너지 순)'으로 못 박는다. 에너지 순서대로 전자를 채워 배치를 잡아라.", "cite": ""}, "CH1-132": {"name": "오비탈 에너지 순서", "course": "ch1", "unit": "Ⅱ-3", "tier": "A", "mis": ["s가 가장 낮다.", "4s가 먼저 채워진다.", "4s가 에너지가 더 낮다.", "부껍질도 영향을 준다."], "dx": "다전자 원자에서 4s가 3d보다 에너지가 낮아 먼저 채워진다는 순서를 놓친 경우다. 껍질 번호만 보고 채우면 전이 금속 영역의 전자 배치가 어긋난다.", "fix": "다전자 원자에서 '4s가 3d보다 낮아 먼저 채워진다'를 못 박는다. 껍질 번호만 보지 말고 이 순서로 전이 금속 영역을 채워라.", "cite": ""}, "CH1-133": {"name": "파울리 배타원리", "course": "ch1", "unit": "Ⅱ-3", "tier": "A", "mis": ["같은 상태가 될 수 없다.", "스핀이 달라야 한다.", "파울리 배타원리 때문이다.", "스핀이 둘뿐이다."], "dx": "한 오비탈의 두 전자가 스핀이 반대여야 한다(같은 상태 불가)는 파울리 배타원리를 놓친 경우다. 이 원리가 흔들리면 오비탈에 왜 2개까지만 들어가는지 근거가 사라진다.", "fix": "파울리 배타원리를 '한 오비탈의 두 전자는 스핀이 반대여야 함(같은 상태 불가)'으로 못 박는다. 그래서 오비탈에 2개까지만 들어감을 근거로 삼아라.", "cite": ""}, "CH1-134": {"name": "훈트 규칙", "course": "ch1", "unit": "Ⅱ-3", "tier": "B", "mis": ["홀전자를 최대로 한다.", "평행 스핀이 안정하다.", "전자 반발을 줄인다.", "홀전자를 먼저 만든다."], "dx": "같은 에너지 오비탈에 전자가 먼저 하나씩 평행 스핀으로 들어간다(홀전자 최대)는 훈트 규칙을 놓친 경우다. 이걸 어기면 홀전자 수를 잘못 세고, 그 위에 선 자기성 판단이 어긋난다.", "fix": "훈트 규칙을 '같은 에너지 오비탈엔 먼저 하나씩 평행 스핀으로 채움(홀전자 최대)'으로 못 박는다. 2p⁴ 등을 직접 채워 홀전자 수를 바로 세라.", "cite": ""}, "CH1-135": {"name": "전자 배치 표기", "course": "ch1", "unit": "Ⅱ-3", "tier": "B", "mis": ["전자가 8개이다.", "전자가 6개이다.", "전자가 10개이다.", "전자가 11개라 3s¹이 더해진다."], "dx": "전자 배치 표기(1s²2s²…)의 지수로 전자 수를 읽어내는 게 흔들린 경우다. 표기 해석이 약하면 원자·이온의 전자 수와 배치를 잘못 잡는다.", "fix": "전자 배치 표기(1s²2s²…)에서 '지수가 곧 그 오비탈의 전자 수'임을 못 박는다. 지수를 더해 원자·이온의 전자 수를 읽어 내라.", "cite": ""}, "CH1-136": {"name": "원자가전자", "course": "ch1", "unit": "Ⅱ-3", "tier": "C", "mis": ["최외각 전자이다.", "결합하지 않는다."], "dx": "원자가전자가 결합에 관여하는 가장 바깥 껍질 전자라는 점을 놓친 경우다. 원자가전자를 못 짚으면 결합 수·족 판정·반응성 예측이 줄줄이 막힌다.", "fix": "원자가전자를 '결합에 관여하는 가장 바깥 껍질 전자'로 못 박는다. 이를 짚어 결합 수·족 판정·반응성의 출발로 삼아라.", "cite": ""}, "CH1-137": {"name": "홀전자", "course": "ch1", "unit": "Ⅱ-3", "tier": "C", "mis": ["2p³이 각각 하나씩이다.", "2p⁴에서 2개가 홀전자이다.", "2p²가 하나씩 채워진다."], "dx": "전자 배치에서 짝을 못 이룬 홀전자 수를 잘못 센 경우다(2p³은 3개, 2p⁴는 2개). 훈트 규칙대로 채우지 못하면 홀전자 수가 어긋나 자기성·결합 해석이 틀어진다.", "fix": "홀전자를 '짝을 못 이룬 전자'로 잡고 훈트 규칙대로 채워 센다. 2p³은 3개, 2p⁴는 2개처럼 직접 채워 홀전자 수를 확인하라.", "cite": ""}, "CH1-138": {"name": "바닥상태", "course": "ch1", "unit": "Ⅱ-3", "tier": "C", "mis": ["세 규칙을 모두 따른다.", "가장 안정하다."], "dx": "바닥상태 전자 배치가 쌓음·파울리·훈트 세 규칙을 모두 따르는 가장 안정한 배치라는 점을 놓친 경우다. 세 규칙을 함께 적용하지 못하면 어떤 배치가 바닥상태인지 가리지 못한다.", "fix": "바닥상태 배치를 '쌓음·파울리·훈트 세 규칙을 모두 따르는 가장 안정한 배치'로 못 박는다. 세 규칙을 함께 적용해 바닥상태인지 가려라.", "cite": ""}, "CH1-139": {"name": "들뜬상태", "course": "ch1", "unit": "Ⅱ-3", "tier": "C", "mis": ["에너지가 더 높다.", "에너지를 흡수했다.", "낮은 오비탈을 건너뛴다."], "dx": "들뜬상태가 전자가 에너지를 흡수해 더 높은 오비탈로 올라간(낮은 칸을 건너뛴) 상태라는 점을 놓친 경우다. 바닥상태와의 차이가 흐리면 들뜬 배치를 잘못 판정한다.", "fix": "들뜬상태를 '전자가 에너지를 흡수해 더 높은 오비탈로 올라간(낮은 칸을 건너뛴) 상태'로 못 박는다. 바닥상태와 비교해 들뜬 배치를 판정하라.", "cite": ""}, "CH1-140": {"name": "전자수 세기", "course": "ch1", "unit": "Ⅱ-3", "tier": "C", "mis": ["2+2+6+1 = 11이다.", "2+2+6 = 10이다.", "2+2+4 = 8이다."], "dx": "전자 배치 지수의 합으로 전체 전자 수를 세는 게 흔들린 경우다. 합산이 어긋나면 그 배치가 어느 원소(원자번호)인지부터 틀어진다.", "fix": "전체 전자 수를 '전자 배치 지수의 합'으로 센다. 합이 곧 원자번호임을, 배치에서 원소를 알아내는 데 써라.", "cite": ""}, "CH1-141": {"name": "가려막기", "course": "ch1", "unit": "Ⅱ-3", "tier": "C", "mis": ["인력을 가린다.", "가리는 전자가 많아야 한다.", "인력을 약화한다."], "dx": "안쪽 전자가 핵의 인력을 일부 가려 바깥 전자가 느끼는 인력을 줄인다는 가려막기를 놓친 경우다. 이 개념이 약하면 유효핵전하, 나아가 원자 반지름·이온화 에너지의 주기성을 설명하지 못한다.", "fix": "가려막기를 '안쪽 전자가 핵 인력을 일부 가려 바깥 전자가 느끼는 인력을 줄임'으로 못 박는다. 이를 유효핵전하·반지름·이온화 에너지 주기성의 바탕으로 삼아라.", "cite": ""}, "CH1-142": {"name": "유효핵전하", "course": "ch1", "unit": "Ⅱ-3", "tier": "A", "mis": ["양성자가 늘어난다.", "안쪽 전자가 가린다.", "인력이 더 가려진다.", "전자를 더 강하게 당긴다."], "dx": "유효핵전하를 핵전하에서 가려막기를 뺀 '전자가 실제로 느끼는 (+)전하'로 잡지 못한 경우다. 양성자 수만 보고 가려막기를 빼먹으면 반지름·이온화 에너지·전기음성도의 주기성이 통째로 어긋난다.", "fix": "유효핵전하를 '핵전하 − 가려막기 = 전자가 실제로 느끼는 (+)전하'로 못 박는다. 양성자 수만 보지 말고 가려막기를 빼, 반지름·이온화 에너지·전기음성도 주기성을 풀어라.", "cite": ""}, "CH1-143": {"name": "전자 반발", "course": "ch1", "unit": "Ⅱ-3", "tier": "C", "mis": ["같은 (-)전하끼리 밀어낸다.", "같은 전하끼리 밀어낸다.", "인력을 가린다."], "dx": "같은 (−)전하인 전자끼리 서로 밀어낸다는 전자 반발을 놓친 경우다. 이 반발이 약하면 훈트 규칙(홀전자를 먼저 만들어 반발을 줄임)의 이유를 못 짚는다.", "fix": "전자 반발을 '같은 (−)전하인 전자끼리 서로 밀어냄'으로 못 박는다. 그래서 훈트 규칙이 홀전자를 먼저 만들어 반발을 줄임을 이어 짚어라.", "cite": ""}, "CH1-144": {"name": "주기 구조", "course": "ch1", "unit": "Ⅱ-4", "tier": "C", "mis": ["원자가전자는 족이 결정한다.", "세로줄은 족이다.", "같은 족이 원자가전자가 같다."], "dx": "주기율표에서 무엇이 무엇을 정하는지를 뒤섞은 경우다. 세로줄 족이 원자가전자 수를, 가로줄 주기가 껍질 수를 정한다는 두 축이 흔들리면 주기성·결합 예측의 토대가 무너진다.", "fix": "주기율표를 '세로 족 = 원자가전자 수, 가로 주기 = 껍질 수' 두 축으로 못 박는다. 임의 원소의 위치에서 두 값을 읽어 주기성·결합 예측의 토대로 삼아라.", "cite": ""}, "CH1-145": {"name": "족 성질", "course": "ch1", "unit": "Ⅱ-4", "tier": "C", "mis": ["주기가 껍질 수를 결정한다.", "원자가전자가 같다.", "족이 원자가전자를 결정한다."], "dx": "같은 족이 원자가전자 수가 같아 화학적 성질이 비슷하다는 연결을 놓친 경우다. 족이 성질을 묶는다는 점이 약하면 한 원소로 같은 족 거동을 유추하지 못한다.", "fix": "'같은 족은 원자가전자 수가 같아 화학적 성질이 비슷'함을 못 박는다. 한 원소의 거동으로 같은 족 다른 원소를 유추해 보며 굳혀라.", "cite": ""}, "CH1-146": {"name": "유효핵전하 주기성", "course": "ch1", "unit": "Ⅱ-4", "tier": "C", "mis": ["양성자가 늘어난다.", "껍질 수 증가가 더 크다."], "dx": "유효핵전하가 같은 주기에서 오른쪽으로 갈수록 커지는 까닭(가려막기는 비슷한데 양성자만 늘어남)을 놓친 경우다. 이 한 엔진이 흔들리면 반지름·이온화 에너지·전기음성도의 주기성이 줄줄이 어긋난다.", "fix": "'같은 주기 오른쪽으로 갈수록 유효핵전하 증가(가려막기는 비슷, 양성자만 늘어남)'를 하나의 엔진으로 못 박는다. 이 엔진에서 반지름·이온화 에너지·전기음성도 주기성이 모두 나옴을 짚어라.", "cite": ""}, "CH1-147": {"name": "원자 반지름", "course": "ch1", "unit": "Ⅱ-4", "tier": "A", "mis": ["유효핵전하가 커진다.", "껍질 수가 늘어난다.", "같은 주기에서 Mg이 오른쪽이다.", "껍질 수가 적어진다."], "dx": "원자 반지름이 같은 주기에서 오른쪽으로 작아지고(유효핵전하 증가) 같은 족에서 아래로 커진다(껍질 증가)는 두 방향을 놓친 경우다. 두 경향의 원인을 못 잡으면 이온 반지름·결합 길이 비교가 어긋난다.", "fix": "원자 반지름을 '주기 오른쪽으로 작아짐(유효핵전하 증가), 족 아래로 커짐(껍질 증가)' 두 방향으로 못 박는다. 두 원인을 적어 이온 반지름·결합 길이 비교에 써라.", "cite": ""}, "CH1-148": {"name": "이온 반지름", "course": "ch1", "unit": "Ⅱ-4", "tier": "C", "mis": ["전자를 잃었다.", "전자를 얻어 반발이 커진다.", "이온 종류에 따라 다르다."], "dx": "양이온은 전자를 잃어 작아지고 음이온은 전자를 얻어 반발이 커져 커진다는 점을 놓친 경우다. 전자 수 변화가 반지름을 바꾼다는 감각이 없으면 이온 크기 비교가 어긋난다.", "fix": "'양이온은 전자를 잃어 작아지고, 음이온은 전자를 얻어 반발이 커져 커진다'를 못 박는다. 전자 수 변화로 크기 변화를 잡아 원자와 그 이온을 비교하라.", "cite": ""}, "CH1-149": {"name": "등전자 이온", "course": "ch1", "unit": "Ⅱ-4", "tier": "C", "mis": ["양성자가 전자를 더 당긴다.", "양성자 수가 인력을 정한다.", "전자를 더 강하게 당긴다."], "dx": "전자 수가 같은(등전자) 이온은 양성자가 많을수록 전자를 더 세게 당겨 작아진다는 점을 놓친 경우다. 같은 전자 수에서 양성자 수가 크기를 가른다는 기준이 약하면 등전자 비교가 막힌다.", "fix": "등전자 이온은 '양성자가 많을수록 전자를 세게 당겨 작아진다'를 기준으로 삼는다. 전자 수가 같은 이온들을 양성자 수 순으로 늘어놓고 크기를 비교하라.", "cite": ""}, "CH1-150": {"name": "이온화 에너지", "course": "ch1", "unit": "Ⅱ-4", "tier": "C", "mis": ["반지름이 커져 전자를 떼기 쉽다.", "전자를 떼는 흡열 과정이다.", "더 큰 에너지가 필요하다."], "dx": "이온화 에너지가 기체 원자에서 전자를 떼는 데 드는 흡열 에너지라는 정의를 놓친 경우다. 반지름이 클수록(핵에서 멀수록) 떼기 쉬워 작다는 연결까지 잡아야 주기성으로 이어진다.", "fix": "이온화 에너지를 '기체 원자에서 전자를 떼는 데 드는 흡열 에너지'로 못 박는다. 반지름이 커 핵에서 멀수록 떼기 쉬워 작아짐을 주기성으로 이어라.", "cite": ""}, "CH1-151": {"name": "이온화 에너지 주기성", "course": "ch1", "unit": "Ⅱ-4", "tier": "A", "mis": ["반지름이 커져 전자를 떼기 쉽다.", "반지름이 커진다.", "유효핵전하가 커진다.", "안정한 전자 배치이다.", "전자가 핵에서 멀어진다.", "전자 1개를 잃기 쉽다."], "dx": "이온화 에너지가 같은 주기에서 오른쪽으로 커지고(유효핵전하 증가) 같은 족에서 아래로 작아진다(반지름 증가)는 방향을 놓친 경우다. 이 경향이 흔들리면 금속성·반응성 예측이 어긋난다.", "fix": "이온화 에너지를 '주기 오른쪽으로 커짐(유효핵전하), 족 아래로 작아짐(반지름 증가)'으로 못 박는다. 이 방향으로 금속성·반응성을 예측하라.", "cite": ""}, "CH1-152": {"name": "순차 이온화 에너지", "course": "ch1", "unit": "Ⅱ-4", "tier": "C", "mis": ["전자를 뗄수록 떼기 어렵다.", "E1 < E2 < E3이다.", "안쪽 껍질로 넘어가는 지점이다."], "dx": "전자를 뗄수록 떼기 어려워 순차 이온화 에너지가 E₁<E₂<E₃로 커지고, 값이 급증하는 지점이 안쪽 껍질로 넘어가는 자리라는 점을 놓친 경우다. 이 급증을 못 읽으면 원자가전자 수를 알아내지 못한다.", "fix": "순차 이온화 에너지가 'E₁<E₂<E₃로 커지고 값이 급증하는 자리가 안쪽 껍질로 넘어가는 지점'임을 못 박는다. 급증 직전까지의 전자 수가 원자가전자 수임을 직접 읽어라.", "cite": ""}, "CH1-153": {"name": "전기음성도", "course": "ch1", "unit": "Ⅱ-4", "tier": "C", "mis": ["그것은 이온화 에너지이다.", "당기는 세기가 크다.", "유효핵전하가 커진다."], "dx": "전기음성도를 이온화 에너지와 뒤섞은 경우다. 전기음성도가 '결합에서 공유 전자쌍을 끌어당기는 세기'라는 정의를 놓치면 결합 극성·분자 극성 판단이 어긋난다.", "fix": "전기음성도를 '결합에서 공유 전자쌍을 끌어당기는 세기'로 못 박는다(이온화 에너지와 구분). 이 세기로 결합 극성·분자 극성을 판단하라.", "cite": ""}, "CH1-154": {"name": "전기음성도 주기성", "course": "ch1", "unit": "Ⅱ-4", "tier": "B", "mis": ["원자 반지름이 커진다.", "유효핵전하가 커진다.", "주기성이 있다."], "dx": "전기음성도가 같은 주기에서 오른쪽으로 커지고 같은 족에서 아래로 작아진다는 방향을 놓친 경우다. 이 경향이 흔들리면 두 원자 중 누가 전자쌍을 당기는지(결합 극성)를 못 가른다.", "fix": "전기음성도를 '주기 오른쪽으로 커짐, 족 아래로 작아짐'으로 못 박는다. 두 원자 중 누가 전자쌍을 더 당기는지(결합 극성)를 이 방향으로 가려라.", "cite": ""}, "CH1-155": {"name": "전기음성도 최대", "course": "ch1", "unit": "Ⅱ-4", "tier": "A", "mis": ["산소는 플루오린 다음이다.", "세슘은 매우 작다.", "비금속이 전자를 당긴다.", "비금속성이 큰 쪽이다.", "최대이다.", "전자를 강하게 당긴다."], "dx": "전기음성도가 플루오린(F)에서 최대이고 산소가 그다음, 세슘 같은 금속은 매우 작다는 순위를 놓친 경우다. 최대·최소 기준이 흐리면 어떤 결합이 더 극성인지 비교가 어긋난다.", "fix": "전기음성도를 '플루오린(F) 최대, 산소가 그다음, 세슘 같은 금속은 매우 작음'으로 기준점을 못 박는다. 이 순위로 어느 결합이 더 극성인지 비교하라.", "cite": ""}, "CH1-156": {"name": "금속성", "course": "ch1", "unit": "Ⅱ-4", "tier": "C", "mis": ["오른쪽 위는 비금속성이다.", "양이온이 되려 한다.", "전자를 잃기 쉽다."], "dx": "금속성이 전자를 잃어 양이온이 되려는 성질이고 주기율표 왼쪽 아래에서 크다는 점을 놓친 경우다. 금속성의 방향이 흐리면 이온 형성·결합 종류 판정이 어긋난다.", "fix": "금속성을 '전자를 잃어 양이온이 되려는 성질, 주기율표 왼쪽 아래에서 큼'으로 못 박는다. 이 방향으로 이온 형성·결합 종류를 판정하라.", "cite": ""}, "CH1-157": {"name": "비금속성", "course": "ch1", "unit": "Ⅱ-4", "tier": "C", "mis": ["왼쪽 아래는 금속성이다.", "음이온이 되려 한다.", "전자쌍을 강하게 당긴다."], "dx": "비금속성이 전자를 얻어 음이온이 되고 전자쌍을 강하게 당기는 성질이며 오른쪽 위에서 크다는 점을 놓친 경우다. 비금속성의 방향이 흐리면 결합 극성·음이온 형성 판단이 어긋난다.", "fix": "비금속성을 '전자를 얻어 음이온이 되고 전자쌍을 강하게 당기는 성질, 오른쪽 위에서 큼'으로 못 박는다. 이 방향으로 결합 극성·음이온 형성을 판단하라.", "cite": ""}, "CH1-158": {"name": "알칼리 금속", "course": "ch1", "unit": "Ⅱ-4", "tier": "C", "mis": ["이온화 에너지가 작아진다.", "전자를 잃기 쉽다.", "금속이라 전자를 잃는다."], "dx": "알칼리 금속이 원자가전자 1개라 전자를 잃기 쉽고 아래로 갈수록 이온화 에너지가 작아져 더 잘 잃는다는 점을 놓친 경우다. 이 경향이 약하면 1족 반응성 순서를 못 잡는다.", "fix": "알칼리 금속을 '원자가전자 1개라 전자를 잃기 쉽고, 아래로 갈수록 이온화 에너지가 작아 더 잘 잃음'으로 못 박는다. 1족을 위아래로 늘어놓고 반응성 순서를 잡아라.", "cite": ""}, "CH1-159": {"name": "할로젠", "course": "ch1", "unit": "Ⅱ-4", "tier": "B", "mis": ["전자를 얻는 힘이 약해진다.", "비금속이라 전자를 얻는다.", "위쪽이 반응성이 크다."], "dx": "할로젠이 전자 1개를 얻어 음이온이 되기 쉽고 아래로 갈수록 그 힘이 약해진다(위쪽이 더 반응성)는 점을 놓친 경우다. 이 경향이 흔들리면 17족 반응성 순서가 어긋난다.", "fix": "할로젠을 '전자 1개를 얻어 음이온이 되기 쉽고, 아래로 갈수록 그 힘이 약해짐(위쪽이 더 반응성)'으로 못 박는다. 17족 반응성 순서를 위아래로 가려라.", "cite": ""}, "CH1-160": {"name": "비활성 기체", "course": "ch1", "unit": "Ⅱ-4", "tier": "C", "mis": ["전자 배치가 안정하다.", "이온화 에너지가 크다.", "안정한 배치이다."], "dx": "비활성 기체가 안정한 전자 배치(옥텟)라 반응성이 작고 이온화 에너지가 크다는 점을 놓친 경우다. 이 안정 배치가 다른 원자들이 결합으로 닮으려는 목표라는 다음 개념과 직결된다.", "fix": "비활성 기체를 '안정한 옥텟 배치라 반응성이 작고 이온화 에너지가 큼'으로 못 박는다. 이 안정 배치가 다른 원자들이 결합으로 닮으려는 목표임을 이어 짚어라.", "cite": ""}, "CH1-161": {"name": "전자 친화도", "course": "ch1", "unit": "Ⅱ-4", "tier": "C", "mis": ["이온화 에너지와 다르다.", "음이온이 되기 쉽다.", "비금속이 전자를 얻으려 한다."], "dx": "전자 친화도를 이온화 에너지와 헷갈린 경우다. 전자 친화도가 '원자가 전자를 얻을 때의 에너지 변화'라는 점을 놓치면 비금속이 왜 음이온이 되기 쉬운지 설명이 막힌다.", "fix": "전자 친화도를 '원자가 전자를 얻을 때의 에너지 변화'로 못 박는다(이온화 에너지와 구분). 이로써 비금속이 음이온이 되기 쉬운 까닭을 설명하라.", "cite": ""}, "CH1-162": {"name": "금속 이온화", "course": "ch1", "unit": "Ⅱ-4", "tier": "C", "mis": ["양이온이 되기 쉽다.", "전자를 잃으려 한다.", "전자를 잃기 쉽다."], "dx": "금속이 이온화 에너지가 작아 전자를 잃고 양이온이 되기 쉽다는 점을 놓친 경우다. 이 경향이 약하면 금속이 이온 결합에서 양이온이 되는 까닭을 못 짚는다.", "fix": "금속을 '이온화 에너지가 작아 전자를 잃고 양이온이 되기 쉬움'으로 못 박는다. 그래서 이온결합에서 금속이 양이온이 됨을 이어 짚어라.", "cite": ""}, "CH1-163": {"name": "비금속 전기음성도", "course": "ch1", "unit": "Ⅱ-4", "tier": "C", "mis": ["음이온이 되기 쉽다.", "전자를 얻으려 한다.", "전자를 강하게 당긴다."], "dx": "비금속이 전기음성도가 커 전자를 강하게 당겨 음이온이 되기 쉽다는 점을 놓친 경우다. 이 경향이 약하면 비금속이 이온 결합에서 음이온이 되는 까닭을 못 짚는다.", "fix": "비금속을 '전기음성도가 커 전자를 강하게 당겨 음이온이 되기 쉬움'으로 못 박는다. 그래서 이온결합에서 비금속이 음이온이 됨을 이어 짚어라.", "cite": ""}, "CH1-164": {"name": "이온화 에너지 비교", "course": "ch1", "unit": "Ⅱ-4", "tier": "C", "mis": ["Mg이 오른쪽이다.", "1족은 가장 작다.", "Li이 위에 있다."], "dx": "주기율표 위치로 이온화 에너지를 비교하는 게 흔들린 경우다(오른쪽·위일수록 큼, 1족이 가장 작음). 위치 감각이 약하면 두 원소 중 누가 전자를 더 잘 잃는지 못 가린다.", "fix": "이온화 에너지를 '주기율표 오른쪽·위일수록 크고 1족이 가장 작음'으로 비교한다. 두 원소의 위치로 누가 전자를 더 잘 잃는지 가려라.", "cite": ""}, "CH1-165": {"name": "전기음성도 비교", "course": "ch1", "unit": "Ⅱ-4", "tier": "C", "mis": ["F가 위에 있다.", "O가 위에 있다.", "위쪽이 전자쌍을 더 당긴다."], "dx": "주기율표 위치로 전기음성도를 비교하는 게 흔들린 경우다(오른쪽·위일수록 큼, F가 위). 비교가 약하면 결합에서 어느 쪽이 부분 음전하인지 못 정한다.", "fix": "전기음성도를 '오른쪽·위일수록 크고 F가 가장 큼'으로 비교한다. 결합에서 어느 원자가 부분 음전하인지 위치로 정하라.", "cite": ""}, "CH1-166": {"name": "원자 반지름 비교", "course": "ch1", "unit": "Ⅱ-4", "tier": "C", "mis": ["S가 아래에 있다.", "Na가 같은 주기 왼쪽이다.", "아래쪽이 껍질 수가 많다."], "dx": "주기율표 위치로 원자 반지름을 비교하는 게 흔들린 경우다(왼쪽·아래일수록 큼). 비교가 약하면 결합 길이·이온 크기 문제에서 어긋난다.", "fix": "원자 반지름을 '주기율표 왼쪽·아래일수록 큼'으로 비교한다. 위치로 결합 길이·이온 크기 문제를 풀어라.", "cite": ""}, "CH1-167": {"name": "결합 형성 이유", "course": "ch1", "unit": "Ⅱ-5", "tier": "C", "mis": ["안정한 배치를 향한다.", "안정해진다.", "이미 안정하다."], "dx": "원자가 비활성 기체 같은 안정한 전자 배치에 이르려 결합한다는 동기를 놓친 경우다. 결합이 '안정해지려는 것'이라는 이유가 약하면 이온·공유 결합의 형성을 통째로 설명하지 못한다.", "fix": "결합의 동기를 '비활성 기체 같은 안정한 전자 배치에 이르려는 것'으로 못 박는다. 이 이유에서 이온·공유 결합이 모두 나옴을 짚어라.", "cite": ""}, "CH1-168": {"name": "결합과 에너지", "course": "ch1", "unit": "Ⅱ-5", "tier": "C", "mis": ["발열 과정이다.", "흡열 과정이다.", "발열로 안정해진다."], "dx": "결합 형성을 흡열로 본 경우다. 결합이 만들어질 때 에너지를 방출해(발열) 더 안정해진다는 점을 놓치면 결합 에너지 부호와 안정성 논리가 뒤집힌다.", "fix": "'결합이 만들어질 때 에너지를 방출해(발열) 더 안정해진다'를 못 박는다(흡열 아님). 결합 에너지 부호와 안정성을 이 방향으로 잡아라.", "cite": ""}, "CH1-169": {"name": "이온결합", "course": "ch1", "unit": "Ⅱ-5", "tier": "C", "mis": ["비금속끼리는 공유결합이다.", "전자쌍 공유는 공유결합이다.", "반대 전하끼리 끌린다."], "dx": "이온결합이 금속이 잃고 비금속이 얻어 생긴 반대 전하 이온의 정전기적 인력이라는 점을 놓친 경우다. 이 정의가 흐리면 이온 결정의 구조·성질로 이어지지 못한다.", "fix": "이온결합을 '금속이 잃고 비금속이 얻어 생긴 반대 전하 이온의 정전기적 인력'으로 못 박는다. 이 정의에서 이온 결정의 구조·성질로 이어라.", "cite": ""}, "CH1-170": {"name": "공유결합", "course": "ch1", "unit": "Ⅱ-5", "tier": "C", "mis": ["금속-비금속은 이온결합이다.", "전자를 완전히 주고받는 것은 이온결합이다.", "공유하기 때문이다."], "dx": "공유결합이 비금속끼리 전자쌍을 '공유'하는 결합이라는 점을, 전자를 주고받는 이온결합과 헷갈려 놓친 경우다. 공유와 이동의 구분이 약하면 분자 개념·결합 종류 판정이 어긋난다.", "fix": "공유결합을 '비금속끼리 전자쌍을 공유하는 결합'으로 못 박는다(전자를 주고받는 이온결합과 구분). 공유와 이동을 갈라 결합 종류를 판정하라.", "cite": ""}, "CH1-171": {"name": "금속결합", "course": "ch1", "unit": "Ⅱ-5", "tier": "B", "mis": ["음이온이 아니라 자유전자이다.", "전자쌍 공유는 공유결합이다.", "금속-비금속은 이온결합이다.", "금속결합의 핵심이다."], "dx": "금속결합을 양이온과 자유전자(전자 바다) 사이의 결합으로 보지 못하고 음이온 등으로 오해한 경우다. 자유전자라는 핵심이 흔들리면 금속의 전도성·전성·연성이 설명되지 않는다.", "fix": "금속결합을 '양이온과 자유전자(전자 바다) 사이의 결합'으로 못 박는다. 자유전자라는 핵심에서 전도성·전성·연성이 나옴을 짚어라.", "cite": ""}, "CH1-172": {"name": "이온결정", "course": "ch1", "unit": "Ⅱ-5", "tier": "C", "mis": ["독립된 분자가 없다.", "분자가 아니다.", "분자가 없기 때문이다."], "dx": "이온결정에 독립된 분자가 있다고 본 경우다. 이온이 격자로 무한히 이어져 독립 분자가 없다는 점을 놓치면 이온 화합물을 분자식으로 잘못 쓴다.", "fix": "이온결정을 '이온이 격자로 무한히 이어져 독립 분자가 없음'으로 못 박는다. 그래서 이온 화합물은 분자식이 아니라 실험식으로 씀을 확인하라.", "cite": ""}, "CH1-173": {"name": "공유결합 종류", "course": "ch1", "unit": "Ⅱ-5", "tier": "C", "mis": ["전자쌍 3개를 공유한다.", "단일 결합이 1개이다.", "전자쌍 2개를 공유한다."], "dx": "공유결합을 공유 전자쌍 수(단일 1·이중 2·삼중 3쌍)로 가리는 게 흔들린 경우다. 결합 차수를 잘못 세면 결합 길이·세기, 나아가 분자 구조 판정이 어긋난다.", "fix": "공유결합을 '공유 전자쌍 수(단일 1·이중 2·삼중 3쌍)'로 가린다. 결합 차수를 바로 세어 결합 길이·세기·분자 구조 판정에 써라.", "cite": ""}, "CH1-174": {"name": "결합 에너지 곡선", "course": "ch1", "unit": "Ⅱ-5", "tier": "C", "mis": ["핵끼리 밀어낸다.", "가장 안정한 거리이다.", "거리에 따라 달라진다."], "dx": "두 원자가 가까워질 때 인력과 핵 사이 반발이 균형을 이루는 거리에서 에너지가 최소(가장 안정)가 된다는 곡선을 못 읽은 경우다. 이 곡선이 약하면 결합 길이의 의미를 못 짚는다.", "fix": "'두 원자가 가까워질 때 인력과 핵 사이 반발이 균형을 이루는 거리에서 에너지가 최소(가장 안정)'임을 못 박는다. 곡선의 최저점이 결합 길이임을 읽어라.", "cite": ""}, "CH1-175": {"name": "결합 길이", "course": "ch1", "unit": "Ⅱ-5", "tier": "C", "mis": ["가장 안정한 거리이다.", "더 강하게 당긴다.", "결합 차수가 작다."], "dx": "결합 길이가 에너지가 가장 낮은(가장 안정한) 핵 사이 거리이고 결합 차수가 클수록 짧아진다는 점을 놓친 경우다. 이 관계가 약하면 결합 세기·길이 비교가 어긋난다.", "fix": "결합 길이를 '에너지가 가장 낮은 핵 사이 거리이고 결합 차수가 클수록 짧아짐'으로 못 박는다. 단일·이중·삼중을 길이 순으로 비교하라.", "cite": ""}, "CH1-176": {"name": "이온결정 성질", "course": "ch1", "unit": "Ⅱ-5", "tier": "C", "mis": ["같은 전하가 만나 반발한다.", "정전기적 인력이 강하다.", "같은 전하가 반발한다."], "dx": "이온결정이 외력에 층이 밀리면 같은 전하 이온이 만나 반발해 부서진다는 메커니즘을 놓친 경우다(인력이 강해 단단하지만 동시에 잘 쪼개짐). 이 둘을 함께 못 잡으면 이온결정 물성을 설명하지 못한다.", "fix": "이온결정을 '인력이 강해 단단하지만, 층이 밀리면 같은 전하가 만나 반발해 쪼개짐(취성)'으로 두 성질을 함께 잡는다. 단단함과 부서짐을 한 그림으로 새겨라.", "cite": ""}, "CH1-177": {"name": "이온결정 전도성", "course": "ch1", "unit": "Ⅱ-5", "tier": "A", "mis": ["이온이 고정되어 있다.", "이온이 움직이지 못한다.", "이온이 자유롭게 움직인다.", "이온이 이동할 수 있다.", "이온이 자유로워진다."], "dx": "이온결정이 고체에서는 이온이 고정돼 전기가 안 통하고 녹거나 물에 녹으면 이온이 움직여 통한다는 조건 차이를 놓친 경우다. 이 구분이 약하면 전해질·전기분해 단원이 흔들린다.", "fix": "이온결정을 '고체는 이온이 고정돼 안 통하고, 녹거나 물에 녹으면 이온이 움직여 통함'으로 못 박는다. 이 조건 차이를 전해질·전기분해의 출발로 삼아라.", "cite": ""}, "CH1-178": {"name": "금속 전도성", "course": "ch1", "unit": "Ⅱ-5", "tier": "B", "mis": ["자유전자가 있다.", "자유전자가 항상 있다.", "자유전자가 이동한다."], "dx": "금속이 자유전자 덕분에 전기·열을 잘 통한다는 점을 놓친 경우다. 자유전자가 전하를 나른다는 그림이 약하면 금속 전도성·열전도를 설명하지 못한다.", "fix": "금속 전도성을 '자유전자가 전하를 날라 전기·열을 잘 통함'으로 못 박는다. 자유전자가 주체라는 그림을 열전도까지 이어라.", "cite": ""}, "CH1-179": {"name": "금속 성질", "course": "ch1", "unit": "Ⅱ-5", "tier": "C", "mis": ["자유전자가 결합을 유지한다.", "전자가 전하를 운반한다.", "힘을 가하면 모양이 변한다."], "dx": "자유전자가 양이온 사이를 옮겨 다니며 결합을 유지해, 금속이 두드리면 펴지는(전성·연성) 점을 놓친 경우다. 이 메커니즘이 약하면 금속이 왜 깨지지 않고 변형되는지 설명하지 못한다.", "fix": "'자유전자가 양이온 사이를 옮겨 다니며 결합을 유지해 두드리면 펴짐(전성·연성)'을 못 박는다. 이 메커니즘으로 금속이 깨지지 않고 변형됨을 설명하라.", "cite": ""}, "CH1-180": {"name": "공유결정", "course": "ch1", "unit": "Ⅱ-5", "tier": "A", "mis": ["공유결합이 강하다.", "강한 결합을 끊어야 한다.", "원자가 연속적으로 결합한다.", "독립된 분자가 없다."], "dx": "공유결정이 원자들이 그물처럼 연속으로 공유결합해 독립 분자가 없고 녹는점이 매우 높다는 점을 놓친 경우다. 이 구조가 약하면 다이아몬드·석영의 높은 녹는점과 결정 비교가 어긋난다.", "fix": "공유결정을 '원자가 그물처럼 연속으로 공유결합해 독립 분자가 없고 녹는점이 매우 높음'으로 못 박는다. 다이아몬드·석영으로 높은 녹는점과 결정 비교를 확인하라.", "cite": ""}, "CH1-181": {"name": "흑연", "course": "ch1", "unit": "Ⅱ-5", "tier": "C", "mis": ["일부 전자가 자유롭다.", "탄소끼리 공유결합한다.", "다이아몬드엔 자유 전자가 없다."], "dx": "흑연이 탄소끼리 공유결합한 층 구조이고 남은 일부 전자가 자유로워 전기가 통한다(다이아몬드엔 자유전자가 없음)는 점을 놓친 경우다. 이 대비가 약하면 같은 탄소인데 전도성이 갈리는 까닭을 못 짚는다.", "fix": "흑연을 '탄소끼리 공유결합한 층 구조이고 남은 일부 전자가 자유로워 전기가 통함'으로 못 박는다. 다이아몬드엔 자유전자가 없음과 대비해 전도성 차이를 짚어라.", "cite": ""}, "CH1-182": {"name": "분자결정", "course": "ch1", "unit": "Ⅱ-5", "tier": "C", "mis": ["분자 사이 인력이 약하다.", "분자로 이루어진다.", "녹는점이 낮은 이유이다."], "dx": "분자결정이 분자 사이 약한 인력으로 모인 결정이라 녹는점이 낮다는 점을 놓친 경우다. 끊기는 게 결합이 아니라 분자 간 힘이라는 점이 약하면 화학Ⅱ 분자 간 힘 단원이 흔들린다.", "fix": "분자결정을 '분자 사이 약한 인력으로 모인 결정이라 녹는점이 낮음'으로 못 박는다. 끊기는 게 결합이 아니라 분자 간 힘임을 화학Ⅱ로 이어라.", "cite": ""}, "CH1-183": {"name": "분자결정 비교", "course": "ch1", "unit": "Ⅱ-5", "tier": "C", "mis": ["분자 사이 인력이 약하다.", "녹는점이 더 낮다.", "인력이 약하다."], "dx": "분자결정끼리는 분자 간 힘이 약할수록 녹는점이 낮다는 비교를 놓친 경우다. 결정 유형이 같을 땐 분자 간 힘 세기가 녹는점을 가른다는 기준이 약하면 비교가 어긋난다.", "fix": "분자결정끼리는 '분자 간 힘이 약할수록 녹는점이 낮음'으로 비교한다. 결정 유형이 같을 땐 분자 간 힘 세기가 녹는점을 가름을 기준으로 써라.", "cite": ""}, "CH1-184": {"name": "이온결정 녹는점", "course": "ch1", "unit": "Ⅱ-5", "tier": "C", "mis": ["정전기적 인력이 강하다.", "인력이 더 강하다."], "dx": "이온결정이 강한 정전기적 인력 때문에 녹는점이 높다는 점을 놓친 경우다. 인력 세기가 녹는점을 정한다는 감각이 약하면 격자 에너지 비교로 이어지지 못한다.", "fix": "이온결정을 '강한 정전기적 인력 때문에 녹는점이 높음'으로 못 박는다. 인력 세기가 녹는점을 정함을 격자 에너지 비교로 이어라.", "cite": ""}, "CH1-185": {"name": "결합 극성", "course": "ch1", "unit": "Ⅱ-5", "tier": "C", "mis": ["전자쌍이 치우친다.", "전기음성도 차이가 없다.", "전자쌍이 치우치지 않는다."], "dx": "전기음성도 차이가 있으면 공유 전자쌍이 한쪽으로 치우쳐 극성 결합이 된다는 점을 놓친 경우다. 결합 극성을 못 잡으면 다음 단원 분자 극성·쌍극자 판단이 막힌다.", "fix": "'전기음성도 차이가 있으면 공유 전자쌍이 한쪽으로 치우쳐 극성 결합'임을 못 박는다. 결합 극성을 다음 단원 분자 극성·쌍극자의 출발로 삼아라.", "cite": ""}, "CH1-186": {"name": "격자 에너지", "course": "ch1", "unit": "Ⅱ-5", "tier": "A", "mis": ["정전기적 인력이 강하다.", "인력이 강해진다.", "이온 사이 거리가 가까워야 한다.", "강한 결합을 끊어야 한다.", "형성 과정의 에너지이다."], "dx": "격자 에너지가 이온 사이 정전기적 인력이 강할수록(전하가 크고 거리가 가까울수록) 커진다는 점을 놓친 경우다. 이 결정 인자가 약하면 이온결정 녹는점의 정밀 비교가 어긋난다.", "fix": "격자 에너지를 '이온 전하가 크고 이온 사이 거리가 가까울수록 큼'으로 못 박는다. 이 두 인자로 이온결정 녹는점을 정밀 비교하라.", "cite": ""}, "CH1-187": {"name": "이온결합 판정", "course": "ch1", "unit": "Ⅱ-5", "tier": "C", "mis": ["두 비금속의 결합이다.", "전자쌍을 공유한다."], "dx": "금속과 비금속의 조합을 이온결합으로 판정하는 게 흔들린 경우다(두 비금속이면 공유결합). 구성 원소로 결합 종류를 못 가리면 물질의 성질 예측이 막힌다.", "fix": "'금속 + 비금속 = 이온결합, 비금속끼리 = 공유결합'으로 판정한다. 구성 원소를 보고 결합 종류를 가려 성질을 예측하라.", "cite": ""}, "CH1-188": {"name": "이온결정 배열", "course": "ch1", "unit": "Ⅱ-5", "tier": "C", "mis": ["같은 전하는 반발한다.", "규칙적 격자 구조이다.", "반대 전하가 번갈아 배열된다."], "dx": "이온결정이 반대 전하가 번갈아 규칙 배열된 격자(같은 전하는 서로 멀리)라는 점을 놓친 경우다. 배열 규칙이 약하면 이온결정의 구조·안정성을 이해하지 못한다.", "fix": "이온결정을 '반대 전하가 번갈아 규칙 배열된 격자(같은 전하는 서로 멀리)'로 못 박는다. 이 배열이 정전기적으로 안정한 까닭을 짚어라.", "cite": ""}, "CH1-189": {"name": "공유결합 판정", "course": "ch1", "unit": "Ⅱ-5", "tier": "C", "mis": ["두 비금속의 결합이다.", "전자를 주고받는다."], "dx": "두 비금속의 조합을 공유결합으로 판정하는 게 흔들린 경우다(전자를 주고받는 게 아니라 공유함). 구성 원소로 결합 종류를 못 가리면 분자·이온 구분이 어긋난다.", "fix": "'두 비금속 = 공유결합'으로 판정한다(전자를 주고받는 게 아니라 공유). 구성 원소로 분자·이온을 갈라 결합 종류를 정하라.", "cite": ""}, "CH1-190": {"name": "VSEPR 원리", "course": "ch1", "unit": "Ⅱ-6a", "tier": "C", "mis": ["반발을 최소화한다.", "멀어질수록 안정하다.", "전자쌍 수가 모양을 정한다."], "dx": "중심 원자 둘레 전자쌍이 서로 반발을 최소화하려 가장 멀리 벌어진다는 VSEPR 원리를 놓친 경우다. 전자쌍 수가 배치를 정한다는 출발점이 흔들리면 분자 모양 예측 전체가 무너진다.", "fix": "VSEPR를 '중심 원자 둘레 전자쌍이 반발을 최소화하려 가장 멀리 벌어진다'로 못 박는다. 전자쌍 수를 세는 것이 모양 예측의 출발임을, 한 분자로 직접 적용하라.", "cite": ""}, "CH1-191": {"name": "공유 전자쌍", "course": "ch1", "unit": "Ⅱ-6a", "tier": "C", "mis": ["두 원자가 공유한다.", "결합에 참여하지 않는다.", "고립 전자쌍이 있다."], "dx": "공유 전자쌍(두 원자가 함께 쓰는 결합 전자쌍)과 결합에 안 쓰인 고립 전자쌍을 가르지 못한 경우다. 이 구분이 약하면 결합각과 분자 모양을 정하는 단계에서 막힌다.", "fix": "'공유 전자쌍(두 원자가 함께 씀)과 고립 전자쌍(결합에 안 쓰임)'을 갈라 둔다. 한 분자에서 둘을 각각 세어 결합각·모양 판정에 써라.", "cite": ""}, "CH1-192": {"name": "전자쌍 배치", "course": "ch1", "unit": "Ⅱ-6a", "tier": "C", "mis": ["180°로 멀어진다.", "120°로 멀어진다.", "약 109.5°로 멀어진다."], "dx": "전자쌍 수에 따른 기본 배치 각도(2개 180°·3개 120°·4개 약 109.5°)를 잘못 짝지은 경우다. 이 각도-개수 대응이 흔들리면 모든 분자의 골격 각도가 어긋난다.", "fix": "전자쌍 수와 기본 각도를 '2개 180°, 3개 120°, 4개 약 109.5°'로 짝지어 못 박는다. 영역 수를 세어 골격 각도를 바로 떠올리는 연습을 하라.", "cite": ""}, "CH1-193": {"name": "전자쌍 각도", "course": "ch1", "unit": "Ⅱ-6a", "tier": "C", "mis": ["평면 삼각형이다.", "직선형이다.", "정사면체 구조이다."], "dx": "전자쌍 배치에 맞는 입체 이름(직선형·평면 삼각형·정사면체)을 잘못 붙인 경우다. 배치와 이름의 대응이 흔들리면 분자 구조를 말로 옮기지 못한다.", "fix": "전자쌍 배치의 입체 이름을 '직선형·평면 삼각형·정사면체'로 짝지어 못 박는다. 영역 수에서 이름을 바로 떠올려 구조를 말로 옮겨라.", "cite": ""}, "CH1-194": {"name": "다중결합 취급", "course": "ch1", "unit": "Ⅱ-6a", "tier": "C", "mis": ["한 방향으로 묶인다.", "모양 예측에 포함된다."], "dx": "이중·삼중 결합을 여러 방향으로 세고, VSEPR에서는 하나의 전자 영역(한 방향)으로 묶는다는 점을 놓친 경우다. 이걸 놓치면 CO₂처럼 다중 결합이 있는 분자의 모양을 잘못 잡는다.", "fix": "'이중·삼중 결합도 VSEPR에선 하나의 전자 영역(한 방향)으로 묶는다'를 못 박는다. CO₂를 영역 2개로 세어 직선형이 나옴을 확인하라.", "cite": ""}, "CH1-195": {"name": "분자 모양", "course": "ch1", "unit": "Ⅱ-6a", "tier": "A", "mis": ["비공유 전자쌍이 없다.", "비공유 전자쌍 1개 때문이다.", "비공유 전자쌍 2개 때문이다.", "비공유 전자쌍이 있다.", "중심 C에 영역 4개이다."], "dx": "분자 모양을 전자쌍 배치 그대로 보고, 비공유 전자쌍이 있으면 모양이 달라진다는 점을 놓친 경우다. 전자쌍 배치와 분자 모양을 같은 것으로 보면 굽은형·삼각뿔 같은 실제 모양과 극성 판단이 어긋난다.", "fix": "'전자쌍 배치와 분자 모양은 다르다, 비공유 전자쌍이 있으면 모양이 달라진다'를 못 박는다. 전자 배치는 정사면체라도 비공유 전자쌍이 있으면 굽은형·삼각뿔이 됨을 직접 그려라.", "cite": ""}, "CH1-196": {"name": "분자 루이스 구조", "course": "ch1", "unit": "Ⅱ-6a", "tier": "C", "mis": ["전자쌍 2개를 공유한다.", "O가 H 2개와 결합한다.", "전자쌍 3개를 공유한다."], "dx": "분자의 루이스 구조에서 공유 전자쌍과 결합 상대를 잘못 그린 경우다. 루이스 구조가 틀어지면 거기서 읽는 전자쌍 수와 분자 모양이 통째로 어긋난다.", "fix": "루이스 구조를 '공유 전자쌍과 결합 상대를 정확히 그리는 것'으로 못 박는다. 옥텟을 맞춰 구조를 그린 뒤 거기서 전자쌍 수와 모양을 읽어라.", "cite": ""}, "CH1-197": {"name": "비공유 전자쌍", "course": "ch1", "unit": "Ⅱ-6a", "tier": "C", "mis": ["전자쌍 4개 중 1개가 비공유이다.", "전자쌍 4개 중 2개가 비공유이다."], "dx": "중심 원자의 전자쌍 중 결합에 안 쓰인 비공유 전자쌍 수를 잘못 센 경우다(전자쌍 4개 중 1개냐 2개냐). 비공유 전자쌍 수가 어긋나면 결합각과 모양이 함께 틀어진다.", "fix": "중심 원자의 '결합에 안 쓰인 비공유 전자쌍 수'를 정확히 센다(전자쌍 4개 중 1개냐 2개냐). 이 수로 결합각·모양이 함께 정해짐을 확인하라.", "cite": ""}, "CH1-198": {"name": "결합각", "course": "ch1", "unit": "Ⅱ-6a", "tier": "B", "mis": ["비공유 전자쌍 반발로 작아진다.", "비공유 전자쌍 2개의 반발 때문이다.", "정사면체 구조이다.", "비공유 전자쌍이 반발한다."], "dx": "비공유 전자쌍의 반발로 결합각이 이상값보다 작아진다는 점을 놓친 경우다. 정사면체 109.5°에서 비공유 전자쌍 수만큼 각이 좁아진다는 감각이 없으면 결합각 문제가 어긋난다.", "fix": "'비공유 전자쌍의 반발로 결합각이 이상값보다 작아진다'를 못 박는다. 정사면체 109.5°에서 비공유 전자쌍 수만큼 각이 좁아짐을 NH₃·H₂O로 확인하라.", "cite": ""}, "CH1-199": {"name": "비공유 전자쌍 반발", "course": "ch1", "unit": "Ⅱ-6a", "tier": "C", "mis": ["더 넓게 퍼져 있다.", "더 강하게 반발한다.", "비공유 전자쌍이 더 퍼져 있다."], "dx": "비공유 전자쌍이 한 원자에만 매여 더 넓게 퍼져 공유 전자쌍보다 강하게 반발한다는 점을 놓친 경우다. 이 반발의 세기 차가 약하면 결합각이 왜 좁아지는지 근거가 사라진다.", "fix": "'비공유 전자쌍은 한 원자에만 매여 더 넓게 퍼져 공유 전자쌍보다 강하게 반발'함을 못 박는다. 이 세기 차가 결합각을 좁히는 근거임을 짚어라.", "cite": ""}, "CH1-200": {"name": "결합각 비교", "course": "ch1", "unit": "Ⅱ-6a", "tier": "C", "mis": ["비공유 전자쌍이 많을수록 작다.", "비공유 전자쌍이 더 많다.", "비공유 전자쌍 수가 다르다."], "dx": "비공유 전자쌍이 많을수록 결합각이 더 작아진다는 비교를 놓친 경우다(CH₄ > NH₃ > H₂O). 이 순서를 못 잡으면 비슷한 분자들의 결합각 대소를 가리지 못한다.", "fix": "'비공유 전자쌍이 많을수록 결합각이 더 작음'을 못 박는다. CH₄ > NH₃ > H₂O 순으로 결합각을 늘어놓아 대소를 직접 가려라.", "cite": ""}, "CH1-201": {"name": "결합각 원인", "course": "ch1", "unit": "Ⅱ-6a", "tier": "C", "mis": ["비공유 전자쌍이 공유 전자쌍을 민다.", "반발이 더 크다.", "비공유 전자쌍이 결합각을 줄인다."], "dx": "결합각이 작아지는 원인을 비공유 전자쌍이 공유 전자쌍을 더 세게 밀어서라고 짚지 못한 경우다. 원인이 흐리면 결합각 변화를 설명하는 문제에서 막힌다.", "fix": "결합각이 좁아지는 원인을 '비공유 전자쌍이 공유 전자쌍을 더 세게 밀어서'로 못 박는다. 이 원인으로 결합각 변화 문제를 설명하라.", "cite": ""}, "CH1-202": {"name": "옥텟 규칙", "course": "ch1", "unit": "Ⅱ-6a", "tier": "C", "mis": ["대부분 8개를 채운다.", "헬륨과 같은 배치이다.", "최외각 전자가 8개이다."], "dx": "대부분의 원자가 결합으로 최외각 전자 8개(옥텟, 수소는 헬륨처럼 2개)를 채운다는 규칙을 놓친 경우다. 옥텟이 약하면 루이스 구조와 결합 수를 정하는 기준이 사라진다.", "fix": "옥텟을 '대부분의 원자가 결합으로 최외각 8개(수소는 2개)를 채움'으로 못 박는다. 이를 루이스 구조와 결합 수를 정하는 기준으로 삼아라.", "cite": ""}, "CH1-203": {"name": "분자 모양 결정", "course": "ch1", "unit": "Ⅱ-6a", "tier": "C", "mis": ["비공유 전자쌍도 영향을 준다.", "결합각과 모양을 바꾼다.", "질량은 모양과 무관하다."], "dx": "분자 모양이 공유 전자쌍만이 아니라 비공유 전자쌍까지 함께 정해진다는 점을 놓친 경우다(질량은 모양과 무관). 비공유 전자쌍을 빼고 모양을 잡으면 실제 구조·극성이 어긋난다.", "fix": "분자 모양을 '공유 전자쌍과 비공유 전자쌍을 함께 보고 정함(질량 무관)'으로 못 박는다. 비공유 전자쌍을 빼지 말고 모양·극성을 잡아라.", "cite": ""}, "CH1-204": {"name": "정사면체", "course": "ch1", "unit": "Ⅱ-6a", "tier": "C", "mis": ["대칭적인 입체 구조이다.", "3차원으로 퍼진다.", "대칭 구조이다."], "dx": "전자쌍 4개가 모두 결합이면 정사면체로 3차원 대칭을 이룬다는 점을 놓친 경우다. 이 대칭 구조를 못 잡으면 CH₄ 같은 분자가 왜 무극성인지로 이어지지 못한다.", "fix": "'전자쌍 4개가 모두 결합이면 정사면체로 3차원 대칭'임을 못 박는다. 이 대칭이 CH₄가 무극성인 까닭으로 이어짐을 짚어라.", "cite": ""}, "CH1-205": {"name": "다중 결합", "course": "ch1", "unit": "Ⅱ-6a", "tier": "C", "mis": ["전자쌍 3개를 공유한다.", "공유 전자쌍이 더 많다.", "단일 결합이 1개이다."], "dx": "공유 전자쌍 수로 단일·이중·삼중 결합을 가리는 게 흔들린 경우다. 결합 차수를 잘못 세면 결합 길이·세기와 VSEPR 영역 수가 어긋난다.", "fix": "단일·이중·삼중 결합을 '공유 전자쌍 수'로 가린다. 결합 차수를 바로 세어 결합 길이·세기와 VSEPR 영역 수에 써라.", "cite": ""}, "CH1-263": {"name": "고립 전자쌍", "course": "ch1", "unit": "Ⅱ-6a", "tier": "C", "mis": ["한 원자에만 속한다.", "전자쌍 4개 중 2개가 비공유이다.", "결합각과 모양을 바꾼다."], "dx": "고립(비공유) 전자쌍이 한 원자에만 속하고 분자 모양·결합각을 바꾼다는 점을 놓친 경우다. 고립 전자쌍의 역할이 약하면 실제 분자 모양과 결합각을 잘못 잡는다.", "fix": "고립(비공유) 전자쌍을 '한 원자에만 속하고 분자 모양·결합각을 바꾼다'로 못 박는다. 고립 전자쌍을 세어 실제 모양과 결합각을 잡아라.", "cite": ""}, "CH1-206": {"name": "결합 극성", "course": "ch1", "unit": "Ⅱ-6b", "tier": "C", "mis": ["전자쌍이 치우치지 않는다.", "전기음성도 차이가 없다.", "전자쌍이 더 치우친다."], "dx": "전기음성도 차이가 있어야 공유 전자쌍이 치우쳐 극성 결합이 되고, 차이가 없으면 무극성 결합이라는 점을 놓친 경우다. 결합 극성의 기준이 흐리면 분자 극성 판단으로 이어지지 못한다.", "fix": "'전기음성도 차이가 있으면 극성 결합, 없으면(같은 원자) 무극성 결합'을 못 박는다. 결합마다 전기음성도 차로 극성을 가려 분자 극성의 출발로 삼아라.", "cite": ""}, "CH1-207": {"name": "부분 전하", "course": "ch1", "unit": "Ⅱ-6b", "tier": "C", "mis": ["전자쌍이 그쪽으로 치우친다.", "Cl의 전기음성도가 크다.", "H의 전기음성도가 작다."], "dx": "전기음성도가 큰 쪽(예: Cl)으로 전자쌍이 치우쳐 그쪽이 부분 음전하를 띤다는 점을 놓친 경우다. 부분 전하의 방향이 흐리면 쌍극자 방향·분자 극성이 어긋난다.", "fix": "'전기음성도가 큰 쪽으로 전자쌍이 치우쳐 그쪽이 부분 음전하'임을 못 박는다. 부분 전하의 방향(쌍극자 방향)을 각 결합에 표시하라.", "cite": ""}, "CH1-208": {"name": "쌍극자 모멘트", "course": "ch1", "unit": "Ⅱ-6b", "tier": "C", "mis": ["벡터이다.", "쌍극자가 상쇄된다.", "극성을 나타낸다."], "dx": "쌍극자 모멘트가 크기와 방향을 가진 벡터라 결합 쌍극자들이 합쳐지거나 상쇄된다는 점을 놓친 경우다. 벡터라는 점이 약하면 대칭 분자에서 쌍극자가 왜 사라지는지 설명하지 못한다.", "fix": "쌍극자 모멘트를 '크기와 방향을 가진 벡터라 결합 쌍극자들이 합쳐지거나 상쇄됨'으로 못 박는다. 대칭 분자에서 벡터가 상쇄돼 0이 됨을 화살표로 그려 확인하라.", "cite": ""}, "CH1-209": {"name": "극성결합 vs 극성분자", "course": "ch1", "unit": "Ⅱ-6b", "tier": "C", "mis": ["쌍극자가 상쇄될 수 있다.", "쌍극자가 상쇄된다.", "분자 모양도 고려해야 한다."], "dx": "극성 결합이 있으면 무조건 극성 분자라고 본 경우다. 결합이 극성이라도 대칭 구조면 쌍극자가 상쇄돼 무극성이 된다는 점(분자 모양까지 봐야 함)을 놓치면 CO₂ 같은 분자를 잘못 판정한다.", "fix": "'극성 결합이 있어도 대칭 구조면 쌍극자가 상쇄돼 무극성'임을 못 박는다(분자 모양까지 봐야 함). CO₂가 극성 결합인데 무극성 분자임을 직접 판정하라.", "cite": ""}, "CH1-210": {"name": "무극성 분자", "course": "ch1", "unit": "Ⅱ-6b", "tier": "A", "mis": ["정사면체 대칭으로 상쇄된다.", "정사면체 대칭이다.", "직선형 대칭으로 상쇄된다.", "직선형 대칭이다.", "같은 원자라 전기음성도 차이가 없다.", "평면 삼각형 대칭으로 상쇄된다."], "dx": "무극성 분자가 같은 원자라 전기음성도 차가 없거나, 극성 결합이라도 대칭 구조(직선·평면 삼각·정사면체)로 상쇄돼 생긴다는 두 길을 놓친 경우다. 이 둘이 약하면 분자 극성 판정이 통째로 어긋난다.", "fix": "무극성 분자를 '같은 원자라 전기음성도 차가 없거나, 극성 결합이라도 대칭 구조로 상쇄' 두 길로 못 박는다. 분자마다 어느 길인지 가려 극성을 판정하라.", "cite": ""}, "CH1-211": {"name": "무극성 원인", "course": "ch1", "unit": "Ⅱ-6b", "tier": "C", "mis": ["결합 자체는 극성이다.", "방향이 반대이다.", "CO₂가 그 예이다."], "dx": "결합 자체는 극성인데 방향이 반대라 상쇄돼 분자가 무극성이 된다는 메커니즘을 놓친 경우다(CO₂가 그 예). 이 상쇄 논리가 약하면 무극성의 까닭을 설명하지 못한다.", "fix": "'결합은 극성인데 방향이 반대라 상쇄돼 분자가 무극성'이라는 메커니즘을 못 박는다. CO₂의 두 결합 쌍극자가 반대로 상쇄됨을 그려 확인하라.", "cite": ""}, "CH1-212": {"name": "극성 분자", "course": "ch1", "unit": "Ⅱ-6b", "tier": "B", "mis": ["삼각뿔 비대칭 구조이다.", "전기음성도 차이가 크다.", "굽은형 비대칭 구조이다.", "전기음성도 차이가 있다."], "dx": "극성 분자가 전기음성도 차가 있고 굽은형·삼각뿔 같은 비대칭 구조라 쌍극자가 남아 생긴다는 점을 놓친 경우다. 비대칭이 극성을 만든다는 감각이 약하면 H₂O·NH₃의 극성을 못 짚는다.", "fix": "극성 분자를 '전기음성도 차가 있고 굽은형·삼각뿔 같은 비대칭 구조라 쌍극자가 남음'으로 못 박는다. H₂O·NH₃에서 쌍극자가 안 상쇄됨을 그려 극성을 짚어라.", "cite": ""}, "CH1-213": {"name": "극성 원인", "course": "ch1", "unit": "Ⅱ-6b", "tier": "C", "mis": ["직선형이면 상쇄된다.", "대칭이면 상쇄된다.", "쌍극자 모멘트가 남는다."], "dx": "비대칭 구조라 결합 쌍극자가 상쇄되지 못하고 남은 것이 분자 극성의 원인이라는 점을 놓친 경우다. 대칭이면 상쇄된다는 짝까지 잡아야 극성·무극성을 가른다.", "fix": "'비대칭 구조라 결합 쌍극자가 상쇄되지 못하고 남은 것이 분자 극성의 원인'임을 못 박는다. 대칭이면 상쇄된다는 짝까지 잡아 극성·무극성을 가려라.", "cite": ""}, "CH1-214": {"name": "분자 극성 판단", "course": "ch1", "unit": "Ⅱ-6b", "tier": "C", "mis": ["분자 모양도 고려해야 한다.", "쌍극자가 상쇄될 수 있다.", "결합 극성도 고려해야 한다."], "dx": "분자 극성을 판단할 때 결합 극성과 분자 모양을 함께 봐야 한다는 점을 놓친 경우다. 한쪽만 보면 극성 결합인데 무극성 분자인 경우를 놓쳐 판정이 어긋난다.", "fix": "분자 극성을 '결합 극성과 분자 모양을 함께 보고' 판단한다. 한쪽만 보지 말고, 극성 결합이지만 무극성 분자인 경우를 놓치지 않게 둘 다 확인하라.", "cite": ""}, "CH1-215": {"name": "대칭과 극성", "course": "ch1", "unit": "Ⅱ-6b", "tier": "C", "mis": ["쌍극자가 상쇄된다.", "대칭이면 상쇄된다.", "쌍극자가 남는다."], "dx": "대칭 구조면 쌍극자가 상쇄돼 무극성, 비대칭이면 쌍극자가 남아 극성이라는 대응을 놓친 경우다. 이 대칭-극성 짝이 약하면 분자 극성을 빠르게 가리지 못한다.", "fix": "'대칭이면 상쇄돼 무극성, 비대칭이면 남아 극성'을 짝으로 못 박는다. 분자 모양의 대칭 여부로 극성을 빠르게 가리는 연습을 하라.", "cite": ""}, "CH1-216": {"name": "혼성 오비탈", "course": "ch1", "unit": "Ⅱ-6b", "tier": "C", "mis": ["영역 2개이다.", "영역 4개이다.", "영역 3개이다."], "dx": "전자 영역 수에 따라 혼성이 정해진다(영역 2개 sp·3개 sp²·4개 sp³)는 대응을 놓친 경우다. 영역 수와 혼성의 짝이 흔들리면 분자 구조를 혼성으로 설명하지 못한다.", "fix": "혼성을 '전자 영역 수에 따라 영역 2개 sp, 3개 sp², 4개 sp³'로 짝지어 못 박는다. 영역 수를 세어 혼성을 바로 정하는 연습을 하라.", "cite": ""}, "CH1-217": {"name": "혼성 적용", "course": "ch1", "unit": "Ⅱ-6b", "tier": "A", "mis": ["영역이 2개이다.", "영역이 4개이다."], "dx": "중심 원자의 전자 영역 수를 잘못 세 혼성을 잘못 정한 경우다. 영역 수가 어긋나면 sp·sp²·sp³ 판정과 그에 따른 구조가 통째로 틀어진다.", "fix": "중심 원자의 '전자 영역 수를 정확히 세어' 혼성을 정한다. 비공유 전자쌍까지 포함해 영역을 세고 sp·sp²·sp³와 구조를 잡아라.", "cite": ""}, "CH1-218": {"name": "혼성 수", "course": "ch1", "unit": "Ⅱ-6b", "tier": "C", "mis": ["영역마다 하나이다.", "전자쌍 수가 정한다.", "비공유 전자쌍도 포함된다."], "dx": "혼성 오비탈 수가 전자 영역(전자쌍) 수와 같고 비공유 전자쌍도 센다는 점을 놓친 경우다. 비공유 전자쌍을 빼고 세면 혼성 수가 어긋난다.", "fix": "'혼성 오비탈 수 = 전자 영역(전자쌍) 수, 비공유 전자쌍도 셈'을 못 박는다. 비공유 전자쌍을 빼지 말고 영역을 세어 혼성 수를 맞춰라.", "cite": ""}, "CH1-219": {"name": "극성과 용해", "course": "ch1", "unit": "Ⅱ-6b", "tier": "C", "mis": ["비슷한 극성끼리 섞인다.", "극성이 비슷해야 잘 녹는다."], "dx": "극성은 극성끼리, 무극성은 무극성끼리 잘 녹는다(비슷한 극성끼리 섞임)는 점을 놓친 경우다. 이 규칙이 약하면 화학Ⅱ 용해성 단원의 핵심 판단이 막힌다.", "fix": "'극성은 극성끼리, 무극성은 무극성끼리 잘 녹는다(비슷한 극성끼리 섞임)'를 못 박는다. 이 규칙을 화학Ⅱ 용해성 판단의 핵심으로 삼아라.", "cite": ""}, "CH1-220": {"name": "전기장 배열", "course": "ch1", "unit": "Ⅱ-6b", "tier": "C", "mis": ["부분 전하가 정렬된다.", "부분 전하가 없다.", "부분 전하가 있다."], "dx": "극성 분자가 부분 전하를 가져 전기장 속에서 정렬된다는 점을 놓친 경우다. 무극성 분자는 부분 전하가 없어 정렬되지 않는다는 대비까지 잡아야 극성의 의미가 산다.", "fix": "'극성 분자는 부분 전하가 있어 전기장 속에서 정렬되고, 무극성은 안 됨'을 짝으로 못 박는다. 이 대비로 극성의 의미(부분 전하)를 새겨라.", "cite": ""}, "CH1-221": {"name": "극성과 끓는점", "course": "ch1", "unit": "Ⅱ-6b", "tier": "C", "mis": ["극성 분자의 인력이 강하다.", "쌍극자-쌍극자 인력 때문이다.", "인력의 세기가 다르다."], "dx": "극성 분자가 쌍극자-쌍극자 인력 때문에 비슷한 크기의 무극성 분자보다 끓는점이 높다는 점을 놓친 경우다. 이 연결이 약하면 화학Ⅱ 분자 간 힘·끓는점 비교가 흔들린다.", "fix": "'극성 분자는 쌍극자-쌍극자 인력 때문에 비슷한 크기의 무극성보다 끓는점이 높음'을 못 박는다. 이 연결을 화학Ⅱ 분자 간 힘·끓는점 비교의 바탕으로 삼아라.", "cite": ""}, "CH1-222": {"name": "분산력", "course": "ch1", "unit": "Ⅱ-6b", "tier": "C", "mis": ["무극성 분자에도 작용한다.", "전자가 많아진다.", "순간 쌍극자 때문이다."], "dx": "분산력이 무극성 분자에도 작용하고(순간 쌍극자 때문) 전자가 많을수록 커진다는 점을 놓친 경우다. 분산력의 보편성이 약하면 화학Ⅱ 분자 간 힘의 출발이 흔들린다.", "fix": "'분산력은 무극성 분자에도 작용하고(순간 쌍극자) 전자가 많을수록 큼'을 못 박는다. 분산력의 보편성을 화학Ⅱ 분자 간 힘의 출발로 새겨라.", "cite": ""}, "CH1-248": {"name": "가역 반응", "course": "ch1", "unit": "Ⅲ-1", "tier": "C", "mis": ["양방향으로 진행된다.", "두 방향이 모두 일어난다.", "완전히 변하지 않는다."], "dx": "가역 반응이 정반응과 역반응이 모두 일어나 완전히 한쪽으로 끝나지 않는 반응이라는 점을 놓친 경우다. 양방향이 함께 간다는 전제가 없으면 동적 평형 개념 자체가 서지 못한다.", "fix": "가역 반응을 '정반응과 역반응이 모두 일어나 완전히 한쪽으로 끝나지 않는 반응'으로 못 박는다. 양방향이 함께 감을 동적 평형 개념의 전제로 삼아라.", "cite": ""}, "CH1-249": {"name": "동적 평형 개념", "course": "ch1", "unit": "Ⅲ-1", "tier": "B", "mis": ["동적인 상태이다.", "두 방향이 같은 속도로 일어난다."], "dx": "동적 평형을 반응이 멈춘 정적 상태로 본 경우다. 정반응과 역반응이 같은 속도로 계속 일어나 겉보기만 멈춰 보인다는 점을 놓치면 평형의 모든 해석이 어긋난다.", "fix": "동적 평형을 '멈춘 게 아니라 정반응·역반응이 같은 속도로 계속 일어나 겉보기만 멈춰 보이는 상태'로 못 박는다. '멈춤'으로 그리지 않도록 두 화살표가 계속 도는 그림을 새겨라.", "cite": ""}, "CH1-250": {"name": "동적 평형 정의", "course": "ch1", "unit": "Ⅲ-1", "tier": "C", "mis": ["속도가 같다.", "계속 일어나고 있다.", "두 방향이 함께 일어난다."], "dx": "동적 평형에서 정반응·역반응 속도가 같고 두 반응이 계속 일어난다는 정의를 놓친 경우다. '속도가 같다'와 '계속 일어난다'를 함께 잡지 못하면 평형을 멈춤으로 오해한다.", "fix": "동적 평형을 '정·역 속도가 같고, 두 반응이 계속 일어남' 두 조건으로 못 박는다. '같다'와 '계속'을 함께 잡아 평형을 멈춤으로 오해하지 않게 하라.", "cite": ""}, "CH1-251": {"name": "평형 농도", "course": "ch1", "unit": "Ⅲ-1", "tier": "C", "mis": ["농도가 변하지 않는다.", "일정할 뿐 같지 않다."], "dx": "평형에서 농도가 일정할 뿐 반응물과 생성물 농도가 서로 같은 건 아니라는 점을 놓친 경우다. '일정'과 '같음'을 혼동하면 평형 상수 해석이 어긋난다.", "fix": "'평형에서 농도는 일정할 뿐, 반응물·생성물 농도가 서로 같은 건 아님'을 못 박는다. '일정'과 '같음'을 갈라 평형 상수 해석에 써라.", "cite": ""}, "CH1-252": {"name": "평형의 겉보기", "course": "ch1", "unit": "Ⅲ-1", "tier": "C", "mis": ["농도가 변하지 않는다.", "동적인 상태이다.", "겉보기 변화가 없다."], "dx": "농도가 변하지 않아 멈춘 것처럼 보여도 실제로는 동적 상태라는 점을 놓친 경우다. 겉보기와 실제를 가르지 못하면 평형을 정적인 것으로 잘못 그린다.", "fix": "'농도가 안 변해 멈춘 듯 보여도 실제로는 동적 상태'임을 못 박는다. 겉보기와 실제를 갈라 평형을 정적으로 그리지 마라.", "cite": ""}, "CH1-253": {"name": "평형 상수 식", "course": "ch1", "unit": "Ⅲ-1", "tier": "C", "mis": ["계수가 지수가 된다.", "농도가 일정하다.", "생성물을 분자에 둔다."], "dx": "평형 상수가 (생성물 농도 곱)/(반응물 농도 곱)이고 계수가 지수로 올라간다는 식을 놓친 경우다. 생성물을 분자에, 계수를 지수로 두는 형식이 흔들리면 K 계산이 통째로 어긋난다.", "fix": "평형 상수를 '(생성물 농도 곱)/(반응물 농도 곱), 계수는 지수로'로 못 박는다. 한 반응식으로 생성물을 분자에, 계수를 지수로 올려 K 식을 직접 써라.", "cite": ""}, "CH1-254": {"name": "평형 상수 해석", "course": "ch1", "unit": "Ⅲ-1", "tier": "B", "mis": ["분자(생성물)가 크다.", "분모(반응물)가 크다.", "생성물이 많아진다.", "반응물이 많다."], "dx": "평형 상수가 크면 분자(생성물) 쪽이 많아 정반응으로 치우친 평형, 작으면 반응물 쪽이라는 해석을 놓친 경우다. K의 대소로 평형 위치를 읽지 못하면 반응이 어디로 치우쳤는지 못 가린다.", "fix": "'K가 크면 생성물 쪽으로 치우친 평형, 작으면 반응물 쪽'으로 못 박는다. K 값의 대소로 평형이 어디로 치우쳤는지 읽는 연습을 하라.", "cite": ""}, "CH1-255": {"name": "평형 상수와 온도", "course": "ch1", "unit": "Ⅲ-1", "tier": "B", "mis": ["온도에만 의존한다.", "촉매는 평형을 이동시키지 않는다."], "dx": "평형 상수가 온도에만 의존하고 농도·촉매로는 변하지 않는다는 점을 놓친 경우다. K를 바꾸는 게 온도뿐이라는 점이 약하면 르샤틀리에에서 평형 이동과 K 변화를 뒤섞는다.", "fix": "'평형 상수는 온도에만 의존하고 농도·촉매로는 안 변함'을 못 박는다. K를 바꾸는 게 온도뿐임을, 르샤틀리에에서 이동과 K 변화를 안 섞이게 새겨라.", "cite": ""}, "CH1-256": {"name": "반응 지수", "course": "ch1", "unit": "Ⅲ-1", "tier": "C", "mis": ["평형 전에도 계산한다.", "넣는 농도만 다르다.", "농도가 바뀌면 변한다."], "dx": "반응 지수 Q가 평형 전 임의 시점의 농도로 계산하는, K와 같은 꼴의 값이라는 점을 놓친 경우다. Q가 농도에 따라 변하는 '현재 상태값'이라는 감각이 없으면 방향 판단으로 못 잇는다.", "fix": "반응 지수 Q를 '평형 전 임의 시점의 농도로 계산하는, K와 같은 꼴의 현재 상태값'으로 못 박는다. Q가 농도 따라 변함을 잡아 방향 판단의 재료로 삼아라.", "cite": ""}, "CH1-257": {"name": "반응 지수 방향", "course": "ch1", "unit": "Ⅲ-1", "tier": "A", "mis": ["생성물이 부족하다.", "생성물이 과하다.", "속도가 같다.", "아직 평형이 아니다."], "dx": "Q와 K를 비교해 진행 방향을 정하는 규칙을 놓친 경우다. Q<K면 생성물이 부족해 정반응, Q>K면 생성물이 과해 역반응으로 간다는 판단이 흔들리면 평형이 아닌 상태의 거동을 못 읽는다.", "fix": "'Q<K면 생성물이 부족해 정반응, Q>K면 생성물이 과해 역반응'으로 방향을 못 박는다. Q와 K를 견줘 평형이 아닌 상태가 어디로 갈지 판단하라.", "cite": ""}, "CH1-258": {"name": "비가역 반응", "course": "ch1", "unit": "Ⅲ-1", "tier": "C", "mis": ["역반응이 거의 없다.", "한 방향으로 진행된다."], "dx": "비가역 반응이 역반응이 거의 없어 한 방향으로만 진행하는 반응이라는 점을 놓친 경우다. 가역과의 대비가 약하면 어떤 반응이 평형에 이르는지 가리지 못한다.", "fix": "비가역 반응을 '역반응이 거의 없어 한 방향으로만 진행'으로 못 박는다. 가역과 대비해 어떤 반응이 평형에 이르는지 가려라.", "cite": ""}, "CH1-259": {"name": "평형 도달", "course": "ch1", "unit": "Ⅲ-1", "tier": "C", "mis": ["반응 속도가 다르다.", "역반응이 일어나기 어렵다.", "동적인 상태이다."], "dx": "처음엔 정반응이 빠르다가 역반응이 점점 빨라져 두 속도가 같아질 때 평형에 이른다는 과정을 놓친 경우다. 이 속도 변화 그림이 약하면 평형이 왜 동적인지 이해하지 못한다.", "fix": "평형 도달을 '처음엔 정반응이 빠르다가 역반응이 점점 빨라져 두 속도가 같아질 때'로 못 박는다. 이 속도 변화 그림으로 평형이 동적인 까닭을 새겨라.", "cite": ""}, "CH1-260": {"name": "평형 상수 단위", "course": "ch1", "unit": "Ⅲ-1", "tier": "C", "mis": ["계수에 따라 다르다.", "무차원으로 취급한다."], "dx": "평형 상수를 보통 무차원으로 다룬다는 점을 놓친 경우다. 단위 처리가 흔들리면 계수에 따라 단위가 달라지는 줄 알고 K를 잘못 표기한다.", "fix": "평형 상수를 '보통 무차원으로 다룸'으로 못 박는다. 계수에 따라 단위가 달라진다고 오해하지 않도록 K를 단위 없이 표기하라.", "cite": ""}, "CH1-261": {"name": "반응 지수 활용", "course": "ch1", "unit": "Ⅲ-1", "tier": "C", "mis": ["K와의 대소가 필요하다.", "대소 비교로 판단한다.", "방향 판단에 활용된다."], "dx": "반응 지수를 쓸 때 K와의 대소 비교로 진행 방향을 판단한다는 점을 놓친 경우다. Q만 구하고 K와 견주지 않으면 방향 예측이 안 선다.", "fix": "'반응 지수는 K와의 대소 비교로 진행 방향을 판단'함을 못 박는다. Q만 구하지 말고 반드시 K와 견줘 방향을 정하라.", "cite": ""}, "CH1-262": {"name": "정·역반응 열", "course": "ch1", "unit": "Ⅲ-1", "tier": "C", "mis": ["방향이 반대이다.", "에너지 출입이 반대이다."], "dx": "정반응이 발열이면 역반응은 흡열로 에너지 출입 방향이 반대라는 점을 놓친 경우다. 이 대칭이 약하면 온도 변화에 따른 평형 이동 방향을 못 잡는다.", "fix": "'정반응이 발열이면 역반응은 흡열로 에너지 출입이 반대'임을 못 박는다. 이 대칭으로 온도 변화에 따른 평형 이동 방향을 잡아라.", "cite": ""}, "CH1-264": {"name": "르샤틀리에 정의", "course": "ch1", "unit": "Ⅲ-2", "tier": "C", "mis": ["변화를 완화한다.", "변화에 반응한다."], "dx": "르샤틀리에 원리가 평형에 가한 변화를 '완화하는' 방향으로 평형이 이동한다는 점을 놓친 경우다. 변화에 거스르는 쪽으로 간다는 핵심이 흔들리면 모든 이동 예측이 어긋난다.", "fix": "르샤틀리에를 '평형에 가한 변화를 완화하는(거스르는) 방향으로 이동'으로 못 박는다. 이 한 줄을 농도·온도·압력 변화 모두에 적용하는 출발로 삼아라.", "cite": ""}, "CH1-265": {"name": "농도 변화", "course": "ch1", "unit": "Ⅲ-2", "tier": "C", "mis": ["생성물을 소모한다.", "반응물을 보충한다.", "그 반응물을 소모한다."], "dx": "반응물을 넣으면 그것을 소모하려 정반응, 생성물을 넣으면 역반응으로 이동한다는 점을 놓친 경우다. '넣은 것을 줄이는 쪽'이라는 방향이 약하면 농도 변화 문제가 어긋난다.", "fix": "'반응물을 넣으면 정반응, 생성물을 넣으면 역반응(넣은 것을 줄이는 쪽)'으로 못 박는다. 무엇을 더했는지 보고 이동 방향을 바로 정하라.", "cite": ""}, "CH1-266": {"name": "온도 변화", "course": "ch1", "unit": "Ⅲ-2", "tier": "B", "mis": ["열을 방출한다.", "열을 흡수한다.", "흡열 방향으로 간다.", "발열 방향으로 간다."], "dx": "온도를 올리면 흡열 반응 쪽, 내리면 발열 반응 쪽으로 이동한다는 점을 놓친 경우다(가한 열을 흡수하거나 보충하는 쪽). 이 방향이 흔들리면 온도 문제에서 평형 이동을 잘못 잡는다.", "fix": "'온도를 올리면 흡열 반응 쪽, 내리면 발열 반응 쪽(가한 열을 흡수·보충하는 쪽)'으로 못 박는다. 반응의 발열·흡열을 보고 온도 이동을 잡아라.", "cite": ""}, "CH1-267": {"name": "온도와 평형 상수", "course": "ch1", "unit": "Ⅲ-2", "tier": "C", "mis": ["K는 온도에만 의존한다.", "역반응 쪽으로 이동한다.", "K는 온도에 의존한다."], "dx": "온도 변화만 평형 상수를 바꾸고 그래서 평형이 이동한다는 점을 놓친 경우다. 농도·압력은 K를 안 바꾼다는 대비가 약하면 K 변화와 단순 이동을 혼동한다.", "fix": "'온도 변화만 평형 상수를 바꿔 평형이 이동'함을 못 박는다. 농도·압력은 K를 안 바꿈을 대비해 K 변화와 단순 이동을 갈라라.", "cite": ""}, "CH1-268": {"name": "압력 변화", "course": "ch1", "unit": "Ⅲ-2", "tier": "A", "mis": ["압력 상승을 완화한다.", "압력 하강을 완화한다.", "완화할 차이가 없다.", "분자 수가 같으면 이동하지 않는다."], "dx": "압력을 높이면 기체 분자 수가 적은 쪽으로 평형이 이동하고, 양변 분자 수가 같으면 이동하지 않는다는 점을 놓친 경우다. 압력 변화를 완화할 차이(분자 수 차)가 있어야 이동한다는 점이 약하면 압력 문제가 어긋난다.", "fix": "'압력을 높이면 기체 분자 수가 적은 쪽으로 이동, 양변 분자 수가 같으면 안 움직임'을 못 박는다. 양변 기체 계수를 세어 이동 여부를 정하라.", "cite": ""}, "CH1-269": {"name": "비활성 기체와 평형", "course": "ch1", "unit": "Ⅲ-2", "tier": "C", "mis": ["각 기체 농도가 변하지 않는다.", "반응에 무관하다."], "dx": "부피 고정에서 비활성 기체를 넣어도 각 반응 기체의 농도(분압)가 그대로라 평형이 이동하지 않는다는 점을 놓친 경우다. 전체 압력만 보고 이동을 판단하면 이 함정에 걸린다.", "fix": "'부피 고정에서 비활성 기체를 넣어도 반응 기체의 분압이 그대로라 평형이 이동하지 않음'을 못 박는다. 전체 압력만 보고 판단하는 함정에 걸리지 마라.", "cite": ""}, "CH1-270": {"name": "촉매", "course": "ch1", "unit": "Ⅲ-2", "tier": "A", "mis": ["양방향을 똑같이 가속한다.", "평형 위치가 그대로이다.", "속도만 바꾼다."], "dx": "촉매가 정·역반응을 똑같이 빠르게 해 평형 도달만 앞당기고 평형 위치는 안 바꾼다는 점을 놓친 경우다. 촉매가 K나 평형 위치를 바꾼다고 오해하면 평형과 속도를 뒤섞는다.", "fix": "'촉매는 정·역반응을 똑같이 빠르게 해 평형 도달만 앞당기고 위치는 안 바꿈'을 못 박는다. 촉매가 K나 평형 위치를 바꾼다고 오해하지 마라.", "cite": ""}, "CH1-271": {"name": "압력 적용", "course": "ch1", "unit": "Ⅲ-2", "tier": "C", "mis": ["기체 분자 수가 적은 쪽이다.", "고압이 정반응에 유리하다.", "기체 분자 수가 적은 쪽으로 간다."], "dx": "압력 변화에 따른 이동을 양변 기체 분자 수 비교로 정하는 적용이 흔들린 경우다. 고압이면 분자 수가 적은 쪽이 유리하다는 셈이 약하면 문제 적용이 어긋난다.", "fix": "압력 이동을 '양변 기체 분자 수 비교'로 적용한다. 고압이면 분자 수가 적은 쪽이 유리함을 계수로 셈해 문제에 써라.", "cite": ""}, "CH1-272": {"name": "온도 적용", "course": "ch1", "unit": "Ⅲ-2", "tier": "C", "mis": ["흡열 방향(역반응)으로 이동한다.", "열을 방출하는 쪽이다.", "발열 정반응에 유리하다."], "dx": "온도 변화에 따른 이동을 반응의 발열·흡열 방향으로 정하는 적용이 흔들린 경우다. 발열 정반응이면 저온이 유리하다는 판단이 약하면 온도 문제 적용이 어긋난다.", "fix": "온도 이동을 '반응의 발열·흡열 방향'으로 적용한다. 발열 정반응이면 저온이 유리함을 판단해 문제에 써라.", "cite": ""}, "CH1-273": {"name": "평형 이동과 K", "course": "ch1", "unit": "Ⅲ-2", "tier": "C", "mis": ["K는 온도에만 의존한다."], "dx": "농도·압력 변화는 평형을 이동시켜도 평형 상수는 그대로이고 온도만 K를 바꾼다는 점을 놓친 경우다. 이 원칙이 약하면 이동이 일어났으니 K도 변했다고 잘못 본다.", "fix": "'농도·압력 변화는 평형을 이동시켜도 K는 그대로, 온도만 K를 바꿈'을 못 박는다. 이동이 일어났으니 K도 변했다고 잘못 보지 마라.", "cite": ""}, "CH1-274": {"name": "르샤틀리에 활용", "course": "ch1", "unit": "Ⅲ-2", "tier": "C", "mis": ["변화를 완화하는 방향으로 간다.", "평형 이동을 다룬다."], "dx": "여러 조건 변화에 르샤틀리에 원리를 적용해 이동 방향을 종합 판단하는 게 흔들린 경우다. '변화를 완화하는 쪽'이라는 한 줄로 농도·온도·압력을 꿰지 못하면 복합 문제가 막힌다.", "fix": "여러 조건 변화를 '변화를 완화하는 쪽'이라는 한 줄로 종합 판단한다. 농도·온도·압력을 이 한 원리로 꿰어 복합 문제를 풀어라.", "cite": ""}, "CH1-275": {"name": "평형 재도달", "course": "ch1", "unit": "Ⅲ-2", "tier": "C", "mis": ["속도가 다시 같아진다.", "동적 평형이 재형성된다."], "dx": "평형이 깨진 뒤 정·역반응 속도가 다시 같아지며 새 동적 평형에 이른다는 점을 놓친 경우다. 이 재형성 그림이 약하면 평형 이동을 '한 번 가고 끝'으로 오해한다.", "fix": "'평형이 깨진 뒤 정·역 속도가 다시 같아지며 새 동적 평형에 이름'을 못 박는다. 이동을 '한 번 가고 끝'이 아니라 새 평형의 재형성으로 그려라.", "cite": ""}, "CH1-276": {"name": "증발·응축 평형", "course": "ch1", "unit": "Ⅲ-3", "tier": "C", "mis": ["동적인 상태이다."], "dx": "밀폐 용기에서 증발과 응축이 같은 속도로 일어나는 동적 평형 상태라는 점을 놓친 경우다. 이 평형이 약하면 증기압이 무엇의 압력인지 정의가 흐려진다.", "fix": "'밀폐 용기에서 증발과 응축이 같은 속도로 일어나는 동적 평형'을 못 박는다. 이 평형이 증기압의 정의(무엇의 압력인지)임을 짚어라.", "cite": ""}, "CH1-277": {"name": "증기압", "course": "ch1", "unit": "Ⅲ-3", "tier": "C", "mis": ["양에 의존하지 않는다.", "온도가 높으면 커진다.", "휘발성이 다르다."], "dx": "증기압이 액체 양과 무관한 세기 성질이고 온도가 높을수록·휘발성이 클수록 커진다는 점을 놓친 경우다. 증기압의 성격이 흐리면 끓는점·휘발성 비교가 어긋난다.", "fix": "증기압을 '액체 양과 무관한 세기 성질이고 온도가 높을수록·휘발성이 클수록 큼'으로 못 박는다. 양에 안 변함을 잡아 끓는점·휘발성 비교에 써라.", "cite": ""}, "CH1-278": {"name": "증기압과 온도", "course": "ch1", "unit": "Ⅲ-3", "tier": "C", "mis": ["증발이 활발해진다.", "증발이 줄어든다.", "온도가 높으면 커진다."], "dx": "온도가 높을수록 증발이 활발해져 증기압이 커진다는 점을 놓친 경우다. 온도와 증기압의 방향이 흔들리면 증기압 곡선·끓음 조건 해석이 어긋난다.", "fix": "'온도가 높을수록 증발이 활발해져 증기압이 커짐'을 못 박는다. 이 방향으로 증기압 곡선과 끓음 조건을 해석하라.", "cite": ""}, "CH1-279": {"name": "증기압 평형", "course": "ch1", "unit": "Ⅲ-3", "tier": "C", "mis": ["증발과 응축 속도가 같다.", "동적인 상태이다."], "dx": "증기압이 증발 속도와 응축 속도가 같아진 동적 평형에서의 증기 압력이라는 점을 놓친 경우다. 평형과 증기압의 연결이 약하면 증기압을 단순 '증발한 양'으로 오해한다.", "fix": "증기압을 '증발 속도와 응축 속도가 같아진 동적 평형에서의 증기 압력'으로 못 박는다. 단순 '증발한 양'이 아님을 잡아라.", "cite": ""}, "CH1-280": {"name": "끓음", "course": "ch1", "unit": "Ⅲ-3", "tier": "C", "mis": ["전체에서 일어난다.", "같아져야 끓는다.", "증기압 = 외부 압력이다."], "dx": "끓음이 증기압이 외부 압력과 같아질 때 액체 내부 전체에서 기화가 일어나는 현상이라는 점을 놓친 경우다. 표면 증발과의 차이가 약하면 끓는점 조건을 못 잡는다.", "fix": "끓음을 '증기압이 외부 압력과 같아질 때 액체 내부 전체에서 기화가 일어나는 현상'으로 못 박는다. 표면 증발과의 차이로 끓는점 조건을 잡아라.", "cite": ""}, "CH1-281": {"name": "끓는점과 압력", "course": "ch1", "unit": "Ⅲ-3", "tier": "B", "mis": ["낮은 증기압에서 끓는다.", "높은 압력에서 끓는다.", "높은 증기압이 필요하다.", "외부 압력이 낮다."], "dx": "외부 압력이 낮으면 더 낮은 증기압에서도 같아져 더 낮은 온도에서 끓는다는 점을 놓친 경우다. 압력과 끓는점의 관계가 흔들리면 높은 산에서 끓는점이 낮은 까닭을 못 짚는다.", "fix": "'외부 압력이 낮으면 더 낮은 증기압에서도 같아져 더 낮은 온도에서 끓음'을 못 박는다. 높은 산에서 끓는점이 낮은 까닭을 이로 설명하라.", "cite": ""}, "CH1-282": {"name": "승화", "course": "ch1", "unit": "Ⅲ-3", "tier": "C", "mis": ["액체를 거치지 않는다.", "고체에서 시작한다.", "승화가 그 예이다."], "dx": "승화가 액체를 거치지 않고 고체에서 바로 기체로(또는 반대로) 변하는 상변화라는 점을 놓친 경우다. 이 경로가 약하면 드라이아이스 같은 예를 상변화로 분류하지 못한다.", "fix": "승화를 '액체를 거치지 않고 고체에서 바로 기체로(또는 반대로) 변하는 상변화'로 못 박는다. 드라이아이스를 예로 상변화로 분류하라.", "cite": ""}, "CH1-283": {"name": "용해·석출 평형", "course": "ch1", "unit": "Ⅲ-3", "tier": "C", "mis": ["동적인 상태이다.", "두 속도가 같아야 한다."], "dx": "포화 용액에서 용해와 석출이 같은 속도로 일어나는 동적 평형이라는 점을 놓친 경우다. 두 속도가 같다는 점이 약하면 포화 상태를 '더는 아무 일도 없는 상태'로 오해한다.", "fix": "'포화 용액에서 용해와 석출이 같은 속도로 일어나는 동적 평형'을 못 박는다. 두 속도가 같음을 잡아 포화를 '아무 일 없는 상태'로 오해하지 마라.", "cite": ""}, "CH1-284": {"name": "포화 용액", "course": "ch1", "unit": "Ⅲ-3", "tier": "B", "mis": ["동적인 상태이다."], "dx": "포화 용액을 용해가 멈춘 상태로 보고, 용해와 석출이 같은 속도로 계속되는 동적 상태라는 점을 놓친 경우다. 이 동적 본질이 약하면 온도 변화에 따른 평형 이동을 설명하지 못한다.", "fix": "포화 용액을 '용해가 멈춘 게 아니라 용해·석출이 같은 속도로 계속되는 동적 상태'로 못 박는다. 이 동적 본질로 온도 변화에 따른 이동을 설명하라.", "cite": ""}, "CH1-285": {"name": "불포화 용액", "course": "ch1", "unit": "Ⅲ-3", "tier": "C", "mis": ["더 녹는 중이다.", "아직 포화되지 않았다.", "용해가 우세하다."], "dx": "불포화 용액이 아직 포화에 못 미쳐 용해가 우세하게 더 녹는 중인 상태라는 점을 놓친 경우다. 포화와의 대비가 약하면 용액 상태를 가리지 못한다.", "fix": "불포화 용액을 '아직 포화에 못 미쳐 용해가 우세하게 더 녹는 중'으로 못 박는다. 포화와 대비해 용액 상태를 가려라.", "cite": ""}, "CH1-286": {"name": "과포화 용액", "course": "ch1", "unit": "Ⅲ-3", "tier": "C", "mis": ["용해도를 넘어선다.", "작은 자극에도 석출된다.", "이미 과포화이다."], "dx": "과포화 용액이 용해도를 넘게 녹은 불안정한 상태라 작은 자극에도 석출된다는 점을 놓친 경우다. 이 불안정성이 약하면 과포화를 그냥 진한 용액으로 오해한다.", "fix": "과포화 용액을 '용해도를 넘게 녹은 불안정한 상태라 작은 자극에도 석출됨'으로 못 박는다. 그냥 진한 용액으로 오해하지 마라.", "cite": ""}, "CH1-287": {"name": "용해도", "course": "ch1", "unit": "Ⅲ-3", "tier": "C", "mis": ["온도에 의존한다.", "물질마다 다르다."], "dx": "용해도가 일정 온도에서 녹을 수 있는 최대량이고 물질·온도마다 다르다는 점을 놓친 경우다. 용해도의 정의가 흐리면 용해도 곡선·포화 판정이 어긋난다.", "fix": "용해도를 '일정 온도에서 녹을 수 있는 최대량이고 물질·온도마다 다름'으로 못 박는다. 이 정의로 용해도 곡선·포화 판정을 잡아라.", "cite": ""}, "CH1-288": {"name": "고체 용해도와 온도", "course": "ch1", "unit": "Ⅲ-3", "tier": "C", "mis": ["온도에 비례하는 경향이다.", "온도에 의존한다.", "고체 용해도가 커진다."], "dx": "대부분의 고체가 온도가 높을수록 용해도가 커진다는 경향을 놓친 경우다. 이 경향이 약하면 온도를 내릴 때 석출되는(재결정) 현상을 설명하지 못한다.", "fix": "'대부분의 고체는 온도가 높을수록 용해도가 커짐'을 못 박는다. 온도를 내릴 때 석출되는(재결정) 현상을 이로 설명하라.", "cite": ""}, "CH1-289": {"name": "기체 용해도와 온도", "course": "ch1", "unit": "Ⅲ-3", "tier": "B", "mis": ["입자가 빠져나간다.", "입자가 덜 빠져나간다.", "온도가 낮을수록 용해도가 크다.", "경향이 반대이다."], "dx": "기체는 온도가 높을수록 입자가 빠져나가 용해도가 작아진다는(고체와 반대) 점을 놓친 경우다. 이 반대 경향이 약하면 따뜻한 탄산음료가 김 빠지는 까닭, 화학Ⅱ 용해 단원이 흔들린다.", "fix": "'기체는 온도가 높을수록 빠져나가 용해도가 작아짐(고체와 반대)'을 못 박는다. 따뜻한 탄산음료가 김 빠지는 까닭을 이로 설명하고 화학Ⅱ로 이어라.", "cite": ""}, "CH1-290": {"name": "기체 용해도와 압력", "course": "ch1", "unit": "Ⅲ-3", "tier": "C", "mis": ["용해도가 커진다.", "헨리 법칙에 따른다."], "dx": "기체 용해도가 압력이 높을수록 커진다는(헨리 법칙) 점을 놓친 경우다. 이 압력 의존이 약하면 화학Ⅱ 헨리 법칙으로 이어지지 못한다.", "fix": "'기체 용해도는 압력이 높을수록 커짐(헨리 법칙)'을 못 박는다. 이 압력 의존을 화학Ⅱ 헨리 법칙의 출발로 삼아라.", "cite": ""}, "CH1-291": {"name": "용해 평형", "course": "ch1", "unit": "Ⅲ-3", "tier": "C", "mis": ["동적인 상태이다.", "용해와 석출 속도가 같다."], "dx": "용해 평형에서 용해와 석출 속도가 같아 겉보기 농도가 일정한 동적 상태라는 점을 놓친 경우다. 이 평형의 동적 본질이 약하면 포화 용액의 거동을 잘못 그린다.", "fix": "용해 평형을 '용해와 석출 속도가 같아 겉보기 농도가 일정한 동적 상태'로 못 박는다. 이 동적 본질로 포화 용액의 거동을 그려라.", "cite": ""}, "CH1-292": {"name": "동적 평형 예", "course": "ch1", "unit": "Ⅲ-3", "tier": "C", "mis": ["멈춘 것이 아니다.", "동적인 상태이다.", "용해와 석출이 계속 일어난다."], "dx": "증발·응축, 용해·석출 같은 동적 평형의 예가 멈춘 게 아니라 양방향이 계속 일어나는 상태라는 점을 놓친 경우다. 여러 예를 멈춤으로 오해하면 동적 평형 개념 전체가 흔들린다.", "fix": "증발·응축, 용해·석출 같은 예를 '멈춘 게 아니라 양방향이 계속 일어나는 동적 평형'으로 못 박는다. 여러 예를 멈춤으로 오해하지 않게 양방향 그림을 새겨라.", "cite": ""}, "CH1-294": {"name": "용액 구성", "course": "ch1", "unit": "Ⅳ-1", "tier": "C", "mis": ["용질은 녹는 물질이다.", "용매는 녹이는 물질이다.", "물이 소금을 녹인다."], "dx": "용질(녹는 물질)과 용매(녹이는 물질)의 역할을 가르지 못한 경우다. 둘을 뒤바꾸면 농도 정의의 분자·분모가 어긋나 모든 농도 계산이 틀어진다.", "fix": "'용질 = 녹는 물질, 용매 = 녹이는 물질'로 역할을 갈라 둔다. 소금물에서 소금(용질)·물(용매)을 짚어 농도 정의의 분자·분모를 맞춰라.", "cite": ""}, "CH1-295": {"name": "퍼센트 농도", "course": "ch1", "unit": "Ⅳ-1", "tier": "C", "mis": ["분모는 용액의 질량이다.", "용액 질량으로 나눈다.", "질량 기준이다."], "dx": "퍼센트 농도의 분모가 용질이 아니라 용액 전체 질량이라는 점을 놓친 경우다. 분모를 잘못 잡으면 질량 백분율이 어긋나 농도 환산이 막힌다.", "fix": "퍼센트 농도를 '용액 전체 질량에 대한 용질 질량의 백분율'로 못 박는다. 분모가 용질이 아니라 용액임을 확인하고 질량 백분율을 계산하라.", "cite": ""}, "CH1-296": {"name": "몰농도 정의", "course": "ch1", "unit": "Ⅳ-1", "tier": "B", "mis": ["용액의 부피이다.", "질량이 아니라 몰수이다.", "부피 기준이다."], "dx": "몰농도가 용질의 질량이 아니라 몰수를, 용매가 아니라 용액 부피로 나눈 값이라는 정의를 놓친 경우다. 이 정의가 흔들리면 몰농도 계산의 분자·분모가 모두 어긋난다.", "fix": "몰농도를 '용질 몰수 ÷ 용액 부피'로 못 박는다(질량·용매가 아님). 분자에 몰수, 분모에 용액 부피를 두고 계산해 굳혀라.", "cite": ""}, "CH1-297": {"name": "몰농도 단위", "course": "ch1", "unit": "Ⅳ-1", "tier": "C", "mis": ["질량이 아니라 몰수이다.", "부피(L) 기준이다.", "몰수 기준이다."], "dx": "몰농도 단위가 용액 부피(L)당 몰수(mol/L)라는 점을 놓친 경우다. 단위 감각이 흐리면 질량 기준 농도와 섞어 쓴다.", "fix": "몰농도 단위를 '용액 부피(L)당 몰수(mol/L)'로 못 박는다. 단위로 질량 기준 농도와 안 섞이게 mol/L를 늘 붙여라.", "cite": ""}, "CH1-298": {"name": "몰농도 계산", "course": "ch1", "unit": "Ⅳ-1", "tier": "C", "mis": ["1 / 0.5 = 2이다.", "1 / 2 = 0.5이다.", "부피가 필요하다."], "dx": "몰농도를 (용질 몰수 ÷ 용액 부피)로 셈하는 게 흔들린 경우다. 어느 쪽을 나누는지 헷갈리면 농도 값이 뒤집힌다.", "fix": "몰농도를 '용질 몰수 ÷ 용액 부피'로 셈한다. 어느 쪽을 나누는지 헷갈리지 않게 분자·분모를 적고 계산하라.", "cite": ""}, "CH1-299": {"name": "용액 제조", "course": "ch1", "unit": "Ⅳ-1", "tier": "C", "mis": ["용질을 먼저 넣는다.", "용액 부피가 기준이다.", "비커는 부피가 부정확하다."], "dx": "정해진 몰농도 용액을 만들 때 용질을 녹인 뒤 용액의 최종 부피를 맞춘다는 절차를 놓친 경우다. 부피가 기준이라는 점이 약하면 농도가 맞지 않게 제조한다.", "fix": "용액 제조를 '용질을 녹인 뒤 용액의 최종 부피를 맞춤(부피가 기준)'으로 못 박는다. 부피 플라스크로 정해진 부피까지 채우는 절차를 따라가라.", "cite": ""}, "CH1-300": {"name": "몰농도 기준 부피", "course": "ch1", "unit": "Ⅳ-1", "tier": "C", "mis": ["용액 부피이다.", "용질이 부피를 차지한다.", "용액 전체 부피이다."], "dx": "몰농도의 기준이 용매가 아니라 용질까지 포함한 용액 전체 부피라는 점을 놓친 경우다. 용매 부피로 잡으면 농도가 어긋난다.", "fix": "몰농도의 기준을 '용매가 아니라 용질까지 포함한 용액 전체 부피'로 못 박는다. 용매 부피로 잡지 않도록 '용액 부피'를 분모로 써라.", "cite": ""}, "CH1-301": {"name": "희석", "course": "ch1", "unit": "Ⅳ-1", "tier": "B", "mis": ["용매만 더한다.", "부피가 늘어난다."], "dx": "희석이 용매만 더해 부피를 늘리는 것이고 용질 몰수는 그대로라는 점을 놓친 경우다. 몰수 보존을 놓치면 희석 후 농도를 못 구한다.", "fix": "희석을 '용매만 더해 부피를 늘리고 용질 몰수는 그대로'로 못 박는다. 몰수 보존을 잡아 희석 후 농도를 구하라.", "cite": ""}, "CH1-302": {"name": "희석 계산", "course": "ch1", "unit": "Ⅳ-1", "tier": "C", "mis": ["부피가 늘어 농도는 작아진다.", "부피가 2배가 된다.", "용질 몰수가 일정하다."], "dx": "희석에서 용질 몰수가 보존돼 (처음 농도 × 부피 = 나중 농도 × 부피)라는 관계를 놓친 경우다. 이 식이 약하면 희석 농도 계산이 어긋난다.", "fix": "희석을 '처음 농도 × 부피 = 나중 농도 × 부피(용질 몰수 보존)'로 못 박는다. 이 식에 값을 넣어 희석 농도를 직접 구하라.", "cite": ""}, "CH1-303": {"name": "농도 환산", "course": "ch1", "unit": "Ⅳ-1", "tier": "C", "mis": ["질량과 부피를 연결한다.", "질량과 몰수를 연결한다.", "두 값으로 환산한다."], "dx": "농도 단위를 환산할 때 밀도가 질량과 부피를 잇는 다리라는 점을 놓친 경우다. 밀도를 빼먹으면 퍼센트 농도와 몰농도 사이 환산이 막힌다.", "fix": "농도 환산에서 '밀도가 질량과 부피를 잇는 다리'임을 못 박는다. 퍼센트 농도와 몰농도 사이를 밀도로 건너 환산하라.", "cite": ""}, "CH1-304": {"name": "몰농도와 온도", "course": "ch1", "unit": "Ⅳ-1", "tier": "C", "mis": ["부피가 온도에 따라 변한다.", "부피는 온도에 의존한다.", "용질의 몰수는 변하지 않는다."], "dx": "몰농도가 부피 기준이라 온도가 오르면 부피가 늘어 값이 작아진다는 점(용질 몰수는 그대로)을 놓친 경우다. 이걸 놓치면 온도가 다른 용액의 농도 비교가 어긋난다.", "fix": "'몰농도는 부피 기준이라 온도가 오르면 부피가 늘어 값이 작아짐(용질 몰수는 그대로)'을 못 박는다. 온도가 다른 용액을 비교할 때 이를 반영하라.", "cite": ""}, "CH1-305": {"name": "퍼센트 농도와 온도", "course": "ch1", "unit": "Ⅳ-1", "tier": "C", "mis": ["질량 기준이다.", "질량으로 정한다."], "dx": "퍼센트 농도가 질량 기준이라 온도에 무관하다는 점을 놓친 경우다. 몰농도와 달리 온도로 안 변한다는 대비가 약하면 농도 비교를 잘못한다.", "fix": "'퍼센트 농도는 질량 기준이라 온도에 무관'함을 못 박는다. 몰농도와 달리 온도로 안 변함을 대비해 농도 비교에 써라.", "cite": ""}, "CH1-306": {"name": "몰수와 부피", "course": "ch1", "unit": "Ⅳ-1", "tier": "C", "mis": ["부피에 비례한다."], "dx": "같은 농도에서 용질 몰수가 용액 부피에 비례한다는 점을 놓친 경우다. 부피를 두 배로 하면 몰수도 두 배라는 감각이 약하면 양 계산이 어긋난다.", "fix": "'같은 농도에서 용질 몰수는 용액 부피에 비례'함을 못 박는다. 부피를 두 배로 하면 몰수도 두 배임을 잡아 양을 계산하라.", "cite": ""}, "CH1-307": {"name": "몰수 계산", "course": "ch1", "unit": "Ⅳ-1", "tier": "C", "mis": ["1 × 0.5 = 0.5이다.", "0.1 × 2 = 0.2이다.", "곱으로 구한다."], "dx": "용질 몰수를 (몰농도 × 부피)로 셈하는 게 흔들린 경우다. 곱으로 구한다는 점이 약하면 용액 속 용질 양을 못 구한다.", "fix": "용질 몰수를 '몰농도 × 부피'로 셈한다. 곱으로 구함을 잡아 용액 속 용질 양을 직접 구하라.", "cite": ""}, "CH1-308": {"name": "몰수 환산", "course": "ch1", "unit": "Ⅳ-1", "tier": "C", "mis": ["나누어야 한다.", "질량 / 몰질량이다.", "몰질량으로 나눈다."], "dx": "몰수를 (질량 ÷ 몰질량)으로 환산하는 게 흔들린 경우다. 나누는 방향이 헷갈리면 질량과 몰수를 못 잇는다.", "fix": "몰수를 '질량 ÷ 몰질량'으로 환산한다. 나누는 방향을 헷갈리지 않게 질량을 몰질량으로 나눠 몰수를 이으라.", "cite": ""}, "CH1-309": {"name": "농도 비교", "course": "ch1", "unit": "Ⅳ-1", "tier": "C", "mis": ["몰질량이 영향을 준다.", "농도가 높을수록 많다.", "단순 비례가 아니다."], "dx": "같은 질량·부피라도 몰질량이 다르면 몰농도가 다르다는 점을 놓친 경우다. 농도를 단순 양 비례로만 보면 서로 다른 물질의 농도 비교가 어긋난다.", "fix": "'같은 질량·부피라도 몰질량이 다르면 몰농도가 다름'을 못 박는다. 농도를 단순 양 비례로 보지 말고 몰질량을 반영해 비교하라.", "cite": ""}, "CH1-310": {"name": "실험 기구", "course": "ch1", "unit": "Ⅳ-1", "tier": "C", "mis": ["비커는 부정확하다.", "정밀한 기구이다.", "정밀한 기구가 필요하다."], "dx": "정확한 부피 측정에 비커가 아니라 부피 플라스크·피펫 같은 정밀 기구를 써야 한다는 점을 놓친 경우다. 기구 선택이 약하면 제조한 농도의 정확도가 떨어진다.", "fix": "정확한 부피 측정에 '비커가 아니라 부피 플라스크·피펫 같은 정밀 기구'를 써야 함을 못 박는다. 제조 농도의 정확도를 위해 기구를 가려 쓰라.", "cite": ""}, "CH1-311": {"name": "용액 부피", "course": "ch1", "unit": "Ⅳ-1", "tier": "C", "mis": ["부피 변화가 있다.", "용질도 부피를 차지한다."], "dx": "용질이 녹으면 부피가 달라질 수 있어 용매 부피가 아니라 용액 부피를 따로 맞춰야 한다는 점을 놓친 경우다. 이걸 놓치면 몰농도가 어긋난다.", "fix": "'용질이 녹으면 부피가 달라질 수 있어 용매 부피가 아니라 용액 부피를 따로 맞춤'을 못 박는다. 용액 부피를 기준으로 제조해 몰농도를 맞춰라.", "cite": ""}, "CH1-312": {"name": "자동이온화", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["자동이온화가 일어난다.", "1:1로 생긴다.", "자동이온화 때문이다."], "dx": "물이 스스로 H⁺와 OH⁻로 조금 갈라지는(자동 이온화) 1:1 평형이라는 점을 놓친 경우다. 이 자동 이온화가 약하면 물 이온곱·pH의 토대가 사라진다.", "fix": "'물이 스스로 H⁺와 OH⁻로 조금 갈라지는(자동 이온화) 1:1 평형'을 못 박는다. 이 자동 이온화를 물 이온곱·pH의 토대로 삼아라.", "cite": ""}, "CH1-313": {"name": "물의 이온곱", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["곱이다.", "10⁻¹⁴이다."], "dx": "물 이온곱이 [H⁺]와 [OH⁻]의 곱이고 25°C에서 10⁻¹⁴이라는 점을 놓친 경우다. 이 곱이 흔들리면 한쪽 농도로 다른 쪽을 구하는 모든 계산이 막힌다.", "fix": "물 이온곱을 '[H⁺]와 [OH⁻]의 곱으로 25°C에서 10⁻¹⁴'로 못 박는다. 이 곱으로 한쪽 농도에서 다른 쪽을 구하는 데 써라.", "cite": ""}, "CH1-314": {"name": "중성 농도", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["10⁻⁷이다.", "두 이온 농도가 같다."], "dx": "25°C 중성에서 [H⁺]=[OH⁻]=10⁻⁷ mol/L이라는 기준값을 놓친 경우다. 이 값이 흐리면 산성·염기성을 가르는 기준이 사라진다.", "fix": "'25°C 중성에서 [H⁺]=[OH⁻]=10⁻⁷ mol/L'를 기준값으로 못 박는다. 이 값을 산성·염기성을 가르는 기준으로 삼아라.", "cite": ""}, "CH1-315": {"name": "순수한 물", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["두 이온 농도가 같다.", "중성이다."], "dx": "순수한 물이 [H⁺]=[OH⁻]라 중성이라는 점을 놓친 경우다. 두 이온이 같다는 중성 조건이 약하면 액성 판정이 어긋난다.", "fix": "'순수한 물은 [H⁺]=[OH⁻]라 중성'임을 못 박는다. 두 이온이 같다는 중성 조건으로 액성을 판정하라.", "cite": ""}, "CH1-316": {"name": "Kw와 온도", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["평형 상수이기 때문이다.", "온도에 의존한다."], "dx": "물 이온곱 상수가 평형 상수라 온도에만 의존한다는 점을 놓친 경우다. 온도가 바뀌면 10⁻¹⁴도 달라진다는 점이 약하면 비표준 온도 문제가 어긋난다.", "fix": "'물 이온곱 상수는 평형 상수라 온도에만 의존'함을 못 박는다. 온도가 바뀌면 10⁻¹⁴도 달라짐을 비표준 온도 문제에 반영하라.", "cite": ""}, "CH1-317": {"name": "pH 정의", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["음의 로그이다.", "음의 로그이기 때문이다.", "-log(10⁻³) = 3이다."], "dx": "pH가 [H⁺]의 음의 로그(-log[H⁺])라는 정의를 놓친 경우다. 정의가 흔들리면 농도에서 pH를 못 구한다.", "fix": "pH를 '[H⁺]의 음의 로그(-log[H⁺])'로 못 박는다. 이 정의로 농도에서 pH를 직접 구하라.", "cite": ""}, "CH1-318": {"name": "pOH 정의", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["음의 로그이다.", "음의 로그이기 때문이다.", "-log(10⁻³) = 3이다."], "dx": "pOH가 [OH⁻]의 음의 로그라는 정의를 놓친 경우다. pH와 짝을 이루는 이 정의가 약하면 염기성 정량 계산이 막힌다.", "fix": "pOH를 '[OH⁻]의 음의 로그'로 못 박는다. pH와 짝지어 염기성 용액의 정량 계산에 써라.", "cite": ""}, "CH1-319": {"name": "pH+pOH", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["Kw = 10⁻¹⁴에서 나온다.", "합이 14이다.", "14 - 3 = 11이다."], "dx": "25°C에서 물 이온곱 10⁻¹⁴로부터 pH + pOH = 14가 나온다는 점을 놓친 경우다. 이 관계가 약하면 pH와 pOH를 서로 환산하지 못한다.", "fix": "'25°C에서 pH + pOH = 14(물 이온곱 10⁻¹⁴에서 나옴)'를 못 박는다. 한쪽에서 다른 쪽을 14에서 빼 환산하라.", "cite": ""}, "CH1-320": {"name": "산성 판정", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["[H⁺]가 크다.", "수소 이온이 더 많다.", "[H⁺]가 더 크다."], "dx": "산성이 [H⁺]가 [OH⁻]보다 많은(중성 10⁻⁷보다 큰) 상태라는 점을 놓친 경우다. 두 이온의 대소로 산성을 가르지 못하면 액성 판정이 어긋난다.", "fix": "'산성 = [H⁺]가 [OH⁻]보다 많음(중성 10⁻⁷보다 큼)'을 못 박는다. 두 이온의 대소로 산성을 가려라.", "cite": ""}, "CH1-321": {"name": "중성 판정", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["[H⁺] = [OH⁻]이다.", "두 이온 농도가 같다.", "pH 0은 강한 산성이다."], "dx": "중성이 [H⁺]=[OH⁻]인 상태라는 점을 놓친 경우다(pH 0은 강산성이지 중성이 아님). 중성 조건이 흐리면 산성·염기성과의 경계를 못 잡는다.", "fix": "'중성 = [H⁺]=[OH⁻]'를 못 박는다(pH 0은 강산성이지 중성 아님). 중성 조건으로 산성·염기성과의 경계를 잡아라.", "cite": ""}, "CH1-322": {"name": "염기성 판정", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["[OH⁻]가 더 많다.", "수산화 이온이 더 많다.", "[OH⁻]가 더 크다."], "dx": "염기성이 [OH⁻]가 [H⁺]보다 많은 상태라는 점을 놓친 경우다. 두 이온의 대소로 염기성을 가르지 못하면 액성 판정이 어긋난다.", "fix": "'염기성 = [OH⁻]가 [H⁺]보다 많음'을 못 박는다. 두 이온의 대소로 염기성을 가려라.", "cite": ""}, "CH1-323": {"name": "산성 이온 농도", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["수소 이온이 더 많다.", "중성보다 크다."], "dx": "산성에서 [H⁺]가 중성 농도(10⁻⁷)보다 크다는 점을 놓친 경우다. 기준 농도와의 비교가 약하면 농도값으로 액성을 못 가린다.", "fix": "'산성에서 [H⁺]가 중성 농도(10⁻⁷)보다 큼'을 못 박는다. 기준 농도와 견줘 농도값으로 액성을 가려라.", "cite": ""}, "CH1-324": {"name": "염기성 이온 농도", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["수산화 이온이 더 많다."], "dx": "염기성에서 [OH⁻]가 중성 농도보다 크다는 점을 놓친 경우다. 기준과의 비교가 약하면 농도값으로 염기성을 못 가린다.", "fix": "'염기성에서 [OH⁻]가 중성 농도보다 큼'을 못 박는다. 기준과 견줘 농도값으로 염기성을 가려라.", "cite": ""}, "CH1-325": {"name": "pH-농도 관계", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["음의 로그이기 때문이다.", "로그 척도이다."], "dx": "pH가 [H⁺]의 음의 로그라 농도가 클수록 pH가 작아진다는 반대 관계를 놓친 경우다. 이 방향이 흔들리면 어느 용액이 더 산성인지 못 가린다.", "fix": "'pH는 [H⁺]의 음의 로그라 농도가 클수록 pH가 작아짐'을 못 박는다. 이 반대 방향으로 어느 용액이 더 산성인지 가려라.", "cite": ""}, "CH1-326": {"name": "pH 비교", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["pH 차이 2 = 100배이다.", "pH가 작을수록 [H⁺]가 크다.", "로그 척도이다."], "dx": "pH가 로그 척도라 pH 차이 1이 [H⁺] 10배(차이 2면 100배)라는 점을 놓친 경우다. 척도 감각이 없으면 pH 차이를 농도 비로 환산하지 못한다.", "fix": "'pH는 로그 척도라 차이 1이 [H⁺] 10배(차이 2면 100배)'임을 못 박는다. pH 차를 농도 비로 환산하는 연습을 하라.", "cite": ""}, "CH1-327": {"name": "pH 계산", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["-log(10⁻³) = 3이다.", "-log(10⁻¹¹) = 11이다.", "-log(10⁻⁵) = 5이다."], "dx": "[H⁺]에서 pH = -log[H⁺]로 계산하는 게 흔들린 경우다. 10의 거듭제곱 농도에서 지수를 pH로 옮기는 셈이 약하면 답이 어긋난다.", "fix": "[H⁺]에서 'pH = -log[H⁺]'로 계산한다. 10의 거듭제곱 농도에서 지수를 pH로 옮기는 셈을 직접 해 보라.", "cite": ""}, "CH1-328": {"name": "pH-pOH 계산", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["14 - 11 = 3이다.", "14 - 5 = 9이다.", "14 - 7 = 7이다."], "dx": "pH = 14 - pOH(25°C)로 환산하는 게 흔들린 경우다. 한쪽을 구해 14에서 빼는 셈이 약하면 산·염기 정량이 막힌다.", "fix": "'pH = 14 - pOH(25°C)'로 환산한다. 한쪽을 구해 14에서 빼는 셈으로 산·염기 정량을 이으라.", "cite": ""}, "CH1-329": {"name": "지시약", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["염기성에서 변색한다.", "산성에서 붉어진다.", "산성에서 노란색이다."], "dx": "지시약이 액성에 따라 색이 변한다는 점을 놓친 경우다(예: 페놀프탈레인은 염기성에서 붉어짐). 지시약의 변색 방향이 흐리면 색으로 액성을 못 읽는다.", "fix": "'지시약은 액성에 따라 색이 변함'을 못 박는다(페놀프탈레인은 염기성에서 붉어짐). 변색 방향으로 색을 보고 액성을 읽어라.", "cite": ""}, "CH1-330": {"name": "산성 세기", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["[H⁺]가 더 크다.", "수소 이온이 많아야 강하다.", "pH가 더 작다."], "dx": "[H⁺]가 클수록 더 강한 산성이고 그만큼 pH가 작다는 점을 놓친 경우다. 농도와 세기·pH의 연결이 약하면 산성 세기 비교가 어긋난다.", "fix": "'[H⁺]가 클수록 더 강한 산성이고 그만큼 pH가 작음'을 못 박는다. 농도·세기·pH를 이어 산성 세기를 비교하라.", "cite": ""}, "CH1-331": {"name": "염기성 세기", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["수산화 이온이 많아야 강하다.", "[OH⁻]가 더 크다.", "pH가 더 크다."], "dx": "[OH⁻]가 클수록 더 강한 염기성이고 그만큼 pH가 크다는 점을 놓친 경우다. 농도와 세기·pH의 연결이 약하면 염기성 세기 비교가 어긋난다.", "fix": "'[OH⁻]가 클수록 더 강한 염기성이고 그만큼 pH가 큼'을 못 박는다. 농도·세기·pH를 이어 염기성 세기를 비교하라.", "cite": ""}, "CH1-332": {"name": "희석과 pH", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["[H⁺]가 줄어든다.", "[OH⁻]가 줄어든다.", "이온 농도가 묽어진다."], "dx": "산을 물로 희석하면 [H⁺]가 줄어 pH가 7에 가까워진다는 점을 놓친 경우다. 희석이 액성을 중성 쪽으로 미는 효과가 약하면 희석 문제가 어긋난다.", "fix": "'산을 물로 희석하면 [H⁺]가 줄어 pH가 7에 가까워짐'을 못 박는다. 희석이 액성을 중성 쪽으로 미는 효과를 문제에 반영하라.", "cite": ""}, "CH1-333": {"name": "Kw 적용", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["곱이 10⁻¹⁴이다.", "곱이 일정하다."], "dx": "[H⁺]와 [OH⁻]의 곱이 10⁻¹⁴(25°C)로 일정해 한쪽 농도로 다른 쪽을 구한다는 적용을 놓친 경우다. 이 곱을 안 쓰면 [OH⁻]에서 [H⁺]로 못 넘어간다.", "fix": "'[H⁺]와 [OH⁻]의 곱이 10⁻¹⁴(25°C)로 일정'함을 못 박는다. 이 곱으로 [OH⁻]에서 [H⁺]를 구하는 환산을 하라.", "cite": ""}, "CH1-334": {"name": "Kw 일정성", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["액성과 무관하다.", "온도에만 의존한다."], "dx": "물 이온곱이 산성이든 염기성이든 액성과 무관하게 일정(온도에만 의존)하다는 점을 놓친 경우다. 산성이면 곱이 커진다고 오해하면 정량이 어긋난다.", "fix": "'물 이온곱은 산성이든 염기성이든 액성과 무관하게 일정(온도에만 의존)'함을 못 박는다. 산성이면 곱이 커진다고 오해하지 마라.", "cite": ""}, "CH1-335": {"name": "산중염 판정", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["[OH⁻]가 더 많다.", "[H⁺]가 더 많다.", "[H⁺] = [OH⁻]이다."], "dx": "[H⁺]와 [OH⁻]의 대소로 산성·중성·염기성을 가리는 게 흔들린 경우다([H⁺]가 크면 산성 등). 이 기준이 약하면 농도만 주어진 용액의 액성을 못 정한다.", "fix": "'[H⁺]와 [OH⁻]의 대소로 산성·중성·염기성을 가림([H⁺]가 크면 산성 등)'을 못 박는다. 농도만 주어진 용액의 액성을 이 기준으로 정하라.", "cite": ""}, "CH1-336": {"name": "Kw", "course": "ch1", "unit": "Ⅳ-2", "tier": "C", "mis": ["농도는 10⁻⁷이다.", "곱이 10⁻¹⁴이다.", "곱이다."], "dx": "물 이온곱이 10⁻¹⁴라 중성에서 각 이온 농도가 10⁻⁷이 된다는 점을 놓친 경우다. 곱과 중성 농도의 연결이 약하면 액성 기준이 흐려진다.", "fix": "'물 이온곱이 10⁻¹⁴라 중성에서 각 이온 농도가 10⁻⁷'임을 못 박는다. 곱과 중성 농도를 이어 액성 기준을 세워라.", "cite": ""}, "CH1-337": {"name": "중화 정의", "course": "ch1", "unit": "Ⅳ-3", "tier": "C", "mis": ["염도 생긴다.", "산과 염기이다.", "물과 염이 생긴다."], "dx": "중화 반응이 산과 염기가 만나 물과 염을 만드는 반응이라는 점을 놓친 경우다(염도 함께 생김). 생성물이 흐리면 중화 반응식을 잘못 쓴다.", "fix": "중화 반응을 '산과 염기가 만나 물과 염을 만드는 반응(염도 함께 생김)'으로 못 박는다. 생성물을 물과 염으로 잡아 반응식을 써라.", "cite": ""}, "CH1-338": {"name": "알짜 이온 반응식", "course": "ch1", "unit": "Ⅳ-3", "tier": "C", "mis": ["반응에 참여하지 않는다.", "물이 생긴다.", "구경꾼 이온은 제외한다."], "dx": "중화의 알짜 이온 반응식이 H⁺ + OH⁻ → H₂O이고 반응에 참여 안 하는 구경꾼 이온은 뺀다는 점을 놓친 경우다. 구경꾼을 빼는 규칙이 약하면 알짜식을 못 쓴다.", "fix": "중화 알짜 이온식을 'H⁺ + OH⁻ → H₂O(구경꾼 이온은 뺌)'로 못 박는다. 반응에 참여 안 하는 이온을 지워 알짜식을 써라.", "cite": ""}, "CH1-339": {"name": "구경꾼 이온", "course": "ch1", "unit": "Ⅳ-3", "tier": "C", "mis": ["반응에 참여하지 않는다.", "그대로 남는다."], "dx": "구경꾼 이온이 반응에 참여하지 않고 그대로 남아 알짜 이온식에서 빠진다는 점을 놓친 경우다. 무엇이 구경꾼인지 못 가리면 알짜식이 어긋난다.", "fix": "'구경꾼 이온은 반응에 참여 안 하고 그대로 남아 알짜식에서 빠짐'을 못 박는다. 무엇이 구경꾼인지 가려 알짜식을 잡아라.", "cite": ""}, "CH1-340": {"name": "중화점 양적관계", "course": "ch1", "unit": "Ⅳ-3", "tier": "C", "mis": ["1:1로 반응한다."], "dx": "중화점에서 H⁺와 OH⁻가 1:1로 반응해 몰수가 같아진다는 점을 놓친 경우다. 이 1:1 비가 약하면 중화 양적관계가 어긋난다.", "fix": "'중화점에서 H⁺와 OH⁻가 1:1로 반응해 몰수가 같아짐'을 못 박는다. 이 1:1 비를 중화 양적관계의 바탕으로 삼아라.", "cite": ""}, "CH1-341": {"name": "양적관계 식", "course": "ch1", "unit": "Ⅳ-3", "tier": "C", "mis": ["농도와 부피를 곱한다.", "몰수가 같아야 한다.", "농도 × 부피가 몰수이다."], "dx": "중화 양적관계를 (산이 낸 H⁺ 몰수 = 염기가 낸 OH⁻ 몰수)로, 몰수를 농도 × 부피로 잡는 게 흔들린 경우다. 이 식이 약하면 적정 계산이 막힌다.", "fix": "중화 양적관계를 '산이 낸 H⁺ 몰수 = 염기가 낸 OH⁻ 몰수, 몰수 = 농도 × 부피'로 못 박는다. 이 식에 값을 넣어 적정 계산을 하라.", "cite": ""}, "CH1-342": {"name": "가수", "course": "ch1", "unit": "Ⅳ-3", "tier": "C", "mis": ["가수만큼 H⁺를 낸다.", "가수가 2이다.", "내놓는 H⁺ 수를 정한다."], "dx": "산·염기가 가수만큼 H⁺·OH⁻를 내놓아 양적관계에 가수를 반영해야 한다는 점을 놓친 경우다(2가 산은 H⁺ 2몰). 가수를 빼먹으면 중화 양론이 어긋난다.", "fix": "'산·염기는 가수만큼 H⁺·OH⁻를 내놓아 양적관계에 가수를 반영(2가 산은 H⁺ 2몰)'함을 못 박는다. 가수를 곱해 중화량을 셈하라.", "cite": ""}, "CH1-343": {"name": "중화열", "course": "ch1", "unit": "Ⅳ-3", "tier": "C", "mis": ["열을 방출한다.", "발열 반응이다."], "dx": "중화 반응이 발열이라 열을 방출한다는 점을 놓친 경우다. 중화가 발열이라는 점이 약하면 중화열·열화학 연결이 흔들린다.", "fix": "'중화 반응은 발열이라 열을 방출'함을 못 박는다. 중화가 발열임을 중화열·열화학 연결에 써라.", "cite": ""}, "CH1-344": {"name": "중화적정", "course": "ch1", "unit": "Ⅳ-3", "tier": "C", "mis": ["기준 용액이 필요하다.", "여러 방법이 있다.", "양적관계로 구한다."], "dx": "중화적정이 농도를 아는 표준 용액으로 모르는 산·염기 농도를 양적관계로 구하는 방법이라는 점을 놓친 경우다. 이 원리가 약하면 화학Ⅱ 적정 단원이 흔들린다.", "fix": "중화적정을 '농도를 아는 표준 용액으로 모르는 산·염기 농도를 양적관계로 구하는 방법'으로 못 박는다. 이 원리를 화학Ⅱ 적정의 바탕으로 삼아라.", "cite": ""}, "CH1-345": {"name": "양적관계 계산", "course": "ch1", "unit": "Ⅳ-3", "tier": "C", "mis": ["몰수가 같아야 한다.", "OH⁻ 0.01몰 = H⁺ 0.01몰이다."], "dx": "완전 중화에서 H⁺ 몰수 = OH⁻ 몰수로 미지의 농도·부피를 구하는 게 흔들린 경우다. 양변 몰수를 맞추는 셈이 약하면 적정 계산이 어긋난다.", "fix": "'완전 중화에서 H⁺ 몰수 = OH⁻ 몰수'로 미지의 농도·부피를 구한다. 양변 몰수를 맞추는 셈으로 적정 계산을 하라.", "cite": ""}, "CH1-346": {"name": "중화점 pH", "course": "ch1", "unit": "Ⅳ-3", "tier": "C", "mis": ["중성이 된다.", "남는 이온이 없다."], "dx": "강산-강염기 중화점이 남는 이온이 없어 중성(pH 7)이라는 점을 놓친 경우다. 이 기준이 약하면 약산·약염기가 섞일 때 당량점이 왜 중성이 아닌지(화학Ⅱ)로 이어지지 못한다.", "fix": "'강산-강염기 중화점은 남는 이온이 없어 중성(pH 7)'임을 못 박는다. 이 기준에서 약산·약염기가 섞이면 왜 중성이 아닌지(화학Ⅱ)로 이어라.", "cite": ""}, "CH1-347": {"name": "염", "course": "ch1", "unit": "Ⅳ-3", "tier": "C", "mis": ["음이온과 양이온이 결합한다.", "H₂O는 물이다.", "염마다 다르다."], "dx": "염이 산의 음이온과 염기의 양이온이 결합한 물질이라는 점을 놓친 경우다. 염의 구성이 흐리면 염 가수분해로 인한 액성 변화(화학Ⅱ)를 이해하지 못한다.", "fix": "염을 '산의 음이온과 염기의 양이온이 결합한 물질'로 못 박는다. 염의 구성을 잡아 화학Ⅱ 염 가수분해·액성 변화로 이어라.", "cite": ""}, "CH1-348": {"name": "일상의 중화", "course": "ch1", "unit": "Ⅳ-3", "tier": "C", "mis": ["염기로 산을 중화한다.", "산을 중화한다."], "dx": "위산 중화제·제산처럼 일상에서 산을 염기로(또는 반대로) 중화하는 예를 놓친 경우다. 중화의 실제 쓰임이 약하면 응용 문제를 못 잡는다.", "fix": "'위산 중화제·제산처럼 일상에서 산을 염기로(또는 반대로) 중화'함을 못 박는다. 중화의 실제 쓰임을 응용 문제에 연결하라.", "cite": ""}, "CH1-349": {"name": "양적관계 기본", "course": "ch1", "unit": "Ⅳ-3", "tier": "C", "mis": ["1:1로 반응한다.", "H⁺ + OH⁻ → H₂O이다."], "dx": "중화에서 H⁺ + OH⁻ → H₂O로 1:1 반응한다는 기본을 놓친 경우다. 이 1:1 골격이 약하면 가수·농도 보정을 얹을 토대가 사라진다.", "fix": "'중화는 H⁺ + OH⁻ → H₂O로 1:1 반응'함을 골격으로 못 박는다. 이 1:1 위에 가수·농도 보정을 얹어 양적관계를 풀어라.", "cite": ""}, "CH1-350": {"name": "가수 양적관계", "course": "ch1", "unit": "Ⅳ-3", "tier": "C", "mis": ["H⁺ 0.2몰을 내놓는다.", "가수가 2이다."], "dx": "2가 산·염기가 1몰당 H⁺·OH⁻ 2몰을 내놓는다는 점을 양적관계에 반영하는 게 흔들린 경우다. 가수 배수를 빼먹으면 중화량 계산이 어긋난다.", "fix": "'2가 산·염기는 1몰당 H⁺·OH⁻ 2몰을 내놓음'을 양적관계에 반영한다. 가수 배수를 빼먹지 않게 곱해 중화량을 셈하라.", "cite": ""}, "CH1-351": {"name": "중화점 전후", "course": "ch1", "unit": "Ⅳ-3", "tier": "C", "mis": ["OH⁻가 남는다.", "아직 다 반응하지 않았다.", "한쪽 이온이 남는다."], "dx": "중화점 전엔 한쪽 이온이 남고 지나면 다른 쪽이 남는다는 점을 놓친 경우다. 이 전후 구분이 약하면 적정 곡선의 pH 변화를 못 읽는다.", "fix": "'중화점 전엔 한쪽 이온이 남고 지나면 다른 쪽이 남음'을 못 박는다. 이 전후 구분으로 적정 곡선의 pH 변화를 읽어라.", "cite": ""}, "CH1-352": {"name": "중화 생성물", "course": "ch1", "unit": "Ⅳ-3", "tier": "C", "mis": ["중화 반응이다.", "물도 생긴다.", "산이 아니다."], "dx": "중화 반응의 생성물이 물과 염이라는 점을 놓친 경우다(산이 더 생기는 게 아님). 생성물이 흐리면 반응 결과를 잘못 쓴다.", "fix": "'중화 반응의 생성물은 물과 염'임을 못 박는다(산이 더 생기는 게 아님). 생성물을 물과 염으로 잡아 반응 결과를 써라.", "cite": ""}, "CH1-353": {"name": "물 생성", "course": "ch1", "unit": "Ⅳ-3", "tier": "C", "mis": ["구경꾼 이온은 반응하지 않는다.", "OH⁻와 결합한다.", "물이 생긴다."], "dx": "중화에서 H⁺와 OH⁻가 결합해 물이 생기고 구경꾼 이온은 반응하지 않는다는 점을 놓친 경우다. 물이 생기는 핵심 반응을 못 짚으면 알짜식이 어긋난다.", "fix": "'중화에서 H⁺와 OH⁻가 결합해 물이 생기고 구경꾼 이온은 반응 안 함'을 못 박는다. 물이 생기는 핵심 반응을 짚어 알짜식을 잡아라.", "cite": ""}, "CH1-354": {"name": "표준 용액", "course": "ch1", "unit": "Ⅳ-3", "tier": "C", "mis": ["기준이 된다.", "기준이 되기 때문이다.", "기준이 필요하다."], "dx": "표준 용액이 농도를 정확히 아는 기준 용액이라는 점을 놓친 경우다. 기준이 되는 까닭이 약하면 적정에서 미지 농도를 못 구한다.", "fix": "표준 용액을 '농도를 정확히 아는 기준 용액'으로 못 박는다. 기준이 되는 까닭을 잡아 적정에서 미지 농도를 구하라.", "cite": ""}, "CH1-355": {"name": "완전 중화", "course": "ch1", "unit": "Ⅳ-3", "tier": "C", "mis": ["남는 이온이 없어야 한다.", "모두 반응한다.", "1:1로 반응한다."], "dx": "완전 중화가 H⁺와 OH⁻가 모두 반응해 남는 이온이 없는 상태라는 점을 놓친 경우다. 이 조건이 약하면 당량점·중화점 판정이 어긋난다.", "fix": "완전 중화를 'H⁺와 OH⁻가 모두 반응해 남는 이온이 없는 상태'로 못 박는다. 이 조건으로 당량점·중화점을 판정하라.", "cite": ""}, "CH1-356": {"name": "화학식량", "course": "ch1", "unit": "부록", "tier": "C", "mis": ["모두 더한다.", "더한다.", "부피가 아니다."], "dx": "화학식량이 화학식 속 모든 원자 원자량의 합이라는 점을 놓친 경우다. 합으로 구한다는 점이 약하면 몰질량과 그 위에 선 양적관계가 통째로 어긋난다.", "fix": "화학식량을 '화학식 속 모든 원자 원자량의 합'으로 못 박는다. 합으로 구함을 잡아 몰질량·양적관계의 기준으로 삼아라.", "cite": ""}, "CH1-357": {"name": "분자량", "course": "ch1", "unit": "부록", "tier": "C", "mis": ["1×2 + 16 = 18이다.", "12 + 16×2 = 44이다.", "16×2 = 32이다."], "dx": "분자량을 구성 원자 원자량의 합으로 정확히 셈하는 게 흔들린 경우다(예: H₂O는 1×2 + 16 = 18). 첨자만큼 원자량을 곱해 더하지 못하면 몰질량이 어긋난다.", "fix": "분자량을 '구성 원자 원자량을 첨자만큼 곱해 더한 합'으로 못 박는다. H₂O를 1×2 + 16 = 18로 직접 계산해 굳혀라.", "cite": ""}, "CH1-358": {"name": "질량비", "course": "ch1", "unit": "부록", "tier": "C", "mis": ["2:16 = 1:8이다.", "원자 수가 아니라 질량비이다.", "원자량을 곱해야 한다."], "dx": "성분 질량비를 원자 수의 비로 보고, (원자 수 × 원자량)의 비라는 점을 놓친 경우다(물에서 H:O = 2:16 = 1:8). 원자량을 곱하는 단계를 빼면 질량비가 어긋난다.", "fix": "성분 질량비를 '(원자 수 × 원자량)의 비'로 못 박는다(원자 수비가 아님). 물에서 H:O = 2:16 = 1:8을 원자량 곱해 구하라.", "cite": ""}, "CH1-359": {"name": "질량 백분율", "course": "ch1", "unit": "부록", "tier": "C", "mis": ["2/18 × 100이다.", "12/44 × 100이다.", "12/16 × 100이다."], "dx": "성분의 질량 백분율을 (성분 질량 ÷ 전체 화학식량 × 100)으로 구하는 게 흔들린 경우다. 분모를 전체 화학식량으로 잡지 못하면 조성 분석이 어긋난다.", "fix": "질량 백분율을 '(성분 질량 ÷ 전체 화학식량 × 100)'으로 못 박는다. 분모를 전체 화학식량으로 잡아 조성을 분석하라.", "cite": ""}, "CH1-360": {"name": "실험식 정의", "course": "ch1", "unit": "부록", "tier": "C", "mis": ["실제 원자 수는 분자식이다.", "가장 간단한 비이다.", "원자 수의 비이다."], "dx": "실험식이 원자 수의 가장 간단한 정수비라는 점을 놓친 경우다(실제 원자 수는 분자식). 가장 간단한 비라는 정의가 흐리면 실험식을 못 구한다.", "fix": "실험식을 '원자 수의 가장 간단한 정수비'로 못 박는다(실제 원자 수는 분자식). 가장 간단한 비라는 정의로 실험식을 구하라.", "cite": ""}, "CH1-361": {"name": "분자식 정의", "course": "ch1", "unit": "부록", "tier": "C", "mis": ["가장 간단한 비는 실험식이다.", "H₂O처럼 같을 수 있다.", "분자 없는 물질은 실험식이다."], "dx": "분자식이 분자 속 실제 원자 수이고 실험식과 같을 수도(H₂O), 정수배일 수도 있다는 점을 놓친 경우다. 둘의 관계가 흐리면 분자식과 실험식을 혼동한다.", "fix": "분자식을 '분자 속 실제 원자 수(실험식과 같을 수도, 정수배일 수도)'로 못 박는다. 둘의 관계를 잡아 분자식과 실험식을 혼동하지 마라.", "cite": ""}, "CH1-362": {"name": "실험식 구하기", "course": "ch1", "unit": "부록", "tier": "C", "mis": ["2로 나눈다.", "6으로 나눈다."], "dx": "성분 원자 수를 공약수로 나눠 가장 간단한 정수비로 줄이는 게 흔들린 경우다(6:12:6을 1:2:1로). 약분이 약하면 실험식을 못 잡는다.", "fix": "실험식을 '성분 원자 수를 공약수로 나눠 가장 간단한 정수비로 줄여' 구한다. 6:12:6을 1:2:1로 약분해 실험식을 잡아라.", "cite": ""}, "CH1-363": {"name": "실험식·분자식 관계", "course": "ch1", "unit": "부록", "tier": "C", "mis": ["배수가 1이 아닐 수 있다.", "배수를 모른다.", "정수배가 다를 수 있다."], "dx": "분자식이 실험식의 정수배이고 그 배수가 1이 아닐 수 있다는 점을 놓친 경우다. 배수가 늘 1이라 여기면 분자식을 실험식과 같게 잘못 쓴다.", "fix": "'분자식은 실험식의 정수배이고 그 배수가 1이 아닐 수 있음'을 못 박는다. 배수가 늘 1이라 여기지 말고 분자식을 따로 확정하라.", "cite": ""}, "CH1-364": {"name": "실험식→분자식", "course": "ch1", "unit": "부록", "tier": "C", "mis": ["180/30 = 6이다.", "나눈다.", "60/30 = 2배이다."], "dx": "분자량 ÷ 실험식량 = 배수로 실험식에서 분자식을 구하는 게 흔들린 경우다(180/30 = 6배). 이 배수 계산이 약하면 분자식을 확정하지 못한다.", "fix": "'분자량 ÷ 실험식량 = 배수'로 실험식에서 분자식을 구한다. 180/30 = 6배처럼 배수를 구해 분자식을 확정하라.", "cite": ""}, "CH1-365": {"name": "조성 분석", "course": "ch1", "unit": "부록", "tier": "C", "mis": ["나눈다.", "몰수로 환산해야 한다.", "분자량이 있어야 한다."], "dx": "성분 질량(%)을 원자량으로 나눠 몰수비로 환산해야 실험식이 나온다는 점을 놓친 경우다(분자식엔 분자량도 필요). 질량비를 바로 원자 수비로 쓰면 실험식이 어긋난다.", "fix": "조성 분석을 '성분 질량(%)을 원자량으로 나눠 몰수비로 환산해 실험식을 구함(분자식엔 분자량도 필요)'으로 못 박는다. 질량비를 바로 원자 수비로 쓰지 마라.", "cite": ""}, "CH1-366": {"name": "실험식 적용", "course": "ch1", "unit": "부록", "tier": "C", "mis": ["분자가 없다.", "분자식이 항상 쓰이지 않는다."], "dx": "이온 결합 물질처럼 분자가 없는 물질은 분자식이 아니라 실험식으로 나타낸다는 점을 놓친 경우다. 이 적용이 약하면 NaCl 같은 물질에 분자식을 잘못 붙인다.", "fix": "'분자가 없는 이온 결합 물질은 분자식이 아니라 실험식으로 나타냄'을 못 박는다. NaCl 같은 물질에 분자식을 붙이지 않게 가려라.", "cite": ""}, "CH1-367": {"name": "일정 성분비", "course": "ch1", "unit": "부록", "tier": "C", "mis": ["성분비가 일정하다.", "일정 성분비이다.", "혼합물은 비가 일정하지 않다."], "dx": "한 화합물의 성분 질량비가 항상 일정하다는 일정 성분비 법칙을 놓친 경우다(혼합물은 비가 자유로움). 이 법칙이 약하면 화합물과 혼합물을 가르지 못한다.", "fix": "'한 화합물의 성분 질량비는 항상 일정(혼합물은 자유)'이라는 일정 성분비 법칙을 못 박는다. 이 법칙으로 화합물과 혼합물을 가려라.", "cite": ""}, "CH1-368": {"name": "실험식량", "course": "ch1", "unit": "부록", "tier": "C", "mis": ["12 + 1 = 13이다.", "같지 않을 수 있다.", "12 + 2 + 16 = 30이다."], "dx": "실험식량이 실험식 속 원자 원자량의 합이고 분자량과 같지 않을 수 있다는 점을 놓친 경우다. 실험식량을 분자량과 혼동하면 분자식 배수 계산이 어긋난다.", "fix": "실험식량을 '실험식 속 원자 원자량의 합(분자량과 같지 않을 수 있음)'으로 못 박는다. 분자량과 혼동하지 말고 분자식 배수 계산에 써라.", "cite": ""}, "CH1-224": {"name": "엔탈피 정의", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["질량이 아니다.", "변화량으로 다룬다.", "상태가 에너지를 바꾼다."], "dx": "엔탈피를 질량 같은 양으로 오해하거나 절대값으로 다루려 한 경우다. 엔탈피가 일정 압력에서의 열함량이고 절대값 대신 변화량(ΔH)으로 다룬다는 점이 약하면 반응열 계산이 막힌다.", "fix": "엔탈피를 '일정 압력에서의 열함량이고 절대값 대신 변화량(ΔH)으로 다룸'으로 못 박는다. 절대값을 구하려 말고 ΔH로 반응열을 계산하라.", "cite": ""}, "CH1-225": {"name": "반응엔탈피 정의", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["생성물 - 반응물이다.", "처음과 끝 상태로만 정해진다.", "생성물 - 반응물이 음수이다."], "dx": "반응엔탈피가 (생성물 엔탈피 − 반응물 엔탈피)이고 처음·끝 상태로만 정해진다는 점을 놓친 경우다. 이 정의가 약하면 경로와 무관하다는 헤스 법칙으로 이어지지 못한다.", "fix": "반응엔탈피를 '(생성물 엔탈피 − 반응물 엔탈피), 처음·끝 상태로만 정해짐'으로 못 박는다. 경로와 무관함을 잡아 헤스 법칙으로 이어라.", "cite": ""}, "CH1-226": {"name": "발열 ΔH 부호", "course": "ch1", "unit": "엔탈피", "tier": "B", "mis": ["에너지를 방출한다.", "에너지가 줄어든다."], "dx": "발열 반응이 에너지를 방출해 엔탈피가 줄어 ΔH<0이라는 점을 놓친 경우다. 방출=음의 부호라는 약속이 흔들리면 열화학 반응식의 부호가 어긋난다.", "fix": "'발열은 에너지를 방출해 엔탈피가 줄어 ΔH<0'을 못 박는다. 방출 = 음의 부호라는 약속으로 열화학 반응식 부호를 잡아라.", "cite": ""}, "CH1-227": {"name": "흡열 ΔH 부호", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["에너지를 흡수한다.", "에너지가 늘어난다."], "dx": "흡열 반응이 에너지를 흡수해 엔탈피가 늘어 ΔH>0이라는 점을 놓친 경우다. 흡수=양의 부호라는 약속이 약하면 흡열 반응의 ΔH를 잘못 적는다.", "fix": "'흡열은 에너지를 흡수해 엔탈피가 늘어 ΔH>0'을 못 박는다. 흡수 = 양의 부호라는 약속으로 흡열 ΔH를 적어라.", "cite": ""}, "CH1-228": {"name": "발열 온도 변화", "course": "ch1", "unit": "엔탈피", "tier": "B", "mis": ["열을 방출한다.", "에너지를 내보낸다."], "dx": "발열 반응이 열을 방출해 주위 온도를 올린다는 점을 놓친 경우다. 방출과 온도 상승의 연결이 약하면 온도 변화로 발열을 판단하지 못한다.", "fix": "'발열은 열을 방출해 주위 온도를 올림'을 못 박는다. 방출과 온도 상승을 이어 온도 변화로 발열을 판단하라.", "cite": ""}, "CH1-229": {"name": "흡열 온도 변화", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["열을 흡수한다.", "에너지를 받아들인다."], "dx": "흡열 반응이 열을 흡수해 주위 온도를 내린다는 점을 놓친 경우다. 흡수와 온도 하강의 연결이 약하면 온도 변화로 흡열을 판단하지 못한다.", "fix": "'흡열은 열을 흡수해 주위 온도를 내림'을 못 박는다. 흡수와 온도 하강을 이어 온도 변화로 흡열을 판단하라.", "cite": ""}, "CH1-230": {"name": "열화학 반응식", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["ΔH를 함께 쓴다.", "물질의 양에 비례한다.", "발열·흡열을 구분한다."], "dx": "열화학 반응식이 반응식에 ΔH를 함께 쓰고 그 값이 물질의 양(계수)에 비례한다는 점을 놓친 경우다. 양에 비례한다는 점이 약하면 두 배 반응의 열량을 못 구한다.", "fix": "열화학 반응식을 '반응식에 ΔH를 함께 쓰고 그 값이 물질의 양(계수)에 비례'로 못 박는다. 계수를 두 배로 하면 ΔH도 두 배임을 셈하라.", "cite": ""}, "CH1-231": {"name": "열화학 반응식 상태", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["상태가 ΔH를 바꾼다.", "상태마다 엔탈피가 다르다.", "상태가 다르다."], "dx": "물질의 상태(기체·액체·고체)가 ΔH를 바꾸므로 상태를 표기해야 한다는 점을 놓친 경우다. 상태가 같은 물질도 엔탈피가 다르다는 점이 약하면 ΔH가 어긋난다.", "fix": "'물질의 상태(기체·액체·고체)가 ΔH를 바꾸므로 상태를 표기'함을 못 박는다. 상태가 같은 물질도 엔탈피가 다름을 잡아 ΔH를 맞춰라.", "cite": ""}, "CH1-232": {"name": "발열 반응 예", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["열을 흡수한다.", "빛 에너지를 흡수한다.", "주위 온도가 내려간다."], "dx": "연소·중화 같은 발열 반응이 열을 방출해 주위가 따뜻해진다는 점을 놓친 경우다. 발열 예를 흡열로 오해하면 반응 분류가 어긋난다.", "fix": "'연소·중화 같은 반응은 발열이라 주위가 따뜻해짐'을 못 박는다. 발열 예를 흡열로 오해하지 말고 반응을 분류하라.", "cite": ""}, "CH1-233": {"name": "흡열 반응 예", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["흡열 반응이다.", "에너지를 흡수한다.", "열을 흡수한다."], "dx": "광합성·물의 분해 같은 흡열 반응이 에너지를 흡수한다는 점을 놓친 경우다. 흡열 예를 못 짚으면 반응을 발열·흡열로 가르지 못한다.", "fix": "'광합성·물의 분해 같은 반응은 흡열이라 에너지를 흡수'함을 못 박는다. 흡열 예를 짚어 반응을 발열·흡열로 가려라.", "cite": ""}, "CH1-234": {"name": "발열과 엔탈피", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["엔탈피가 줄어든다.", "에너지를 방출한다."], "dx": "발열 반응에서 엔탈피가 줄어든다(ΔH<0)는 점을 놓친 경우다. 방출과 엔탈피 감소의 연결이 약하면 부호 판단이 어긋난다.", "fix": "'발열 반응은 엔탈피가 줄어듦(ΔH<0)'을 못 박는다. 방출과 엔탈피 감소를 이어 부호를 판단하라.", "cite": ""}, "CH1-235": {"name": "흡열과 엔탈피", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["엔탈피가 늘어난다.", "에너지를 흡수한다."], "dx": "흡열 반응에서 엔탈피가 늘어난다(ΔH>0)는 점을 놓친 경우다. 흡수와 엔탈피 증가의 연결이 약하면 부호 판단이 어긋난다.", "fix": "'흡열 반응은 엔탈피가 늘어남(ΔH>0)'을 못 박는다. 흡수와 엔탈피 증가를 이어 부호를 판단하라.", "cite": ""}, "CH1-236": {"name": "정·역반응", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["방향이 반대이다.", "에너지 출입이 반대이다."], "dx": "정반응과 역반응이 에너지 출입 방향이 반대라는 점을 놓친 경우다. 이 대칭이 약하면 역반응 ΔH의 부호를 못 잡는다.", "fix": "'정반응과 역반응은 에너지 출입 방향이 반대'임을 못 박는다. 이 대칭으로 역반응 ΔH의 부호를 잡아라.", "cite": ""}, "CH1-237": {"name": "정·역반응 ΔH", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["방향만 반대이다.", "부호가 반대이다.", "방향이 반대이다."], "dx": "역반응의 ΔH가 정반응과 크기는 같고 부호만 반대라는 점을 놓친 경우다. 이 관계가 약하면 헤스 법칙으로 반응을 조합할 때 부호를 틀린다.", "fix": "'역반응의 ΔH는 정반응과 크기는 같고 부호만 반대'임을 못 박는다. 이 관계로 헤스 법칙에서 반응을 뒤집을 때 부호를 바꿔라.", "cite": ""}, "CH1-238": {"name": "헤스 법칙", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["처음과 끝으로만 정해진다.", "경로와 무관하다."], "dx": "반응엔탈피가 경로와 무관하게 처음·끝 상태로만 정해진다는 헤스 법칙을 놓친 경우다. 경로 독립성이 약하면 여러 단계로 ΔH를 구하는 계산이 막힌다.", "fix": "헤스 법칙을 '반응엔탈피는 경로와 무관하게 처음·끝 상태로만 정해짐'으로 못 박는다. 경로 독립성을 잡아 여러 단계로 ΔH를 구하라.", "cite": ""}, "CH1-239": {"name": "헤스 법칙 적용", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["평균이 아니라 합이다.", "정·역반응 관계이다.", "물질의 양에 비례한다."], "dx": "여러 반응의 ΔH를 더하거나 빼서(평균이 아니라 합) 목표 반응의 ΔH를 구하는 게 흔들린 경우다. 반응을 뒤집거나 배수할 때 ΔH도 함께 바꾸지 못하면 계산이 어긋난다.", "fix": "'여러 반응의 ΔH를 더하거나 빼서(평균이 아니라 합) 목표 ΔH를 구함'을 못 박는다. 반응을 뒤집으면 부호 반대, 배수하면 함께 곱해 계산하라.", "cite": ""}, "CH1-240": {"name": "결합 에너지", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["발열 과정이다.", "흡열 과정이다.", "끊는 데 더 많은 에너지가 든다."], "dx": "결합을 끊는 데 에너지가 필요(흡열)하고 결합을 만들 때 방출(발열)된다는 점을 놓친 경우다. 끊음·만듦의 부호가 흔들리면 결합 에너지로 ΔH를 못 구한다.", "fix": "'결합을 끊는 데 에너지가 필요(흡열), 만들 때 방출(발열)'을 못 박는다. 끊음·만듦의 부호를 잡아 결합 에너지로 ΔH를 구하라.", "cite": ""}, "CH1-241": {"name": "결합 에너지로 ΔH", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["반응물 - 생성물이다.", "양쪽을 모두 본다.", "결합 에너지 차이를 이용한다."], "dx": "반응엔탈피를 (끊은 결합 에너지 합 − 만든 결합 에너지 합)으로 구한다는 점을 놓친 경우다. 양쪽 결합 에너지를 모두 보지 않으면 ΔH가 어긋난다.", "fix": "반응엔탈피를 '(끊은 결합 에너지 합 − 만든 결합 에너지 합)'으로 못 박는다. 양쪽 결합 에너지를 모두 넣어 ΔH를 구하라.", "cite": ""}, "CH1-242": {"name": "결합 에너지 적용", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["만드는 에너지가 더 커야 한다.", "생성물 결합이 더 강해야 발열이다.", "차이가 ΔH가 된다."], "dx": "만드는 결합이 끊는 결합보다 강해 방출 에너지가 더 크면 발열이라는 점을 놓친 경우다. 양쪽 결합 세기 비교가 약하면 반응의 발열·흡열을 못 가린다.", "fix": "'만드는 결합이 끊는 결합보다 강해 방출 에너지가 더 크면 발열'임을 못 박는다. 양쪽 결합 세기를 비교해 발열·흡열을 가려라.", "cite": ""}, "CH1-243": {"name": "상태와 ΔH", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["상태마다 엔탈피가 다르다.", "상태가 다르다."], "dx": "같은 물질도 상태에 따라 엔탈피가 달라 ΔH가 바뀐다는 점을 놓친 경우다(물의 증발열처럼). 상태 의존을 빼면 ΔH가 어긋난다.", "fix": "'같은 물질도 상태에 따라 엔탈피가 달라 ΔH가 바뀜(물의 증발열처럼)'을 못 박는다. 상태 의존을 빼지 말고 ΔH를 맞춰라.", "cite": ""}, "CH1-244": {"name": "흡열 과정 예", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["열을 흡수한다.", "열을 방출한다."], "dx": "융해·기화·물의 분해 같은 흡열 과정이 열을 흡수한다는 점을 놓친 경우다. 흡열 과정을 발열로 오해하면 상변화·반응 분류가 어긋난다.", "fix": "'융해·기화·물의 분해 같은 과정은 흡열이라 열을 흡수'함을 못 박는다. 흡열 과정을 발열로 오해하지 말고 상변화를 분류하라.", "cite": ""}, "CH1-245": {"name": "발열 ΔH 표기", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["에너지를 방출한다.", "음의 값이다."], "dx": "발열 반응의 ΔH를 음의 값으로 표기한다는 점을 놓친 경우다. 방출인데 양수로 적으면 열화학 반응식의 부호가 뒤집힌다.", "fix": "'발열 반응의 ΔH는 음의 값으로 표기'함을 못 박는다. 방출인데 양수로 적지 않게 부호를 음으로 맞춰라.", "cite": ""}, "CH1-246": {"name": "발열·흡열 판단", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["열을 방출했다.", "열을 흡수했다.", "온도가 올라가면 발열이다."], "dx": "온도 변화로 발열·흡열을 판단하는 게 흔들린 경우다(온도 오르면 발열, 내리면 흡열). 이 판단이 약하면 실험에서 반응의 열 성격을 못 읽는다.", "fix": "'온도가 오르면 발열, 내리면 흡열'로 판단함을 못 박는다. 실험에서 온도 변화로 반응의 열 성격을 읽어라.", "cite": ""}, "CH1-247": {"name": "상태 함수", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["상태 함수이다.", "경로와 무관하다."], "dx": "엔탈피가 경로와 무관하게 상태로만 정해지는 상태 함수라는 점을 놓친 경우다. 상태 함수라는 본질이 약하면 헤스 법칙이 왜 성립하는지 근거가 사라진다.", "fix": "엔탈피를 '경로와 무관하게 상태로만 정해지는 상태 함수'로 못 박는다. 이 본질이 헤스 법칙의 근거임을 짚어라.", "cite": ""}, "CH1-293": {"name": "흡열 ΔH 표기", "course": "ch1", "unit": "엔탈피", "tier": "C", "mis": ["에너지를 흡수한다.", "양의 값이다."], "dx": "흡열 반응의 ΔH를 양의 값으로 표기한다는 점을 놓친 경우다. 흡수인데 음수로 적으면 열화학 반응식의 부호가 뒤집힌다.", "fix": "'흡열 반응의 ΔH는 양의 값으로 표기'함을 못 박는다. 흡수인데 음수로 적지 않게 부호를 양으로 맞춰라.", "cite": ""}, "CH2-251": {"name": "아레니우스 정의", "course": "ch2", "unit": "산염기세기", "tier": "C", "mis": ["염기는 OH⁻를 내놓는다.", "산은 H⁺를 내놓는다.", "내놓는 이온이 다르다."], "dx": "아레니우스 정의에서 산이 물에서 H⁺를, 염기가 OH⁻를 내놓는다는 점을 놓친 경우다. 이 기본 정의가 흐리면 브뢴스테드로 확장하는 흐름을 못 짚는다.", "fix": "아레니우스 정의를 '산은 물에서 H⁺를, 염기는 OH⁻를 내놓음'으로 못 박는다. 이 기본 정의에서 브뢴스테드로 확장하는 흐름으로 이어라.", "cite": ""}, "CH2-252": {"name": "브뢴스테드 정의", "course": "ch2", "unit": "산염기세기", "tier": "B", "mis": ["산은 양성자 주개이다.", "염기는 양성자 받개이다.", "양성자 이동으로 정의한다."], "dx": "브뢴스테드 정의에서 산이 양성자(H⁺) 주개, 염기가 양성자 받개라는 점을 놓친 경우다. 양성자 이동으로 산·염기를 보는 관점이 약하면 짝산-짝염기 개념이 안 선다.", "fix": "브뢴스테드 정의를 '산은 양성자(H⁺) 주개, 염기는 양성자 받개'로 못 박는다. 양성자 이동으로 보는 관점으로 짝산-짝염기 개념을 세워라.", "cite": ""}, "CH2-253": {"name": "짝산-짝염기", "course": "ch2", "unit": "산염기세기", "tier": "C", "mis": ["H⁺를 얻는다.", "H⁺ 하나 차이이다.", "H⁺를 잃는다."], "dx": "짝산-짝염기가 H⁺ 하나 차이로 이어진 쌍(산이 H⁺를 잃으면 짝염기)이라는 점을 놓친 경우다. 이 관계가 약하면 산 세기와 짝염기 세기의 반비례를 못 짚는다.", "fix": "짝산-짝염기를 'H⁺ 하나 차이로 이어진 쌍(산이 H⁺를 잃으면 짝염기)'으로 못 박는다. 이 관계로 산 세기와 짝염기 세기의 반비례를 짚어라.", "cite": ""}, "CH2-254": {"name": "양쪽성", "course": "ch2", "unit": "산염기세기", "tier": "C", "mis": ["둘 다 가능하다.", "양쪽성이다."], "dx": "양쪽성 물질이 산으로도 염기로도 작용할 수 있다는(물이 대표적) 점을 놓친 경우다. 양쪽성이 약하면 물의 자동 이온화처럼 같은 물질이 양쪽으로 행동하는 경우를 설명하지 못한다.", "fix": "양쪽성 물질을 '산으로도 염기로도 작용할 수 있음(물이 대표)'으로 못 박는다. 양쪽성으로 물의 자동 이온화처럼 같은 물질이 양쪽으로 행동하는 경우를 설명하라.", "cite": ""}, "CH2-255": {"name": "산 세기", "course": "ch2", "unit": "산염기세기", "tier": "C", "mis": ["이온화 정도가 기준이다.", "세기와 농도는 다르다."], "dx": "산의 세기를 농도와 같은 것으로 본 경우다. 세기가 이온화하는 정도이고 농도(얼마나 많이 녹았나)와는 다른 개념이라는 점을 놓치면 묽은 강산과 진한 약산을 혼동한다.", "fix": "산의 세기를 '이온화하는 정도(농도와 다른 개념)'로 못 박는다. 세기와 농도를 갈라 묽은 강산과 진한 약산을 혼동하지 마라.", "cite": ""}, "CH2-256": {"name": "강산", "course": "ch2", "unit": "산염기세기", "tier": "C", "mis": ["이온화가 거의 완전하다.", "거의 다 이온화한다."], "dx": "강산이 물에서 거의 완전히 이온화하는 산이라는 점을 놓친 경우다. 거의 다 이온화한다는 점이 약하면 강산 용액의 [H⁺]를 잘못 잡는다.", "fix": "강산을 '물에서 거의 완전히 이온화하는 산'으로 못 박는다. 거의 다 이온화함을 잡아 강산 용액의 [H⁺]를 맞춰라.", "cite": ""}, "CH2-257": {"name": "강산 예", "course": "ch2", "unit": "산염기세기", "tier": "C", "mis": ["일부만 이온화한다.", "거의 완전히 이온화한다."], "dx": "HCl·HNO₃·H₂SO₄처럼 거의 완전히 이온화하는 산이 강산이라는 점을 놓친 경우다. 강산 예를 약산과 혼동하면 산 세기 분류가 어긋난다.", "fix": "'HCl·HNO₃·H₂SO₄처럼 거의 완전히 이온화하는 산이 강산'임을 못 박는다. 강산 예를 약산과 혼동하지 말고 분류하라.", "cite": ""}, "CH2-258": {"name": "약산 예", "course": "ch2", "unit": "산염기세기", "tier": "C", "mis": ["일부만 이온화한다."], "dx": "아세트산(CH₃COOH)·탄산처럼 일부만 이온화하는 산이 약산이라는 점을 놓친 경우다. 약산 예를 강산과 혼동하면 산 세기 분류가 어긋난다.", "fix": "'아세트산(CH₃COOH)·탄산처럼 일부만 이온화하는 산이 약산'임을 못 박는다. 약산 예를 강산과 혼동하지 말고 분류하라.", "cite": ""}, "CH2-259": {"name": "약산", "course": "ch2", "unit": "산염기세기", "tier": "C", "mis": ["일부만 이온화한다.", "이온화가 덜 된다."], "dx": "약산이 물에서 일부만 이온화해 이온화 평형을 이룬다는 점을 놓친 경우다. 일부만 이온화한다는 점이 약하면 이온화 상수로 세기를 다루는 단계로 이어지지 못한다.", "fix": "약산을 '물에서 일부만 이온화해 이온화 평형을 이룸'으로 못 박는다. 일부만 이온화함을 잡아 이온화 상수로 세기를 다루는 단계로 이어라.", "cite": ""}, "CH2-260": {"name": "강염기 예", "course": "ch2", "unit": "산염기세기", "tier": "C", "mis": ["일부만 이온화한다.", "거의 완전히 이온화한다.", "이온화가 거의 완전하다."], "dx": "NaOH·KOH처럼 거의 완전히 이온화하는 염기가 강염기라는 점을 놓친 경우다. 강염기 예를 약염기와 혼동하면 염기 세기 분류가 어긋난다.", "fix": "'NaOH·KOH처럼 거의 완전히 이온화하는 염기가 강염기'임을 못 박는다. 강염기 예를 약염기와 혼동하지 말고 분류하라.", "cite": ""}, "CH2-261": {"name": "약염기 예", "course": "ch2", "unit": "산염기세기", "tier": "B", "mis": ["일부만 이온화한다.", "약염기이다.", "이온화가 덜 된다."], "dx": "암모니아(NH₃)처럼 일부만 이온화하는 염기가 약염기라는 점을 놓친 경우다. 약염기 예를 강염기와 혼동하면 염기 세기 분류가 어긋난다.", "fix": "'암모니아(NH₃)처럼 일부만 이온화하는 염기가 약염기'임을 못 박는다. 약염기 예를 강염기와 혼동하지 말고 분류하라.", "cite": ""}, "CH2-262": {"name": "이온화 상수", "course": "ch2", "unit": "산염기세기", "tier": "C", "mis": ["산의 평형 상수이다.", "농도와 무관하다.", "가리키는 대상이 다르다."], "dx": "이온화 상수가 산의 이온화 평형 상수라 농도와 무관하게(온도에만 의존) 물질 고유 값이라는 점을 놓친 경우다. 평형 상수라는 점이 약하면 Kₐ를 농도와 헷갈린다.", "fix": "이온화 상수를 '산의 이온화 평형 상수라 농도와 무관하게(온도에만 의존) 물질 고유 값'으로 못 박는다. 평형 상수임을 잡아 Kₐ를 농도와 헷갈리지 마라.", "cite": ""}, "CH2-263": {"name": "Ka와 세기", "course": "ch2", "unit": "산염기세기", "tier": "A", "mis": ["이온화가 잘 된다.", "이온화가 덜 된다.", "이온 쪽으로 치우친다.", "세기 척도이다."], "dx": "이온화 상수 Kₐ가 클수록 이온화가 잘 돼(이온 쪽으로 치우쳐) 더 강한 산이라는 점을 놓친 경우다. Kₐ가 세기의 척도라는 점이 약하면 두 산의 세기를 비교하지 못한다.", "fix": "'이온화 상수 Kₐ가 클수록 이온화가 잘 돼(이온 쪽으로 치우쳐) 더 강한 산'임을 못 박는다. Kₐ가 세기의 척도임을 잡아 두 산의 세기를 비교하라.", "cite": ""}, "CH2-264": {"name": "Ka 해석", "course": "ch2", "unit": "산염기세기", "tier": "C", "mis": ["이온 쪽으로 치우친다.", "이온화 정도이다.", "이온화가 덜 된다."], "dx": "Kₐ가 크면 이온화 평형이 이온 쪽으로 치우쳐 이온화가 많이 된 것이라는 해석을 놓친 경우다. Kₐ의 대소로 이온화 정도를 못 읽으면 산 세기 해석이 어긋난다.", "fix": "'Kₐ가 크면 이온화 평형이 이온 쪽으로 치우쳐 이온화가 많이 된 것'으로 못 박는다. Kₐ의 대소로 이온화 정도를 읽어 산 세기를 해석하라.", "cite": ""}, "CH2-265": {"name": "Ka·Kb 관계", "course": "ch2", "unit": "산염기세기", "tier": "A", "mis": ["Kw로 연결된다.", "곱이 일정하다.", "짝 관계식이다.", "Ka가 크면 Kb가 작다.", "짝 관계에만 성립한다."], "dx": "산의 이온화 상수 Kₐ와 그 짝염기의 이온화 상수를 곱하면 물 이온곱 상수(10⁻¹⁴)가 된다는 짝 관계를 놓친 경우다. 이 관계가 약하면 산이 강할수록 짝염기가 약하다는 결론을 못 끌어낸다.", "fix": "'산의 Kₐ와 그 짝염기의 이온화 상수를 곱하면 물 이온곱 상수(10⁻¹⁴)'임을 못 박는다. 이 곱 관계로 산이 강할수록 짝염기가 약하다는 결론을 끌어내라.", "cite": ""}, "CH2-266": {"name": "짝염기 세기", "course": "ch2", "unit": "산염기세기", "tier": "C", "mis": ["Ka가 크면 Kb가 작다.", "Kb가 작다.", "Kb가 크다."], "dx": "산의 Kₐ가 클수록 짝염기의 이온화 상수는 작아 짝염기가 약하다는 반비례를 놓친 경우다. 산 세기와 짝염기 세기의 반대 관계가 약하면 짝 관계 문제가 어긋난다.", "fix": "'산의 Kₐ가 클수록 짝염기의 이온화 상수는 작아 짝염기가 약함(반비례)'을 못 박는다. 산 세기와 짝염기 세기의 반대 관계로 짝 관계 문제를 풀어라.", "cite": ""}, "CH2-267": {"name": "강산 vs 약산", "course": "ch2", "unit": "산염기세기", "tier": "C", "mis": ["이온화가 잘 된다."], "dx": "강산과 약산의 차이가 이온화하는 정도(강산은 거의 완전, 약산은 일부)라는 점을 놓친 경우다. 이 기준이 약하면 같은 농도라도 [H⁺]가 다른 까닭을 못 짚는다.", "fix": "'강산과 약산의 차이는 이온화하는 정도(강산은 거의 완전, 약산은 일부)'임을 못 박는다. 이 기준으로 같은 농도라도 [H⁺]가 다른 까닭을 짚어라.", "cite": ""}, "CH2-268": {"name": "pKa", "course": "ch2", "unit": "산염기세기", "tier": "C", "mis": ["Ka가 크다."], "dx": "pKₐ가 Kₐ의 음의 로그라 pKₐ가 작을수록(Kₐ가 클수록) 강한 산이라는 점을 놓친 경우다. pKₐ와 세기의 반대 관계가 약하면 pKₐ 값으로 세기를 잘못 비교한다.", "fix": "pKₐ를 'Kₐ의 음의 로그라 pKₐ가 작을수록(Kₐ가 클수록) 강한 산'으로 못 박는다. pKₐ와 세기의 반대 관계로 pKₐ 값으로 세기를 비교하라.", "cite": ""}, "CH2-269": {"name": "물 이온곱", "course": "ch2", "unit": "산염기세기", "tier": "C", "mis": ["매우 작은 값이다.", "두 이온의 곱이다.", "중성 조건이다."], "dx": "물 이온곱이 [H⁺]와 [OH⁻]의 곱으로 25°C에서 10⁻¹⁴인 매우 작은 값이라는 점을 놓친 경우다. 이 값이 약하면 pH 계산과 Kₐ·짝염기 상수의 곱 관계가 흔들린다.", "fix": "물 이온곱을 '[H⁺]와 [OH⁻]의 곱으로 25°C에서 10⁻¹⁴인 매우 작은 값'으로 못 박는다. 이 값으로 pH 계산과 Kₐ·짝염기 상수의 곱 관계를 잡아라.", "cite": ""}, "CH2-270": {"name": "이온화도", "course": "ch2", "unit": "산염기세기", "tier": "C", "mis": ["일부만 이온화한다.", "거의 완전히 이온화한다.", "이온화가 잘 된다."], "dx": "이온화도가 녹은 산·염기 중 실제로 이온화한 비율이고 강산은 1에 가깝고 약산은 작다는 점을 놓친 경우다. 이온화도가 약하면 세기를 정량적으로 비교하지 못한다.", "fix": "이온화도를 '녹은 산·염기 중 실제로 이온화한 비율, 강산은 1에 가깝고 약산은 작음'으로 못 박는다. 이온화도로 세기를 정량적으로 비교하라.", "cite": ""}, "CH2-271": {"name": "전기 전도성", "course": "ch2", "unit": "산염기세기", "tier": "C", "mis": ["이온이 많다.", "이온이 전류를 나른다."], "dx": "이온이 많을수록 전류를 잘 날라 전기 전도성이 크다는 점을 놓친 경우다(같은 농도면 강산·강염기가 약산·약염기보다 잘 통함). 이온 수와 전도성의 연결이 약하면 전도도로 산·염기 세기를 판별하지 못한다.", "fix": "'이온이 많을수록 전류를 잘 날라 전기 전도성이 큼(같은 농도면 강산·강염기가 약산·약염기보다 잘 통함)'을 못 박는다. 이온 수와 전도성을 이어 전도도로 산·염기 세기를 판별하라.", "cite": ""}, "CH2-272": {"name": "pH 정의", "course": "ch2", "unit": "완충", "tier": "B", "mis": ["음의 로그이다.", "로그 척도이다.", "수소 이온 기준이다."], "dx": "pH가 [H⁺]의 음의 로그라 농도가 10배 변할 때 1씩 변하는 로그 척도라는 점을 놓친 경우다. 정의와 척도가 약하면 산·염기 정량과 완충 계산의 출발이 흔들린다.", "fix": "pH를 '[H⁺]의 음의 로그라 농도 10배에 1씩 변하는 로그 척도'로 못 박는다. 정의와 척도를 잡아 산·염기 정량·완충 계산의 출발로 삼아라.", "cite": ""}, "CH2-273": {"name": "pOH 정의", "course": "ch2", "unit": "완충", "tier": "C", "mis": ["수산화 이온 기준이다.", "음의 로그이다."], "dx": "pOH가 [OH⁻]의 음의 로그라는 정의를 놓친 경우다. pH와 짝을 이루는 이 정의가 약하면 염기성 용액의 정량 계산이 막힌다.", "fix": "pOH를 '[OH⁻]의 음의 로그'로 못 박는다. pH와 짝지어 염기성 용액의 정량 계산에 써라.", "cite": ""}, "CH2-274": {"name": "pH+pOH", "course": "ch2", "unit": "완충", "tier": "C", "mis": ["합이 14이다."], "dx": "25°C에서 pH + pOH = 14라는 관계를 놓친 경우다. 한쪽에서 다른 쪽을 환산하는 이 식이 약하면 산·염기 계산이 끊긴다.", "fix": "'25°C에서 pH + pOH = 14'를 못 박는다. 한쪽에서 다른 쪽을 14에서 빼 환산하라.", "cite": ""}, "CH2-275": {"name": "중성 pH", "course": "ch2", "unit": "완충", "tier": "C", "mis": ["[H⁺] = [OH⁻]이다.", "중성 조건이다."], "dx": "중성에서 [H⁺]=[OH⁻]라 25°C에서 pH가 7이라는 점을 놓친 경우다. 중성 기준이 흐리면 산성·염기성과의 경계를 못 잡는다.", "fix": "'중성은 [H⁺]=[OH⁻]라 25°C에서 pH 7'임을 못 박는다. 중성 기준으로 산성·염기성과의 경계를 잡아라.", "cite": ""}, "CH2-276": {"name": "산성 pH", "course": "ch2", "unit": "완충", "tier": "B", "mis": ["H⁺가 많다.", "7보다 작다."], "dx": "산성이 [H⁺]가 많아 pH가 7보다 작은 상태라는 점을 놓친 경우다. pH와 액성의 대응이 약하면 pH 값으로 산성을 못 가린다.", "fix": "'산성은 [H⁺]가 많아 pH가 7보다 작음'을 못 박는다. pH와 액성의 대응으로 pH 값으로 산성을 가려라.", "cite": ""}, "CH2-277": {"name": "염기성 pH", "course": "ch2", "unit": "완충", "tier": "C", "mis": ["OH⁻가 많다."], "dx": "염기성이 [OH⁻]가 많아 pH가 7보다 큰 상태라는 점을 놓친 경우다. pH와 액성의 대응이 약하면 pH 값으로 염기성을 못 가린다.", "fix": "'염기성은 [OH⁻]가 많아 pH가 7보다 큼'을 못 박는다. pH와 액성의 대응으로 pH 값으로 염기성을 가려라.", "cite": ""}, "CH2-278": {"name": "pH와 농도", "course": "ch2", "unit": "완충", "tier": "C", "mis": ["음의 로그이다."], "dx": "pH가 [H⁺]의 음의 로그라 농도가 진할수록 pH가 작아진다는 반대 관계를 놓친 경우다. 이 방향이 약하면 농도에서 pH를 못 구한다.", "fix": "'pH는 [H⁺]의 음의 로그라 농도가 진할수록 pH가 작아짐'을 못 박는다. 이 반대 방향으로 농도에서 pH를 구하라.", "cite": ""}, "CH2-279": {"name": "pH 척도", "course": "ch2", "unit": "완충", "tier": "C", "mis": ["로그 척도이다."], "dx": "pH가 로그 척도라 pH 차이 1이 [H⁺] 10배 차이라는 점을 놓친 경우다. 척도 감각이 약하면 pH 차를 농도 비로 환산하지 못한다.", "fix": "'pH는 로그 척도라 차이 1이 [H⁺] 10배'임을 못 박는다. 척도 감각으로 pH 차를 농도 비로 환산하라.", "cite": ""}, "CH2-280": {"name": "강산 pH", "course": "ch2", "unit": "완충", "tier": "C", "mis": ["거의 완전히 이온화한다."], "dx": "강산이 거의 완전히 이온화해 [H⁺]가 산의 농도와 거의 같다는 점을 놓친 경우다. 이 근사가 약하면 강산 용액의 pH를 못 구한다.", "fix": "'강산은 거의 완전히 이온화해 [H⁺]가 산의 농도와 거의 같음'을 못 박는다. 이 근사로 강산 용액의 pH를 구하라.", "cite": ""}, "CH2-281": {"name": "강염기 pOH", "course": "ch2", "unit": "완충", "tier": "C", "mis": ["거의 완전히 이온화한다."], "dx": "강염기가 거의 완전히 이온화해 [OH⁻]가 염기의 농도와 거의 같다는 점을 놓친 경우다. 이 근사가 약하면 강염기의 pOH·pH를 못 구한다.", "fix": "'강염기는 거의 완전히 이온화해 [OH⁻]가 염기의 농도와 거의 같음'을 못 박는다. 이 근사로 강염기의 pOH·pH를 구하라.", "cite": ""}, "CH2-282": {"name": "약산 근사", "course": "ch2", "unit": "완충", "tier": "C", "mis": ["일부만 이온화한다.", "√(Ka·C)이다."], "dx": "약산은 일부만 이온화해 [H⁺]가 √(Kₐ·C)로 근사된다는 점을 놓친 경우다. 강산처럼 농도를 그대로 [H⁺]로 쓰면 약산 pH가 어긋난다.", "fix": "'약산은 일부만 이온화해 [H⁺]가 √(Kₐ·C)로 근사됨'을 못 박는다. 강산처럼 농도를 그대로 [H⁺]로 쓰지 말고 이 근사로 약산 pH를 구하라.", "cite": ""}, "CH2-283": {"name": "약산 vs 강산 pH", "course": "ch2", "unit": "완충", "tier": "C", "mis": ["H⁺가 적다.", "이온화가 덜 된다."], "dx": "같은 농도라도 약산은 일부만 이온화해 [H⁺]가 적어 강산보다 pH가 높다는 점을 놓친 경우다. 이온화 정도 차이가 약하면 두 산의 pH를 잘못 비교한다.", "fix": "'같은 농도라도 약산은 일부만 이온화해 [H⁺]가 적어 강산보다 pH가 높음'을 못 박는다. 이온화 정도 차이로 두 산의 pH를 비교하라.", "cite": ""}, "CH2-284": {"name": "약산 이온화", "course": "ch2", "unit": "완충", "tier": "C", "mis": ["일부만 이온화한다."], "dx": "약산이 물에서 일부만 이온화해 이온화 평형을 이룬다는 점을 놓친 경우다. 일부만 이온화한다는 점이 약하면 완충·가수분해로 이어지지 못한다.", "fix": "'약산은 물에서 일부만 이온화해 이온화 평형을 이룸'을 못 박는다. 일부만 이온화함을 잡아 완충·가수분해로 이어라.", "cite": ""}, "CH2-285": {"name": "완충 용액 구성", "course": "ch2", "unit": "완충", "tier": "A", "mis": ["약산이 필요하다.", "약한 쌍이 필요하다.", "두 성분이 필요하다.", "양쪽을 중화해야 한다."], "dx": "완충 용액이 약산과 그 짝염기(또는 약염기와 짝산)가 함께 들어 있는 용액이라는 점을 놓친 경우다. 두 성분이 함께 있어야 산·염기 양쪽을 중화할 수 있다는 점이 약하면 완충의 구성을 잘못 잡는다.", "fix": "완충 용액을 '약산과 그 짝염기(또는 약염기와 짝산)가 함께 든 용액'으로 못 박는다. 두 성분이 함께 있어야 산·염기 양쪽을 중화함을 잡아 구성을 바로 잡아라.", "cite": ""}, "CH2-286": {"name": "완충 작용", "course": "ch2", "unit": "완충", "tier": "C", "mis": ["짝염기가 중화한다.", "약산이 중화한다.", "완충 작용이다."], "dx": "완충 작용이 산을 넣으면 짝염기가, 염기를 넣으면 약산이 중화해 pH를 거의 일정하게 유지하는 것이라는 점을 놓친 경우다. 두 성분의 역할 분담이 약하면 왜 pH가 안 변하는지 설명하지 못한다.", "fix": "완충 작용을 '산을 넣으면 짝염기가, 염기를 넣으면 약산이 중화해 pH를 거의 일정하게 유지'로 못 박는다. 두 성분의 역할 분담으로 왜 pH가 안 변하는지 설명하라.", "cite": ""}, "CH2-287": {"name": "헨더슨-하셀바흐", "course": "ch2", "unit": "완충", "tier": "C", "mis": ["log 1 = 0이다.", "+ log이다."], "dx": "헨더슨-하셀바흐 식이 pH = pKₐ + log([짝염기]/[약산])이고 둘이 같으면 log 1 = 0이라 pH = pKₐ가 된다는 점을 놓친 경우다. 이 식이 약하면 완충 용액의 pH를 못 구한다.", "fix": "헨더슨-하셀바흐를 'pH = pKₐ + log([짝염기]/[약산]), 둘이 같으면 log 1 = 0이라 pH = pKₐ'로 못 박는다. 이 식으로 완충 용액의 pH를 구하라.", "cite": ""}, "CH2-288": {"name": "공통 이온 효과", "course": "ch2", "unit": "완충", "tier": "C", "mis": ["평형이 분자 쪽으로 이동한다.", "이온화가 억제된다."], "dx": "짝염기(공통 이온)를 더하면 약산의 이온화 평형이 분자 쪽으로 밀려 이온화가 억제된다는 공통 이온 효과를 놓친 경우다. 이 효과가 약하면 완충 용액에서 약산이 왜 덜 이온화하는지 못 짚는다.", "fix": "공통 이온 효과를 '짝염기(공통 이온)를 더하면 약산의 이온화 평형이 분자 쪽으로 밀려 이온화가 억제됨'으로 못 박는다. 이 효과로 완충 용액에서 약산이 왜 덜 이온화하는지 짚어라.", "cite": ""}, "CH2-289": {"name": "염 가수분해", "course": "ch2", "unit": "완충", "tier": "A", "mis": ["짝염기가 가수분해한다.", "짝산이 가수분해한다.", "가수분해하지 않는다.", "이온이 가수분해한다."], "dx": "약산·약염기에서 온 이온이 물과 반응(가수분해)해 용액이 중성이 아니게 된다는 점을 놓친 경우다(약산의 짝염기는 염기성, 약염기의 짝산은 산성). 가수분해를 놓치면 당량점이 왜 중성이 아닌지 설명하지 못한다.", "fix": "'약산·약염기에서 온 이온이 물과 반응(가수분해)해 용액이 중성이 아님(약산의 짝염기는 염기성, 약염기의 짝산은 산성)'을 못 박는다. 가수분해로 당량점이 왜 중성이 아닌지 설명하라.", "cite": ""}, "CH2-290": {"name": "가수분해 정의", "course": "ch2", "unit": "완충-d", "tier": "C", "mis": ["단순 용해가 아니다.", "약한 이온이 있어야 한다.", "이온이 물과 반응한다."], "dx": "가수분해가 단순 용해가 아니라 약한 산·염기에서 온 이온이 물과 반응해 H⁺나 OH⁻를 내놓는 것이라는 점을 놓친 경우다. 어떤 이온이 가수분해하는지가 약하면 염 용액의 액성을 못 가린다.", "fix": "가수분해를 '단순 용해가 아니라 약한 산·염기에서 온 이온이 물과 반응해 H⁺나 OH⁻를 내놓는 것'으로 못 박는다. 어떤 이온이 가수분해하는지로 염 용액의 액성을 가려라.", "cite": ""}, "CH2-291": {"name": "완충 응용", "course": "ch2", "unit": "완충-d", "tier": "C", "mis": ["pH를 유지한다.", "pH에 민감하다."], "dx": "완충 용액이 외부에서 산·염기가 들어와도 pH를 일정하게 유지해 혈액 같은 생체 환경을 지킨다는 응용을 놓친 경우다. 완충과 생체의 연결이 약하면 응용 맥락을 못 짚는다.", "fix": "'완충 용액은 외부에서 산·염기가 들어와도 pH를 일정하게 유지해 혈액 같은 생체 환경을 지킴'을 못 박는다. 완충과 생체의 연결로 응용 맥락을 짚어라.", "cite": ""}, "CH2-292": {"name": "pH 측정", "course": "ch2", "unit": "완충-d", "tier": "C", "mis": ["pH를 알려준다.", "측정 가능하다.", "수치가 아니라 색이다."], "dx": "지시약이 수치가 아니라 색 변화로 대략의 pH를 알려준다는 점을 놓친 경우다(정확한 값은 pH 측정기). 측정 방식의 차이가 약하면 지시약으로 정확한 pH를 읽으려는 오류를 범한다.", "fix": "'지시약은 수치가 아니라 색 변화로 대략의 pH를 알려줌(정확한 값은 pH 측정기)'을 못 박는다. 측정 방식의 차이를 잡아 지시약으로 정확한 pH를 읽으려는 오류를 피하라.", "cite": ""}, "CH2-293": {"name": "강염기 vs 약염기", "course": "ch2", "unit": "완충-d", "tier": "C", "mis": ["OH⁻가 많다.", "거의 완전히 이온화한다."], "dx": "같은 농도라도 강염기는 거의 완전히 이온화해 [OH⁻]가 많아 약염기보다 pH가 높다는 점을 놓친 경우다. 이온화 정도 차이가 약하면 두 염기의 pH를 잘못 비교한다.", "fix": "'같은 농도라도 강염기는 거의 완전히 이온화해 [OH⁻]가 많아 약염기보다 pH가 높음'을 못 박는다. 이온화 정도 차이로 두 염기의 pH를 비교하라.", "cite": ""}, "CH2-294": {"name": "물의 pH", "course": "ch2", "unit": "완충-d", "tier": "C", "mis": ["[H⁺] = [OH⁻]이다.", "자동 이온화한다."], "dx": "순수한 물이 자동 이온화해 [H⁺]=[OH⁻]라 25°C에서 pH가 7이라는 점을 놓친 경우다. 물의 중성 기준이 흐리면 산·염기 판정의 기준점이 사라진다.", "fix": "'순수한 물은 자동 이온화해 [H⁺]=[OH⁻]라 25°C에서 pH 7'임을 못 박는다. 물의 중성 기준을 산·염기 판정의 기준점으로 삼아라.", "cite": ""}, "CH2-295": {"name": "강산 vs 약산", "course": "ch2", "unit": "완충-d", "tier": "C", "mis": ["H⁺가 많다.", "거의 완전히 이온화한다."], "dx": "같은 농도라도 강산은 거의 완전히 이온화해 [H⁺]가 많아 약산보다 pH가 낮다는 점을 놓친 경우다. 이온화 정도 차이가 약하면 두 산의 pH를 잘못 비교한다.", "fix": "'같은 농도라도 강산은 거의 완전히 이온화해 [H⁺]가 많아 약산보다 pH가 낮음'을 못 박는다. 이온화 정도 차이로 두 산의 pH를 비교하라.", "cite": ""}, "CH2-358": {"name": "탄소화합물 정의", "course": "ch2", "unit": "탄소화합물", "tier": "C", "mis": ["탄소가 중심이다.", "수소가 흔히 들어간다.", "무기 탄소 화합물은 제외한다."], "dx": "탄소화합물이 탄소를 중심으로 수소 등이 결합한 화합물이고 CO₂·탄산염 같은 무기 탄소 화합물은 제외한다는 점을 놓친 경우다. 이 경계가 흐리면 무엇이 탄소화합물인지 못 가린다.", "fix": "탄소화합물을 '탄소를 중심으로 수소 등이 결합한 화합물, CO₂·탄산염 같은 무기 탄소 화합물은 제외'로 못 박는다. 이 경계로 무엇이 탄소화합물인지 가려라.", "cite": ""}, "CH2-359": {"name": "탄소의 결합", "course": "ch2", "unit": "탄소화합물", "tier": "C", "mis": ["다양한 결합을 한다.", "원자가가 4이다.", "탄소끼리 결합한다."], "dx": "탄소가 원자가 4라 최대 4개 원자와 결합하고 탄소끼리도 이어진다는 점을 놓친 경우다. 결합 손이 4개라는 점이 약하면 탄소 골격의 다양성을 설명하지 못한다.", "fix": "'탄소는 원자가 4라 최대 4개 원자와 결합하고 탄소끼리도 이어짐'을 못 박는다. 결합 손이 4개임을 잡아 탄소 골격의 다양성을 설명하라.", "cite": ""}, "CH2-360": {"name": "탄소 골격", "course": "ch2", "unit": "탄소화합물", "tier": "C", "mis": ["두 모양 모두 가능하다.", "골격이 다양하다."], "dx": "탄소 골격이 사슬·고리, 곧은 사슬·가지 사슬 등 다양한 모양을 이룰 수 있다는 점을 놓친 경우다. 골격 다양성이 약하면 이성질체가 왜 생기는지 못 짚는다.", "fix": "'탄소 골격이 사슬·고리, 곧은 사슬·가지 사슬 등 다양한 모양을 이룸'을 못 박는다. 골격 다양성으로 이성질체가 왜 생기는지 짚어라.", "cite": ""}, "CH2-361": {"name": "작용기 정의", "course": "ch2", "unit": "탄소화합물", "tier": "C", "mis": ["성질을 결정한다.", "작용기로 성질이 갈린다.", "작용기가 성질을 결정한다."], "dx": "작용기가 분자의 특징적 성질을 결정하는 원자단이라는 점을 놓친 경우다. 작용기가 성질을 가른다는 점이 약하면 같은 작용기끼리 비슷한 성질을 보이는 까닭을 못 짚는다.", "fix": "작용기를 '분자의 특징적 성질을 결정하는 원자단'으로 못 박는다. 작용기가 성질을 가름을 잡아 같은 작용기끼리 비슷한 성질을 보이는 까닭을 짚어라.", "cite": ""}, "CH2-362": {"name": "알코올", "course": "ch2", "unit": "탄소화합물", "tier": "C", "mis": ["-OH이다.", "-OH는 알코올이다."], "dx": "하이드록시기(-OH)를 가진 화합물이 알코올이라는 점을 놓친 경우다. 작용기 -OH가 알코올의 정체라는 점이 약하면 알코올을 못 가린다.", "fix": "'하이드록시기(-OH)를 가진 화합물이 알코올'임을 못 박는다. 작용기 -OH가 알코올의 정체임을 잡아 알코올을 가려라.", "cite": ""}, "CH2-363": {"name": "알코올 예", "course": "ch2", "unit": "탄소화합물", "tier": "C", "mis": ["-OH를 가진다."], "dx": "메탄올·에탄올처럼 -OH를 가진 화합물이 알코올이라는 점을 놓친 경우다. 예를 다른 작용기와 혼동하면 알코올 분류가 어긋난다.", "fix": "'메탄올·에탄올처럼 -OH를 가진 화합물이 알코올'임을 못 박는다. 예를 다른 작용기와 혼동하지 말고 분류하라.", "cite": ""}, "CH2-364": {"name": "카복실산", "course": "ch2", "unit": "탄소화합물", "tier": "C", "mis": ["-COOH이다.", "-COOH는 카복실산이다.", "-COOH를 가진다."], "dx": "카복실기(-COOH)를 가진 화합물이 카복실산이라는 점을 놓친 경우다. 작용기 -COOH가 카복실산의 정체라는 점이 약하면 그 산성을 설명하지 못한다.", "fix": "'카복실기(-COOH)를 가진 화합물이 카복실산'임을 못 박는다. 작용기 -COOH가 카복실산의 정체임을 잡아 그 산성을 설명하라.", "cite": ""}, "CH2-365": {"name": "카복실산 예", "course": "ch2", "unit": "탄소화합물", "tier": "C", "mis": ["-COOH를 가진다."], "dx": "아세트산·폼산처럼 -COOH를 가진 화합물이 카복실산이라는 점을 놓친 경우다. 예를 다른 작용기와 혼동하면 분류가 어긋난다.", "fix": "'아세트산·폼산처럼 -COOH를 가진 화합물이 카복실산'임을 못 박는다. 예를 다른 작용기와 혼동하지 말고 분류하라.", "cite": ""}, "CH2-366": {"name": "카복실산 성질", "course": "ch2", "unit": "탄소화합물", "tier": "C", "mis": ["H⁺를 내놓는다.", "극성이 있다."], "dx": "카복실산이 -COOH의 수소를 H⁺로 내놓아 산성을 띠고 극성이라는 점을 놓친 경우다. 산성의 근원이 카복실기라는 점이 약하면 알코올과의 산성 차이를 못 짚는다.", "fix": "'카복실산은 -COOH의 수소를 H⁺로 내놓아 산성을 띠고 극성'임을 못 박는다. 산성의 근원이 카복실기임을 잡아 알코올과의 산성 차이를 짚어라.", "cite": ""}, "CH2-367": {"name": "아민", "course": "ch2", "unit": "탄소화합물", "tier": "C", "mis": ["-NH₂이다.", "H⁺를 받는다.", "-NH₂는 아민이다."], "dx": "아미노기(-NH₂)를 가진 화합물이 아민이고 H⁺를 받아 염기성을 띤다는 점을 놓친 경우다. 작용기 -NH₂가 아민의 정체라는 점이 약하면 그 염기성을 설명하지 못한다.", "fix": "'아미노기(-NH₂)를 가진 화합물이 아민이고 H⁺를 받아 염기성'임을 못 박는다. 작용기 -NH₂가 아민의 정체임을 잡아 그 염기성을 설명하라.", "cite": ""}, "CH2-368": {"name": "알데하이드", "course": "ch2", "unit": "탄소화합물", "tier": "C", "mis": ["-CHO가 작용기이다."], "dx": "알데하이드기(-CHO)를 가진 화합물이 알데하이드라는 점을 놓친 경우다. 이 작용기가 약하면 알코올 산화로 알데하이드가 생기는 흐름을 못 짚는다.", "fix": "'알데하이드기(-CHO)를 가진 화합물이 알데하이드'임을 못 박는다. 이 작용기를 잡아 알코올 산화로 알데하이드가 생기는 흐름을 짚어라.", "cite": ""}, "CH2-369": {"name": "케톤", "course": "ch2", "unit": "탄소화합물", "tier": "C", "mis": ["가운데에 있다.", "카보닐기이다.", "카보닐기를 가진다."], "dx": "케톤이 카보닐기(C=O)를 두 탄소 사이(분자 가운데)에 가진 화합물이라는 점을 놓친 경우다. 카보닐기의 위치가 약하면 알데하이드와 케톤을 구분하지 못한다.", "fix": "'케톤은 카보닐기(C=O)를 두 탄소 사이(분자 가운데)에 가진 화합물'임을 못 박는다. 카보닐기의 위치로 알데하이드와 케톤을 구분하라.", "cite": ""}, "CH2-370": {"name": "에스터", "course": "ch2", "unit": "탄소화합물", "tier": "C", "mis": ["카복실산과 알코올이다.", "-COO⁻이다."], "dx": "에스터가 카복실산과 알코올이 결합해 생기고 -COO- 결합을 가진 화합물이라는 점을 놓친 경우다. 어디서 오는지가 약하면 에스터화 반응을 설명하지 못한다.", "fix": "'에스터는 카복실산과 알코올이 결합해 생기고 -COO- 결합을 가짐'을 못 박는다. 어디서 오는지를 잡아 에스터화 반응을 설명하라.", "cite": ""}, "CH2-371": {"name": "에스터화", "course": "ch2", "unit": "탄소화합물", "tier": "C", "mis": ["물도 생긴다.", "카복실산과 알코올이다.", "에스터를 만든다."], "dx": "에스터화가 카복실산과 알코올이 반응해 에스터와 함께 물이 생기는 반응이라는 점을 놓친 경우다. 물이 함께 생긴다는 점이 약하면 에스터화 반응식을 잘못 쓴다.", "fix": "에스터화를 '카복실산과 알코올이 반응해 에스터와 함께 물이 생기는 반응'으로 못 박는다. 물이 함께 생김을 잡아 에스터화 반응식을 바로 써라.", "cite": ""}, "CH2-372": {"name": "에스터 성질", "course": "ch2", "unit": "탄소화합물", "tier": "C", "mis": ["향기가 난다.", "중성이다."], "dx": "에스터가 향기가 나고 중성이라는 점을 놓친 경우다(과일 향의 원인). 에스터의 성질이 약하면 카복실산·알코올과 구분하지 못한다.", "fix": "'에스터는 향기가 나고 중성(과일 향의 원인)'임을 못 박는다. 에스터의 성질로 카복실산·알코올과 구분하라.", "cite": ""}, "CH2-373": {"name": "알코올 산화", "course": "ch2", "unit": "탄소화합물", "tier": "C", "mis": ["알데하이드를 거친다.", "산화된다."], "dx": "알코올이 산화되면 알데하이드를 거쳐 카복실산으로 간다는 점을 놓친 경우다(단계적 산화). 이 산화 순서가 약하면 산화 생성물을 잘못 잡는다.", "fix": "'알코올이 산화되면 알데하이드를 거쳐 카복실산으로 감(단계적 산화)'을 못 박는다. 이 산화 순서로 산화 생성물을 바로 잡아라.", "cite": ""}, "CH2-374": {"name": "산화 방향", "course": "ch2", "unit": "탄소화합물", "tier": "C", "mis": ["환원 방향이다.", "산화의 끝이다.", "산화 방향이다."], "dx": "알코올 산화의 방향이 알데하이드를 거쳐 카복실산에서 끝난다는 점을 놓친 경우다. 산화의 끝이 카복실산이라는 점이 약하면 산화·환원 방향을 거꾸로 잡는다.", "fix": "'알코올 산화의 방향이 알데하이드를 거쳐 카복실산에서 끝남'을 못 박는다. 산화의 끝이 카복실산임을 잡아 산화·환원 방향을 거꾸로 잡지 마라.", "cite": ""}, "CH2-375": {"name": "작용기와 성질", "course": "ch2", "unit": "탄소화합물", "tier": "C", "mis": ["작용기가 성질을 결정한다.", "작용기가 같으면 비슷하다."], "dx": "작용기가 같으면 탄소 사슬이 달라도 비슷한 화학적 성질을 보인다는 점을 놓친 경우다. 작용기가 성질을 묶는다는 원리가 약하면 화합물을 작용기로 분류하지 못한다.", "fix": "'작용기가 같으면 탄소 사슬이 달라도 비슷한 화학적 성질'임을 못 박는다. 작용기가 성질을 묶음을 잡아 화합물을 작용기로 분류하라.", "cite": ""}, "CH2-376": {"name": "이성질체", "course": "ch2", "unit": "탄소화합물", "tier": "C", "mis": ["분자식은 같다.", "구조가 다르다."], "dx": "이성질체가 분자식은 같지만 구조가 달라 성질이 다른 화합물이라는 점을 놓친 경우다. 같은 분자식이라도 구조가 다르면 다른 물질이라는 점이 약하면 이성질체를 같은 물질로 오해한다.", "fix": "이성질체를 '분자식은 같지만 구조가 달라 성질이 다른 화합물'로 못 박는다. 같은 분자식이라도 구조가 다르면 다른 물질임을 잡아 같은 물질로 오해하지 마라.", "cite": ""}, "CH2-377": {"name": "같은 작용기", "course": "ch2", "unit": "탄소화합물", "tier": "C", "mis": ["둘 다 -OH이다.", "같은 작용기이다."], "dx": "같은 작용기를 가진 화합물끼리 특징적인 반응을 공유한다는 점을 놓친 경우다(둘 다 -OH면 알코올의 성질). 이 점이 약하면 작용기로 성질을 예측하지 못한다.", "fix": "'같은 작용기를 가진 화합물끼리 특징적인 반응을 공유함(둘 다 -OH면 알코올의 성질)'을 못 박는다. 이로써 작용기로 성질을 예측하라.", "cite": ""}, "CH2-378": {"name": "카복실산 반응", "course": "ch2", "unit": "탄소화합물-d", "tier": "C", "mis": ["산이기 때문이다.", "수소 기체가 나온다."], "dx": "카복실산이 산이라 금속과 반응해 수소 기체를 내놓는다는 점을 놓친 경우다. 카복실산이 산으로 행동한다는 점이 약하면 그 반응을 예측하지 못한다.", "fix": "'카복실산은 산이라 금속과 반응해 수소 기체를 내놓음'을 못 박는다. 카복실산이 산으로 행동함을 잡아 그 반응을 예측하라.", "cite": ""}, "CH2-379": {"name": "에터", "course": "ch2", "unit": "탄소화합물-d", "tier": "C", "mis": ["산소가 두 탄소 사이에 있다.", "-O⁻이다.", "사슬 사이에 있다."], "dx": "에터가 산소가 두 탄소 사이에 낀(C-O-C) 구조라는 점을 놓친 경우다. 산소의 위치가 약하면 에터를 알코올 등과 구분하지 못한다.", "fix": "에터를 '산소가 두 탄소 사이에 낀(C-O-C) 구조'로 못 박는다. 산소의 위치로 에터를 알코올 등과 구분하라.", "cite": ""}, "CH2-380": {"name": "알코올 수소 결합", "course": "ch2", "unit": "탄소화합물-d", "tier": "C", "mis": ["-OH가 수소 결합을 한다.", "수소 결합이 있다."], "dx": "알코올이 -OH 때문에 분자끼리 수소 결합을 해 끓는점이 높다는 점을 놓친 경우다. -OH와 수소 결합의 연결이 약하면 알코올이 비슷한 탄화수소보다 끓는점이 높은 까닭을 못 짚는다.", "fix": "'알코올은 -OH 때문에 분자끼리 수소 결합을 해 끓는점이 높음'을 못 박는다. -OH와 수소 결합의 연결로 알코올이 비슷한 탄화수소보다 끓는점이 높은 까닭을 짚어라.", "cite": ""}, "CH2-381": {"name": "끓는점 경향", "course": "ch2", "unit": "탄소화합물-d", "tier": "C", "mis": ["분산력이 커진다."], "dx": "같은 계열에서 탄소 수가 많아 분자가 클수록 분산력이 커져 끓는점이 높아진다는 점을 놓친 경우다. 이 경향이 약하면 탄화수소의 끓는점 순서를 못 잡는다.", "fix": "'같은 계열에서 탄소 수가 많아 분자가 클수록 분산력이 커져 끓는점이 높아짐'을 못 박는다. 이 경향으로 탄화수소의 끓는점 순서를 잡아라.", "cite": ""}, "CH2-382": {"name": "케톤 예", "course": "ch2", "unit": "탄소화합물-d", "tier": "C", "mis": ["카보닐기를 가진다."], "dx": "아세톤처럼 카보닐기를 분자 가운데 가진 화합물이 케톤이라는 점을 놓친 경우다. 예를 알데하이드와 혼동하면 분류가 어긋난다.", "fix": "'아세톤처럼 카보닐기를 분자 가운데 가진 화합물이 케톤'임을 못 박는다. 예를 알데하이드와 혼동하지 말고 분류하라.", "cite": ""}, "CH2-383": {"name": "산성 비교", "course": "ch2", "unit": "탄소화합물-d", "tier": "C", "mis": ["카복실기가 H⁺를 잘 내놓는다.", "H⁺를 거의 내놓지 않는다."], "dx": "카복실산은 카복실기가 H⁺를 잘 내놓아 산성인 반면 알코올은 -OH의 수소를 거의 내놓지 않아 중성에 가깝다는 점을 놓친 경우다. 둘 다 산소-수소 결합이 있어도 산성이 갈린다는 점이 약하면 산성 비교가 어긋난다.", "fix": "'카복실산은 카복실기가 H⁺를 잘 내놓아 산성, 알코올은 -OH의 수소를 거의 내놓지 않아 중성에 가까움'을 못 박는다. 둘 다 산소-수소 결합이 있어도 산성이 갈림을 잡아 산성을 비교하라.", "cite": ""}, "CH2-136": {"name": "총괄성 정의", "course": "ch2", "unit": "총괄성", "tier": "A", "mis": ["종류와 무관하다.", "질량과 무관하다.", "크기와 무관하다.", "입자 수가 같다.", "입자 수에 의존한다."], "dx": "총괄성이 용질의 종류·질량·크기와 무관하게 오직 녹아 있는 입자 수에만 의존하는 성질이라는 점을 놓친 경우다. 이 핵심이 흔들리면 증기압 내림·끓는점 오름·어는점 내림을 한 원리로 꿰지 못한다.", "fix": "총괄성을 '용질의 종류·질량·크기와 무관하게 오직 녹아 있는 입자 수에만 의존하는 성질'로 못 박는다. 이 핵심으로 증기압 내림·끓는점 오름·어는점 내림을 한 원리로 꿰어라.", "cite": ""}, "CH2-137": {"name": "증기압 내림", "course": "ch2", "unit": "총괄성", "tier": "B", "mis": ["증발이 어려워진다.", "증기압이 내려간다.", "종류와 무관하다."], "dx": "비휘발성 용질을 녹이면 용매가 증발할 자리를 차지해 용액의 증기압이 순용매보다 낮아진다는 점을 놓친 경우다. 증기압 내림이 약하면 그 결과인 끓는점 오름으로 이어지지 못한다.", "fix": "'비휘발성 용질을 녹이면 용매가 증발할 자리를 차지해 용액의 증기압이 순용매보다 낮아짐'을 못 박는다. 증기압 내림을 그 결과인 끓는점 오름으로 이어라.", "cite": ""}, "CH2-138": {"name": "라울 법칙", "course": "ch2", "unit": "총괄성", "tier": "C", "mis": ["용매 몰분율 기준이다.", "몰분율에 비례한다.", "용매 몰분율이 1보다 작다."], "dx": "용액의 증기압이 (순용매 증기압 × 용매 몰분율)이라는 라울 법칙을 놓친 경우다. 용매 몰분율이 1보다 작아 증기압이 내려간다는 점이 약하면 증기압을 정량적으로 못 구한다.", "fix": "라울 법칙을 '용액의 증기압 = 순용매 증기압 × 용매 몰분율'로 못 박는다. 용매 몰분율이 1보다 작아 증기압이 내려감을 잡아 정량 계산하라.", "cite": ""}, "CH2-139": {"name": "끓는점 오름", "course": "ch2", "unit": "총괄성", "tier": "C", "mis": ["증기압이 내려간다.", "식에 m이 들어간다."], "dx": "끓는점 오름이 증기압 내림 때문에 일어나고 그 크기가 몰랄 농도에 비례(식에 m이 들어감)한다는 점을 놓친 경우다. 농도와의 비례가 약하면 끓는점 오름을 계산하지 못한다.", "fix": "끓는점 오름을 '증기압 내림 때문에 일어나고 크기가 몰랄 농도에 비례'로 못 박는다. 농도와의 비례로 끓는점 오름을 계산하라.", "cite": ""}, "CH2-140": {"name": "어는점 내림", "course": "ch2", "unit": "총괄성", "tier": "A", "mis": ["총괄성이다.", "어는점이 내려간다.", "식에 m이 들어간다.", "종류와 무관하다."], "dx": "어는점 내림이 용질 입자 수(몰랄 농도)에 비례해 일어나는 총괄성이고 용질 종류와 무관하다는 점을 놓친 경우다. 농도 비례가 약하면 제설제·부동액 같은 응용과 어는점 내림 계산을 못 잡는다.", "fix": "어는점 내림을 '용질 입자 수(몰랄 농도)에 비례해 일어나는 총괄성, 용질 종류 무관'으로 못 박는다. 농도 비례로 제설제·부동액 응용과 계산을 잡아라.", "cite": ""}, "CH2-141": {"name": "몰랄 오름 상수", "course": "ch2", "unit": "총괄성", "tier": "C", "mis": ["용매 고유의 값이다.", "농도와 무관하다."], "dx": "끓는점 오름·어는점 내림의 비례 상수가 용매마다 정해진 고유 값이고 농도와 무관하다는 점을 놓친 경우다. 상수의 성격이 약하면 용매가 바뀔 때 계산이 어긋난다.", "fix": "'끓는점 오름·어는점 내림의 비례 상수는 용매마다 정해진 고유 값이고 농도와 무관'함을 못 박는다. 상수가 용매에 달림을 잡아 용매가 바뀔 때 계산을 맞춰라.", "cite": ""}, "CH2-142": {"name": "전해질", "course": "ch2", "unit": "총괄성", "tier": "C", "mis": ["이온으로 나뉜다.", "입자 수가 다르다.", "이온화하지 않는다."], "dx": "전해질이 물에서 이온으로 나뉘어 화학식 단위보다 입자 수가 늘어난다는 점을 놓친 경우다(NaCl 1몰이 이온 2몰로). 이온화로 입자가 는다는 점이 약하면 전해질 총괄성을 과소평가한다.", "fix": "'전해질은 물에서 이온으로 나뉘어 화학식 단위보다 입자 수가 늘어남(NaCl 1몰이 이온 2몰로)'을 못 박는다. 이온화로 입자가 늚을 잡아 전해질 총괄성을 과소평가 마라.", "cite": ""}, "CH2-143": {"name": "반트호프 인자", "course": "ch2", "unit": "총괄성", "tier": "B", "mis": ["이온 2개로 나뉜다.", "이온화하지 않는다.", "이온화로 입자 수가 는다."], "dx": "반트호프 인자 i가 화학식 단위 하나가 내놓는 입자 수라는 점을 놓친 경우다(NaCl은 약 2, 비전해질은 1). i를 모르면 전해질의 총괄성 크기를 잘못 잡는다.", "fix": "반트호프 인자 i를 '화학식 단위 하나가 내놓는 입자 수(NaCl은 약 2, 비전해질은 1)'로 못 박는다. i를 잡아 전해질의 총괄성 크기를 맞춰라.", "cite": ""}, "CH2-144": {"name": "전해질 총괄성", "course": "ch2", "unit": "총괄성", "tier": "C", "mis": ["전해질의 입자 수가 많다.", "이온화로 입자 수가 는다.", "입자 수가 는다."], "dx": "전해질이 이온화로 입자 수가 늘어 같은 몰랄 농도라도 총괄성이 더 크게 나타난다는 점을 놓친 경우다. 입자 수 증가가 약하면 전해질과 비전해질의 총괄성 차이를 못 짚는다.", "fix": "'전해질은 이온화로 입자 수가 늘어 같은 몰랄 농도라도 총괄성이 더 크게 나타남'을 못 박는다. 입자 수 증가로 전해질과 비전해질의 총괄성 차이를 짚어라.", "cite": ""}, "CH2-145": {"name": "전해질 계산", "course": "ch2", "unit": "총괄성", "tier": "C", "mis": ["i를 곱해야 한다.", "입자 수가 늘어난다.", "입자 수를 반영한다."], "dx": "전해질의 총괄성을 계산할 때 반트호프 인자 i를 곱해 늘어난 입자 수를 반영해야 한다는 점을 놓친 경우다. i를 빼먹으면 전해질의 끓는점 오름·어는점 내림이 과소평가된다.", "fix": "'전해질의 총괄성은 반트호프 인자 i를 곱해 늘어난 입자 수를 반영'함을 못 박는다. i를 빼먹지 말고 끓는점 오름·어는점 내림을 계산하라.", "cite": ""}, "CH2-146": {"name": "전해질 비교", "course": "ch2", "unit": "총괄성", "tier": "C", "mis": ["NaCl의 입자 수가 많다."], "dx": "같은 몰랄 농도라도 내놓는 입자 수가 많은 전해질일수록 총괄성이 크다는 점을 놓친 경우다(NaCl이 포도당보다 큼). 입자 수로 비교하지 못하면 총괄성 순서가 어긋난다.", "fix": "'같은 몰랄 농도라도 내놓는 입자 수가 많은 전해질일수록 총괄성이 큼(NaCl이 포도당보다 큼)'을 못 박는다. 입자 수로 총괄성 순서를 잡아라.", "cite": ""}, "CH2-147": {"name": "응용", "course": "ch2", "unit": "총괄성", "tier": "C", "mis": ["어는점이 내려간다.", "어는점 내림을 이용한다."], "dx": "어는점 내림을 도로 제설제·자동차 부동액에 이용한다는 응용을 놓친 경우다. 총괄성과 실생활의 연결이 약하면 응용 문제를 못 잡는다.", "fix": "'어는점 내림을 도로 제설제·자동차 부동액에 이용'함을 못 박는다. 총괄성과 실생활의 연결로 응용 문제를 잡아라.", "cite": ""}, "CH2-148": {"name": "총괄성 관계", "course": "ch2", "unit": "총괄성", "tier": "C", "mis": ["같은 방향으로 변한다.", "같은 입자 수에 의존한다."], "dx": "증기압 내림·끓는점 오름·어는점 내림·삼투압이 모두 같은 입자 수에 따라 함께 변한다는 점을 놓친 경우다. 네 성질이 한 원인(입자 수)에서 나온다는 점이 약하면 총괄성을 따로따로 외우게 된다.", "fix": "'증기압 내림·끓는점 오름·어는점 내림·삼투압이 모두 같은 입자 수에 따라 함께 변함'을 못 박는다. 네 성질이 한 원인(입자 수)에서 나옴을 잡아 따로따로 외우지 마라.", "cite": ""}, "CH2-149": {"name": "총괄성 크기", "course": "ch2", "unit": "총괄성", "tier": "C", "mis": ["입자 수에 비례한다.", "입자 수가 많다."], "dx": "총괄성의 크기가 녹아 있는 입자 수에 비례한다는 점을 놓친 경우다. 입자 수가 많을수록 효과가 크다는 비례가 약하면 총괄성 크기 비교가 어긋난다.", "fix": "'총괄성의 크기는 녹아 있는 입자 수에 비례'함을 못 박는다. 입자 수가 많을수록 효과가 큼을 잡아 총괄성 크기를 비교하라.", "cite": ""}, "CH2-150": {"name": "비전해질 비교", "course": "ch2", "unit": "총괄성", "tier": "C", "mis": ["둘 다 비전해질이다.", "입자 수가 같다."], "dx": "둘 다 비전해질이면 같은 몰랄 농도에서 내놓는 입자 수가 같아 총괄성이 같다는 점을 놓친 경우다. 비전해질은 종류와 무관하게 입자 수가 같다는 점이 약하면 총괄성을 잘못 비교한다.", "fix": "'둘 다 비전해질이면 같은 몰랄 농도에서 내놓는 입자 수가 같아 총괄성이 같음'을 못 박는다. 비전해질은 종류 무관하게 입자 수가 같음을 잡아 비교하라.", "cite": ""}, "CH2-151": {"name": "몰랄 상수", "course": "ch2", "unit": "총괄성", "tier": "C", "mis": ["용매 고유의 값이다.", "용매마다 정해진다."], "dx": "몰랄 오름·내림 상수가 용매마다 고유하게 정해진 값이라는 점을 놓친 경우다. 용매가 정하는 상수라는 점이 약하면 다른 용매로 바뀔 때 총괄성 계산이 어긋난다.", "fix": "'몰랄 오름·내림 상수는 용매마다 고유하게 정해진 값'임을 못 박는다. 용매가 정하는 상수임을 잡아 다른 용매로 바뀔 때 계산을 맞춰라.", "cite": ""}, "CH2-112": {"name": "몰랄 농도 정의", "course": "ch2", "unit": "농도", "tier": "A", "mis": ["용매 질량 기준이다.", "질량 기준이다.", "용질 몰수/용매 kg이다.", "용매 질량당 몰수이다."], "dx": "몰랄 농도가 용매 질량(kg)당 용질 몰수라는 정의를 놓친 경우다(용액 부피나 용액 질량이 아님). 분모가 용매 질량이라는 점이 약하면 총괄성 계산에서 농도를 잘못 잡는다.", "fix": "몰랄 농도를 '용매 질량(kg)당 용질 몰수'로 못 박는다(용액 부피·질량이 아님). 분모가 용매 질량임을 잡아 총괄성 계산에 써라.", "cite": ""}, "CH2-113": {"name": "몰분율 정의", "course": "ch2", "unit": "농도", "tier": "C", "mis": ["몰수 기준이다.", "전체 몰수로 나눈다.", "몰수의 비이다."], "dx": "몰분율이 한 성분의 몰수를 전체 몰수로 나눈 비라는 정의를 놓친 경우다. 몰수 기준이라는 점이 약하면 라울 법칙(용매 몰분율) 적용이 막힌다.", "fix": "몰분율을 '한 성분의 몰수를 전체 몰수로 나눈 비'로 못 박는다. 몰수 기준임을 잡아 라울 법칙(용매 몰분율) 적용에 써라.", "cite": ""}, "CH2-114": {"name": "퍼센트 농도 정의", "course": "ch2", "unit": "농도", "tier": "C", "mis": ["용액 질량 기준이다.", "질량 백분율이다."], "dx": "퍼센트 농도가 용액 질량에 대한 용질 질량의 백분율이라는 정의를 놓친 경우다. 분모가 용액 질량이라는 점이 약하면 다른 농도로의 환산이 어긋난다.", "fix": "퍼센트 농도를 '용액 질량에 대한 용질 질량의 백분율'로 못 박는다. 분모가 용액 질량임을 잡아 다른 농도로의 환산을 맞춰라.", "cite": ""}, "CH2-115": {"name": "몰농도 정의", "course": "ch2", "unit": "농도", "tier": "C", "mis": ["용액 부피 기준이다.", "부피 기준이다.", "용질 몰수/용액 L이다."], "dx": "몰농도가 용액 부피(L)당 용질 몰수라는 정의를 놓친 경우다. 부피 기준이라는 점이 약하면 온도에 따라 값이 변하는 성질과 환산이 흔들린다.", "fix": "몰농도를 '용액 부피(L)당 용질 몰수'로 못 박는다. 부피 기준임을 잡아 온도에 따라 값이 변하는 성질과 환산을 따져라.", "cite": ""}, "CH2-116": {"name": "몰랄 농도 온도", "course": "ch2", "unit": "농도", "tier": "C", "mis": ["질량은 변하지 않는다.", "질량 기준이다."], "dx": "몰랄 농도가 질량 기준이라 온도가 변해도 값이 변하지 않는다는 점을 놓친 경우다. 온도 무관이라는 점이 약하면 총괄성 식에 왜 몰농도가 아닌 몰랄 농도를 쓰는지 못 짚는다.", "fix": "'몰랄 농도는 질량 기준이라 온도가 변해도 값이 변하지 않음'을 못 박는다. 온도 무관임을 잡아 총괄성 식에 몰농도가 아닌 몰랄 농도를 쓰는 까닭을 짚어라.", "cite": ""}, "CH2-117": {"name": "몰농도 온도", "course": "ch2", "unit": "농도", "tier": "A", "mis": ["부피가 변한다.", "분모가 커진다."], "dx": "몰농도가 부피 기준이라 온도가 오르면 부피가 늘어(분모가 커져) 값이 작아진다는 점을 놓친 경우다. 온도 의존이 약하면 온도가 다른 조건에서 몰농도를 그대로 쓰는 오류를 범한다.", "fix": "'몰농도는 부피 기준이라 온도가 오르면 부피가 늘어(분모가 커져) 값이 작아짐'을 못 박는다. 온도가 다른 조건에서 몰농도를 그대로 쓰지 마라.", "cite": ""}, "CH2-118": {"name": "농도 근사", "course": "ch2", "unit": "농도", "tier": "A", "mis": ["부피와 질량이 거의 같다.", "용질이 많다.", "근사일 뿐이다.", "용질이 적어진다."], "dx": "묽은 수용액에서 용질이 적어 부피(L)와 질량(kg)이 거의 같을 때만 몰농도와 몰랄 농도가 근사적으로 같다는 점을 놓친 경우다. 이 근사가 용질이 많으면 깨진다는 한계가 약하면 진한 용액에서 잘못 쓴다.", "fix": "'묽은 수용액에서 용질이 적어 부피(L)와 질량(kg)이 거의 같을 때만 몰농도와 몰랄 농도가 근사적으로 같음'을 못 박는다. 진한 용액에선 이 근사가 깨짐을 잡아라.", "cite": ""}, "CH2-119": {"name": "몰분율 합", "course": "ch2", "unit": "농도", "tier": "C", "mis": ["전체를 1로 본다.", "백분율이 아니다."], "dx": "모든 성분의 몰분율을 더하면 1이 된다는(백분율이 아님) 점을 놓친 경우다. 합이 1이라는 점이 약하면 한 성분 몰분율에서 나머지를 구하지 못한다.", "fix": "'모든 성분의 몰분율을 더하면 1(백분율 아님)'임을 못 박는다. 합이 1임을 잡아 한 성분에서 나머지 몰분율을 구하라.", "cite": ""}, "CH2-120": {"name": "몰분율 단위", "course": "ch2", "unit": "농도", "tier": "B", "mis": ["몰수의 비이다."], "dx": "몰분율이 몰수의 비라 단위가 없는 값이라는 점을 놓친 경우다. 무차원이라는 점이 약하면 몰분율을 다른 농도 단위와 섞어 쓴다.", "fix": "몰분율을 '몰수의 비라 단위가 없는 값'으로 못 박는다. 무차원임을 잡아 다른 농도 단위와 섞어 쓰지 마라.", "cite": ""}, "CH2-121": {"name": "퍼센트 농도 온도", "course": "ch2", "unit": "농도", "tier": "C", "mis": ["질량은 온도에 무관하다.", "질량 기준이다.", "질량은 변하지 않는다."], "dx": "퍼센트 농도가 질량 기준이라 온도에 무관하다는 점을 놓친 경우다. 몰농도와 달리 온도로 안 변한다는 대비가 약하면 농도 비교를 잘못한다.", "fix": "'퍼센트 농도는 질량 기준이라 온도에 무관'함을 못 박는다. 몰농도와 달리 온도로 안 변함을 대비해 농도 비교에 써라.", "cite": ""}, "CH2-122": {"name": "용액 구성", "course": "ch2", "unit": "농도", "tier": "C", "mis": ["용매가 필요하다.", "두 가지 이상이 섞인다."], "dx": "용액이 용매에 용질이 녹아 고르게 섞인 혼합물이라는 점을 놓친 경우다. 용매·용질 구성이 흐리면 농도의 분자·분모를 잘못 잡는다.", "fix": "용액을 '용매에 용질이 녹아 고르게 섞인 혼합물'로 못 박는다. 용매·용질 구성을 잡아 농도의 분자·분모를 맞춰라.", "cite": ""}, "CH2-123": {"name": "용질·용매", "course": "ch2", "unit": "농도", "tier": "C", "mis": ["역할이 반대이다.", "물이 녹인다.", "양으로 구분한다."], "dx": "용질(녹는 것)과 용매(녹이는 것, 보통 양이 많은 쪽)의 역할을 가르지 못한 경우다. 둘을 뒤바꾸면 농도 정의가 어긋난다.", "fix": "'용질 = 녹는 것, 용매 = 녹이는 것(보통 양이 많은 쪽)'으로 역할을 갈라 둔다. 둘을 뒤바꾸지 말고 농도 정의에 써라.", "cite": ""}, "CH2-124": {"name": "몰랄 농도 의미", "course": "ch2", "unit": "농도", "tier": "C", "mis": ["용매 질량 기준이다.", "질량 기준이다.", "용질은 몰수로 센다."], "dx": "몰랄 농도가 용매 질량(kg)당 용질을 몰수로 센 값이라는 의미를 놓친 경우다. 용질을 질량이 아니라 몰수로 센다는 점이 약하면 몰랄 농도를 잘못 계산한다.", "fix": "몰랄 농도를 '용매 질량(kg)당 용질을 몰수로 센 값'으로 못 박는다. 용질을 질량이 아니라 몰수로 셈을 잡아 바로 계산하라.", "cite": ""}, "CH2-125": {"name": "농도 환산", "course": "ch2", "unit": "농도", "tier": "C", "mis": ["부피와 질량을 잇는다.", "질량을 부피로 바꾼다."], "dx": "농도 단위를 환산할 때 밀도가 부피와 질량을 잇는 다리라는 점을 놓친 경우다. 밀도를 빼먹으면 몰농도와 몰랄·퍼센트 사이 환산이 막힌다.", "fix": "농도 환산에서 '밀도가 부피와 질량을 잇는 다리'임을 못 박는다. 몰농도와 몰랄·퍼센트 사이를 밀도로 건너 환산하라.", "cite": ""}, "CH2-126": {"name": "몰랄 농도 계산", "course": "ch2", "unit": "농도", "tier": "C", "mis": ["분모가 커진다."], "dx": "몰랄 농도를 (용질 몰수 ÷ 용매 kg)으로 셈하는 게 흔들린 경우다. 분모를 용액이 아니라 용매 질량으로 잡지 못하면 총괄성 계산이 어긋난다.", "fix": "몰랄 농도를 '용질 몰수 ÷ 용매 kg'으로 셈한다. 분모를 용액이 아니라 용매 질량으로 잡아 총괄성 계산을 맞춰라.", "cite": ""}, "CH2-127": {"name": "ppm", "course": "ch2", "unit": "농도", "tier": "C", "mis": ["100만분의 1이다.", "퍼센트보다 훨씬 작다.", "미량 농도이다."], "dx": "ppm이 100만분의 1을 나타내 퍼센트보다 훨씬 작은 미량 농도 단위라는 점을 놓친 경우다. 척도 감각이 약하면 미량 성분의 농도를 잘못 읽는다.", "fix": "ppm을 '100만분의 1을 나타내 퍼센트보다 훨씬 작은 미량 농도 단위'로 못 박는다. 척도 감각을 잡아 미량 성분의 농도를 읽어라.", "cite": ""}, "CH2-128": {"name": "온도 무관 농도", "course": "ch2", "unit": "농도", "tier": "C", "mis": ["질량 기준이다.", "부피 기준만 변한다.", "몰수 기준이다."], "dx": "질량·몰수 기준 농도(몰랄·몰분율·퍼센트)는 온도에 무관하고 부피 기준 몰농도만 변한다는 점을 놓친 경우다. 무엇이 기준인지로 온도 의존이 갈린다는 점이 약하면 온도 문제에서 농도를 잘못 고른다.", "fix": "'질량·몰수 기준 농도(몰랄·몰분율·퍼센트)는 온도 무관, 부피 기준 몰농도만 변함'을 못 박는다. 무엇이 기준인지로 온도 의존이 갈림을 잡아 온도 문제에서 농도를 골라라.", "cite": ""}, "CH2-129": {"name": "농도 의미", "course": "ch2", "unit": "농도", "tier": "C", "mis": ["용질이 많이 녹아 있다.", "용질이 적게 녹아 있다.", "농도가 용질 양을 반영한다."], "dx": "농도가 용액(또는 용매) 일정량에 용질이 얼마나 녹아 있는지를 나타낸다는 점을 놓친 경우다. 농도가 용질 양을 반영한다는 감각이 약하면 진하고 묽음을 잘못 판단한다.", "fix": "농도를 '용액(또는 용매) 일정량에 용질이 얼마나 녹아 있는지'로 못 박는다. 농도가 용질 양을 반영함을 잡아 진하고 묽음을 판단하라.", "cite": ""}, "CH2-130": {"name": "농도 세기 성질", "course": "ch2", "unit": "농도", "tier": "C", "mis": ["세기 성질이다.", "양에 의존하지 않는다."], "dx": "농도가 용액 양과 무관한 세기 성질이라는 점을 놓친 경우다. 용액을 더 떠도 농도는 그대로라는 점이 약하면 양에 따라 농도가 변한다고 잘못 본다.", "fix": "농도를 '용액 양과 무관한 세기 성질(더 떠도 농도는 그대로)'로 못 박는다. 양에 따라 농도가 변한다고 보지 마라.", "cite": ""}, "CH2-131": {"name": "몰농도 의미", "course": "ch2", "unit": "농도", "tier": "C", "mis": ["몰농도가 용질 몰수를 반영한다.", "용액 부피가 1 L여야 한다.", "용액 부피 기준이다."], "dx": "몰농도가 용액 1 L당 몰수의 비라 부피가 꼭 1 L가 아니어도 정의된다는 점을 놓친 경우다. 부피가 1 L여야 한다고 오해하면 다른 부피의 농도 계산이 막힌다.", "fix": "몰농도를 '용액 1 L당 몰수의 비라 부피가 꼭 1 L가 아니어도 정의됨'으로 못 박는다. 부피가 1 L여야 한다고 오해 말고 다른 부피의 농도를 계산하라.", "cite": ""}, "CH2-132": {"name": "묽힘", "course": "ch2", "unit": "농도", "tier": "C", "mis": ["용매만 더한다.", "용매만 늘어난다.", "용질을 더하지 않는다."], "dx": "묽힘이 용매만 더해 용질 몰수는 그대로이고 농도만 낮추는 것이라는 점을 놓친 경우다. 용질 몰수 보존이 약하면 묽힘 후 농도를 못 구한다.", "fix": "묽힘을 '용매만 더해 용질 몰수는 그대로이고 농도만 낮춤'으로 못 박는다. 용질 몰수 보존을 잡아 묽힘 후 농도를 구하라.", "cite": ""}, "CH2-133": {"name": "몰분율 해석", "course": "ch2", "unit": "농도", "tier": "C", "mis": ["비율을 나타낸다."], "dx": "몰분율을 입자 수로 따진 성분의 비율로 읽지 못한 경우다. 비율이라는 해석이 약하면 라울 법칙에서 용매 몰분율이 증기압 내림으로 이어지는 흐름을 못 짚는다.", "fix": "몰분율을 '입자 수로 따진 성분의 비율'로 못 박는다. 비율임을 잡아 라울 법칙에서 용매 몰분율이 증기압 내림으로 이어지는 흐름을 짚어라.", "cite": ""}, "CH2-134": {"name": "농도 비교", "course": "ch2", "unit": "농도", "tier": "C", "mis": ["기준이 다르다.", "몰수가 다르다.", "몰수 = 질량/분자량이다."], "dx": "서로 다른 농도 단위는 기준(부피·질량·몰수)이 달라 직접 비교하려면 몰수 = 질량/분자량 등으로 통일해야 한다는 점을 놓친 경우다. 기준 차이를 무시하면 농도 비교가 어긋난다.", "fix": "'서로 다른 농도 단위는 기준(부피·질량·몰수)이 달라, 비교하려면 몰수 = 질량/분자량 등으로 통일'함을 못 박는다. 기준 차이를 무시 말고 통일해 비교하라.", "cite": ""}, "CH2-135": {"name": "농도와 총괄성", "course": "ch2", "unit": "농도", "tier": "C", "mis": ["입자 수에 의존한다.", "입자 수에 비례한다."], "dx": "총괄성이 용질 입자 수에 비례해 농도(입자 수 기준)가 그 크기를 정한다는 점을 놓친 경우다. 입자 수와 총괄성의 연결이 약하면 다음 단원 총괄성 계산이 흔들린다.", "fix": "'총괄성은 용질 입자 수에 비례해 농도(입자 수 기준)가 그 크기를 정함'을 못 박는다. 입자 수와 총괄성의 연결을 다음 단원의 바탕으로 삼아라.", "cite": ""}, "CH2-211": {"name": "용해 정의", "course": "ch2", "unit": "용해", "tier": "C", "mis": ["새 물질을 만들지 않는다.", "층을 이루지 않는다.", "균일하게 섞인다."], "dx": "용해가 새 물질을 만들지 않고 용질이 용매에 고르게 섞이는(층을 이루지 않는) 현상이라는 점을 놓친 경우다. 용해를 화학 반응과 혼동하면 용해 과정의 본질을 잘못 잡는다.", "fix": "용해를 '새 물질을 만들지 않고 용질이 용매에 고르게 섞이는(층을 이루지 않는) 현상'으로 못 박는다. 화학 반응과 혼동 말고 용해의 본질을 잡아라.", "cite": ""}, "CH2-212": {"name": "용해 단계", "course": "ch2", "unit": "용해", "tier": "C", "mis": ["새 인력이 생긴다.", "인력을 끊어야 한다."], "dx": "용해가 용질·용매 사이 기존 인력을 끊고(흡열) 용질-용매 새 인력을 만드는(발열) 단계로 이뤄진다는 점을 놓친 경우다. 이 단계 구분이 약하면 용해 엔탈피의 부호를 설명하지 못한다.", "fix": "용해를 '용질·용매 사이 기존 인력을 끊고(흡열) 용질-용매 새 인력을 만드는(발열) 단계'로 못 박는다. 이 단계 구분으로 용해 엔탈피의 부호를 설명하라.", "cite": ""}, "CH2-213": {"name": "용해 엔탈피", "course": "ch2", "unit": "용해", "tier": "C", "mis": ["물질에 따라 다르다."], "dx": "용해 엔탈피가 인력을 끊는 흡열과 새 인력을 만드는 발열의 합이라 물질에 따라 발열일 수도 흡열일 수도 있다는 점을 놓친 경우다. 이 수지가 약하면 용해 시 온도 변화를 예측하지 못한다.", "fix": "용해 엔탈피를 '인력을 끊는 흡열과 새 인력을 만드는 발열의 합이라 물질에 따라 발열일 수도 흡열일 수도 있음'으로 못 박는다. 이 수지로 용해 시 온도 변화를 예측하라.", "cite": ""}, "CH2-214": {"name": "용해 자발성", "course": "ch2", "unit": "용해", "tier": "C", "mis": ["무질서도가 커진다.", "ΔG = ΔH - TΔS이다.", "TΔS가 우세하다."], "dx": "용해가 흡열이어도 입자가 흩어져 엔트로피가 커지면(TΔS 항) 자발적일 수 있다는 점을 놓친 경우다. ΔG = ΔH − TΔS를 용해에 적용하지 못하면 흡열 용해가 왜 일어나는지 설명하지 못한다.", "fix": "'용해가 흡열이어도 입자가 흩어져 엔트로피가 커지면(TΔS 항) 자발적일 수 있음'을 못 박는다. ΔG = ΔH − TΔS를 용해에 적용해 흡열 용해가 왜 일어나는지 설명하라.", "cite": ""}, "CH2-215": {"name": "용해성 규칙", "course": "ch2", "unit": "용해", "tier": "C", "mis": ["성질이 다르다.", "성질이 비슷해야 한다."], "dx": "비슷한 성질끼리 잘 녹는다(극성은 극성에, 무극성은 무극성에)는 용해성 규칙을 놓친 경우다. 이 규칙이 약하면 어떤 용질이 어떤 용매에 녹는지 예측하지 못한다.", "fix": "'비슷한 성질끼리 잘 녹음(극성은 극성에, 무극성은 무극성에)'을 용해성 규칙으로 못 박는다. 이 규칙으로 어떤 용질이 어떤 용매에 녹는지 예측하라.", "cite": ""}, "CH2-216": {"name": "용해성", "course": "ch2", "unit": "용해", "tier": "C", "mis": ["성질이 다르다.", "극성끼리 잘 녹는다."], "dx": "극성 물질은 극성 용매에, 무극성 물질은 무극성 용매에 잘 녹는다는 점을 놓친 경우다. 분자 간 힘의 닮음이 용해를 정한다는 점이 약하면 기름이 물에 안 섞이는 까닭을 못 짚는다.", "fix": "'극성 물질은 극성 용매에, 무극성 물질은 무극성 용매에 잘 녹음'을 못 박는다. 분자 간 힘의 닮음이 용해를 정함을 잡아 기름이 물에 안 섞이는 까닭을 짚어라.", "cite": ""}, "CH2-217": {"name": "용해도 정의", "course": "ch2", "unit": "용해", "tier": "C", "mis": ["온도 의존이다.", "최대 용해량이다.", "물질마다 다르다."], "dx": "용해도가 일정 온도에서 녹을 수 있는 최대량이고 물질·온도마다 다르다는 점을 놓친 경우다. 용해도 정의가 흐리면 포화·불포화 판정이 어긋난다.", "fix": "용해도를 '일정 온도에서 녹을 수 있는 최대량이고 물질·온도마다 다름'으로 못 박는다. 이 정의로 포화·불포화를 판정하라.", "cite": ""}, "CH2-218": {"name": "포화 용액", "course": "ch2", "unit": "용해", "tier": "C", "mis": ["동적 평형이다.", "용해도만큼 녹았다."], "dx": "포화 용액이 용해도만큼 녹아 용해와 석출이 동적 평형을 이룬 상태라는 점을 놓친 경우다. 동적 평형이라는 점이 약하면 포화를 '더는 아무 일 없는' 상태로 오해한다.", "fix": "포화 용액을 '용해도만큼 녹아 용해와 석출이 동적 평형을 이룬 상태'로 못 박는다. 동적 평형임을 잡아 포화를 '아무 일 없는' 상태로 오해 마라.", "cite": ""}, "CH2-219": {"name": "불포화 용액", "course": "ch2", "unit": "용해", "tier": "C", "mis": ["용해도보다 적게 녹았다.", "최대보다 적다.", "더 녹을 수 있다."], "dx": "불포화 용액이 용해도보다 적게 녹아 더 녹을 수 있는 상태라는 점을 놓친 경우다. 포화와의 대비가 약하면 용액 상태를 가리지 못한다.", "fix": "불포화 용액을 '용해도보다 적게 녹아 더 녹을 수 있는 상태'로 못 박는다. 포화와 대비해 용액 상태를 가려라.", "cite": ""}, "CH2-220": {"name": "고체 용해도와 온도", "course": "ch2", "unit": "용해", "tier": "C", "mis": ["온도가 높으면 더 녹는다."], "dx": "대부분의 고체가 온도가 높을수록 용해도가 커진다는 점을 놓친 경우다. 이 경향이 약하면 온도를 내릴 때 석출되는 재결정 현상을 설명하지 못한다.", "fix": "'대부분의 고체는 온도가 높을수록 용해도가 커짐'을 못 박는다. 온도를 내릴 때 석출되는 재결정 현상을 이로 설명하라.", "cite": ""}, "CH2-221": {"name": "기체 용해도와 온도", "course": "ch2", "unit": "용해", "tier": "B", "mis": ["발열이라 온도가 높으면 덜 녹는다.", "발열이라 온도가 높으면 불리하다.", "발열 과정이다.", "온도가 낮으면 더 녹는다."], "dx": "기체 용해가 발열이라 온도가 높을수록 용해도가 작아진다는(고체와 반대) 점을 놓친 경우다. 이 반대 경향이 약하면 따뜻한 물에서 기체가 덜 녹는 까닭을 못 짚는다.", "fix": "'기체 용해는 발열이라 온도가 높을수록 용해도가 작아짐(고체와 반대)'을 못 박는다. 이 반대 경향으로 따뜻한 물에서 기체가 덜 녹는 까닭을 짚어라.", "cite": ""}, "CH2-222": {"name": "헨리 법칙", "course": "ch2", "unit": "용해", "tier": "A", "mis": ["정비례이다.", "온도가 일정해야 한다.", "헨리 법칙이다.", "기체에 대한 법칙이다.", "이상적인 기체에 잘 맞는다."], "dx": "헨리 법칙이 일정 온도에서 기체 용해도가 그 기체 분압에 정비례한다는 법칙이라는 점을 놓친 경우다. 압력과 용해도의 정비례가 약하면 압력 변화에 따른 기체 용해량을 못 구한다.", "fix": "헨리 법칙을 '일정 온도에서 기체 용해도가 그 기체 분압에 정비례'로 못 박는다. 압력과 용해도의 정비례로 압력 변화에 따른 기체 용해량을 구하라.", "cite": ""}, "CH2-223": {"name": "헨리 응용", "course": "ch2", "unit": "용해", "tier": "C", "mis": ["압력이 낮아져 빠져나온다.", "압력 변화 때문이다.", "압력이 높으면 더 녹는다."], "dx": "압력이 낮아지면 녹아 있던 기체가 빠져나온다는(탄산음료를 열면 거품, 잠수병) 헨리 법칙 응용을 놓친 경우다. 압력 변화와 기체 방출을 못 이으면 응용 현상을 설명하지 못한다.", "fix": "'압력이 낮아지면 녹아 있던 기체가 빠져나옴(탄산음료를 열면 거품, 잠수병)'을 못 박는다. 압력 변화와 기체 방출을 이어 응용 현상을 설명하라.", "cite": ""}, "CH2-224": {"name": "헨리 법칙 계산", "course": "ch2", "unit": "용해", "tier": "C", "mis": ["정비례이다."], "dx": "기체 용해도가 분압에 정비례한다는 헨리 법칙으로 용해량을 계산하는 게 흔들린 경우다. 압력을 두 배로 하면 용해량도 두 배라는 비례가 약하면 계산이 어긋난다.", "fix": "'기체 용해도가 분압에 정비례'함을 헨리 법칙으로 계산한다. 압력을 두 배로 하면 용해량도 두 배임을 잡아 용해량을 구하라.", "cite": ""}, "CH2-225": {"name": "압력과 고체 용해도", "course": "ch2", "unit": "용해", "tier": "C", "mis": ["고체는 압력에 둔감하다.", "압력에 둔감하다."], "dx": "고체·액체의 용해도가 압력에 거의 영향받지 않는다는 점을 놓친 경우다. 압력이 기체 용해도에만 크게 작용한다는 점이 약하면 헨리 법칙을 고체에까지 잘못 적용한다.", "fix": "'고체·액체의 용해도는 압력에 거의 영향받지 않음'을 못 박는다. 압력이 기체 용해도에만 크게 작용함을 잡아 헨리 법칙을 고체에 잘못 적용 마라.", "cite": ""}, "CH2-226": {"name": "압력과 기체 용해도", "course": "ch2", "unit": "용해", "tier": "C", "mis": ["헨리 법칙이다.", "정비례이다."], "dx": "기체 용해도가 압력이 높을수록 커진다는(헨리 법칙) 점을 놓친 경우다. 압력이 기체를 용액에 밀어 넣는다는 그림이 약하면 압력-기체 용해도 관계가 어긋난다.", "fix": "'기체 용해도는 압력이 높을수록 커짐(헨리 법칙)'을 못 박는다. 압력이 기체를 용액에 밀어 넣는 그림으로 압력-기체 용해도 관계를 잡아라.", "cite": ""}, "CH2-227": {"name": "과포화 용액", "course": "ch2", "unit": "용해", "tier": "C", "mis": ["용해도를 넘는다.", "쉽게 석출된다."], "dx": "과포화 용액이 용해도를 넘게 녹은 불안정한 상태라 작은 자극에도 쉽게 석출된다는 점을 놓친 경우다. 이 불안정성이 약하면 과포화를 그냥 진한 용액으로 오해한다.", "fix": "과포화 용액을 '용해도를 넘게 녹은 불안정한 상태라 작은 자극에도 쉽게 석출됨'으로 못 박는다. 그냥 진한 용액으로 오해 마라.", "cite": ""}, "CH2-228": {"name": "헨리 법칙 한계", "course": "ch2", "unit": "용해", "tier": "C", "mis": ["잘 녹는 기체는 벗어난다.", "이상적 조건에서 벗어난다."], "dx": "헨리 법칙이 물에 잘 녹거나 반응하는 기체(HCl·NH₃)에는 잘 맞지 않는다는 한계를 놓친 경우다. 법칙이 이상적 조건에서만 성립한다는 점이 약하면 적용 범위를 잘못 잡는다.", "fix": "'헨리 법칙은 물에 잘 녹거나 반응하는 기체(HCl·NH₃)에는 잘 맞지 않음'을 못 박는다. 이상적 조건에서만 성립함을 잡아 적용 범위를 가려라.", "cite": ""}, "CH2-229": {"name": "온도와 기체 용해도", "course": "ch2", "unit": "용해", "tier": "C", "mis": ["기체 용해는 발열이다.", "온도가 높으면 덜 녹는다."], "dx": "기체 용해가 발열이라 온도가 높을수록 덜 녹는다는 점을 놓친 경우다. 이 경향이 약하면 수온이 오르면 물속 산소가 줄어드는 환경 문제로 이어지지 못한다.", "fix": "'기체 용해는 발열이라 온도가 높을수록 덜 녹음'을 못 박는다. 이 경향으로 수온이 오르면 물속 산소가 줄어드는 환경 문제로 이어라.", "cite": ""}, "CH2-230": {"name": "용해 평형", "course": "ch2", "unit": "용해", "tier": "C", "mis": ["동적 평형이다.", "포화 상태이다."], "dx": "용해 평형이 용해와 석출 속도가 같은 포화 상태의 동적 평형이라는 점을 놓친 경우다. 동적 본질이 약하면 포화 용액에서 일어나는 일을 잘못 그린다.", "fix": "용해 평형을 '용해와 석출 속도가 같은 포화 상태의 동적 평형'으로 못 박는다. 동적 본질을 잡아 포화 용액에서 일어나는 일을 그려라.", "cite": ""}, "CH2-337": {"name": "화학 전지", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["화학 → 전기이다.", "자발적 반응이다.", "산화환원 반응을 이용한다."], "dx": "화학 전지가 자발적인 산화환원 반응의 화학 에너지를 전기 에너지로 바꾸는 장치라는 점을 놓친 경우다. 자발 반응이 전기를 만든다는 점이 약하면 전기분해와 구분하지 못한다.", "fix": "화학 전지를 '자발적인 산화환원 반응의 화학 에너지를 전기 에너지로 바꾸는 장치'로 못 박는다. 자발 반응이 전기를 만듦을 잡아 전기분해와 구분하라.", "cite": ""}, "CH2-338": {"name": "전극 반응", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["환원전극은 환원이다.", "산화전극은 산화이다.", "전극마다 다르다."], "dx": "산화전극에서는 산화, 환원전극에서는 환원이 일어난다는 점을 놓친 경우다(이름과 일어나는 반응이 같음). 어느 전극에서 무엇이 일어나는지가 약하면 전극 극성·전자 흐름이 어긋난다.", "fix": "'산화전극에서는 산화, 환원전극에서는 환원(이름과 반응이 같음)'을 못 박는다. 어느 전극에서 무엇이 일어나는지로 전극 극성·전자 흐름을 잡아라.", "cite": ""}, "CH2-339": {"name": "전극 극성", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["산화전극이 (-)극이다.", "환원전극이 (+)극이다.", "산화전극에서 나온다."], "dx": "화학 전지에서 산화전극이 (-)극, 환원전극이 (+)극이라는 점을 놓친 경우다. 극성을 뒤집으면 전자가 어디로 흐르는지, 전지 전위 계산이 통째로 어긋난다.", "fix": "화학 전지에서 '산화전극이 (-)극, 환원전극이 (+)극'임을 못 박는다. 극성을 뒤집지 말고 전자 흐름·전지 전위 계산을 맞춰라.", "cite": ""}, "CH2-340": {"name": "전자 이동", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["산화전극에서 나온다.", "(-)극에서 나온다."], "dx": "전자가 산화전극((-)극)에서 도선을 따라 환원전극((+)극)으로 흐른다는 점을 놓친 경우다. 전자 흐름의 방향이 약하면 전류 방향·전극 반응을 잘못 잡는다.", "fix": "'전자가 산화전극((-)극)에서 도선을 따라 환원전극((+)극)으로 흐름'을 못 박는다. 전자 흐름의 방향으로 전류 방향·전극 반응을 잡아라.", "cite": ""}, "CH2-341": {"name": "다니엘 전지", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["아연이 산화된다.", "구리는 환원된다."], "dx": "다니엘 전지에서 아연이 산화(산화전극)되고 구리 이온이 환원(환원전극)된다는 점을 놓친 경우다. 어느 금속이 산화·환원되는지가 약하면 전지의 작동을 설명하지 못한다.", "fix": "'다니엘 전지에서 아연이 산화(산화전극)되고 구리 이온이 환원(환원전극)됨'을 못 박는다. 어느 금속이 산화·환원되는지로 전지의 작동을 설명하라.", "cite": ""}, "CH2-342": {"name": "염다리", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["이온이 이동한다.", "전하 균형을 맞춘다.", "전하 균형이 필요하다."], "dx": "염다리가 이온을 이동시켜 두 반쪽 전지의 전하 균형을 맞춘다는 점을 놓친 경우다. 전하 균형이 없으면 전류가 곧 끊긴다는 점이 약하면 염다리의 역할을 못 짚는다.", "fix": "염다리를 '이온을 이동시켜 두 반쪽 전지의 전하 균형을 맞춤'으로 못 박는다. 전하 균형이 없으면 전류가 곧 끊김을 잡아 염다리의 역할을 짚어라.", "cite": ""}, "CH2-343": {"name": "표준 수소 전극", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["기준이 0 V이다.", "상대값이다.", "기준 전극이다."], "dx": "표준 수소 전극이 전위를 0 V로 정한 기준 전극이고 모든 표준 전위가 이에 대한 상대값이라는 점을 놓친 경우다. 기준이 흐리면 표준 환원 전위의 의미를 못 짚는다.", "fix": "표준 수소 전극을 '전위를 0 V로 정한 기준 전극, 모든 표준 전위가 이에 대한 상대값'으로 못 박는다. 기준을 잡아 표준 환원 전위의 의미를 짚어라.", "cite": ""}, "CH2-344": {"name": "전지 전위", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["환원전극에서 산화전극을 뺀다.", "빼는 값이다.", "전위차이다."], "dx": "전지 전위가 (환원전극의 표준 환원 전위 − 산화전극의 표준 환원 전위)라는 점을 놓친 경우다. 빼는 순서가 약하면 전지 전위의 부호가 뒤집혀 자발성 판단이 어긋난다.", "fix": "전지 전위를 '(환원전극의 표준 환원 전위 − 산화전극의 표준 환원 전위)'로 못 박는다. 빼는 순서를 맞춰 전지 전위의 부호와 자발성 판단을 잡아라.", "cite": ""}, "CH2-345": {"name": "자발성", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["양수면 자발적이다.", "부호가 자발성을 결정한다."], "dx": "전지 전위가 양수면 자발적 반응이라는 점을 놓친 경우다. 부호가 자발성을 정한다는 점이 약하면 그 반응이 전지로 작동할지 전기분해가 필요한지 못 가린다.", "fix": "'전지 전위가 양수면 자발적 반응'임을 못 박는다. 부호가 자발성을 정함을 잡아 전지로 작동할지 전기분해가 필요한지 가려라.", "cite": ""}, "CH2-346": {"name": "표준 환원 전위", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["환원되기 쉽다.", "잘 환원된다."], "dx": "표준 환원 전위가 클수록 환원되기 쉽다는 점을 놓친 경우다. 전위로 환원되기 쉬운 정도를 못 읽으면 어느 물질이 환원전극이 되는지, 산화제 세기를 못 가린다.", "fix": "'표준 환원 전위가 클수록 환원되기 쉬움'을 못 박는다. 전위로 어느 물질이 환원전극이 되는지, 산화제 세기를 가려라.", "cite": ""}, "CH2-347": {"name": "전기분해", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["비자발적이다.", "전기를 공급받는다.", "외부 전원이 필요하다."], "dx": "전기분해가 비자발적 반응을 외부 전원으로 강제로 일으키는 것이라는 점을 놓친 경우다. 외부 전원이 필요하다는 점이 약하면 자발 반응을 쓰는 전지와 혼동한다.", "fix": "전기분해를 '비자발적 반응을 외부 전원으로 강제로 일으키는 것'으로 못 박는다. 외부 전원이 필요함을 잡아 자발 반응을 쓰는 전지와 혼동하지 마라.", "cite": ""}, "CH2-348": {"name": "전기분해 전극", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["전자를 받는다.", "전자를 잃는다.", "전극마다 다르다."], "dx": "전기분해에서도 산화전극에서 산화, 환원전극에서 환원이 일어나지만 외부 전원에 연결돼 극성은 전지와 반대((+)극이 산화전극)라는 점을 놓친 경우다. 이 차이가 약하면 전기분해 전극 반응을 잘못 잡는다.", "fix": "'전기분해에서도 산화전극에서 산화·환원전극에서 환원이지만 극성은 전지와 반대((+)극이 산화전극)'임을 못 박는다. 이 차이로 전기분해 전극 반응을 잡아라.", "cite": ""}, "CH2-349": {"name": "패러데이 법칙", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["전하량에 비례한다.", "정비례이다."], "dx": "전기분해에서 석출되는 물질의 양이 흘려준 전하량에 정비례한다는 패러데이 법칙을 놓친 경우다. 전하량과 석출량의 비례가 약하면 석출량 계산이 막힌다.", "fix": "패러데이 법칙을 '석출되는 물질의 양이 흘려준 전하량에 정비례'로 못 박는다. 전하량과 석출량의 비례로 석출량을 계산하라.", "cite": ""}, "CH2-350": {"name": "전하량", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["Q = It이다."], "dx": "전하량 Q를 (전류 I × 시간 t)로 구한다는 점을 놓친 경우다. 이 식이 약하면 전류와 시간에서 흘려준 전하량을 못 구한다.", "fix": "전하량을 'Q = 전류 I × 시간 t'로 못 박는다. 이 식으로 전류와 시간에서 흘려준 전하량을 구하라.", "cite": ""}, "CH2-351": {"name": "패러데이 상수", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["패러데이 상수이다.", "전자 1몰의 전하량이다."], "dx": "패러데이 상수가 전자 1몰의 전하량(약 96500 C)이라는 점을 놓친 경우다. 이 상수가 약하면 전하량을 전자 몰수로 환산하지 못한다.", "fix": "패러데이 상수를 '전자 1몰의 전하량(약 96500 C)'으로 못 박는다. 이 상수로 전하량을 전자 몰수로 환산하라.", "cite": ""}, "CH2-352": {"name": "전기분해 응용", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["전기분해 응용이다.", "산업에 쓰인다."], "dx": "전기분해가 전기 도금·금속 정련·물 분해 같은 산업에 쓰인다는 응용을 놓친 경우다. 전기분해와 실생활의 연결이 약하면 응용 문제를 못 잡는다.", "fix": "'전기분해가 전기 도금·금속 정련·물 분해 같은 산업에 쓰임'을 못 박는다. 전기분해와 실생활의 연결로 응용 문제를 잡아라.", "cite": ""}, "CH2-353": {"name": "물 전기분해", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["수소와 산소가 생긴다.", "부피비가 2:1이다.", "전기가 필요하다."], "dx": "물을 전기분해하면 수소와 산소가 생기고 그 부피비가 2:1이라는 점을 놓친 경우다. 이 부피비가 약하면 물 전기분해의 양적관계가 어긋난다.", "fix": "'물을 전기분해하면 수소와 산소가 생기고 부피비가 2:1'임을 못 박는다. 이 부피비로 물 전기분해의 양적관계를 맞춰라.", "cite": ""}, "CH2-354": {"name": "전지 vs 전기분해", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["자발적 반응으로 전기를 만든다.", "방향이 반대이다.", "전기를 공급받는다."], "dx": "화학 전지는 자발 반응으로 전기를 만들고 전기분해는 전기를 받아 비자발 반응을 일으켜 방향이 반대라는 점을 놓친 경우다. 둘을 구분 못 하면 어느 쪽이 에너지를 만들고 쓰는지 헷갈린다.", "fix": "'화학 전지는 자발 반응으로 전기를 만들고 전기분해는 전기를 받아 비자발 반응을 일으켜 방향이 반대'임을 못 박는다. 둘을 구분해 어느 쪽이 에너지를 만들고 쓰는지 잡아라.", "cite": ""}, "CH2-355": {"name": "패러데이 계산", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["가수가 작으면 더 석출된다.", "가수에 반비례한다."], "dx": "같은 전하량이라도 이온의 가수가 클수록 석출되는 몰수가 적다(가수에 반비례)는 점을 놓친 경우다. 가수 보정이 약하면 서로 다른 이온의 석출량을 잘못 비교한다.", "fix": "'같은 전하량이라도 이온의 가수가 클수록 석출되는 몰수가 적음(가수에 반비례)'을 못 박는다. 가수 보정으로 서로 다른 이온의 석출량을 비교하라.", "cite": ""}, "CH2-356": {"name": "전극 질량", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["금속이 녹아 나간다.", "금속이 석출된다.", "녹고 석출된다."], "dx": "산화전극에서는 금속이 녹아 나가 질량이 줄고 환원전극에서는 금속이 석출돼 질량이 는다는 점을 놓친 경우다. 어느 전극이 녹고 쌓이는지가 약하면 전극 질량 변화를 잘못 잡는다.", "fix": "'산화전극에서는 금속이 녹아 질량이 줄고 환원전극에서는 석출돼 질량이 늚'을 못 박는다. 어느 전극이 녹고 쌓이는지로 전극 질량 변화를 잡아라.", "cite": ""}, "CH2-357": {"name": "산화제 세기", "course": "ch2", "unit": "전기화학", "tier": "C", "mis": ["전자를 잘 받는다.", "전위로 비교한다."], "dx": "산화제의 세기가 전자를 얼마나 잘 받는지(표준 환원 전위가 클수록 강함)로 정해진다는 점을 놓친 경우다. 전위로 산화제 세기를 비교하지 못하면 반응 방향을 못 예측한다.", "fix": "'산화제의 세기는 전자를 얼마나 잘 받는지(표준 환원 전위가 클수록 강함)로 정해짐'을 못 박는다. 전위로 산화제 세기를 비교해 반응 방향을 예측하라.", "cite": ""}, "CH2-171": {"name": "계와 주위", "course": "ch2", "unit": "엔탈피", "tier": "C", "mis": ["계는 대상 자체이다.", "주위는 나머지이다.", "서로 다르다."], "dx": "계(관찰 대상인 반응)와 주위(그 밖의 모든 것)를 가르지 못한 경우다. 이 구분이 약하면 열이 계에서 주위로 나가는지 들어오는지(발열·흡열)를 잘못 잡는다.", "fix": "'계 = 관찰 대상인 반응, 주위 = 그 밖의 모든 것'으로 갈라 둔다. 이 구분으로 열이 계에서 주위로 나가는지 들어오는지(발열·흡열)를 잡아라.", "cite": ""}, "CH2-172": {"name": "엔탈피 정의", "course": "ch2", "unit": "엔탈피", "tier": "C", "mis": ["일정 압력 기준이다.", "절대값은 알 수 없다.", "상태 함수이다."], "dx": "엔탈피가 일정 압력에서의 열함량이고 절대값은 알 수 없어 변화량(ΔH)으로만 다루는 상태 함수라는 점을 놓친 경우다. 절대값 대신 변화량이라는 점이 약하면 반응엔탈피 계산이 막힌다.", "fix": "엔탈피를 '일정 압력에서의 열함량이고 절대값은 알 수 없어 변화량(ΔH)으로만 다루는 상태 함수'로 못 박는다. 변화량임을 잡아 반응엔탈피를 계산하라.", "cite": ""}, "CH2-173": {"name": "반응엔탈피", "course": "ch2", "unit": "엔탈피", "tier": "C", "mis": ["생성물 − 반응물이다.", "빼는 값이다.", "둘 다 필요하다."], "dx": "반응엔탈피가 (생성물 엔탈피 − 반응물 엔탈피)라는 점을 놓친 경우다. 생성물에서 반응물을 뺀다는 방향이 약하면 ΔH 부호가 뒤집힌다.", "fix": "반응엔탈피를 '(생성물 엔탈피 − 반응물 엔탈피)'로 못 박는다. 생성물에서 반응물을 빼는 방향을 잡아 ΔH 부호를 맞춰라.", "cite": ""}, "CH2-174": {"name": "ΔH 부호", "course": "ch2", "unit": "엔탈피", "tier": "A", "mis": ["열을 방출한다.", "열을 흡수한다.", "엔탈피가 감소한다.", "주위에서 열을 흡수한다.", "열 출입에 따라 부호가 정해진다."], "dx": "열을 방출하면 ΔH<0(발열), 흡수하면 ΔH>0(흡열)이라는 부호 약속을 놓친 경우다. 열 출입 방향과 부호의 대응이 흔들리면 열화학 반응식의 부호가 어긋난다.", "fix": "'열을 방출하면 ΔH<0(발열), 흡수하면 ΔH>0(흡열)'을 못 박는다. 열 출입 방향과 부호의 대응으로 열화학 반응식 부호를 잡아라.", "cite": ""}, "CH2-175": {"name": "표준 상태", "course": "ch2", "unit": "엔탈피", "tier": "C", "mis": ["25°C 기준이다.", "기준 조건이 있다."], "dx": "표준 상태가 25°C·1기압 같은 정해진 기준 조건이라는 점을 놓친 경우다. 기준 조건이 흐리면 표준 생성·반응 엔탈피의 비교 기준이 사라진다.", "fix": "표준 상태를 '25°C·1기압 같은 정해진 기준 조건'으로 못 박는다. 기준 조건을 잡아 표준 생성·반응 엔탈피의 비교 기준으로 삼아라.", "cite": ""}, "CH2-176": {"name": "표준 생성 엔탈피", "course": "ch2", "unit": "엔탈피", "tier": "A", "mis": ["기준점이 된다.", "가장 안정한 홑원소 물질이다.", "화합물은 0이 아닐 수 있다.", "안정한 홑원소만 0이다.", "1몰 기준이다."], "dx": "표준 생성 엔탈피에서 가장 안정한 홑원소 물질만 0이고 화합물은 0이 아니라는 점을 놓친 경우다(1몰 기준). 기준점인 홑원소 0을 못 잡으면 생성 엔탈피로 반응엔탈피를 구하지 못한다.", "fix": "표준 생성 엔탈피에서 '가장 안정한 홑원소 물질만 0, 화합물은 0이 아님(1몰 기준)'을 못 박는다. 기준점인 홑원소 0을 잡아 생성 엔탈피로 반응엔탈피를 구하라.", "cite": ""}, "CH2-177": {"name": "반응엔탈피 계산", "course": "ch2", "unit": "엔탈피", "tier": "C", "mis": ["생성물 − 반응물이다.", "빼는 값이다.", "계수를 반영한다."], "dx": "반응엔탈피를 (생성물 생성 엔탈피 합 − 반응물 생성 엔탈피 합)으로, 계수를 곱해 구한다는 점을 놓친 경우다. 계수 반영을 빼먹으면 ΔH 계산이 어긋난다.", "fix": "반응엔탈피를 '(생성물 생성 엔탈피 합 − 반응물 생성 엔탈피 합), 계수를 곱해' 구한다. 계수 반영을 빼먹지 말고 ΔH를 계산하라.", "cite": ""}, "CH2-178": {"name": "헤스 법칙", "course": "ch2", "unit": "엔탈피", "tier": "B", "mis": ["엔탈피는 양에 비례한다.", "방향이 반대이다.", "상태 함수이다.", "엔탈피가 더해진다."], "dx": "엔탈피가 상태 함수라 반응엔탈피가 경로와 무관하고 여러 반응의 ΔH를 더해(뒤집으면 부호 반대, 배수하면 함께) 구한다는 헤스 법칙을 놓친 경우다. 이 조합 규칙이 약하면 다단계 ΔH 계산이 막힌다.", "fix": "헤스 법칙을 '엔탈피가 상태 함수라 반응엔탈피가 경로와 무관, 여러 ΔH를 더해 구함(뒤집으면 부호 반대, 배수하면 함께)'으로 못 박는다. 이 조합 규칙으로 다단계 ΔH를 계산하라.", "cite": ""}, "CH2-179": {"name": "결합 에너지", "course": "ch2", "unit": "엔탈피", "tier": "A", "mis": ["에너지가 필요하다.", "안정해진다.", "반응물 − 생성물이다.", "평균 결합 에너지를 쓴다.", "끊기 어렵다."], "dx": "결합 에너지로 반응엔탈피를 구할 때 (반응물에서 끊은 결합 에너지 합 − 생성물에서 만든 결합 에너지 합)으로, 평균 결합 에너지를 쓴다는 점을 놓친 경우다. 끊음·만듦의 방향이 흔들리면 ΔH 부호가 뒤집힌다.", "fix": "결합 에너지로 반응엔탈피를 '(반응물에서 끊은 결합 에너지 합 − 생성물에서 만든 결합 에너지 합), 평균 결합 에너지로' 구한다. 끊음·만듦의 방향을 잡아 ΔH 부호를 맞춰라.", "cite": ""}, "CH2-180": {"name": "흡열과 엔탈피", "course": "ch2", "unit": "엔탈피", "tier": "C", "mis": ["엔탈피가 증가한다.", "열을 흡수한다.", "주위에서 열을 흡수한다."], "dx": "흡열 반응에서 엔탈피가 늘어(ΔH>0) 주위에서 열을 흡수한다는 점을 놓친 경우다. 흡수와 엔탈피 증가의 연결이 약하면 부호 판단이 어긋난다.", "fix": "'흡열 반응은 엔탈피가 늘어(ΔH>0) 주위에서 열을 흡수'함을 못 박는다. 흡수와 엔탈피 증가를 이어 부호를 판단하라.", "cite": ""}, "CH2-181": {"name": "결합 에너지 적용", "course": "ch2", "unit": "엔탈피", "tier": "C", "mis": ["에너지가 방출된다.", "결합 에너지가 결정한다."], "dx": "결합을 만들 때 방출하는 에너지가 끊을 때 흡수하는 것보다 크면 발열이라는 점을 놓친 경우다. 결합 에너지 수지로 발열·흡열을 가르지 못하면 반응의 열 성격을 잘못 본다.", "fix": "'결합을 만들 때 방출하는 에너지가 끊을 때 흡수하는 것보다 크면 발열'임을 못 박는다. 결합 에너지 수지로 발열·흡열을 가려라.", "cite": ""}, "CH2-182": {"name": "열량계", "course": "ch2", "unit": "엔탈피", "tier": "B", "mis": ["c는 비열이다.", "열 손실이 없다.", "열량을 측정한다.", "열을 방출한다."], "dx": "열량계에서 방출·흡수한 열량을 q = m·c·ΔT(c는 비열)로 구하고 열 손실이 없다고 가정한다는 점을 놓친 경우다. 이 측정 식이 약하면 반응열을 실험으로 못 구한다.", "fix": "열량계에서 열량을 'q = m·c·ΔT(c는 비열), 열 손실이 없다고 가정'으로 못 박는다. 이 측정 식으로 반응열을 실험으로 구하라.", "cite": ""}, "CH2-183": {"name": "비열", "course": "ch2", "unit": "엔탈피", "tier": "C", "mis": ["열을 많이 흡수한다.", "1 g 기준이다."], "dx": "비열이 물질 1 g의 온도를 1°C 올리는 데 드는 열량이고 비열이 클수록 같은 열에 온도가 덜 오른다는 점을 놓친 경우다. 비열의 의미가 약하면 q=mcΔT 계산이 어긋난다.", "fix": "비열을 '물질 1 g의 온도를 1°C 올리는 데 드는 열량, 클수록 같은 열에 온도가 덜 오름'으로 못 박는다. 비열의 의미를 잡아 q=mcΔT를 계산하라.", "cite": ""}, "CH2-184": {"name": "엔탈피와 열", "course": "ch2", "unit": "엔탈피", "tier": "C", "mis": ["일정 압력 기준이다.", "q = ΔH이다."], "dx": "일정 압력에서 반응이 주고받는 열량이 곧 반응엔탈피(q = ΔH)라는 점을 놓친 경우다. 이 등식이 약하면 열량계로 잰 열을 ΔH로 연결하지 못한다.", "fix": "'일정 압력에서 반응이 주고받는 열량이 곧 반응엔탈피(q = ΔH)'임을 못 박는다. 이 등식으로 열량계로 잰 열을 ΔH로 연결하라.", "cite": ""}, "CH2-185": {"name": "상태 함수", "course": "ch2", "unit": "엔탈피", "tier": "C", "mis": ["처음과 끝 상태로 정해진다.", "상태 함수이다.", "경로와 무관하다."], "dx": "엔탈피가 처음·끝 상태로만 정해지고 경로와 무관한 상태 함수라는 점을 놓친 경우다. 이 본질이 약하면 헤스 법칙이 왜 성립하는지 근거가 사라진다.", "fix": "엔탈피를 '처음·끝 상태로만 정해지고 경로와 무관한 상태 함수'로 못 박는다. 이 본질을 헤스 법칙이 성립하는 근거로 삼아라.", "cite": ""}, "CH2-186": {"name": "생성 엔탈피 해석", "course": "ch2", "unit": "엔탈피", "tier": "C", "mis": ["에너지가 높다.", "에너지가 낮다.", "에너지 높낮이를 나타낸다."], "dx": "생성 엔탈피를 화합물이 구성 홑원소보다 에너지가 높은지 낮은지를 나타내는 값으로 읽지 못한 경우다. 에너지 높낮이라는 해석이 약하면 화합물의 상대적 안정성을 못 비교한다.", "fix": "생성 엔탈피를 '화합물이 구성 홑원소보다 에너지가 높은지 낮은지를 나타내는 값'으로 읽는다. 에너지 높낮이로 화합물의 상대적 안정성을 비교하라.", "cite": ""}, "CH2-187": {"name": "열용량", "course": "ch2", "unit": "엔탈피", "tier": "C", "mis": ["열용량은 물질 전체이다.", "질량을 곱한다.", "질량이 곱해진다."], "dx": "열용량이 물질 전체의 값이라 (질량 × 비열)로 구해지고 단위 질량당 값인 비열과 다르다는 점을 놓친 경우다. 둘을 혼동하면 열량 계산에서 질량을 두 번 곱하거나 빠뜨린다.", "fix": "열용량을 '물질 전체의 값이라 (질량 × 비열)로 구함, 단위 질량당 값인 비열과 다름'으로 못 박는다. 둘을 혼동해 질량을 두 번 곱하거나 빠뜨리지 마라.", "cite": ""}, "CH2-188": {"name": "발열과 엔탈피", "course": "ch2", "unit": "엔탈피", "tier": "C", "mis": ["엔탈피가 감소한다."], "dx": "발열 반응에서 엔탈피가 줄어든다(ΔH<0)는 점을 놓친 경우다. 방출과 엔탈피 감소의 연결이 약하면 부호 판단이 어긋난다.", "fix": "'발열 반응은 엔탈피가 줄어듦(ΔH<0)'을 못 박는다. 방출과 엔탈피 감소를 이어 부호를 판단하라.", "cite": ""}, "CH2-189": {"name": "엔트로피 정의", "course": "ch2", "unit": "엔트로피", "tier": "C", "mis": ["무질서도를 나타낸다."], "dx": "엔트로피가 입자와 에너지의 무질서도(흩어진 정도)를 나타내는 양이라는 점을 놓친 경우다. 이 정의가 흐리면 ΔS 부호와 자발성 판단의 한 축이 무너진다.", "fix": "엔트로피를 '입자와 에너지의 무질서도(흩어진 정도)를 나타내는 양'으로 못 박는다. 이 정의를 ΔS 부호와 자발성 판단의 한 축으로 삼아라.", "cite": ""}, "CH2-190": {"name": "상태별 엔트로피", "course": "ch2", "unit": "엔트로피", "tier": "B", "mis": ["기체가 더 무질서하다.", "무질서도 순서이다."], "dx": "엔트로피가 고체 < 액체 < 기체 순으로 커진다(입자가 자유로울수록 무질서)는 점을 놓친 경우다. 이 순서가 약하면 상태 변화·반응에서 엔트로피 증감을 못 가린다.", "fix": "엔트로피를 '고체 < 액체 < 기체 순으로 커짐(자유로울수록 무질서)'으로 못 박는다. 이 순서로 상태 변화·반응의 엔트로피 증감을 가려라.", "cite": ""}, "CH2-191": {"name": "온도와 엔트로피", "course": "ch2", "unit": "엔트로피", "tier": "C", "mis": ["입자 운동이 활발해진다.", "입자 운동에 영향을 준다."], "dx": "온도가 높을수록 입자 운동이 활발해져 엔트로피가 커진다는 점을 놓친 경우다. 온도와 무질서도의 연결이 약하면 온도 변화에 따른 엔트로피 변화를 못 짚는다.", "fix": "'온도가 높을수록 입자 운동이 활발해져 엔트로피가 커짐'을 못 박는다. 온도와 무질서도를 이어 온도 변화에 따른 엔트로피 변화를 짚어라.", "cite": ""}, "CH2-192": {"name": "기체 수와 엔트로피", "course": "ch2", "unit": "엔트로피", "tier": "C", "mis": ["무질서도가 커진다.", "무질서도가 작아진다.", "기체 몰수가 핵심이다."], "dx": "반응에서 기체 분자 수가 늘면 엔트로피가 커진다는(기체 몰수 변화가 핵심) 점을 놓친 경우다. 양변 기체 몰수를 비교하지 못하면 반응의 ΔS 부호를 잘못 잡는다.", "fix": "'반응에서 기체 분자 수가 늘면 엔트로피가 커짐(기체 몰수 변화가 핵심)'을 못 박는다. 양변 기체 몰수를 비교해 반응의 ΔS 부호를 잡아라.", "cite": ""}, "CH2-193": {"name": "상태 변화와 엔트로피", "course": "ch2", "unit": "엔트로피", "tier": "C", "mis": ["무질서도가 커진다.", "무질서도가 작아진다."], "dx": "융해·기화는 엔트로피를 키우고 응고·액화는 줄인다는 점을 놓친 경우다. 상변화 방향과 무질서도 변화를 못 이으면 ΔS 부호가 어긋난다.", "fix": "'융해·기화는 엔트로피를 키우고 응고·액화는 줄임'을 못 박는다. 상변화 방향과 무질서도 변화를 이어 ΔS 부호를 잡아라.", "cite": ""}, "CH2-194": {"name": "ΔS 정의", "course": "ch2", "unit": "엔트로피", "tier": "C", "mis": ["생성물 − 반응물이다.", "빼는 값이다.", "양수는 증가이다."], "dx": "엔트로피 변화 ΔS가 (생성물 엔트로피 − 반응물 엔트로피)이고 양수면 증가라는 점을 놓친 경우다. 부호의 의미가 약하면 자발성 식에서 ΔS를 잘못 넣는다.", "fix": "ΔS를 '(생성물 엔트로피 − 반응물 엔트로피), 양수면 증가'로 못 박는다. 부호의 의미를 잡아 자발성 식에 ΔS를 바로 넣어라.", "cite": ""}, "CH2-205": {"name": "기체 생성", "course": "ch2", "unit": "엔트로피", "tier": "C", "mis": ["무질서도가 커진다.", "기체가 자유롭게 움직인다."], "dx": "고체·액체에서 기체가 생기는 반응이 엔트로피를 크게 키운다는 점을 놓친 경우다(기체는 자유롭게 움직임). 기체 생성과 무질서도 증가를 못 이으면 ΔS를 과소평가한다.", "fix": "'고체·액체에서 기체가 생기는 반응은 엔트로피를 크게 키움(기체는 자유롭게 움직임)'을 못 박는다. 기체 생성과 무질서도 증가를 이어 ΔS를 과소평가 마라.", "cite": ""}, "CH2-206": {"name": "ΔS 해석", "course": "ch2", "unit": "엔트로피", "tier": "C", "mis": ["양수는 증가이다.", "음수는 감소이다.", "부호가 방향을 나타낸다."], "dx": "ΔS가 양수면 무질서도 증가, 음수면 감소라 부호가 변화 방향을 나타낸다는 점을 놓친 경우다. 부호 해석이 약하면 반응이 무질서를 늘리는지 줄이는지 못 가린다.", "fix": "'ΔS가 양수면 무질서도 증가, 음수면 감소라 부호가 변화 방향을 나타냄'을 못 박는다. 부호 해석으로 반응이 무질서를 늘리는지 줄이는지 가려라.", "cite": ""}, "CH2-209": {"name": "엔트로피 감소 반응", "course": "ch2", "unit": "엔트로피", "tier": "C", "mis": ["전체 엔트로피로 판단한다.", "전체 엔트로피가 기준이다."], "dx": "계의 엔트로피가 줄어도 주위까지 합한 전체 엔트로피가 늘면 자발적일 수 있다는 점을 놓친 경우다. 전체 엔트로피로 판단한다는 기준이 약하면 발열로 엔트로피가 주는 반응의 자발성을 잘못 본다.", "fix": "'계의 엔트로피가 줄어도 주위까지 합한 전체 엔트로피가 늘면 자발적일 수 있음'을 못 박는다. 전체 엔트로피로 판단함을 잡아 발열로 엔트로피가 주는 반응의 자발성을 보라.", "cite": ""}, "CH2-210": {"name": "용해와 엔트로피", "course": "ch2", "unit": "엔트로피", "tier": "C", "mis": ["입자가 흩어진다.", "무질서도가 커진다."], "dx": "용해가 보통 입자가 흩어져 엔트로피가 커지는 과정이라는 점을 놓친 경우다. 용해와 무질서도 증가를 못 이으면 용해 자발성에서 엔트로피 항의 역할을 놓친다.", "fix": "'용해는 보통 입자가 흩어져 엔트로피가 커지는 과정'임을 못 박는다. 용해와 무질서도 증가를 이어 용해 자발성에서 엔트로피 항의 역할을 잡아라.", "cite": ""}, "CH2-036": {"name": "상태 방정식", "course": "ch2", "unit": "이상기체", "tier": "A", "mis": ["절대 온도를 쓴다.", "보일 법칙이다.", "이상 기체 방정식이다.", "보편 상수이다.", "V ∝ n이다.", "R는 단위에 따라 달라진다."], "dx": "이상 기체 상태 방정식 PV=nRT를 절대 온도(K) 기준으로 쓰지 못한 경우다(섭씨를 그대로 넣는 게 전형). 온도를 K로 안 바꾸면 보일·샤를을 아우르는 이 식의 모든 계산이 어긋난다.", "fix": "이상 기체 상태 방정식을 'PV=nRT, 온도는 반드시 절대 온도(K)'로 못 박는다. 섭씨를 넣지 말고 273을 더해 K로 바꾼 뒤 계산하라.", "cite": ""}, "CH2-037": {"name": "보일 법칙", "course": "ch2", "unit": "이상기체", "tier": "B", "mis": ["반비례한다.", "PV = 일정이다."], "dx": "일정 온도에서 압력과 부피가 반비례(PV = 일정)한다는 보일 법칙을 놓친 경우다. 압력을 키우면 부피가 줄어드는 이 관계가 약하면 압력·부피 변화 계산이 어긋난다.", "fix": "보일 법칙을 '일정 온도에서 압력과 부피가 반비례(PV = 일정)'로 못 박는다. 압력을 키우면 부피가 주는 관계로 P₁V₁ = P₂V₂를 적용하라.", "cite": ""}, "CH2-038": {"name": "샤를 법칙", "course": "ch2", "unit": "이상기체", "tier": "C", "mis": ["절대 온도 기준이다.", "V/T = 일정이다."], "dx": "일정 압력에서 부피가 절대 온도에 비례(V/T = 일정)한다는 샤를 법칙을 놓친 경우다. 섭씨로 비례를 따지면 비가 깨져 온도·부피 계산이 어긋난다.", "fix": "샤를 법칙을 '일정 압력에서 부피가 절대 온도에 비례(V/T = 일정)'로 못 박는다. 섭씨 말고 K로 비를 따져 온도·부피를 계산하라.", "cite": ""}, "CH2-039": {"name": "아보가드로 법칙", "course": "ch2", "unit": "이상기체", "tier": "C", "mis": ["종류와 무관하다.", "분자량과 무관하다."], "dx": "같은 온도·압력에서 부피가 몰수에 비례하고 기체 종류·분자량과 무관하다는 아보가드로 법칙을 놓친 경우다. 부피가 곧 몰수를 대변한다는 점이 약하면 기체 양적관계가 막힌다.", "fix": "아보가드로 법칙을 '같은 온도·압력에서 부피가 몰수에 비례, 기체 종류·분자량과 무관'으로 못 박는다. 부피가 곧 몰수를 대변함을 양적관계에 써라.", "cite": ""}, "CH2-040": {"name": "기체 상수", "course": "ch2", "unit": "이상기체", "tier": "C", "mis": ["보편 상수이다.", "상수이다.", "단위에 의존한다."], "dx": "기체 상수 R가 기체 종류와 무관한 보편 상수이고 값은 단위 선택에 따라 달라질 뿐이라는 점을 놓친 경우다. R를 기체마다 다른 값으로 여기면 상태 방정식 계산이 어긋난다.", "fix": "기체 상수 R를 '기체 종류와 무관한 보편 상수, 값은 단위 선택으로만 달라짐'으로 못 박는다. 기체마다 다른 값이라 여기지 말고 단위를 맞춰 R를 써라.", "cite": ""}, "CH2-041": {"name": "몰부피", "course": "ch2", "unit": "이상기체", "tier": "B", "mis": ["22.4 L이다.", "종류와 무관하다.", "조건에 의존한다."], "dx": "표준 상태(0°C, 1 atm)에서 기체 1몰이 종류와 무관하게 22.4 L라는 점, 그리고 이 값이 조건에 의존한다는 점을 놓친 경우다. 조건이 바뀌면 22.4 L가 아니라는 점이 약하면 비표준 조건 계산이 어긋난다.", "fix": "'표준 상태(0°C, 1 atm) 기체 1몰 = 22.4 L, 단 조건이 바뀌면 22.4 L 아님'을 못 박는다. 비표준 조건에선 PV=nRT로 부피를 다시 구하라.", "cite": ""}, "CH2-042": {"name": "이상 기체 가정", "course": "ch2", "unit": "이상기체", "tier": "A", "mis": ["분자 간 힘을 무시한다.", "크기를 무시한다.", "에너지 손실이 없다.", "크기를 0으로 본다."], "dx": "이상 기체가 분자 자체의 크기를 0으로 보고 분자 간 힘을 무시하며 충돌에서 에너지 손실이 없다고 가정한다는 점을 놓친 경우다. 이 가정이 흐리면 실제 기체가 왜·언제 어긋나는지의 기준이 사라진다.", "fix": "이상 기체 가정을 '분자 크기 0, 분자 간 힘 무시, 충돌 시 에너지 손실 없음'으로 못 박는다. 이 가정이 실제 기체가 언제 어긋나는지의 기준임을 잡아라.", "cite": ""}, "CH2-043": {"name": "운동 에너지와 온도", "course": "ch2", "unit": "이상기체", "tier": "A", "mis": ["속력은 √T에 비례한다.", "온도가 결정한다.", "온도가 같다."], "dx": "기체의 평균 운동 에너지가 오직 절대 온도로만 정해진다는 점을 놓친 경우다. 같은 온도면 분자량이 달라도 평균 운동 에너지가 같다는 점이 약하면 무거운 분자가 왜 느린지 설명하지 못한다.", "fix": "'기체의 평균 운동 에너지는 오직 절대 온도로만 정해짐(같은 온도면 분자량 무관)'을 못 박는다. 그래서 무거운 분자가 느린 까닭(같은 에너지, 큰 질량)을 짚어라.", "cite": ""}, "CH2-044": {"name": "온도와 속력", "course": "ch2", "unit": "이상기체", "tier": "C", "mis": ["운동 에너지가 커진다.", "운동 에너지가 변한다.", "v ∝ √T이다."], "dx": "온도가 높을수록 운동 에너지가 커져 분자 속력이 빨라진다(v ∝ √T)는 점을 놓친 경우다. 온도와 속력의 제곱근 관계가 약하면 온도에 따른 속력 분포 변화를 못 읽는다.", "fix": "'온도가 높을수록 운동 에너지가 커져 속력이 빨라짐(v ∝ √T)'을 못 박는다. 온도와 속력의 제곱근 관계로 속력 분포 변화를 읽어라.", "cite": ""}, "CH2-045": {"name": "분자량과 속력", "course": "ch2", "unit": "이상기체", "tier": "A", "mis": ["v ∝ 1/√M이다.", "분자량이 작다.", "H₂가 가볍다."], "dx": "같은 온도에서 분자 속력이 분자량의 제곱근에 반비례(v ∝ 1/√M)해 가벼운 분자가 빠르다는 점을 놓친 경우다(H₂가 가장 빠름). 이 관계가 약하면 확산·분출 속도 비교가 어긋난다.", "fix": "'같은 온도에서 속력은 분자량의 제곱근에 반비례(v ∝ 1/√M)해 가벼운 분자가 빠름'을 못 박는다(H₂가 가장 빠름). 이 관계로 확산·분출 속도를 비교하라.", "cite": ""}, "CH2-046": {"name": "제곱평균제곱근 속력", "course": "ch2", "unit": "이상기체", "tier": "C", "mis": ["√(3RT/M)이다.", "T의 제곱근에 비례한다."], "dx": "제곱평균제곱근 속력이 √(3RT/M)이라 온도의 제곱근에 비례하고 분자량의 제곱근에 반비례한다는 점을 놓친 경우다. 이 식이 약하면 속력을 정량적으로 비교하지 못한다.", "fix": "제곱평균제곱근 속력을 '√(3RT/M)이라 온도의 제곱근에 비례, 분자량의 제곱근에 반비례'로 못 박는다. 이 식으로 속력을 정량 비교하라.", "cite": ""}, "CH2-047": {"name": "속력 분포", "course": "ch2", "unit": "이상기체", "tier": "C", "mis": ["분포를 이룬다.", "빠른 분자가 늘어난다.", "속력이 제각각이다."], "dx": "기체 분자들이 하나의 속력이 아니라 분포를 이루고 온도가 높을수록 분포가 넓고 빠른 쪽으로 이동한다는 점을 놓친 경우다. 이 분포 감각이 약하면 반응 속도에서 활성화 에너지를 넘는 분자 비율 논의로 이어지지 못한다.", "fix": "'기체 분자는 하나의 속력이 아니라 분포를 이루고, 온도가 높을수록 분포가 넓고 빠른 쪽으로 이동'함을 못 박는다. 이 분포를 반응 속도(활성화 에너지 넘는 비율)로 이어라.", "cite": ""}, "CH2-048": {"name": "그레이엄 법칙", "course": "ch2", "unit": "이상기체", "tier": "A", "mis": ["제곱근에 반비례한다.", "그레이엄 법칙이다.", "분자량이 작다."], "dx": "기체의 확산·분출 속도가 분자량의 제곱근에 반비례(그레이엄 법칙)한다는 점을 놓친 경우다. 가벼운 기체가 빨리 퍼진다는 이 관계가 약하면 두 기체의 확산 속도비를 못 구한다.", "fix": "그레이엄 법칙을 '확산·분출 속도가 분자량의 제곱근에 반비례'로 못 박는다. 가벼운 기체가 빨리 퍼짐을 잡아 두 기체의 확산 속도비를 구하라.", "cite": ""}, "CH2-049": {"name": "압력의 기원", "course": "ch2", "unit": "이상기체", "tier": "C", "mis": ["충돌이 압력을 만든다."], "dx": "기체 압력이 분자가 용기 벽에 충돌하며 생긴다는 점을 놓친 경우다. 압력의 기원이 충돌이라는 그림이 약하면 분자 수·속력이 압력을 어떻게 바꾸는지 설명하지 못한다.", "fix": "기체 압력을 '분자가 용기 벽에 충돌하며 생김'으로 못 박는다. 압력의 기원이 충돌임을 잡아 분자 수·속력이 압력을 바꾸는 까닭을 설명하라.", "cite": ""}, "CH2-050": {"name": "실제 기체 편차", "course": "ch2", "unit": "이상기체", "tier": "C", "mis": ["분자 간 힘과 부피 영향이 작다.", "분자 부피 영향이 작다.", "분자 간 힘을 가진다."], "dx": "실제 기체가 분자 부피와 분자 간 힘을 실제로 가져 이상 기체에서 벗어난다는 점을 놓친 경우다(이상 기체는 둘 다 무시). 편차의 두 원인이 약하면 어떤 조건에서 어긋나는지 못 짚는다.", "fix": "'실제 기체는 분자 부피와 분자 간 힘을 실제로 가져 이상 기체에서 벗어남(이상은 둘 다 무시)'을 못 박는다. 편차의 두 원인으로 어느 조건에서 어긋나는지 짚어라.", "cite": ""}, "CH2-051": {"name": "절대 영도", "course": "ch2", "unit": "이상기체", "tier": "C", "mis": ["0°C는 273 K이다.", "운동 에너지가 0이다.", "최저 온도이다."], "dx": "절대 영도(0 K, 약 −273°C)가 분자 운동 에너지가 이론상 0이 되는 최저 온도라는 점을 놓친 경우다(0°C는 273 K). 절대 온도의 기준점이 흐리면 샤를 법칙의 비례가 어긋난다.", "fix": "절대 영도를 '0 K(약 −273°C)로 분자 운동 에너지가 이론상 0이 되는 최저 온도'로 못 박는다(0°C는 273 K). 이 기준점으로 샤를 법칙의 비를 맞춰라.", "cite": ""}, "CH2-001": {"name": "분자 간 힘 정의", "course": "ch2", "unit": "분자간힘", "tier": "C", "mis": ["원자를 묶는 것은 화학 결합이다.", "인력이다.", "상태 변화에 영향을 준다."], "dx": "분자 사이에 작용하는 인력(분자 간 힘)을 원자를 묶는 화학 결합과 뒤섞은 경우다. 분자 간 힘이 분자 '사이'의 힘이라는 점이 흐리면 끓음·녹음 같은 상태 변화의 원인을 잘못 짚는다.", "fix": "분자 간 힘을 '분자 사이에 작용하는 인력(원자를 묶는 화학 결합과는 다름)'으로 못 박는다. '사이의 힘'임을 잡아 끓음·녹음 같은 상태 변화의 원인으로 삼아라.", "cite": ""}, "CH2-002": {"name": "분자 간 힘 vs 결합", "course": "ch2", "unit": "분자간힘", "tier": "B", "mis": ["결합보다 약하다.", "공유 결합은 유지된다."], "dx": "분자 간 힘이 화학 결합보다 훨씬 약하고, 끓을 때 끊기는 건 분자 간 힘이지 분자 안의 공유 결합이 아니라는 점을 놓친 경우다. 이 구분이 없으면 물이 끓으면 H₂O가 H와 O로 쪼개진다고 잘못 본다.", "fix": "'분자 간 힘은 결합보다 훨씬 약하고, 끓을 때 끊기는 건 분자 간 힘이지 분자 안 공유 결합이 아님'을 못 박는다. 물이 끓어도 H₂O가 H와 O로 쪼개지지 않음을 새겨라.", "cite": ""}, "CH2-003": {"name": "분산력 보편성", "course": "ch2", "unit": "분자간힘", "tier": "A", "mis": ["모든 분자에 작용한다.", "전자를 가진다.", "전자가 있어야 한다.", "분산력이 작용한다."], "dx": "분산력이 무극성 분자에만 작용한다고 본 경우다. 전자를 가진 모든 분자에 작용하는 가장 기본 힘이라는 점을 놓치면 극성 분자에도 분산력이 깔려 있다는 사실을 빠뜨린다.", "fix": "분산력을 '전자를 가진 모든 분자에 작용하는 가장 기본 힘(무극성만이 아님)'으로 못 박는다. 극성 분자에도 분산력이 깔려 있음을 잡아라.", "cite": ""}, "CH2-004": {"name": "분산력 원리", "course": "ch2", "unit": "분자간힘", "tier": "C", "mis": ["일시적 쌍극자이다.", "전자 치우침 때문이다.", "순간 쌍극자로 작용한다."], "dx": "분산력이 전자 구름이 순간적으로 치우쳐 생긴 일시적 쌍극자 때문이라는 원리를 놓친 경우다. 순간 쌍극자라는 발생 원리가 약하면 전자 수가 세기를 정하는 까닭으로 이어지지 못한다.", "fix": "분산력을 '전자 구름이 순간적으로 치우쳐 생긴 일시적 쌍극자 때문'으로 못 박는다. 이 발생 원리에서 전자 수가 세기를 정하는 까닭으로 이어라.", "cite": ""}, "CH2-005": {"name": "쌍극자-쌍극자", "course": "ch2", "unit": "분자간힘", "tier": "C", "mis": ["영구 쌍극자가 필요하다.", "영구 쌍극자가 없다."], "dx": "쌍극자-쌍극자 힘이 영구 쌍극자를 가진 극성 분자 사이에서만 작용한다는 점을 놓친 경우다. 무극성 분자엔 이 힘이 없다는 점이 약하면 극성·무극성의 끓는점 차이를 못 짚는다.", "fix": "쌍극자-쌍극자 힘을 '영구 쌍극자를 가진 극성 분자 사이에서만 작용'으로 못 박는다(무극성엔 없음). 이로써 극성·무극성의 끓는점 차이를 짚어라.", "cite": ""}, "CH2-006": {"name": "수소 결합 조건", "course": "ch2", "unit": "분자간힘", "tier": "A", "mis": ["세 원소가 조건이다.", "C는 조건이 아니다.", "조건이 필요하다.", "부분 전하가 커야 한다.", "전자쌍과 H가 끌린다."], "dx": "수소 결합의 조건이 전기음성도가 큰 N·O·F에 직접 결합한 H라는 점을 놓친 경우다(C는 조건이 아님). 이 조건이 흐리면 어떤 분자가 수소 결합을 하는지 판정이 통째로 어긋난다.", "fix": "수소 결합 조건을 'H가 N·O·F에 직접 결합했는가' 한 가지로 거른다(C는 조건 아님). HF·H₂O·NH₃(된다)와 HCl·CH₄(안 된다)를 나란히 두고 직접 가려라.", "cite": ""}, "CH2-007": {"name": "수소 결합 본질", "course": "ch2", "unit": "분자간힘", "tier": "C", "mis": ["분자 사이의 힘이다.", "강한 분자 간 힘이다.", "특히 강한 경우이다."], "dx": "수소 결합을 화학 결합으로 오해한 경우다. 분자 간 힘 중 특히 강한 것일 뿐 분자 안의 결합이 아니라는 점을 놓치면 분자 간 힘의 세기 순서에서 자리를 잘못 잡는다.", "fix": "수소 결합을 '분자 간 힘 중 특히 강한 것일 뿐 분자 안의 결합이 아님'으로 못 박는다. 분자 간 힘 세기 순서에서 그 자리를 바로 잡아라.", "cite": ""}, "CH2-008": {"name": "분산력 세기", "course": "ch2", "unit": "분자간힘", "tier": "B", "mis": ["전자 수가 많아진다.", "분산력이 크다.", "순간 쌍극자가 잘 생긴다.", "전자 구름이 잘 치우친다."], "dx": "분산력이 전자 수가 많을수록(전자 구름이 클수록 잘 치우쳐) 커진다는 점을 놓친 경우다. 이 세기 결정 인자가 약하면 분자량이 큰 분자의 끓는점이 왜 높은지 설명하지 못한다.", "fix": "분산력을 '전자 수가 많을수록(전자 구름이 커 잘 치우쳐) 커짐'으로 못 박는다. 이 인자로 분자량이 큰 분자의 끓는점이 높은 까닭을 설명하라.", "cite": ""}, "CH2-009": {"name": "할로젠 끓는점", "course": "ch2", "unit": "분자간힘", "tier": "B", "mis": ["분자량이 클수록 높다.", "분자량이 가장 작다.", "분산력이 커진다.", "같은 원자 2개이다."], "dx": "할로젠(F₂·Cl₂·Br₂·I₂)이 분자량이 클수록 전자 수가 많아 분산력이 커져 끓는점이 높아진다는 점을 놓친 경우다. 분자량과 분산력의 연결이 약하면 동족 끓는점 순서를 못 잡는다.", "fix": "'할로젠은 분자량이 클수록 전자 수가 많아 분산력이 커져 끓는점이 높아짐'을 못 박는다. F₂·Cl₂·Br₂·I₂를 분자량 순으로 늘어놓고 끓는점 순서를 잡아라.", "cite": ""}, "CH2-010": {"name": "비활성 기체 끓는점", "course": "ch2", "unit": "분자간힘", "tier": "C", "mis": ["분자량이 가장 크다.", "분산력이 커진다.", "전자 수가 가장 적다."], "dx": "비활성 기체가 원자번호가 클수록 전자 수가 많아 분산력이 커져 끓는점이 높아진다는 점을 놓친 경우다. 분산력만 작용하는 이 예가 약하면 분산력-끓는점 관계의 기본을 못 짚는다.", "fix": "'비활성 기체는 원자번호가 클수록 전자 수가 많아 분산력이 커져 끓는점이 높아짐'을 못 박는다. 분산력만 작용하는 이 예로 분산력-끓는점 관계를 익혀라.", "cite": ""}, "CH2-011": {"name": "접촉 면적", "course": "ch2", "unit": "분자간힘", "tier": "C", "mis": ["접촉이 많아진다.", "표면 접촉이 넓다.", "분산력이 더 크다."], "dx": "분자가 길게 뻗어 접촉 면적이 넓을수록 분산력이 커진다는 점을 놓친 경우다. 같은 분자식이라도 모양에 따라 접촉 면적이 달라 끓는점이 갈린다는 점이 약하면 이성질체 비교가 어긋난다.", "fix": "'분자가 길게 뻗어 접촉 면적이 넓을수록 분산력이 커짐'을 못 박는다. 같은 분자식이라도 모양 따라 면적이 달라 끓는점이 갈림을 이성질체로 비교하라.", "cite": ""}, "CH2-012": {"name": "무극성 분자 힘", "course": "ch2", "unit": "분자간힘", "tier": "B", "mis": ["영구 쌍극자가 없다.", "분산력은 모든 분자에 작용한다.", "대칭이라 무극성이다.", "조건을 갖추지 못한다."], "dx": "무극성 분자는 영구 쌍극자가 없어 분자 간 힘이 아예 없다고 본 경우다. 분산력은 무극성 분자에도 작용한다는 점을 놓치면 무극성 물질이 어떻게 액화·고화되는지 설명하지 못한다.", "fix": "'무극성 분자도 분산력이 작용해 분자 간 힘이 있음(아예 없는 게 아님)'을 못 박는다. 그래서 무극성 물질이 액화·고화됨을 짚어라.", "cite": ""}, "CH2-013": {"name": "수소 결합 예", "course": "ch2", "unit": "분자간힘", "tier": "A", "mis": ["H가 C에 결합했다.", "Cl은 조건이 아니다.", "H가 없다.", "C는 조건이 아니다.", "Br은 조건이 아니다."], "dx": "수소 결합을 하는 분자를 가릴 때 H가 N·O·F에 붙었는지를 못 따진 경우다(HF·H₂O·NH₃는 되고, HCl·CH₄는 안 됨). 이 판정이 약하면 어느 물질이 비정상적으로 끓는점이 높은지 못 짚는다.", "fix": "수소 결합 분자를 'H가 N·O·F에 붙었는가'로 가린다. HF·H₂O·NH₃는 되고 HCl·CH₄는 안 됨을 적어, 어느 물질이 비정상적으로 끓는점이 높은지 짚어라.", "cite": ""}, "CH2-014": {"name": "수소 결합 세기", "course": "ch2", "unit": "분자간힘", "tier": "B", "mis": ["부분 전하가 크다.", "분자 간 힘이다.", "강한 분자 간 힘이다."], "dx": "수소 결합이 큰 부분 전하 때문에 보통의 쌍극자-쌍극자 힘보다 강하다는 점을 놓친 경우다. 이 세기 차가 약하면 수소 결합 물질의 유독 높은 끓는점을 설명하지 못한다.", "fix": "'수소 결합은 큰 부분 전하 때문에 보통의 쌍극자-쌍극자 힘보다 강함'을 못 박는다. 이 세기 차로 수소 결합 물질의 유독 높은 끓는점을 설명하라.", "cite": ""}, "CH2-015": {"name": "끓는점 이상", "course": "ch2", "unit": "분자간힘", "tier": "C", "mis": ["물이 분자량은 더 작다.", "수소 결합 때문이다.", "강한 인력이다."], "dx": "물이 분자량이 작은데도 같은 족에서 끓는점이 비정상적으로 높은 까닭이 수소 결합이라는 점을 놓친 경우다. 이 예외를 못 잡으면 16족 수소화물 끓는점 그래프의 튀는 점을 설명하지 못한다.", "fix": "'물이 분자량이 작은데도 같은 족에서 끓는점이 비정상적으로 높은 까닭은 수소 결합'임을 못 박는다. 16족 수소화물 끓는점 그래프의 튀는 점을 이로 설명하라.", "cite": ""}, "CH2-016": {"name": "얼음 밀도", "course": "ch2", "unit": "분자간힘", "tier": "C", "mis": ["빈 공간이 많다.", "수소 결합 구조 때문이다.", "밀도가 작아진다."], "dx": "얼음에서 수소 결합이 규칙적인 빈 공간 구조를 만들어 물보다 밀도가 작아진다는(그래서 뜬다) 점을 놓친 경우다. 이 구조를 못 잡으면 고체가 액체보다 가벼운 물의 예외를 설명하지 못한다.", "fix": "'얼음에서 수소 결합이 규칙적인 빈 공간 구조를 만들어 물보다 밀도가 작아짐(그래서 뜸)'을 못 박는다. 고체가 액체보다 가벼운 물의 예외를 이로 설명하라.", "cite": ""}, "CH2-017": {"name": "물의 특성", "course": "ch2", "unit": "분자간힘", "tier": "C", "mis": ["강한 인력이다.", "분자량은 작다.", "수소 결합 때문이다."], "dx": "물의 높은 끓는점·표면 장력·비열 같은 특성이 수소 결합에서 비롯된다는 점을 놓친 경우다. 분자량은 작은데 인력이 강하다는 연결이 약하면 물의 여러 특이성을 한 원인으로 꿰지 못한다.", "fix": "'물의 높은 끓는점·표면 장력·비열이 모두 수소 결합에서 비롯됨'을 못 박는다. 분자량은 작은데 인력이 강하다는 한 원인으로 물의 특이성을 꿰어라.", "cite": ""}, "CH2-018": {"name": "동족 경향", "course": "ch2", "unit": "분자간힘", "tier": "C", "mis": ["전자 수가 많아진다.", "H가 C에 결합했다.", "분산력이 커진다."], "dx": "수소 결합이 없는 동족 계열에서 전자 수(분자량)가 클수록 분산력이 커져 끓는점이 높아진다는 경향을 놓친 경우다. 이 기본 경향이 약하면 수소 결합 예외와 정상 경향을 구분하지 못한다.", "fix": "'수소 결합이 없는 동족 계열은 전자 수(분자량)가 클수록 분산력이 커져 끓는점이 높아짐'을 못 박는다. 이 정상 경향을 수소 결합 예외와 구분하라.", "cite": ""}, "CH2-019": {"name": "끓는점 관계", "course": "ch2", "unit": "분자간힘", "tier": "A", "mis": ["힘에 비례한다.", "힘을 끊는 데 에너지가 든다.", "쉽게 떨어진다.", "끓을 때 분자 간 힘이 끊긴다.", "강한 분자 간 힘이다.", "힘이 강할수록 높다."], "dx": "끓는점이 분자 간 힘의 세기에 비례한다는 핵심을 놓친 경우다. 끓음이 분자 간 힘을 끊는 과정이라 힘이 강할수록 더 많은 에너지가 들어 끓는점이 높다는 논리가 없으면 모든 끓는점 비교가 막힌다.", "fix": "'끓는점은 분자 간 힘에 비례(끓음이 분자 간 힘을 끊는 과정이라 힘이 강할수록 더 많은 에너지가 듦)'함을 못 박는다. 이 논리로 모든 끓는점 비교를 풀어라.", "cite": ""}, "CH2-020": {"name": "증기압 관계", "course": "ch2", "unit": "분자간힘", "tier": "A", "mis": ["증발이 어렵다.", "증발이 잘 일어난다.", "힘이 강하면 증기압이 작다.", "분자가 잘 떨어지지 않는다.", "분자 간 힘이 강하다."], "dx": "분자 간 힘이 강하면 분자가 잘 떨어져 나가지 못해 증기압이 작다는 반비례를 놓친 경우다. 힘과 증기압의 반대 관계가 약하면 증기압 비교와 총괄성(증기압 내림)이 흔들린다.", "fix": "'분자 간 힘이 강하면 분자가 잘 떨어져 나가지 못해 증기압이 작음(반비례)'을 못 박는다. 이 반대 관계를 증기압 비교와 총괄성(증기압 내림)의 바탕으로 삼아라.", "cite": ""}, "CH2-021": {"name": "증발 관계", "course": "ch2", "unit": "분자간힘", "tier": "C", "mis": ["분자가 잘 떨어지지 않는다.", "증발이 어렵다.", "힘이 증발에 영향을 준다."], "dx": "분자 간 힘이 강할수록 분자가 표면을 떠나기 어려워 증발이 잘 안 일어난다는 점을 놓친 경우다. 힘과 증발의 반비례가 약하면 어느 액체가 빨리 마르는지 못 가린다.", "fix": "'분자 간 힘이 강할수록 분자가 표면을 떠나기 어려워 증발이 잘 안 일어남'을 못 박는다. 이 반비례로 어느 액체가 빨리 마르는지 가려라.", "cite": ""}, "CH2-022": {"name": "녹는점 관계", "course": "ch2", "unit": "분자간힘", "tier": "C", "mis": ["인력이 크다.", "힘에 관련 있다.", "쉽게 풀린다."], "dx": "분자 간 힘이 강할수록 녹는점도 높다는 점을 놓친 경우다. 고체에서 분자를 떼어내는 데 더 큰 에너지가 든다는 연결이 약하면 분자 결정의 녹는점 비교가 어긋난다.", "fix": "'분자 간 힘이 강할수록 녹는점도 높음(고체에서 떼는 데 더 큰 에너지)'을 못 박는다. 이 연결로 분자 결정의 녹는점을 비교하라.", "cite": ""}, "CH2-023": {"name": "끓는점 해석", "course": "ch2", "unit": "분자간힘", "tier": "C", "mis": ["힘에 비례한다.", "쉽게 끓는다.", "끓는점이 척도이다."], "dx": "끓는점을 분자 간 힘 세기의 척도로 읽지 못한 경우다. 끓는점이 높다는 건 힘이 강하다는 뜻이라는 역방향 해석이 약하면 끓는점 자료로 힘을 비교하지 못한다.", "fix": "'끓는점이 높다는 건 분자 간 힘이 강하다는 뜻'으로 역방향 해석을 못 박는다. 끓는점 자료를 힘의 척도로 읽어 분자 간 힘을 비교하라.", "cite": ""}, "CH2-024": {"name": "극성과 끓는점", "course": "ch2", "unit": "분자간힘", "tier": "C", "mis": ["쌍극자-쌍극자 힘이 더해진다."], "dx": "극성 분자가 분산력에 더해 쌍극자-쌍극자 힘까지 작용해 비슷한 크기의 무극성 분자보다 끓는점이 높다는 점을 놓친 경우다. 힘이 '더해진다'는 점이 약하면 극성·무극성 끓는점 차이를 못 짚는다.", "fix": "'극성 분자는 분산력에 쌍극자-쌍극자 힘까지 더해져 비슷한 크기의 무극성보다 끓는점이 높음'을 못 박는다. 힘이 '더해짐'을 잡아 극성·무극성 차이를 짚어라.", "cite": ""}, "CH2-025": {"name": "증기압 해석", "course": "ch2", "unit": "분자간힘", "tier": "C", "mis": ["증발이 잘 일어난다.", "증발이 어렵다.", "분자 간 힘이 약하다."], "dx": "증기압이 크다는 것을 분자 간 힘이 약해 증발이 잘 된다는 뜻으로 읽지 못한 경우다. 증기압을 힘의 척도로 역해석하지 못하면 증기압 자료로 휘발성을 비교하지 못한다.", "fix": "'증기압이 크다는 건 분자 간 힘이 약해 증발이 잘 된다는 뜻'으로 역해석을 못 박는다. 증기압 자료로 휘발성을 비교하라.", "cite": ""}, "CH2-026": {"name": "점성 관계", "course": "ch2", "unit": "분자간힘", "tier": "C", "mis": ["분자가 잘 미끄러지지 않는다.", "인력이 크다.", "분자가 잘 미끄러진다."], "dx": "분자 간 힘이 강할수록 분자가 서로 잘 미끄러지지 못해 점성이 크다는 점을 놓친 경우다. 힘과 점성의 비례가 약하면 액체의 끈적임 차이를 분자 간 힘으로 설명하지 못한다.", "fix": "'분자 간 힘이 강할수록 분자가 서로 잘 미끄러지지 못해 점성이 큼'을 못 박는다. 이 비례로 액체의 끈적임 차이를 분자 간 힘으로 설명하라.", "cite": ""}, "CH2-027": {"name": "종합 비교", "course": "ch2", "unit": "분자간힘", "tier": "C", "mis": ["분산력 차이가 크다.", "극성도 영향을 준다.", "분산력이 매우 클 수 있다."], "dx": "끓는점을 비교할 때 분산력(크기)과 극성을 함께 따지지 못한 경우다. 분산력 차이가 크면 무극성이라도 작은 극성 분자보다 끓는점이 높을 수 있다는 점이 약하면 종합 비교가 어긋난다.", "fix": "끓는점 비교를 '분산력(크기)과 극성을 함께 따져' 한다. 분산력 차이가 크면 무극성이라도 작은 극성 분자보다 끓는점이 높을 수 있음을 잡아 종합 비교하라.", "cite": ""}, "CH2-028": {"name": "휘발성", "course": "ch2", "unit": "분자간힘-d", "tier": "B", "mis": ["증발이 잘 일어난다.", "분자 간 힘이 약하다.", "반비례한다."], "dx": "휘발성이 분자 간 힘에 반비례해 힘이 약할수록 잘 증발한다는 점을 놓친 경우다. 이 반비례가 약하면 어느 물질이 더 휘발성인지 분자 간 힘으로 판단하지 못한다.", "fix": "'휘발성은 분자 간 힘에 반비례해 힘이 약할수록 잘 증발'함을 못 박는다. 이 반비례로 어느 물질이 더 휘발성인지 분자 간 힘으로 판단하라.", "cite": ""}, "CH2-029": {"name": "상태 결정", "course": "ch2", "unit": "분자간힘-d", "tier": "C", "mis": ["응집 정도를 정한다.", "분자가 잘 응집된다.", "분자가 흩어진다."], "dx": "같은 온도에서 분자 간 힘이 분자의 응집 정도를 정해 고체·액체·기체를 가른다는 점을 놓친 경우다. 힘이 강하면 뭉치고 약하면 흩어진다는 연결이 약하면 물질의 상태를 설명하지 못한다.", "fix": "'같은 온도에서 분자 간 힘이 응집 정도를 정해 고체·액체·기체를 가름(강하면 뭉치고 약하면 흩어짐)'을 못 박는다. 힘으로 물질의 상태를 설명하라.", "cite": ""}, "CH2-030": {"name": "힘의 공존", "course": "ch2", "unit": "분자간힘-d", "tier": "B", "mis": ["분산력은 보편적이다.", "분산력도 작용한다.", "모든 분자에 작용한다."], "dx": "극성 분자엔 쌍극자-쌍극자나 수소 결합과 함께 분산력도 늘 깔려 있다는 점(여러 힘의 공존)을 놓친 경우다. 분산력을 빼고 한 힘만 보면 분자 간 힘의 총세기를 잘못 잡는다.", "fix": "'극성 분자엔 쌍극자-쌍극자나 수소 결합과 함께 분산력도 늘 깔려 있음(공존)'을 못 박는다. 분산력을 빼지 말고 분자 간 힘의 총세기를 잡아라.", "cite": ""}, "CH2-031": {"name": "세기 순서", "course": "ch2", "unit": "분자간힘-d", "tier": "C", "mis": ["일시적 쌍극자이다.", "수소 결합이 가장 강하다.", "수소 결합이 더 강하다."], "dx": "분자 간 힘의 세기가 대체로 분산력 < 쌍극자-쌍극자 < 수소 결합 순이라는 점을 놓친 경우다(단 분산력은 크기에 따라 매우 커질 수 있음). 이 순서가 약하면 분자 간 힘 비교가 어긋난다.", "fix": "'분자 간 힘 세기가 대체로 분산력 < 쌍극자-쌍극자 < 수소 결합 순(단 분산력은 크기에 따라 매우 커질 수 있음)'임을 못 박는다. 이 순서로 분자 간 힘을 비교하라.", "cite": ""}, "CH2-032": {"name": "이온-쌍극자", "course": "ch2", "unit": "분자간힘-d", "tier": "C", "mis": ["극성 분자와 작용한다.", "부분 전하가 필요하다.", "물 분자가 이온을 둘러싼다."], "dx": "이온-쌍극자 힘이 이온과 극성 분자 사이에 작용해 물 분자가 이온을 둘러싼다는(수화) 점을 놓친 경우다. 이 힘이 약하면 이온 결정이 물에 녹는 용해 과정을 설명하지 못한다.", "fix": "이온-쌍극자 힘을 '이온과 극성 분자 사이에 작용해 물 분자가 이온을 둘러쌈(수화)'으로 못 박는다. 이 힘으로 이온 결정이 물에 녹는 과정을 설명하라.", "cite": ""}, "CH2-033": {"name": "생체 적용", "course": "ch2", "unit": "분자간힘-d", "tier": "C", "mis": ["수소 결합이다.", "수소 결합이 관여한다."], "dx": "DNA 이중 나선·단백질 구조를 잡아 주는 힘이 수소 결합이라는 점을 놓친 경우다. 분자 간 힘이 생체 분자에서 하는 역할이 약하면 화학과 생명의 연결을 못 짚는다.", "fix": "'DNA 이중 나선·단백질 구조를 잡아 주는 힘이 수소 결합'임을 못 박는다. 분자 간 힘이 생체 분자에서 하는 역할로 화학과 생명을 이어라.", "cite": ""}, "CH2-034": {"name": "분산력 비교", "course": "ch2", "unit": "분자간힘-d", "tier": "C", "mis": ["모두 무극성이다.", "분산력 차이 때문이다.", "인력이 크다."], "dx": "모두 무극성인 분자들끼리는 분산력 차이(전자 수·크기)만으로 끓는점이 갈린다는 점을 놓친 경우다. 분산력 하나로 비교하는 감각이 약하면 무극성 분자들의 순서를 못 잡는다.", "fix": "'모두 무극성인 분자끼리는 분산력 차이(전자 수·크기)만으로 끓는점이 갈림'을 못 박는다. 분산력 하나로 무극성 분자들의 순서를 잡아라.", "cite": ""}, "CH2-035": {"name": "수소 결합 효과", "course": "ch2", "unit": "분자간힘-d", "tier": "C", "mis": ["추가적인 강한 인력이다.", "분자 간 힘이 커진다.", "강한 인력이다."], "dx": "수소 결합이 더해지면 추가로 강한 인력이 생겨 끓는점·녹는점이 크게 올라간다는 점을 놓친 경우다. 이 추가 효과가 약하면 수소 결합 물질이 왜 유독 끓는점이 높은지 설명하지 못한다.", "fix": "'수소 결합이 더해지면 추가로 강한 인력이 생겨 끓는점·녹는점이 크게 올라감'을 못 박는다. 이 추가 효과로 수소 결합 물질의 유독 높은 끓는점을 설명하라.", "cite": ""}, "CH2-231": {"name": "반응 속도 정의", "course": "ch2", "unit": "반응속도", "tier": "C", "mis": ["시간당 변화이다.", "농도 변화이다.", "농도가 변한다."], "dx": "반응 속도가 단위 시간당 농도 변화라는 정의를 놓친 경우다. 시간당 농도가 얼마나 변하는지가 속도라는 점이 약하면 속도를 정량적으로 다루지 못한다.", "fix": "반응 속도를 '단위 시간당 농도 변화'로 못 박는다. 시간당 농도가 얼마나 변하는지가 속도임을 잡아 속도를 정량적으로 다뤄라.", "cite": ""}, "CH2-232": {"name": "반응 속도 표현", "course": "ch2", "unit": "반응속도", "tier": "C", "mis": ["생성물은 늘어난다.", "반응물은 줄어든다.", "생성물로도 표현 가능하다."], "dx": "반응 속도를 반응물 농도 감소나 생성물 농도 증가 어느 쪽으로도 나타낼 수 있다는 점을 놓친 경우다. 부호와 계수를 맞춰 표현하지 못하면 속도 정의가 어긋난다.", "fix": "'반응 속도는 반응물 농도 감소나 생성물 농도 증가 어느 쪽으로도 나타냄(부호·계수 맞춤)'을 못 박는다. 부호와 계수를 맞춰 같은 속도로 표현하라.", "cite": ""}, "CH2-233": {"name": "충돌 이론", "course": "ch2", "unit": "반응속도", "tier": "C", "mis": ["충돌이 필요하다.", "유효 충돌만 반응한다.", "충돌이 잦으면 빨라진다."], "dx": "반응이 입자 충돌로 일어나되 모든 충돌이 아니라 유효 충돌만 반응으로 이어진다는 충돌 이론을 놓친 경우다. 충돌과 반응을 같다고 보면 왜 충돌이 많아도 반응이 느릴 수 있는지 설명하지 못한다.", "fix": "충돌 이론을 '반응이 입자 충돌로 일어나되 모든 충돌이 아니라 유효 충돌만 반응으로 이어짐'으로 못 박는다. 충돌과 반응이 같지 않음을 잡아 충돌이 많아도 느릴 수 있는 까닭을 설명하라.", "cite": ""}, "CH2-234": {"name": "유효 충돌", "course": "ch2", "unit": "반응속도", "tier": "C", "mis": ["유효 충돌만 반응한다.", "방향도 필요하다.", "일부만 넘는다."], "dx": "유효 충돌이 충분한 에너지뿐 아니라 올바른 방향까지 갖춘 충돌이라는 점을 놓친 경우다. 에너지만 보면 방향이 안 맞아 반응 안 되는 충돌을 놓쳐 속도 해석이 어긋난다.", "fix": "유효 충돌을 '충분한 에너지뿐 아니라 올바른 방향까지 갖춘 충돌'로 못 박는다. 에너지만 보지 말고 방향이 안 맞아 반응 안 되는 충돌까지 따져라.", "cite": ""}, "CH2-235": {"name": "활성화 에너지", "course": "ch2", "unit": "반응속도", "tier": "A", "mis": ["장벽이 높다.", "장벽의 높이이다.", "장벽이 낮다.", "장벽이 속도를 좌우한다.", "에너지 분포가 있다."], "dx": "활성화 에너지가 반응이 일어나려면 넘어야 하는 에너지 장벽이고 이 장벽이 높을수록 반응이 느리다는 점을 놓친 경우다. 장벽 개념이 약하면 온도·촉매가 속도를 바꾸는 원리를 못 짚는다.", "fix": "활성화 에너지를 '반응이 일어나려면 넘어야 하는 에너지 장벽, 높을수록 느림'으로 못 박는다. 장벽 개념으로 온도·촉매가 속도를 바꾸는 원리를 짚어라.", "cite": ""}, "CH2-236": {"name": "농도와 속도", "course": "ch2", "unit": "반응속도", "tier": "C", "mis": ["충돌이 잦아진다.", "충돌 빈도가 달라진다.", "입자가 많다."], "dx": "농도가 높을수록 입자가 많아 충돌 빈도가 늘어 반응이 빨라진다는 점을 놓친 경우다. 농도와 충돌 빈도의 연결이 약하면 농도 효과를 설명하지 못한다.", "fix": "'농도가 높을수록 입자가 많아 충돌 빈도가 늘어 빨라짐'을 못 박는다. 농도와 충돌 빈도를 이어 농도 효과를 설명하라.", "cite": ""}, "CH2-237": {"name": "온도와 속도", "course": "ch2", "unit": "반응속도", "tier": "C", "mis": ["입자 운동이 활발하다."], "dx": "온도가 높을수록 입자 운동이 활발해지고 활성화 에너지를 넘는 입자가 크게 늘어 반응이 빨라진다는 점을 놓친 경우다. 온도가 단지 충돌 빈도만이 아니라 유효 충돌 비율을 키운다는 점이 약하면 온도 효과를 과소평가한다.", "fix": "'온도가 높을수록 입자 운동이 활발하고 활성화 에너지를 넘는 입자가 크게 늘어 빨라짐'을 못 박는다. 온도가 충돌 빈도만이 아니라 유효 충돌 비율을 키움을 잡아 온도 효과를 과소평가 마라.", "cite": ""}, "CH2-238": {"name": "표면적과 속도", "course": "ch2", "unit": "반응속도", "tier": "C", "mis": ["충돌할 면이 많다.", "표면적이 커진다.", "충돌할 면이 달라진다."], "dx": "고체 반응물의 표면적이 넓을수록 충돌할 면이 많아 반응이 빨라진다는 점을 놓친 경우다. 덩어리를 잘게 쪼개면 빨라진다는 점이 약하면 표면적 효과를 설명하지 못한다.", "fix": "'고체 반응물의 표면적이 넓을수록 충돌할 면이 많아 빨라짐'을 못 박는다. 덩어리를 잘게 쪼개면 빨라짐을 잡아 표면적 효과를 설명하라.", "cite": ""}, "CH2-239": {"name": "촉매", "course": "ch2", "unit": "반응속도", "tier": "C", "mis": ["장벽을 낮춘다.", "소모되지 않는다."], "dx": "촉매가 활성화 에너지를 낮춰 반응을 빠르게 하면서 자신은 소모되지 않는다는 점을 놓친 경우다. 촉매의 두 특징이 약하면 촉매가 어떻게 속도만 바꾸는지 못 짚는다.", "fix": "촉매를 '활성화 에너지를 낮춰 반응을 빠르게 하면서 자신은 소모되지 않음'으로 못 박는다. 이 두 특징으로 촉매가 어떻게 속도만 바꾸는지 짚어라.", "cite": ""}, "CH2-240": {"name": "촉매와 엔탈피", "course": "ch2", "unit": "반응속도", "tier": "A", "mis": ["활성화 에너지만 낮춘다.", "ΔH 불변이다.", "시작과 끝 에너지가 같다.", "정·역반응을 똑같이 빠르게 한다."], "dx": "촉매가 활성화 에너지만 낮출 뿐 반응물·생성물의 에너지(ΔH)는 바꾸지 않고 정·역반응을 똑같이 빠르게 한다는 점을 놓친 경우다. 촉매가 ΔH나 평형 위치를 바꾼다고 오해하면 속도와 평형을 뒤섞는다.", "fix": "'촉매는 활성화 에너지만 낮출 뿐 반응물·생성물의 에너지(ΔH)는 안 바꾸고 정·역반응을 똑같이 빠르게 함'을 못 박는다. 촉매가 ΔH나 평형 위치를 바꾼다고 오해 마라.", "cite": ""}, "CH2-241": {"name": "촉매 종류", "course": "ch2", "unit": "반응속도", "tier": "C", "mis": ["활성화 에너지를 낮춘다.", "활성화 에너지를 높인다.", "부촉매도 있다."], "dx": "촉매에 활성화 에너지를 낮추는 정촉매뿐 아니라 높이는 부촉매도 있다는 점을 놓친 경우다. 촉매가 늘 속도를 높인다고만 보면 부촉매의 작용을 설명하지 못한다.", "fix": "'촉매에 활성화 에너지를 낮추는 정촉매뿐 아니라 높이는 부촉매도 있음'을 못 박는다. 촉매가 늘 속도를 높인다고만 보지 말고 부촉매 작용을 설명하라.", "cite": ""}, "CH2-242": {"name": "속도식", "course": "ch2", "unit": "반응속도", "tier": "C", "mis": ["실험으로 정한다.", "농도가 들어간다.", "k는 속도 상수이다."], "dx": "속도식이 반응식 계수가 아니라 실험으로 정해지고 농도와 속도 상수 k로 이뤄진다는 점을 놓친 경우다. 계수에서 속도식을 바로 읽으려 하면 반응 차수가 어긋난다.", "fix": "속도식을 '반응식 계수가 아니라 실험으로 정해지고 농도와 속도 상수 k로 이뤄짐'으로 못 박는다. 계수에서 속도식을 바로 읽지 말고 실험 차수를 써라.", "cite": ""}, "CH2-243": {"name": "반응 차수", "course": "ch2", "unit": "반응속도", "tier": "C", "mis": ["실험으로 정한다.", "농도의 지수이다."], "dx": "반응 차수가 속도식에서 각 농도에 붙는 지수이고 실험으로 정해진다는 점을 놓친 경우다. 차수를 계수로 짐작하면 속도식 적용이 어긋난다.", "fix": "반응 차수를 '속도식에서 각 농도에 붙는 지수이고 실험으로 정해짐'으로 못 박는다. 차수를 계수로 짐작 말고 실험으로 정해 속도식에 써라.", "cite": ""}, "CH2-244": {"name": "속도 상수", "course": "ch2", "unit": "반응속도", "tier": "A", "mis": ["농도에 의존하지 않는다.", "온도에 의존한다.", "활성화 에너지가 바뀐다.", "반응에 따라 다르다."], "dx": "속도 상수 k가 농도에는 의존하지 않고 온도와 활성화 에너지에 따라 정해진다는 점을 놓친 경우다. k가 농도로 변한다고 오해하면 속도식의 의미를 잘못 잡는다.", "fix": "속도 상수 k를 '농도에는 의존하지 않고 온도와 활성화 에너지에 따라 정해짐'으로 못 박는다. k가 농도로 변한다고 오해 말고 속도식의 의미를 잡아라.", "cite": ""}, "CH2-245": {"name": "아레니우스 식", "course": "ch2", "unit": "반응속도", "tier": "C", "mis": ["온도가 높으면 k가 커진다.", "장벽이 높다.", "농도와 무관하다."], "dx": "아레니우스 식이 온도가 높거나 활성화 에너지가 낮을수록 속도 상수 k가 커진다는 관계를 나타낸다는 점을 놓친 경우다. 이 관계가 약하면 온도가 k를 통해 속도를 바꾸는 정도를 못 가늠한다.", "fix": "아레니우스 식을 '온도가 높거나 활성화 에너지가 낮을수록 속도 상수 k가 커짐'으로 못 박는다. 이 관계로 온도가 k를 통해 속도를 바꾸는 정도를 가늠하라.", "cite": ""}, "CH2-246": {"name": "촉매와 역반응", "course": "ch2", "unit": "반응속도", "tier": "A", "mis": ["양방향 장벽을 낮춘다.", "위치가 불변이다."], "dx": "촉매가 정반응과 역반응의 활성화 에너지를 똑같이 낮춰 평형 위치는 그대로 두고 평형 도달만 앞당긴다는 점을 놓친 경우다. 한쪽만 빨라진다고 보면 촉매가 평형을 옮긴다는 오개념에 빠진다.", "fix": "'촉매는 정·역반응의 활성화 에너지를 똑같이 낮춰 평형 위치는 그대로 두고 평형 도달만 앞당김'을 못 박는다. 한쪽만 빨라진다고 보지 말고 촉매가 평형을 옮긴다는 오개념을 피하라.", "cite": ""}, "CH2-247": {"name": "온도와 유효 충돌", "course": "ch2", "unit": "반응속도", "tier": "C", "mis": ["빠른 입자가 많아진다.", "에너지가 커진다."], "dx": "온도가 높아지면 빠른 입자가 많아져 활성화 에너지를 넘는 유효 충돌이 크게 는다는 점을 놓친 경우다. 속력 분포의 이동이 약하면 온도가 왜 속도를 급격히 올리는지 못 짚는다.", "fix": "'온도가 높아지면 빠른 입자가 많아져 활성화 에너지를 넘는 유효 충돌이 크게 늚'을 못 박는다. 속력 분포의 이동으로 온도가 왜 속도를 급격히 올리는지 짚어라.", "cite": ""}, "CH2-248": {"name": "촉매 작용", "course": "ch2", "unit": "반응속도", "tier": "C", "mis": ["낮은 경로를 연다.", "경로를 바꾼다."], "dx": "촉매가 활성화 에너지가 더 낮은 다른 반응 경로를 열어 준다는 점을 놓친 경우다. 새 경로를 연다는 그림이 약하면 촉매가 어떻게 장벽을 낮추는지 설명하지 못한다.", "fix": "촉매를 '활성화 에너지가 더 낮은 다른 반응 경로를 열어 줌'으로 못 박는다. 새 경로를 연다는 그림으로 촉매가 어떻게 장벽을 낮추는지 설명하라.", "cite": ""}, "CH2-249": {"name": "시간과 속도", "course": "ch2", "unit": "반응속도", "tier": "C", "mis": ["농도가 줄어든다."], "dx": "시간이 지나며 반응물 농도가 줄어 반응 속도가 점점 느려진다는 점을 놓친 경우다. 농도 감소와 속도 저하의 연결이 약하면 속도-시간 그래프를 잘못 읽는다.", "fix": "'시간이 지나며 반응물 농도가 줄어 반응 속도가 점점 느려짐'을 못 박는다. 농도 감소와 속도 저하를 이어 속도-시간 그래프를 읽어라.", "cite": ""}, "CH2-250": {"name": "전체 차수", "course": "ch2", "unit": "반응속도", "tier": "C", "mis": ["합이다.", "실험으로 정한다."], "dx": "전체 반응 차수가 각 반응물 차수의 합이고 실험으로 정한 값이라는 점을 놓친 경우다. 차수의 합이라는 점이 약하면 전체 차수를 잘못 구한다.", "fix": "전체 반응 차수를 '각 반응물 차수의 합이고 실험으로 정한 값'으로 못 박는다. 차수의 합임을 잡아 전체 차수를 바로 구하라.", "cite": ""}, "CH2-070": {"name": "증기압 정의", "course": "ch2", "unit": "액체", "tier": "B", "mis": ["평형 상태의 압력이다.", "물질 고유의 성질이다.", "액체에서 나타난다.", "동적 평형 상태이다."], "dx": "증기압이 밀폐 용기에서 증발과 응축이 동적 평형을 이룰 때 증기가 나타내는 압력이고 물질 고유 성질이라는 점을 놓친 경우다. 평형 상태의 압력이라는 정의가 약하면 끓는점·휘발성 해석의 출발이 흔들린다.", "fix": "증기압을 '밀폐 용기에서 증발·응축이 동적 평형을 이룰 때 증기가 내는 압력, 물질 고유 성질'로 못 박는다. 평형 상태의 압력임을 잡아 끓는점·휘발성 해석의 출발로 삼아라.", "cite": ""}, "CH2-071": {"name": "증기압과 온도", "course": "ch2", "unit": "액체", "tier": "B", "mis": ["증발이 잘 일어난다.", "온도에 의존한다."], "dx": "온도가 높을수록 증발이 활발해져 증기압이 커진다는 점을 놓친 경우다. 온도 의존이 약하면 같은 액체라도 온도에 따라 증기압이 달라진다는 점을 못 짚는다.", "fix": "'온도가 높을수록 증발이 활발해져 증기압이 커짐'을 못 박는다. 같은 액체라도 온도에 따라 증기압이 달라짐을 증기압 곡선에 반영하라.", "cite": ""}, "CH2-072": {"name": "증기압과 분자 간 힘", "course": "ch2", "unit": "액체", "tier": "C", "mis": ["증발이 잘 일어난다.", "힘이 증발에 영향을 준다."], "dx": "분자 간 힘이 약할수록 분자가 잘 빠져나가 증기압이 크다는 점을 놓친 경우다. 힘과 증기압의 반비례가 약하면 두 액체의 증기압 비교가 어긋난다.", "fix": "'분자 간 힘이 약할수록 분자가 잘 빠져나가 증기압이 큼(반비례)'을 못 박는다. 힘 차이로 두 액체의 증기압을 비교하라.", "cite": ""}, "CH2-073": {"name": "휘발성과 증기압", "course": "ch2", "unit": "액체", "tier": "B", "mis": ["증발이 잘 일어난다.", "같은 방향으로 변한다.", "비례한다."], "dx": "휘발성과 증기압이 같은 방향으로 변해 증기압이 큰 액체가 더 잘 휘발한다는 점을 놓친 경우다. 둘의 연결이 약하면 증기압으로 휘발성을 가늠하지 못한다.", "fix": "'휘발성과 증기압은 같은 방향이라 증기압이 큰 액체가 더 잘 휘발'함을 못 박는다. 증기압으로 휘발성을 가늠하라.", "cite": ""}, "CH2-074": {"name": "증기압 세기 성질", "course": "ch2", "unit": "액체", "tier": "A", "mis": ["세기 성질이다.", "증발 속도만 빨라진다.", "평형값은 같다."], "dx": "증기압을 액체 양에 비례하는 양이라고 본 경우다. 액체가 많으면 증발 속도만 빠를 뿐 평형 증기압 값은 같은 세기 성질이라는 점을 놓치면 양에 따라 증기압이 변한다고 잘못 본다.", "fix": "증기압을 '액체 양과 무관한 세기 성질(많으면 증발 속도만 빠를 뿐 평형 증기압 값은 같음)'로 못 박는다. 양에 따라 증기압이 변한다고 보지 마라.", "cite": ""}, "CH2-075": {"name": "동적 평형", "course": "ch2", "unit": "액체", "tier": "C", "mis": ["속도가 같을 뿐이다.", "두 과정이 모두 일어난다.", "멈추지 않는다."], "dx": "증기압 평형이 증발과 응축이 멈춘 게 아니라 두 과정이 같은 속도로 계속되는 동적 상태라는 점을 놓친 경우다. 멈춤으로 오해하면 증기압이 왜 일정하게 유지되는지 설명하지 못한다.", "fix": "증기압 평형을 '증발·응축이 멈춘 게 아니라 같은 속도로 계속되는 동적 상태'로 못 박는다. 멈춤으로 오해 말고 증기압이 일정하게 유지되는 까닭을 잡아라.", "cite": ""}, "CH2-076": {"name": "끓음 조건", "course": "ch2", "unit": "액체", "tier": "C", "mis": ["끓음 조건이다.", "외부 압력에 의존한다."], "dx": "끓음이 액체의 증기압이 외부 압력과 같아질 때 일어난다는 조건을 놓친 경우다. 이 조건이 약하면 외부 압력이 끓는점을 바꾸는 까닭을 못 짚는다.", "fix": "끓음 조건을 '액체의 증기압이 외부 압력과 같아질 때'로 못 박는다. 이 조건으로 외부 압력이 끓는점을 바꾸는 까닭을 짚어라.", "cite": ""}, "CH2-077": {"name": "끓음 정의", "course": "ch2", "unit": "액체", "tier": "C", "mis": ["내부에서도 기화한다.", "기화 위치가 다르다.", "증기 기포이다."], "dx": "끓음이 표면만이 아니라 액체 내부에서도 증기 기포가 생기며 기화하는 현상이라는 점을 놓친 경우다. 표면 증발과의 위치 차이가 약하면 끓음과 증발을 혼동한다.", "fix": "끓음을 '표면만이 아니라 액체 내부에서도 증기 기포가 생기며 기화'로 못 박는다. 표면 증발과의 위치 차이로 끓음과 증발을 구분하라.", "cite": ""}, "CH2-078": {"name": "끓는점 정의", "course": "ch2", "unit": "액체", "tier": "A", "mis": ["외부 압력에 의존한다.", "같아질 때이다.", "물질 고유 성질이다.", "증발이 어렵다.", "세기 성질이다."], "dx": "끓는점을 압력과 무관한 물질 고유의 고정값으로 본 경우다. 끓는점이 증기압과 외부 압력이 같아지는 온도라 외부 압력에 따라 달라진다는 점을 놓치면 고산·압력솥 현상을 설명하지 못한다.", "fix": "끓는점을 '증기압과 외부 압력이 같아지는 온도라 외부 압력에 따라 달라짐(고정값 아님)'으로 못 박는다. 이로써 고산·압력솥 현상을 설명하라.", "cite": ""}, "CH2-079": {"name": "정상 끓는점", "course": "ch2", "unit": "액체", "tier": "C", "mis": ["1기압 기준이다.", "1기압에서의 값이다."], "dx": "정상 끓는점이 외부 압력 1기압에서의 끓는점이라는 점을 놓친 경우다. 기준 압력이 1기압이라는 점이 약하면 압력이 다를 때의 끓는점과 혼동한다.", "fix": "정상 끓는점을 '외부 압력 1기압에서의 끓는점'으로 못 박는다. 기준 압력이 1기압임을 잡아 압력이 다를 때의 끓는점과 구분하라.", "cite": ""}, "CH2-080": {"name": "압력과 끓는점", "course": "ch2", "unit": "액체", "tier": "A", "mis": ["더 높은 온도에서 도달한다.", "증기압이 빨리 도달한다.", "내부 압력이 높아진다.", "기압이 낮다.", "비례한다."], "dx": "외부 압력이 높을수록 더 높은 온도에서 끓는다는 점을 놓친 경우다(높은 증기압에 도달해야 하므로). 압력과 끓는점의 비례가 약하면 압력솥은 빨리, 높은 산은 낮은 온도에서 끓는 까닭을 못 짚는다.", "fix": "'외부 압력이 높을수록 더 높은 온도에서 끓음(높은 증기압에 도달해야 하므로)'을 못 박는다. 압력솥은 빨리, 높은 산은 낮은 온도에서 끓는 까닭을 짚어라.", "cite": ""}, "CH2-081": {"name": "분자 간 힘과 끓는점", "course": "ch2", "unit": "액체", "tier": "C", "mis": ["증발이 어렵다.", "증발이 쉽다.", "증발 난이도에 영향을 준다."], "dx": "분자 간 힘이 강할수록 증발이 어려워 끓는점이 높다는 점을 놓친 경우다. 힘과 끓는점의 비례가 약하면 분자 간 힘 자료로 끓는점을 비교하지 못한다.", "fix": "'분자 간 힘이 강할수록 증발이 어려워 끓는점이 높음'을 못 박는다. 분자 간 힘 자료로 끓는점을 비교하라.", "cite": ""}, "CH2-082": {"name": "증기압과 끓는점", "course": "ch2", "unit": "액체", "tier": "C", "mis": ["증기압이 빨리 도달한다.", "증기압 크면 끓는점 낮다.", "증발이 어렵다."], "dx": "증기압이 큰 액체일수록 낮은 온도에서 외부 압력에 도달해 끓는점이 낮다는 반비례를 놓친 경우다. 증기압과 끓는점의 반대 관계가 약하면 두 자료를 잇지 못한다.", "fix": "'증기압이 큰 액체일수록 낮은 온도에서 외부 압력에 도달해 끓는점이 낮음(반비례)'을 못 박는다. 증기압과 끓는점 두 자료를 이 반대 관계로 이으라.", "cite": ""}, "CH2-083": {"name": "증기압-온도 곡선", "course": "ch2", "unit": "액체", "tier": "C", "mis": ["지수적으로 증가한다.", "증발이 잘 일어난다.", "비선형적으로 증가한다."], "dx": "증기압이 온도에 따라 직선이 아니라 지수적으로(가파르게) 증가한다는 점을 놓친 경우다. 곡선의 비선형성이 약하면 증기압-온도 그래프를 잘못 읽는다.", "fix": "'증기압은 온도에 따라 직선이 아니라 지수적으로(가파르게) 증가'함을 못 박는다. 곡선의 비선형성을 잡아 증기압-온도 그래프를 읽어라.", "cite": ""}, "CH2-084": {"name": "물의 끓는점", "course": "ch2", "unit": "액체", "tier": "C", "mis": ["1기압에서의 값이다.", "압력에 의존한다."], "dx": "물의 끓는점 100°C가 1기압에서의 값일 뿐 압력에 따라 달라진다는 점을 놓친 경우다. 100°C를 고정값으로 외우면 압력이 다른 상황에서 끓는점을 잘못 잡는다.", "fix": "'물의 끓는점 100°C는 1기압에서의 값일 뿐 압력에 따라 달라짐'을 못 박는다. 100°C를 고정값으로 외우지 말고 압력이 다른 상황을 따져라.", "cite": ""}, "CH2-085": {"name": "끓는점 조건", "course": "ch2", "unit": "액체", "tier": "C", "mis": ["끓음 조건이다."], "dx": "끓는점이 증기압과 외부 압력이 같아지는 조건에서 정해진다는 점을 놓친 경우다. 이 조건이 약하면 주어진 압력에서 언제 끓는지 판단하지 못한다.", "fix": "끓는점을 '증기압과 외부 압력이 같아지는 조건에서 정해짐'으로 못 박는다. 이 조건으로 주어진 압력에서 언제 끓는지 판단하라.", "cite": ""}, "CH2-086": {"name": "증발 속도", "course": "ch2", "unit": "액체", "tier": "C", "mis": ["운동 에너지가 커진다.", "증발할 면이 넓다."], "dx": "증발 속도가 온도가 높아 운동 에너지가 클수록, 그리고 증발할 표면이 넓을수록 빨라진다는 점을 놓친 경우다. 이 두 인자가 약하면 같은 액체라도 증발 빠르기 차이를 설명하지 못한다.", "fix": "'증발 속도는 온도가 높아 운동 에너지가 클수록, 표면이 넓을수록 빨라짐'을 못 박는다. 이 두 인자로 같은 액체의 증발 빠르기 차이를 설명하라.", "cite": ""}, "CH2-087": {"name": "증기압 비교", "course": "ch2", "unit": "액체", "tier": "C", "mis": ["에탄올의 분자 간 힘이 약하다.", "분자 간 힘이 다르다.", "증발이 잘 일어난다."], "dx": "두 액체의 증기압을 분자 간 힘으로 비교하지 못한 경우다(에탄올은 물보다 힘이 약해 증기압이 큼). 힘 차이로 증기압을 가늠하지 못하면 물질별 증기압 순서가 어긋난다.", "fix": "두 액체의 증기압을 '분자 간 힘으로 비교'한다(에탄올은 물보다 힘이 약해 증기압이 큼). 힘 차이로 물질별 증기압 순서를 잡아라.", "cite": ""}, "CH2-088": {"name": "증발 정의", "course": "ch2", "unit": "액체", "tier": "C", "mis": ["표면에서 일어난다.", "표면에서 항상 일어난다.", "기화 현상이다."], "dx": "증발이 끓는점 아래에서도 액체 표면에서 늘 일어나는 기화라는 점을 놓친 경우다. 표면에서 일어난다는 점이 약하면 내부에서까지 기화하는 끓음과 구분하지 못한다.", "fix": "증발을 '끓는점 아래에서도 액체 표면에서 늘 일어나는 기화'로 못 박는다. 표면에서 일어남을 잡아 내부까지 기화하는 끓음과 구분하라.", "cite": ""}, "CH2-089": {"name": "끓는점과 분자 간 힘", "course": "ch2", "unit": "액체", "tier": "C", "mis": ["증발이 어렵다.", "증발이 쉽다.", "끓는점이 척도이다."], "dx": "끓는점을 분자 간 힘의 척도로 읽지 못한 경우다. 끓는점이 높다는 건 힘이 강하다는 뜻이라는 역해석이 약하면 끓는점 자료로 분자 간 힘을 비교하지 못한다.", "fix": "'끓는점이 높다는 건 분자 간 힘이 강하다는 뜻'으로 역해석을 못 박는다. 끓는점 자료를 힘의 척도로 읽어 분자 간 힘을 비교하라.", "cite": ""}, "CH2-090": {"name": "증발과 에너지", "course": "ch2", "unit": "액체", "tier": "A", "mis": ["분자 간 힘을 끊는다.", "흡열 과정이다.", "열을 흡수한다."], "dx": "증발이 분자 간 힘을 끊어 내는 흡열 과정이라 주위에서 열을 흡수한다는 점을 놓친 경우다. 흡열이라는 점이 약하면 땀·알코올이 증발할 때 시원해지는 냉각 효과를 설명하지 못한다.", "fix": "증발을 '분자 간 힘을 끊는 흡열 과정이라 주위에서 열을 흡수'로 못 박는다. 흡열임을 잡아 땀·알코올이 증발할 때 시원해지는 냉각 효과를 설명하라.", "cite": ""}, "CH2-152": {"name": "삼투 정의", "course": "ch2", "unit": "삼투압", "tier": "C", "mis": ["용매가 이동한다.", "반투막이 필요하다.", "용질은 막을 통과하지 못한다."], "dx": "삼투가 반투막을 사이에 두고 용매가 이동하는 현상(용질은 막을 통과 못 함)이라는 점을 놓친 경우다. 무엇이 움직이는지가 흐리면 삼투압의 의미로 이어지지 못한다.", "fix": "삼투를 '반투막을 사이에 두고 용매가 이동하는 현상(용질은 막 통과 못 함)'으로 못 박는다. 무엇이 움직이는지(용매)를 잡아 삼투압의 의미로 이어라.", "cite": ""}, "CH2-153": {"name": "반투막", "course": "ch2", "unit": "삼투압", "tier": "C", "mis": ["용매만 통과시킨다.", "용질을 막는다."], "dx": "반투막이 용매는 통과시키고 용질은 막는 막이라는 점을 놓친 경우다. 막의 선택성이 약하면 왜 용매만 이동해 농도 차가 생기는지 설명하지 못한다.", "fix": "반투막을 '용매는 통과시키고 용질은 막는 막'으로 못 박는다. 막의 선택성으로 왜 용매만 이동해 농도 차가 생기는지 설명하라.", "cite": ""}, "CH2-154": {"name": "삼투 방향", "course": "ch2", "unit": "삼투압", "tier": "B", "mis": ["농도 차를 줄인다.", "평형을 향한다.", "진한 쪽으로 이동한다."], "dx": "삼투에서 용매가 묽은 쪽에서 진한 쪽으로 이동해 농도 차를 줄인다는 방향을 놓친 경우다(진한 쪽이 묽어짐). 방향을 뒤집으면 세포의 수축·팽창 판단이 통째로 어긋난다.", "fix": "삼투 방향을 '용매가 묽은 쪽에서 진한 쪽으로 이동해 농도 차를 줄임(진한 쪽이 묽어짐)'으로 못 박는다. 방향을 뒤집지 말고 세포의 수축·팽창을 판단하라.", "cite": ""}, "CH2-155": {"name": "삼투압 정의", "course": "ch2", "unit": "삼투압", "tier": "C", "mis": ["삼투를 멈추게 한다.", "용매 이동을 멈춘다."], "dx": "삼투압이 용매의 삼투 이동을 멈추기 위해 진한 쪽에 걸어야 하는 압력이라는 점을 놓친 경우다. '멈추는 압력'이라는 정의가 약하면 삼투압을 단순 농도로 오해한다.", "fix": "삼투압을 '용매의 삼투 이동을 멈추기 위해 진한 쪽에 걸어야 하는 압력'으로 못 박는다. '멈추는 압력'임을 잡아 단순 농도로 오해 마라.", "cite": ""}, "CH2-156": {"name": "반트호프 식", "course": "ch2", "unit": "삼투압", "tier": "A", "mis": ["부피 기준 농도이다.", "켈빈 온도를 쓴다.", "π = MRT이다.", "보편 상수이다."], "dx": "반트호프 식 π=MRT에서 M이 몰농도, T가 절대 온도라는 점을 놓친 경우다. 부피 기준 농도와 켈빈 온도를 안 쓰면 삼투압 계산이 어긋난다.", "fix": "반트호프 식을 'π=MRT, M은 몰농도, T는 절대 온도'로 못 박는다. 부피 기준 농도와 켈빈 온도를 써서 삼투압을 계산하라.", "cite": ""}, "CH2-157": {"name": "총괄성", "course": "ch2", "unit": "삼투압", "tier": "C", "mis": ["총괄성이다.", "종류와 무관하다."], "dx": "삼투압이 용질 입자 수에만 의존하는 총괄성이고 용질 종류와 무관하다는 점을 놓친 경우다. 총괄성이라는 점이 약하면 전해질에서 i를 반영해야 하는 이유로 이어지지 못한다.", "fix": "삼투압을 '용질 입자 수에만 의존하는 총괄성, 용질 종류 무관'으로 못 박는다. 총괄성임을 잡아 전해질에서 i를 반영하는 이유로 이어라.", "cite": ""}, "CH2-158": {"name": "전해질 삼투압", "course": "ch2", "unit": "삼투압", "tier": "C", "mis": ["i를 곱해야 한다.", "이온화로 입자 수가 는다.", "입자 수가 많다."], "dx": "전해질의 삼투압을 계산할 때 이온화로 늘어난 입자 수를 반영해 i를 곱해야 한다는 점을 놓친 경우다. i를 빼먹으면 전해질 용액의 삼투압이 과소평가된다.", "fix": "'전해질의 삼투압은 이온화로 늘어난 입자 수를 반영해 i를 곱해야' 함을 못 박는다. i를 빼먹어 전해질 용액의 삼투압을 과소평가 마라.", "cite": ""}, "CH2-159": {"name": "전해질 비교", "course": "ch2", "unit": "삼투압", "tier": "C", "mis": ["전해질의 입자 수가 많다.", "이온화로 입자 수가 는다.", "입자 수가 많다."], "dx": "같은 몰농도라도 이온화로 입자 수가 많은 전해질의 삼투압이 더 크다는 점을 놓친 경우다. 입자 수로 비교하지 못하면 삼투압 순서가 어긋난다.", "fix": "'같은 몰농도라도 이온화로 입자 수가 많은 전해질의 삼투압이 더 큼'을 못 박는다. 입자 수로 삼투압 순서를 잡아라.", "cite": ""}, "CH2-160": {"name": "온도 의존", "course": "ch2", "unit": "삼투압", "tier": "C", "mis": ["π = MRT이다.", "절대 온도에 비례한다."], "dx": "삼투압이 절대 온도에 비례한다는(π=MRT) 점을 놓친 경우다. 온도가 오르면 삼투압이 커진다는 점이 약하면 온도가 다른 조건의 삼투압 계산이 어긋난다.", "fix": "'삼투압은 절대 온도에 비례(π=MRT)'함을 못 박는다. 온도가 오르면 삼투압이 커짐을 온도가 다른 조건의 계산에 반영하라.", "cite": ""}, "CH2-161": {"name": "농도 의존", "course": "ch2", "unit": "삼투압", "tier": "B", "mis": ["몰농도에 비례한다."], "dx": "삼투압이 몰농도에 비례한다는 점을 놓친 경우다. 농도가 진할수록 삼투압이 크다는 비례가 약하면 농도로 삼투압을 가늠하지 못한다.", "fix": "'삼투압은 몰농도에 비례'함을 못 박는다. 농도가 진할수록 삼투압이 큼을 잡아 농도로 삼투압을 가늠하라.", "cite": ""}, "CH2-162": {"name": "등장액", "course": "ch2", "unit": "삼투압", "tier": "C", "mis": ["삼투압이 같다.", "입자 수가 같다."], "dx": "등장액이 삼투압(입자 농도)이 같아 용매의 알짜 이동이 없는 용액이라는 점을 놓친 경우다. 등장의 기준이 약하면 세포가 변형 없이 유지되는 조건을 못 짚는다.", "fix": "등장액을 '삼투압(입자 농도)이 같아 용매의 알짜 이동이 없는 용액'으로 못 박는다. 등장 기준으로 세포가 변형 없이 유지되는 조건을 짚어라.", "cite": ""}, "CH2-163": {"name": "고장액", "course": "ch2", "unit": "삼투압", "tier": "C", "mis": ["농도가 진하다.", "삼투압이 높다.", "물이 진한 쪽으로 빠진다."], "dx": "고장액이 세포보다 삼투압이 높아 물이 세포 밖(진한 쪽)으로 빠져 세포가 쭈그러드는 용액이라는 점을 놓친 경우다. 이 방향이 약하면 세포 수축을 잘못 판단한다.", "fix": "고장액을 '세포보다 삼투압이 높아 물이 세포 밖(진한 쪽)으로 빠져 세포가 쭈그러드는 용액'으로 못 박는다. 이 방향으로 세포 수축을 판단하라.", "cite": ""}, "CH2-164": {"name": "저장액", "course": "ch2", "unit": "삼투압", "tier": "C", "mis": ["농도가 묽다.", "삼투압이 낮다.", "물이 세포 안으로 들어온다."], "dx": "저장액이 세포보다 삼투압이 낮아 물이 세포 안으로 들어와 세포가 부푸는 용액이라는 점을 놓친 경우다. 이 방향이 약하면 적혈구가 터지는(용혈) 현상을 설명하지 못한다.", "fix": "저장액을 '세포보다 삼투압이 낮아 물이 세포 안으로 들어와 세포가 부푸는 용액'으로 못 박는다. 이 방향으로 적혈구가 터지는(용혈) 현상을 설명하라.", "cite": ""}, "CH2-165": {"name": "세포와 삼투", "course": "ch2", "unit": "삼투압", "tier": "C", "mis": ["물이 들어온다.", "물이 빠져나간다.", "삼투압이 같다."], "dx": "세포를 둘러싼 용액의 농도에 따라 물이 세포로 들어오거나 빠져나간다는 삼투 적용을 놓친 경우다. 용액 농도와 물 이동을 못 이으면 세포의 팽창·수축을 예측하지 못한다.", "fix": "'세포를 둘러싼 용액의 농도에 따라 물이 세포로 들어오거나 빠져나감'을 못 박는다. 용액 농도와 물 이동을 이어 세포의 팽창·수축을 예측하라.", "cite": ""}, "CH2-166": {"name": "역삼투", "course": "ch2", "unit": "삼투압", "tier": "C", "mis": ["큰 압력이 필요하다.", "삼투와 반대 방향이다."], "dx": "역삼투가 삼투압보다 큰 압력을 진한 쪽에 걸어 용매를 반대 방향(진한 쪽에서 묽은 쪽)으로 밀어내는 것이라는 점을 놓친 경우다. 이 반대 방향이 약하면 정수·담수화 원리를 못 짚는다.", "fix": "역삼투를 '삼투압보다 큰 압력을 진한 쪽에 걸어 용매를 반대 방향(진한 쪽에서 묽은 쪽)으로 밀어냄'으로 못 박는다. 이 반대 방향으로 정수·담수화 원리를 짚어라.", "cite": ""}, "CH2-167": {"name": "역삼투 응용", "course": "ch2", "unit": "삼투압", "tier": "C", "mis": ["용질을 분리한다.", "용질을 거른다.", "순수한 물을 얻는다."], "dx": "역삼투로 용질을 걸러 순수한 물을 얻는다는(해수 담수화·정수기) 응용을 놓친 경우다. 역삼투와 실생활의 연결이 약하면 응용 문제를 못 잡는다.", "fix": "'역삼투로 용질을 걸러 순수한 물을 얻음(해수 담수화·정수기)'을 못 박는다. 역삼투와 실생활의 연결로 응용 문제를 잡아라.", "cite": ""}, "CH2-168": {"name": "분자량 측정", "course": "ch2", "unit": "삼투압", "tier": "C", "mis": ["πV = nRT로 몰수를 구한다.", "묽은 용액에서도 측정이 쉽다."], "dx": "삼투압에서 πV=nRT로 몰수를 구해 분자량을 알아낼 수 있고 묽은 용액에서도 측정이 쉽다는 점을 놓친 경우다. 이 활용이 약하면 고분자 분자량 측정에 왜 삼투압을 쓰는지 못 짚는다.", "fix": "'삼투압에서 πV=nRT로 몰수를 구해 분자량을 알아낼 수 있고 묽은 용액에서도 측정이 쉬움'을 못 박는다. 이 활용으로 고분자 분자량 측정에 삼투압을 쓰는 까닭을 짚어라.", "cite": ""}, "CH2-169": {"name": "삼투압 크기", "course": "ch2", "unit": "삼투압", "tier": "C", "mis": ["민감한 총괄성이다.", "묽은 용액에서도 크다."], "dx": "삼투압이 묽은 용액에서도 비교적 크게 나타나는 가장 민감한 총괄성이라는 점을 놓친 경우다. 이 민감성이 약하면 어는점 내림보다 삼투압이 분자량 측정에 유리한 까닭을 못 짚는다.", "fix": "'삼투압은 묽은 용액에서도 비교적 크게 나타나는 가장 민감한 총괄성'임을 못 박는다. 이 민감성으로 어는점 내림보다 삼투압이 분자량 측정에 유리한 까닭을 짚어라.", "cite": ""}, "CH2-170": {"name": "삼투 현상", "course": "ch2", "unit": "삼투압", "tier": "C", "mis": ["물이 진한 쪽으로 이동한다."], "dx": "삼투에서 물이 진한 쪽으로 이동해 그쪽 액면이 높아지는 현상을 놓친 경우다. 관찰되는 액면 차가 곧 삼투압과 관련된다는 점이 약하면 삼투 실험을 잘못 읽는다.", "fix": "'삼투에서 물이 진한 쪽으로 이동해 그쪽 액면이 높아짐'을 못 박는다. 관찰되는 액면 차가 삼투압과 관련됨을 잡아 삼투 실험을 읽어라.", "cite": ""}, "CH2-320": {"name": "산화 정의", "course": "ch2", "unit": "산화수", "tier": "B", "mis": ["전자를 잃는다.", "산소를 얻는다.", "수소를 잃는다."], "dx": "산화가 전자를 잃는 것(또는 산소를 얻거나 수소를 잃는 것)이라는 점을 놓친 경우다. 전자 잃음이 산화의 본질이라는 점이 약하면 환원과 짝지어 산화환원을 보지 못한다.", "fix": "산화를 '전자를 잃는 것(또는 산소를 얻거나 수소를 잃는 것)'으로 못 박는다. 전자 잃음이 산화의 본질임을 잡아 환원과 짝지어 산화환원을 보라.", "cite": ""}, "CH2-321": {"name": "환원 정의", "course": "ch2", "unit": "산화수", "tier": "C", "mis": ["전자를 얻는다.", "산소를 잃는다."], "dx": "환원이 전자를 얻는 것(또는 산소를 잃거나 수소를 얻는 것)이라는 점을 놓친 경우다. 전자 얻음이 환원의 본질이라는 점이 약하면 산화와의 대응이 흔들린다.", "fix": "환원을 '전자를 얻는 것(또는 산소를 잃거나 수소를 얻는 것)'으로 못 박는다. 전자 얻음이 환원의 본질임을 잡아 산화와 대응시켜라.", "cite": ""}, "CH2-322": {"name": "동시성", "course": "ch2", "unit": "산화수", "tier": "C", "mis": ["전자를 주고받는다."], "dx": "산화와 환원이 한쪽이 잃은 전자를 다른 쪽이 얻으며 항상 동시에 일어난다는 점을 놓친 경우다. 따로 일어난다고 보면 산화환원을 한 반응으로 못 본다.", "fix": "'산화와 환원은 한쪽이 잃은 전자를 다른 쪽이 얻으며 항상 동시에 일어남'을 못 박는다. 따로 일어난다고 보지 말고 산화환원을 한 반응으로 보라.", "cite": ""}, "CH2-323": {"name": "산화수 규칙", "course": "ch2", "unit": "산화수", "tier": "B", "mis": ["보통 -2이다.", "보통 +1이다.", "중성 원소이다.", "+1이다."], "dx": "산화수 규칙(홑원소는 0, 수소는 보통 +1, 산소는 보통 -2)을 놓친 경우다. 이 기본 규칙이 흔들리면 화합물 속 원자의 산화수를 못 매긴다.", "fix": "산화수 규칙을 '홑원소는 0, 수소는 보통 +1, 산소는 보통 -2'로 못 박는다. 이 기본 규칙으로 화합물 속 원자의 산화수를 매겨라.", "cite": ""}, "CH2-324": {"name": "산화수 합", "course": "ch2", "unit": "산화수", "tier": "C", "mis": ["중성이다.", "전하와 같다."], "dx": "한 화학종에서 산화수의 합이 전체 전하와 같다는(중성은 0, 이온은 그 전하) 점을 놓친 경우다. 이 합 규칙이 약하면 모르는 원자의 산화수를 역산하지 못한다.", "fix": "'한 화학종에서 산화수의 합이 전체 전하와 같음(중성 0, 이온은 그 전하)'을 못 박는다. 이 합 규칙으로 모르는 원자의 산화수를 역산하라.", "cite": ""}, "CH2-325": {"name": "산화수 변화", "course": "ch2", "unit": "산화수", "tier": "C", "mis": ["증가=산화이다.", "감소=환원이다.", "산화수 변화가 필요하다."], "dx": "산화수가 증가하면 산화, 감소하면 환원이라는 점을 놓친 경우다. 산화수 변화로 산화·환원을 가리지 못하면 어느 물질이 산화·환원됐는지 못 짚는다.", "fix": "'산화수가 증가하면 산화, 감소하면 환원'을 못 박는다. 산화수 변화로 어느 물질이 산화·환원됐는지 가려라.", "cite": ""}, "CH2-326": {"name": "산화제", "course": "ch2", "unit": "산화수", "tier": "C", "mis": ["상대를 산화시킨다.", "전자를 받는다.", "환원된다."], "dx": "산화제가 상대를 산화시키면서 자신은 환원되는(전자를 받는) 물질이라는 점을 놓친 경우다. 산화제가 환원된다는 역설적 관계가 약하면 산화제·환원제를 거꾸로 잡는다.", "fix": "산화제를 '상대를 산화시키면서 자신은 환원되는(전자를 받는) 물질'로 못 박는다. 산화제가 환원된다는 역설을 잡아 산화제·환원제를 거꾸로 잡지 마라.", "cite": ""}, "CH2-327": {"name": "환원제", "course": "ch2", "unit": "산화수", "tier": "A", "mis": ["자신은 산화된다.", "전자를 내놓는다.", "전자를 잃는다.", "산화된다.", "상대를 환원시킨다."], "dx": "환원제가 상대를 환원시키면서 자신은 산화되는(전자를 내놓는) 물질이라는 점을 놓친 경우다. 환원제가 산화된다는 관계가 약하면 산화제·환원제를 거꾸로 잡는다.", "fix": "환원제를 '상대를 환원시키면서 자신은 산화되는(전자를 내놓는) 물질'로 못 박는다. 환원제가 산화된다는 관계를 잡아 산화제·환원제를 거꾸로 잡지 마라.", "cite": ""}, "CH2-328": {"name": "산화제와 전자", "course": "ch2", "unit": "산화수", "tier": "C", "mis": ["전자를 받는다."], "dx": "산화제가 전자를 받는다는 점을 놓친 경우다. 전자를 받아 자신이 환원된다는 흐름이 약하면 전자 이동 방향을 잘못 잡는다.", "fix": "'산화제는 전자를 받음'을 못 박는다. 전자를 받아 자신이 환원되는 흐름으로 전자 이동 방향을 잡아라.", "cite": ""}, "CH2-329": {"name": "환원제와 전자", "course": "ch2", "unit": "산화수", "tier": "C", "mis": ["전자를 내놓는다.", "전자를 잃는다."], "dx": "환원제가 전자를 내놓는다는 점을 놓친 경우다. 전자를 잃어 자신이 산화된다는 흐름이 약하면 전자 이동 방향을 잘못 잡는다.", "fix": "'환원제는 전자를 내놓음'을 못 박는다. 전자를 잃어 자신이 산화되는 흐름으로 전자 이동 방향을 잡아라.", "cite": ""}, "CH2-330": {"name": "산화제 산화수", "course": "ch2", "unit": "산화수", "tier": "C", "mis": ["환원된다."], "dx": "산화제는 전자를 받아 산화수가 감소한다(환원됨)는 점을 놓친 경우다. 산화수 변화로 산화제를 가리지 못하면 반응 해석이 어긋난다.", "fix": "'산화제는 전자를 받아 산화수가 감소함(환원됨)'을 못 박는다. 산화수 변화로 산화제를 가려 반응을 해석하라.", "cite": ""}, "CH2-331": {"name": "환원제 산화수", "course": "ch2", "unit": "산화수", "tier": "C", "mis": ["산화된다."], "dx": "환원제는 전자를 잃어 산화수가 증가한다(산화됨)는 점을 놓친 경우다. 산화수 변화로 환원제를 가리지 못하면 반응 해석이 어긋난다.", "fix": "'환원제는 전자를 잃어 산화수가 증가함(산화됨)'을 못 박는다. 산화수 변화로 환원제를 가려 반응을 해석하라.", "cite": ""}, "CH2-332": {"name": "전자 균형", "course": "ch2", "unit": "산화수", "tier": "C", "mis": ["전자가 보존된다."], "dx": "산화에서 잃은 전자 수와 환원에서 얻은 전자 수가 같아야(전자 보존) 한다는 점을 놓친 경우다. 전자 균형이 약하면 산화환원 반응식의 계수를 못 맞춘다.", "fix": "'산화에서 잃은 전자 수와 환원에서 얻은 전자 수가 같아야(전자 보존) 함'을 못 박는다. 전자 균형으로 산화환원 반응식의 계수를 맞춰라.", "cite": ""}, "CH2-333": {"name": "과산화물", "course": "ch2", "unit": "산화수", "tier": "C", "mis": ["과산화물 예외이다.", "예외이다."], "dx": "과산화물에서는 산소의 산화수가 보통의 -2가 아니라 -1이라는 예외를 놓친 경우다. 이 예외를 모르면 과산화수소 같은 물질의 산화수가 어긋난다.", "fix": "'과산화물에서는 산소의 산화수가 보통의 -2가 아니라 -1'임을 못 박는다. 이 예외로 과산화수소 같은 물질의 산화수를 맞춰라.", "cite": ""}, "CH2-334": {"name": "금속 수소화물", "course": "ch2", "unit": "산화수", "tier": "C", "mis": ["금속 수소화물 예외이다.", "예외이다."], "dx": "금속 수소화물에서는 수소의 산화수가 보통의 +1이 아니라 -1이라는 예외를 놓친 경우다. 이 예외를 모르면 NaH 같은 물질의 산화수가 어긋난다.", "fix": "'금속 수소화물에서는 수소의 산화수가 보통의 +1이 아니라 -1'임을 못 박는다. 이 예외로 NaH 같은 물질의 산화수를 맞춰라.", "cite": ""}, "CH2-335": {"name": "산화수 계산", "course": "ch2", "unit": "산화수", "tier": "C", "mis": ["산화수 규칙이다.", "합이 0이다."], "dx": "산화수 규칙과 합이 전하와 같다는 조건으로 모르는 원자의 산화수를 구하는 게 흔들린 경우다. 이 셈이 약하면 산화·환원 판정의 출발이 막힌다.", "fix": "모르는 원자의 산화수를 '산화수 규칙과 합이 전하와 같다는 조건으로' 구한다. 이 셈을 산화·환원 판정의 출발로 삼아라.", "cite": ""}, "CH2-336": {"name": "산화제 역할", "course": "ch2", "unit": "산화수", "tier": "C", "mis": ["자신은 환원된다.", "전자를 받는다."], "dx": "산화제가 전자를 받아 자신은 환원되면서 상대를 산화시키는 역할이라는 점을 놓친 경우다. 이 역할이 흐리면 반응에서 산화제를 못 짚는다.", "fix": "산화제를 '전자를 받아 자신은 환원되면서 상대를 산화시키는 역할'로 못 박는다. 이 역할로 반응에서 산화제를 짚어라.", "cite": ""}, "CH2-062": {"name": "돌턴 법칙", "course": "ch2", "unit": "분압", "tier": "A", "mis": ["분압을 더한다.", "합이다.", "분압이 더해진다.", "이상 기체 가정이다."], "dx": "전체 압력이 각 성분 기체 분압의 합이라는 돌턴 법칙을 놓친 경우다(각 기체가 독립적으로 압력을 냄). 분압을 더한다는 점이 약하면 혼합 기체의 전체·성분 압력 관계가 어긋난다.", "fix": "돌턴 법칙을 '전체 압력 = 각 성분 기체 분압의 합(각 기체가 독립적으로 압력을 냄)'으로 못 박는다. 분압을 더해 혼합 기체의 전체·성분 압력을 잡아라.", "cite": ""}, "CH2-063": {"name": "분압 정의", "course": "ch2", "unit": "분압", "tier": "C", "mis": ["성분별 압력이다.", "전체 부피 기준이다."], "dx": "분압이 한 성분 기체가 전체 부피를 혼자 차지했을 때 낼 압력이라는 점을 놓친 경우다. 전체 부피 기준이라는 점이 약하면 분압의 의미를 잘못 잡는다.", "fix": "분압을 '한 성분 기체가 전체 부피를 혼자 차지했을 때 낼 압력'으로 못 박는다. 전체 부피 기준임을 잡아 분압의 의미를 바로 세워라.", "cite": ""}, "CH2-064": {"name": "분압-몰분율", "course": "ch2", "unit": "분압", "tier": "A", "mis": ["정의 관계이다.", "비례 관계이다.", "곱한다.", "분압 = 전체 압력 × 몰분율이다."], "dx": "분압이 (전체 압력 × 그 성분의 몰분율)이라는 관계를 놓친 경우다. 이 정의 관계가 약하면 혼합 기체에서 각 성분의 분압을 못 구한다.", "fix": "분압을 '전체 압력 × 그 성분의 몰분율'로 못 박는다. 이 정의 관계로 혼합 기체에서 각 성분의 분압을 구하라.", "cite": ""}, "CH2-065": {"name": "몰분율", "course": "ch2", "unit": "분압", "tier": "B", "mis": ["전체를 1로 본다.", "전체 몰수로 나눈다.", "부분/전체이다."], "dx": "몰분율이 (성분 몰수 ÷ 전체 몰수)이고 모든 성분의 몰분율 합이 1이라는 점을 놓친 경우다. 몰분율 정의가 약하면 분압-몰분율 계산이 막힌다.", "fix": "몰분율을 '성분 몰수 ÷ 전체 몰수, 모든 성분의 합은 1'로 못 박는다. 이 정의로 분압-몰분율 계산을 이어가라.", "cite": ""}, "CH2-066": {"name": "분압-몰수", "course": "ch2", "unit": "분압", "tier": "C", "mis": ["P ∝ n이다.", "비례한다."], "dx": "같은 온도·부피에서 분압이 그 성분의 몰수에 비례한다는 점을 놓친 경우다. 분압이 몰수를 대변한다는 점이 약하면 몰수로 분압을 가늠하지 못한다.", "fix": "'같은 온도·부피에서 분압은 그 성분의 몰수에 비례'함을 못 박는다. 분압이 몰수를 대변함을 잡아 몰수로 분압을 가늠하라.", "cite": ""}, "CH2-067": {"name": "분압비", "course": "ch2", "unit": "분압", "tier": "B", "mis": ["분압이 몰수에 비례한다.", "분압은 몰수에만 비례한다."], "dx": "분압의 비가 곧 몰수의 비라는 점을 놓친 경우다(같은 온도·부피에서). 분압비=몰비라는 점이 약하면 압력 자료로 성분 조성을 못 읽는다.", "fix": "'분압의 비가 곧 몰수의 비(같은 온도·부피)'임을 못 박는다. 분압비 = 몰비로 압력 자료에서 성분 조성을 읽어라.", "cite": ""}, "CH2-068": {"name": "수상 치환", "course": "ch2", "unit": "분압", "tier": "C", "mis": ["수증기압을 뺀다.", "수증기가 섞인다."], "dx": "물 위로 기체를 모을 때(수상 치환) 모인 기체에 수증기가 섞여 있어 전체 압력에서 그 온도의 수증기압을 빼야 한다는 점을 놓친 경우다. 이 보정을 빼먹으면 포집한 기체의 분압이 과대평가된다.", "fix": "'수상 치환으로 모은 기체엔 수증기가 섞여 있어 전체 압력에서 그 온도의 수증기압을 빼야' 함을 못 박는다. 이 보정을 빼먹어 포집 기체 분압을 과대평가하지 마라.", "cite": ""}, "CH2-069": {"name": "분압 계산", "course": "ch2", "unit": "분압", "tier": "C", "mis": ["몰분율을 곱한다."], "dx": "분압을 (몰분율 × 전체 압력)으로 계산하는 게 흔들린 경우다. 몰분율을 구해 전체 압력에 곱하는 절차가 약하면 분압 값이 어긋난다.", "fix": "분압을 '몰분율 × 전체 압력'으로 계산한다. 몰분율을 구해 전체 압력에 곱하는 절차를 따라 분압 값을 맞춰라.", "cite": ""}, "CH2-052": {"name": "실제 기체 특징", "course": "ch2", "unit": "실제기체", "tier": "B", "mis": ["분자에 크기가 있다.", "분자 간 힘이 있다.", "가정이 다르다."], "dx": "실제 기체가 이상 기체와 달리 분자에 크기가 있고 분자 간 힘이 작용한다는 점을 놓친 경우다. 이 두 차이가 약하면 실제 기체가 이상 기체에서 벗어나는 까닭을 못 짚는다.", "fix": "실제 기체를 '이상과 달리 분자에 크기가 있고 분자 간 힘이 작용함'으로 못 박는다. 이 두 차이로 실제 기체가 이상에서 벗어나는 까닭을 짚어라.", "cite": ""}, "CH2-053": {"name": "이상 기체 근접 조건", "course": "ch2", "unit": "실제기체", "tier": "C", "mis": ["인력과 부피 영향이 작다.", "분자 부피 영향이 작다.", "분자가 빠르게 움직인다."], "dx": "실제 기체가 고온·저압에서 이상 기체에 가까워진다(분자 부피·인력 영향이 작아짐)는 점을 놓친 경우다. 분자가 멀리 빠르게 움직이는 조건이라는 점이 약하면 언제 이상 기체로 봐도 되는지 못 가린다.", "fix": "'실제 기체는 고온·저압에서 이상 기체에 가까워짐(분자 부피·인력 영향이 작아짐)'을 못 박는다. 분자가 멀리 빠르게 움직이는 조건임을 잡아 언제 이상으로 봐도 되는지 가려라.", "cite": ""}, "CH2-054": {"name": "이상 기체 편차", "course": "ch2", "unit": "실제기체", "tier": "A", "mis": ["분자 부피 영향이 크다.", "인력 영향이 크다.", "분자가 가까워진다.", "조건에 의존한다.", "분자가 느려진다."], "dx": "실제 기체가 고압에서는 분자 부피 영향이, 저온에서는 인력 영향이 커져 이상 기체에서 크게 벗어난다는 점을 놓친 경우다. 어느 조건에서 무엇이 편차를 키우는지 못 가르면 실제 기체 거동을 잘못 본다.", "fix": "'고압에선 분자 부피 영향이, 저온에선 인력 영향이 커져 이상에서 크게 벗어남'을 못 박는다. 어느 조건에서 무엇이 편차를 키우는지 갈라 실제 거동을 잡아라.", "cite": ""}, "CH2-055": {"name": "반데르발스 식", "course": "ch2", "unit": "실제기체", "tier": "C", "mis": ["실제 기체용이다.", "두 요인을 보정한다.", "보정 항이 있다."], "dx": "반데르발스 식이 이상 기체 방정식에 분자 부피와 인력 두 요인을 보정한 실제 기체용 식이라는 점을 놓친 경우다. 두 보정 항의 의미가 약하면 실제 기체 식을 해석하지 못한다.", "fix": "반데르발스 식을 '이상 기체 방정식에 분자 부피와 인력 두 요인을 보정한 실제 기체용 식'으로 못 박는다. 두 보정 항의 의미를 잡아 실제 기체 식을 해석하라.", "cite": ""}, "CH2-056": {"name": "반데르발스 상수", "course": "ch2", "unit": "실제기체", "tier": "A", "mis": ["부피는 b이다.", "인력은 a이다.", "기체 고유 값이다.", "a는 인력, b는 부피이다."], "dx": "반데르발스 상수에서 a가 분자 간 인력을, b가 분자 자체 부피를 나타내는 기체 고유 값이라는 점을 놓친 경우다. a와 b의 역할을 바꾸면 실제 기체 비교가 어긋난다.", "fix": "반데르발스 상수를 'a는 분자 간 인력, b는 분자 자체 부피를 나타내는 기체 고유 값'으로 못 박는다. a와 b의 역할을 바꾸지 말고 실제 기체를 비교하라.", "cite": ""}, "CH2-057": {"name": "압축 인자", "course": "ch2", "unit": "실제기체", "tier": "A", "mis": ["항상 PV = nRT이다.", "정의 식이다.", "편차가 없다.", "조건에 따라 변한다.", "Z = PV/nRT이다."], "dx": "압축 인자가 Z = PV/nRT로 정의되고 이상 기체는 Z=1, 그에서 벗어나면 실제 기체라는 점을 놓친 경우다. Z가 1에서 얼마나 떨어졌는지가 편차의 척도라는 점이 약하면 실제 기체 정도를 못 읽는다.", "fix": "압축 인자를 'Z = PV/nRT로 정의, 이상 기체는 Z=1, 벗어나면 실제 기체'로 못 박는다. Z가 1에서 떨어진 정도를 편차의 척도로 읽어라.", "cite": ""}, "CH2-058": {"name": "압축 인자 해석", "course": "ch2", "unit": "실제기체", "tier": "C", "mis": ["부피가 작아진다.", "분자 부피 영향이 크다.", "조건에 따라 다르다."], "dx": "압축 인자가 1보다 작으면 인력이 우세해 부피가 이상보다 작고, 1보다 크면 분자 부피 영향이 우세하다는 해석을 놓친 경우다. Z의 위아래 의미가 약하면 어느 효과가 지배하는지 못 가린다.", "fix": "'Z<1이면 인력이 우세해 부피가 이상보다 작고, Z>1이면 분자 부피 영향이 우세함'을 못 박는다. Z의 위아래로 어느 효과가 지배하는지 가려라.", "cite": ""}, "CH2-059": {"name": "편차 크기", "course": "ch2", "unit": "실제기체", "tier": "C", "mis": ["인력 영향이 크다.", "부피 영향이 크다."], "dx": "실제 기체 편차의 크기가 조건에 따라 인력이 큰지 분자 부피가 큰지로 갈린다는 점을 놓친 경우다. 어느 요인이 더 센지를 못 따지면 편차 크기를 비교하지 못한다.", "fix": "'실제 기체 편차의 크기는 조건에 따라 인력이 큰지 분자 부피가 큰지로 갈림'을 못 박는다. 어느 요인이 더 센지 따져 편차 크기를 비교하라.", "cite": ""}, "CH2-060": {"name": "이상 기체 근접", "course": "ch2", "unit": "실제기체", "tier": "C", "mis": ["인력이 약하다.", "편차가 작다.", "인력과 부피가 다르다."], "dx": "분자 간 힘이 약하고 작은 기체일수록 이상 기체에 가깝게 거동한다는 점을 놓친 경우다(He가 대표적). 인력·부피와 이상성의 관계가 약하면 어느 기체가 더 이상적인지 못 가린다.", "fix": "'분자 간 힘이 약하고 작은 기체일수록 이상 기체에 가깝게 거동'함을 못 박는다(He가 대표). 인력·부피와 이상성의 관계로 어느 기체가 더 이상적인지 가려라.", "cite": ""}, "CH2-061": {"name": "저압 근사", "course": "ch2", "unit": "실제기체", "tier": "C", "mis": ["편차가 작다.", "편차가 작아진다."], "dx": "저압에서는 분자 사이 거리가 멀어 분자 부피·인력의 영향이 작아져 편차가 작아진다는 점을 놓친 경우다. 압력이 낮을수록 이상 기체에 가깝다는 점이 약하면 근사 조건을 못 잡는다.", "fix": "'저압에선 분자 사이 거리가 멀어 분자 부피·인력의 영향이 작아져 편차가 작아짐'을 못 박는다. 압력이 낮을수록 이상에 가까움을 근사 조건으로 잡아라.", "cite": ""}, "CH2-091": {"name": "결정성 고체", "course": "ch2", "unit": "고체", "tier": "C", "mis": ["규칙적 배열이다.", "규칙적 구조 때문이다.", "배열이 다르다."], "dx": "결정성 고체가 입자가 규칙적으로 배열된 고체라는 점을 놓친 경우다. 규칙적 배열이 약하면 일정한 녹는점을 갖는 결정성과 그렇지 않은 비결정성의 차이를 못 짚는다.", "fix": "결정성 고체를 '입자가 규칙적으로 배열된 고체'로 못 박는다. 규칙 배열이 일정한 녹는점으로 이어짐을 잡아 비결정성과 구분하라.", "cite": ""}, "CH2-092": {"name": "비결정성 고체", "course": "ch2", "unit": "고체", "tier": "C", "mis": ["불규칙한 배열 때문이다.", "무정형이다.", "불규칙한 배열이다."], "dx": "비결정성(무정형) 고체가 입자 배열이 불규칙해 일정한 녹는점이 없다는 점을 놓친 경우다(유리가 대표적). 불규칙 배열이 약하면 결정성과의 차이를 가르지 못한다.", "fix": "비결정성(무정형) 고체를 '입자 배열이 불규칙해 일정한 녹는점이 없음'으로 못 박는다(유리가 대표). 불규칙 배열로 결정성과의 차이를 가려라.", "cite": ""}, "CH2-093": {"name": "이온 결정", "course": "ch2", "unit": "고체", "tier": "C", "mis": ["이온 결합이다.", "이온으로 이루어진다."], "dx": "이온 결정이 양이온과 음이온이 이온 결합으로 격자를 이룬 고체라는 점을 놓친 경우다. 구성이 흐리면 녹는점·전도성 같은 이온 결정의 성질로 이어지지 못한다.", "fix": "이온 결정을 '양이온과 음이온이 이온 결합으로 격자를 이룬 고체'로 못 박는다. 이 구성에서 녹는점·전도성 같은 성질로 이어라.", "cite": ""}, "CH2-094": {"name": "이온 결정 녹는점", "course": "ch2", "unit": "고체", "tier": "C", "mis": ["이온 결합이 강하다.", "정전기적 인력이 강하다."], "dx": "이온 결정이 강한 정전기적 인력 때문에 녹는점이 높다는 점을 놓친 경우다. 인력 세기가 녹는점을 정한다는 연결이 약하면 결정 유형별 녹는점 비교가 어긋난다.", "fix": "'이온 결정은 강한 정전기적 인력 때문에 녹는점이 높음'을 못 박는다. 인력 세기가 녹는점을 정함을 결정 유형별 비교에 써라.", "cite": ""}, "CH2-095": {"name": "이온 결정 전도성", "course": "ch2", "unit": "고체", "tier": "A", "mis": ["이온이 고정되어 있다.", "이온이 자유롭게 움직인다.", "이온이 이동하지 못한다.", "이온이 이동한다.", "이온이 자유롭다."], "dx": "이온 결정이 고체에서는 이온이 격자에 고정돼 전기가 안 통하고, 녹거나 물에 녹으면 이온이 자유로이 움직여 통한다는 조건 차이를 놓친 경우다. 이 구분이 약하면 전해질·전기분해 단원이 흔들린다.", "fix": "이온 결정을 '고체는 이온이 격자에 고정돼 안 통하고, 녹거나 물에 녹으면 이온이 움직여 통함'으로 못 박는다. 이 조건 차이를 전해질·전기분해의 바탕으로 삼아라.", "cite": ""}, "CH2-096": {"name": "이온 결정 성질", "course": "ch2", "unit": "고체", "tier": "C", "mis": ["취성이 있다.", "같은 전하 이온이 반발한다."], "dx": "이온 결정이 외력에 층이 밀리면 같은 전하 이온이 마주쳐 반발해 쪼개지는(취성) 성질을 놓친 경우다. 단단하지만 잘 부서지는 이 이중성이 약하면 이온 결정 물성을 설명하지 못한다.", "fix": "이온 결정을 '단단하지만 층이 밀리면 같은 전하가 마주쳐 반발해 쪼개짐(취성)'으로 두 성질을 함께 잡는다. 단단함과 부서짐을 한 그림으로 새겨라.", "cite": ""}, "CH2-097": {"name": "분자 결정", "course": "ch2", "unit": "고체", "tier": "C", "mis": ["분자 간 힘이다.", "분자로 이루어진다."], "dx": "분자 결정이 분자들이 약한 분자 간 힘으로 모인 고체라는 점을 놓친 경우다. 끊기는 게 결합이 아니라 분자 간 힘이라는 점이 약하면 낮은 녹는점의 까닭을 못 짚는다.", "fix": "분자 결정을 '분자들이 약한 분자 간 힘으로 모인 고체'로 못 박는다. 끊기는 게 결합이 아니라 분자 간 힘임을 잡아 낮은 녹는점의 까닭을 짚어라.", "cite": ""}, "CH2-098": {"name": "분자 결정 녹는점", "course": "ch2", "unit": "고체", "tier": "B", "mis": ["분자 간 힘이 약하다.", "약한 인력 때문이다."], "dx": "분자 결정이 분자 간 힘이 약해 녹는점이 낮다는 점을 놓친 경우다. 약한 힘이 낮은 녹는점으로 이어진다는 연결이 약하면 결정 유형별 비교가 어긋난다.", "fix": "'분자 결정은 분자 간 힘이 약해 녹는점이 낮음'을 못 박는다. 약한 힘이 낮은 녹는점으로 이어짐을 결정 유형별 비교에 써라.", "cite": ""}, "CH2-099": {"name": "분자 결정 예", "course": "ch2", "unit": "고체", "tier": "C", "mis": ["이온으로 이루어진다.", "원자들이 공유 결합으로 연결된다.", "분자로 이루어진다."], "dx": "드라이아이스(CO₂)·얼음·아이오딘처럼 분자로 이뤄진 고체가 분자 결정이라는 점을 놓친 경우다. 예를 이온·공유 결정과 혼동하면 결정 유형 분류가 어긋난다.", "fix": "'드라이아이스(CO₂)·얼음·아이오딘처럼 분자로 이뤄진 고체가 분자 결정'임을 못 박는다. 예를 이온·공유 결정과 혼동하지 말고 분류하라.", "cite": ""}, "CH2-100": {"name": "공유 결정", "course": "ch2", "unit": "고체", "tier": "C", "mis": ["공유 결합으로 이어진다.", "원자로 이루어진다."], "dx": "공유 결정이 원자들이 그물처럼 연속으로 공유 결합한 고체라 독립 분자가 없다는 점을 놓친 경우다. 연속 결합 구조가 약하면 매우 높은 녹는점의 까닭을 못 짚는다.", "fix": "공유 결정을 '원자들이 그물처럼 연속으로 공유 결합한 고체라 독립 분자가 없음'으로 못 박는다. 연속 결합 구조로 매우 높은 녹는점의 까닭을 짚어라.", "cite": ""}, "CH2-101": {"name": "공유 결정 녹는점", "course": "ch2", "unit": "고체", "tier": "B", "mis": ["공유 결합이 강하다.", "결합이 강하다."], "dx": "공유 결정이 녹으려면 강한 공유 결합을 끊어야 해 녹는점이 매우 높다는 점을 놓친 경우다. 결정 중 녹는점이 가장 높은 까닭이 약하면 녹는점 순서를 잘못 잡는다.", "fix": "'공유 결정은 녹으려면 강한 공유 결합을 끊어야 해 녹는점이 매우 높음'을 못 박는다. 결정 중 녹는점이 가장 높은 까닭을 녹는점 순서에 써라.", "cite": ""}, "CH2-102": {"name": "공유 결정 예", "course": "ch2", "unit": "고체", "tier": "C", "mis": ["분자로 이루어진다.", "이온으로 이루어진다.", "원자들이 공유 결합으로 연결된다."], "dx": "다이아몬드·흑연·석영처럼 원자가 공유 결합으로 이어진 고체가 공유 결정이라는 점을 놓친 경우다. 예를 분자·이온 결정과 혼동하면 결정 유형 분류가 어긋난다.", "fix": "'다이아몬드·흑연·석영처럼 원자가 공유 결합으로 이어진 고체가 공유 결정'임을 못 박는다. 예를 분자·이온 결정과 혼동하지 말고 분류하라.", "cite": ""}, "CH2-103": {"name": "공유 결정 전도성", "course": "ch2", "unit": "고체", "tier": "C", "mis": ["전자가 결합에 묶여 있다.", "자유 전자가 없다."], "dx": "공유 결정이 전자가 결합에 묶여 자유 전자가 없어 보통 전기가 안 통한다는 점을 놓친 경우다. 이 기본이 약하면 예외인 흑연이 왜 특별한지 대비가 서지 않는다.", "fix": "'공유 결정은 전자가 결합에 묶여 자유 전자가 없어 보통 전기가 안 통함'을 못 박는다. 이 기본에서 예외인 흑연이 왜 특별한지 대비하라.", "cite": ""}, "CH2-104": {"name": "흑연 전도성", "course": "ch2", "unit": "고체", "tier": "C", "mis": ["자유 전자가 있다.", "남은 전자가 자유롭다."], "dx": "흑연이 탄소마다 결합에 안 쓰인 전자가 층을 따라 자유로워 전기가 통한다는 점을 놓친 경우다. 이 자유 전자가 약하면 같은 탄소인 다이아몬드와 전도성이 갈리는 까닭을 못 짚는다.", "fix": "'흑연은 탄소마다 결합에 안 쓰인 전자가 층을 따라 자유로워 전기가 통함'을 못 박는다. 이 자유 전자로 다이아몬드와 전도성이 갈리는 까닭을 짚어라.", "cite": ""}, "CH2-105": {"name": "다이아몬드 전도성", "course": "ch2", "unit": "고체", "tier": "A", "mis": ["자유 전자가 없다.", "모든 전자가 결합에 쓰인다.", "남는 전자가 없다."], "dx": "다이아몬드가 탄소의 전자 4개를 모두 공유 결합에 써 남는 자유 전자가 없어 전기가 안 통한다는 점을 놓친 경우다. 흑연과의 이 차이가 약하면 같은 원소인데 한쪽만 통하는 까닭을 설명하지 못한다.", "fix": "'다이아몬드는 탄소의 전자 4개를 모두 공유 결합에 써 남는 자유 전자가 없어 전기가 안 통함'을 못 박는다. 흑연과의 이 차이로 같은 원소인데 한쪽만 통하는 까닭을 설명하라.", "cite": ""}, "CH2-106": {"name": "금속 결정", "course": "ch2", "unit": "고체", "tier": "C", "mis": ["양이온과 자유 전자이다.", "금속 결합이다.", "자유 전자가 양이온을 둘러싼다."], "dx": "금속 결정이 양이온이 자유 전자 바다에 잠긴 구조라는 점을 놓친 경우다. 자유 전자라는 핵심이 약하면 금속의 전도성·전성·연성을 설명하지 못한다.", "fix": "금속 결정을 '양이온이 자유 전자 바다에 잠긴 구조'로 못 박는다. 자유 전자라는 핵심에서 전도성·전성·연성을 설명하라.", "cite": ""}, "CH2-107": {"name": "금속 전도성", "course": "ch2", "unit": "고체", "tier": "C", "mis": ["자유 전자 때문이다."], "dx": "금속이 자유 전자가 전하를 날라 전기·열을 잘 통한다는 점을 놓친 경우다. 자유 전자가 전도의 주체라는 그림이 약하면 금속 전도성을 설명하지 못한다.", "fix": "'금속은 자유 전자가 전하를 날라 전기·열을 잘 통함'을 못 박는다. 자유 전자가 전도의 주체라는 그림으로 금속 전도성을 설명하라.", "cite": ""}, "CH2-108": {"name": "금속 성질", "course": "ch2", "unit": "고체", "tier": "C", "mis": ["자유 전자가 결합을 유지한다.", "자유 전자 덕분이다."], "dx": "자유 전자가 양이온 사이를 옮겨 다니며 결합을 유지해 금속이 두드리면 펴지고 늘어난다는(전성·연성) 점을 놓친 경우다. 이 메커니즘이 약하면 금속이 깨지지 않고 변형되는 까닭을 못 짚는다.", "fix": "'자유 전자가 양이온 사이를 옮겨 다니며 결합을 유지해 두드리면 펴지고 늘어남(전성·연성)'을 못 박는다. 이 메커니즘으로 금속이 깨지지 않고 변형됨을 설명하라.", "cite": ""}, "CH2-109": {"name": "녹는점 비교", "course": "ch2", "unit": "고체", "tier": "C", "mis": ["공유 결합이 강하다.", "분자 간 힘이 약하다."], "dx": "결정 유형별 녹는점을 끊어야 하는 힘의 세기로 비교하지 못한 경우다(공유·이온 결정은 높고 분자 결정은 낮음). 무엇을 끊는지에 따라 녹는점이 갈린다는 점이 약하면 결정 비교가 어긋난다.", "fix": "결정 유형별 녹는점을 '끊어야 하는 힘의 세기'로 비교한다(공유·이온은 높고 분자는 낮음). 무엇을 끊는지에 따라 녹는점이 갈림을 잡아 비교하라.", "cite": ""}, "CH2-110": {"name": "단위 세포", "course": "ch2", "unit": "고체", "tier": "C", "mis": ["최소 반복 단위이다.", "구조에 따라 다르다.", "규칙적 배열의 단위이다."], "dx": "단위 세포가 결정의 규칙적 배열을 이루는 최소 반복 단위라는 점을 놓친 경우다. 반복 단위라는 개념이 약하면 단위 세포 속 입자 수·결정 구조 계산이 어긋난다.", "fix": "단위 세포를 '결정의 규칙적 배열을 이루는 최소 반복 단위'로 못 박는다. 반복 단위 개념으로 단위 세포 속 입자 수·결정 구조를 계산하라.", "cite": ""}, "CH2-111": {"name": "흑연 구조", "course": "ch2", "unit": "고체", "tier": "C", "mis": ["남은 전자가 자유롭다.", "층 사이가 약하다.", "평면 층 구조이다."], "dx": "흑연이 탄소가 평면 층으로 공유 결합하고 층 사이는 약한 힘으로 묶여(잘 미끄러짐) 남은 전자가 자유로운 구조라는 점을 놓친 경우다. 이 층 구조가 약하면 흑연의 윤활성·전도성을 함께 설명하지 못한다.", "fix": "흑연을 '탄소가 평면 층으로 공유 결합하고 층 사이는 약한 힘으로 묶여(잘 미끄러짐) 남은 전자가 자유로운 구조'로 못 박는다. 이 층 구조로 흑연의 윤활성·전도성을 함께 설명하라.", "cite": ""}, "CH2-195": {"name": "자발성 방향", "course": "ch2", "unit": "자발성", "tier": "C", "mis": ["전체 엔트로피로 판단한다.", "열역학 2법칙이다.", "전체 엔트로피가 기준이다."], "dx": "반응의 자발성이 계와 주위를 합한 전체 엔트로피가 증가하는 방향으로 정해진다는 점을 놓친 경우다(열역학 제2법칙). 전체 엔트로피 기준이 약하면 깁스 자유 에너지로 넘어가는 논리를 못 짚는다.", "fix": "자발성을 '계와 주위를 합한 전체 엔트로피가 증가하는 방향(열역학 제2법칙)'으로 못 박는다. 전체 엔트로피 기준을 잡아 깁스 자유 에너지로 넘어가는 논리로 이어라.", "cite": ""}, "CH2-196": {"name": "열역학 제2법칙", "course": "ch2", "unit": "자발성", "tier": "C", "mis": ["엔트로피가 증가한다.", "법칙이 다르다."], "dx": "열역학 제2법칙이 자발적 변화에서 우주 전체의 엔트로피가 항상 증가한다는 법칙이라는 점을 놓친 경우다. 이 법칙이 약하면 자발성의 근본 기준을 못 잡는다.", "fix": "열역학 제2법칙을 '자발적 변화에서 우주 전체의 엔트로피가 항상 증가'로 못 박는다. 이 법칙을 자발성의 근본 기준으로 삼아라.", "cite": ""}, "CH2-197": {"name": "깁스 자유 에너지", "course": "ch2", "unit": "자발성", "tier": "C", "mis": ["빼는 식이다.", "엔탈피도 들어간다.", "켈빈 온도이다."], "dx": "깁스 자유 에너지가 엔탈피와 엔트로피를 한데 묶어 자발성을 판단하는 양이라는 점을 놓친 경우다. 두 요인을 하나로 합친다는 점이 약하면 ΔG 식의 의미를 못 짚는다.", "fix": "깁스 자유 에너지를 '엔탈피와 엔트로피를 한데 묶어 자발성을 판단하는 양'으로 못 박는다. 두 요인을 하나로 합침을 잡아 ΔG 식의 의미를 짚어라.", "cite": ""}, "CH2-198": {"name": "ΔG 식", "course": "ch2", "unit": "자발성", "tier": "A", "mis": ["빼는 식이다.", "식이 다르다.", "T가 곱해진다.", "켈빈 온도이다.", "음수가 자발이다."], "dx": "깁스 식 ΔG = ΔH − TΔS에서 T가 절대 온도이고 TΔS 항이 빠진다는 점을 놓친 경우다. 식의 꼴이나 켈빈 온도를 틀리면 자발성 판단이 통째로 어긋난다.", "fix": "깁스 식을 'ΔG = ΔH − TΔS, T는 절대 온도(TΔS 항이 빠짐)'로 못 박는다. 식의 꼴과 켈빈 온도를 맞춰 자발성을 판단하라.", "cite": ""}, "CH2-199": {"name": "자발성 판단", "course": "ch2", "unit": "자발성", "tier": "B", "mis": ["양수가 비자발이다.", "평형이다.", "음수가 자발이다."], "dx": "ΔG가 음수면 자발, 0이면 평형, 양수면 비자발이라는 판정 기준을 놓친 경우다. ΔG 부호가 자발성을 정한다는 점이 약하면 반응이 일어날지 가리지 못한다.", "fix": "'ΔG가 음수면 자발, 0이면 평형, 양수면 비자발'을 못 박는다. ΔG 부호가 자발성을 정함을 잡아 반응이 일어날지 가려라.", "cite": ""}, "CH2-200": {"name": "부호 조합", "course": "ch2", "unit": "자발성", "tier": "C", "mis": ["ΔG가 항상 양수이다.", "고온에서 TΔS가 우세하다."], "dx": "ΔH와 ΔS의 부호 조합에 따라 자발성이 갈린다는 점을 놓친 경우다(발열·엔트로피 증가면 항상 자발, 반대면 항상 비자발, 나머지는 온도에 좌우). 이 조합 분석이 약하면 온도에 따른 자발성 전환을 못 짚는다.", "fix": "'ΔH·ΔS 부호 조합으로 자발성이 갈림(발열·엔트로피 증가면 항상 자발, 반대면 항상 비자발, 나머지는 온도에 좌우)'을 못 박는다. 이 조합으로 온도에 따른 자발성 전환을 짚어라.", "cite": ""}, "CH2-201": {"name": "자발성 결정", "course": "ch2", "unit": "자발성", "tier": "C", "mis": ["둘 다 필요하다.", "온도도 영향을 준다."], "dx": "자발성이 엔탈피·엔트로피·온도 셋을 함께 봐야 정해진다는 점을 놓친 경우다. 한 가지만 보면 ΔG 부호를 잘못 잡아 자발성 판단이 어긋난다.", "fix": "자발성을 '엔탈피·엔트로피·온도 셋을 함께 봐야 정해짐'으로 못 박는다. 한 가지만 보지 말고 셋으로 ΔG 부호를 잡아라.", "cite": ""}, "CH2-202": {"name": "발열과 자발성", "course": "ch2", "unit": "자발성", "tier": "A", "mis": ["ΔS와 온도에도 의존한다.", "TΔS가 우세해진다.", "ΔG = ΔH - TΔS이다.", "TΔS 항 때문이다.", "ΔS와 온도에 따라 다르다."], "dx": "발열 반응이면 무조건 자발적이라고 본 경우다. 자발성은 ΔG = ΔH − TΔS로 정해져 엔트로피와 온도(TΔS 항)에도 좌우된다는 점을 놓치면 흡열인데 자발적인 반응을 설명하지 못한다.", "fix": "'발열 반응이라고 무조건 자발이 아님, 자발성은 ΔG = ΔH − TΔS로 엔트로피·온도(TΔS)에도 좌우'됨을 못 박는다. 흡열인데 자발적인 반응(엔트로피 증가)을 이로 설명하라.", "cite": ""}, "CH2-203": {"name": "온도와 자발성", "course": "ch2", "unit": "자발성", "tier": "C", "mis": ["TΔS 항 때문이다.", "전환 온도가 존재한다."], "dx": "온도가 TΔS 항을 통해 ΔG를 바꿔, 어떤 온도를 경계로 자발성이 뒤바뀔 수 있다는 점을 놓친 경우다. 온도의 역할이 약하면 전환 온도 개념으로 이어지지 못한다.", "fix": "'온도가 TΔS 항을 통해 ΔG를 바꿔, 어떤 온도를 경계로 자발성이 뒤바뀜'을 못 박는다. 온도의 역할을 잡아 전환 온도 개념으로 이어라.", "cite": ""}, "CH2-204": {"name": "ΔG 크기", "course": "ch2", "unit": "자발성", "tier": "C", "mis": ["음수가 자발이다."], "dx": "ΔG가 더 큰 음수일수록 더 자발적이라는 점을 놓친 경우다. ΔG 크기가 자발성의 정도를 나타낸다는 점이 약하면 두 반응의 자발성을 비교하지 못한다.", "fix": "'ΔG가 더 큰 음수일수록 더 자발적'임을 못 박는다. ΔG 크기가 자발성의 정도임을 잡아 두 반응의 자발성을 비교하라.", "cite": ""}, "CH2-207": {"name": "자발성과 속도", "course": "ch2", "unit": "자발성", "tier": "C", "mis": ["자발성과 속도는 다르다.", "속도와 무관하다.", "방향만 알려준다."], "dx": "자발성과 반응 속도를 같은 것으로 본 경우다. ΔG는 반응이 일어나는 방향만 알려줄 뿐 빠르기와는 무관하다는 점을 놓치면 자발적인데도 느린 반응(다이아몬드가 흑연으로 바뀌는 변화)을 설명하지 못한다.", "fix": "'자발성과 반응 속도는 다름, ΔG는 방향만 알려줄 뿐 빠르기와 무관'함을 못 박는다. 자발적인데도 느린 반응(다이아몬드가 흑연으로)을 이로 설명하라.", "cite": ""}, "CH2-208": {"name": "전환 온도", "course": "ch2", "unit": "자발성", "tier": "C", "mis": ["ΔG = 0인 온도이다.", "경계 온도이다."], "dx": "전환 온도가 ΔG = 0이 되는 온도라 그 위아래로 자발성이 뒤바뀌는 경계라는 점을 놓친 경우다. 이 경계 온도가 약하면 언제부터 반응이 자발적이 되는지 못 구한다.", "fix": "전환 온도를 'ΔG = 0이 되는 온도라 그 위아래로 자발성이 뒤바뀌는 경계'로 못 박는다. ΔG=0으로 두고 언제부터 자발적이 되는지 구하라.", "cite": ""}, "CH2-296": {"name": "중화 반응", "course": "ch2", "unit": "적정", "tier": "C", "mis": ["염과 물을 만든다.", "H⁺와 OH⁻가 물을 만든다.", "산과 염기이다."], "dx": "중화 반응이 산과 염기가 만나 염과 물을 만드는 반응이라는 점을 놓친 경우다. 생성물이 흐리면 적정에서 일어나는 반응을 잘못 잡는다.", "fix": "중화 반응을 '산과 염기가 만나 염과 물을 만드는 반응'으로 못 박는다. 생성물을 염과 물로 잡아 적정에서 일어나는 반응을 바로 잡아라.", "cite": ""}, "CH2-297": {"name": "알짜 이온 반응", "course": "ch2", "unit": "적정", "tier": "C", "mis": ["H⁺와 OH⁻가 물을 만든다.", "참여 이온만 쓴다."], "dx": "중화의 알짜 이온 반응식이 H⁺ + OH⁻ → H₂O이고 구경꾼 이온은 빠진다는 점을 놓친 경우다. 참여 이온만 쓰는 규칙이 약하면 알짜식이 어긋난다.", "fix": "중화 알짜 이온식을 'H⁺ + OH⁻ → H₂O, 구경꾼 이온은 뺌'으로 못 박는다. 참여 이온만 쓰는 규칙으로 알짜식을 맞춰라.", "cite": ""}, "CH2-298": {"name": "중화열", "course": "ch2", "unit": "적정", "tier": "B", "mis": ["열을 방출한다.", "발열 반응이다."], "dx": "중화 반응이 발열이라 열을 방출한다는 점을 놓친 경우다. 중화가 발열이라는 점이 약하면 적정 중 온도 변화나 중화열 문제를 못 짚는다.", "fix": "'중화 반응은 발열이라 열을 방출'함을 못 박는다. 중화가 발열임을 잡아 적정 중 온도 변화나 중화열 문제를 짚어라.", "cite": ""}, "CH2-299": {"name": "중화 양적 관계", "course": "ch2", "unit": "적정", "tier": "C", "mis": ["가수가 들어간다.", "몰수가 같다.", "부피가 들어간다."], "dx": "중화 양적 관계가 (산이 낸 H⁺ 몰수 = 염기가 낸 OH⁻ 몰수)이고 가수와 부피를 반영해야 한다는 점을 놓친 경우다. 가수를 빼먹으면 적정 계산이 어긋난다.", "fix": "중화 양적 관계를 '(산이 낸 H⁺ 몰수 = 염기가 낸 OH⁻ 몰수), 가수와 부피를 반영'으로 못 박는다. 가수를 빼먹지 말고 적정 계산을 하라.", "cite": ""}, "CH2-300": {"name": "적정 정의", "course": "ch2", "unit": "적정", "tier": "C", "mis": ["표준 용액이 필요하다.", "농도를 구한다.", "표준 용액이 기준이다."], "dx": "적정이 농도를 아는 표준 용액으로 모르는 산·염기의 농도를 중화 양론으로 구하는 방법이라는 점을 놓친 경우다. 이 원리가 약하면 적정 실험의 목적을 잘못 잡는다.", "fix": "적정을 '농도를 아는 표준 용액으로 모르는 산·염기의 농도를 중화 양론으로 구하는 방법'으로 못 박는다. 이 원리로 적정 실험의 목적을 잡아라.", "cite": ""}, "CH2-301": {"name": "표준 용액", "course": "ch2", "unit": "적정", "tier": "C", "mis": ["농도를 안다.", "농도가 기준이다.", "기준이 필요하다."], "dx": "표준 용액이 농도를 정확히 아는 기준 용액이라는 점을 놓친 경우다. 기준이 되는 까닭이 약하면 적정에서 미지 농도를 못 구한다.", "fix": "표준 용액을 '농도를 정확히 아는 기준 용액'으로 못 박는다. 기준이 되는 까닭을 잡아 적정에서 미지 농도를 구하라.", "cite": ""}, "CH2-302": {"name": "당량점", "course": "ch2", "unit": "적정", "tier": "C", "mis": ["몰수가 같다.", "완전히 중화된다."], "dx": "당량점이 산과 염기의 몰수(가수 반영)가 같아져 완전히 중화된 지점이라는 점을 놓친 경우다. 당량점의 정의가 약하면 적정 곡선에서 그 위치를 못 잡는다.", "fix": "당량점을 '산과 염기의 몰수(가수 반영)가 같아져 완전히 중화된 지점'으로 못 박는다. 당량점의 정의로 적정 곡선에서 그 위치를 잡아라.", "cite": ""}, "CH2-303": {"name": "적정 곡선", "course": "ch2", "unit": "적정", "tier": "C", "mis": ["부피-pH 그래프이다.", "pH 변화를 나타낸다.", "pH 도약이 있다."], "dx": "적정 곡선이 가한 부피에 따른 pH 그래프이고 당량점 부근에서 pH가 급격히 도약한다는 점을 놓친 경우다. 곡선의 모양이 약하면 도약으로 당량점을 못 찾는다.", "fix": "적정 곡선을 '가한 부피에 따른 pH 그래프이고 당량점 부근에서 pH가 급격히 도약'으로 못 박는다. 곡선의 모양으로 도약에서 당량점을 찾아라.", "cite": ""}, "CH2-304": {"name": "강산-강염기 당량점", "course": "ch2", "unit": "적정", "tier": "A", "mis": ["중성이다.", "가수분해하지 않는다."], "dx": "강산-강염기 적정의 당량점이 생긴 염이 가수분해하지 않아 중성(pH 7)이라는 점을 놓친 경우다. 이 기준이 약하면 어떤 지시약을 골라야 하는지 판단이 어긋난다.", "fix": "'강산-강염기 적정의 당량점은 생긴 염이 가수분해하지 않아 중성(pH 7)'임을 못 박는다. 이 기준으로 어떤 지시약을 골라야 하는지 판단하라.", "cite": ""}, "CH2-305": {"name": "약산-강염기 당량점", "course": "ch2", "unit": "적정", "tier": "C", "mis": ["짝염기가 가수분해한다."], "dx": "약산-강염기 적정의 당량점이 약산의 짝염기가 가수분해해 염기성(pH > 7)이 된다는 점을 놓친 경우다. 이걸 놓치면 당량점을 중성으로 잘못 보고 지시약을 틀리게 고른다.", "fix": "'약산-강염기 적정의 당량점은 약산의 짝염기가 가수분해해 염기성(pH > 7)'임을 못 박는다. 당량점을 중성으로 잘못 보지 말고 지시약을 바로 골라라.", "cite": ""}, "CH2-306": {"name": "강산-약염기 당량점", "course": "ch2", "unit": "적정", "tier": "C", "mis": ["짝산이 가수분해한다."], "dx": "강산-약염기 적정의 당량점이 약염기의 짝산이 가수분해해 산성(pH < 7)이 된다는 점을 놓친 경우다. 이걸 놓치면 당량점을 중성으로 잘못 보고 지시약을 틀리게 고른다.", "fix": "'강산-약염기 적정의 당량점은 약염기의 짝산이 가수분해해 산성(pH < 7)'임을 못 박는다. 당량점을 중성으로 잘못 보지 말고 지시약을 바로 골라라.", "cite": ""}, "CH2-307": {"name": "pH 도약", "course": "ch2", "unit": "적정", "tier": "C", "mis": ["pH 도약이 있다.", "당량점 부근이다."], "dx": "당량점 부근에서 적은 양을 더해도 pH가 크게 도약한다는 점을 놓친 경우다. 이 급변 구간이 약하면 당량점을 정확히 짚지 못한다.", "fix": "'당량점 부근에서 적은 양을 더해도 pH가 크게 도약'함을 못 박는다. 이 급변 구간으로 당량점을 정확히 짚어라.", "cite": ""}, "CH2-308": {"name": "지시약", "course": "ch2", "unit": "적정", "tier": "C", "mis": ["pH에 따라 변색한다.", "변색 범위가 있다."], "dx": "지시약이 특정 pH 범위(변색 범위)에서 색이 변한다는 점을 놓친 경우다. 변색 범위가 있다는 점이 약하면 지시약 선택의 기준을 못 잡는다.", "fix": "지시약을 '특정 pH 범위(변색 범위)에서 색이 변함'으로 못 박는다. 변색 범위가 있음을 잡아 지시약 선택의 기준으로 삼아라.", "cite": ""}, "CH2-309": {"name": "지시약 선택", "course": "ch2", "unit": "적정", "tier": "C", "mis": ["당량점이 염기성이다.", "pH 도약이 넓다.", "도약 구간에 맞춰야 한다."], "dx": "지시약을 고를 때 그 변색 범위가 적정 곡선의 pH 도약 구간 안에 들어야 한다는 점을 놓친 경우다. 도약에 안 맞는 지시약을 쓰면 종말점이 당량점에서 벗어나 오차가 커진다.", "fix": "지시약을 고를 때 '변색 범위가 적정 곡선의 pH 도약 구간 안에 들어야' 함을 못 박는다. 도약에 안 맞는 지시약을 쓰면 종말점이 당량점에서 벗어나 오차가 커짐을 잡아라.", "cite": ""}, "CH2-310": {"name": "페놀프탈레인", "course": "ch2", "unit": "적정", "tier": "C", "mis": ["염기성에서 분홍색이다.", "산성에서 무색이다."], "dx": "페놀프탈레인이 산성에서 무색, 염기성에서 분홍색이라는 점을 놓친 경우다. 변색 방향이 흐리면 색으로 액성·종말점을 잘못 읽는다.", "fix": "페놀프탈레인을 '산성에서 무색, 염기성에서 분홍색'으로 못 박는다. 변색 방향을 잡아 색으로 액성·종말점을 읽어라.", "cite": ""}, "CH2-311": {"name": "페놀프탈레인 범위", "course": "ch2", "unit": "적정", "tier": "C", "mis": ["염기성 범위이다.", "pH 8-10이다."], "dx": "페놀프탈레인의 변색 범위가 약 pH 8-10(염기성 쪽)이라는 점을 놓친 경우다. 이 범위가 약하면 약산-강염기 적정처럼 당량점이 염기성인 경우에 맞는 지시약인지 못 가린다.", "fix": "페놀프탈레인의 변색 범위를 '약 pH 8-10(염기성 쪽)'으로 못 박는다. 이 범위로 약산-강염기 적정처럼 당량점이 염기성인 경우에 맞는 지시약인지 가려라.", "cite": ""}, "CH2-312": {"name": "메틸 오렌지 범위", "course": "ch2", "unit": "적정", "tier": "C", "mis": ["산성 범위이다.", "pH 3-4.5이다."], "dx": "메틸 오렌지의 변색 범위가 약 pH 3-4.5(산성 쪽)라는 점을 놓친 경우다. 이 범위가 약하면 강산-약염기 적정처럼 당량점이 산성인 경우에 맞는 지시약인지 못 가린다.", "fix": "메틸 오렌지의 변색 범위를 '약 pH 3-4.5(산성 쪽)'로 못 박는다. 이 범위로 강산-약염기 적정처럼 당량점이 산성인 경우에 맞는 지시약인지 가려라.", "cite": ""}, "CH2-313": {"name": "지시약 역할", "course": "ch2", "unit": "적정", "tier": "C", "mis": ["농도가 아니라 당량점이다.", "색 변화로 종말점을 본다.", "다른 방법도 있다."], "dx": "지시약이 색 변화로 종말점을 알려 당량점을 찾게 해 준다는(농도를 직접 재는 게 아님) 점을 놓친 경우다. 지시약의 역할이 약하면 종말점과 당량점의 관계를 못 짚는다.", "fix": "지시약을 '색 변화로 종말점을 알려 당량점을 찾게 해 줌(농도를 직접 재는 게 아님)'으로 못 박는다. 지시약의 역할로 종말점과 당량점의 관계를 짚어라.", "cite": ""}, "CH2-314": {"name": "중화 부피", "course": "ch2", "unit": "적정-d", "tier": "C", "mis": ["몰수가 같다.", "몰수가 같아야 한다."], "dx": "중화에 필요한 부피를 산·염기 몰수가 같아지는 조건으로 구한다는 점을 놓친 경우다. 몰수 일치라는 기준이 약하면 적정에 쓰인 부피를 못 구한다.", "fix": "중화에 필요한 부피를 '산·염기 몰수가 같아지는 조건'으로 구한다. 몰수 일치를 기준으로 적정에 쓰인 부피를 구하라.", "cite": ""}, "CH2-315": {"name": "중화 양론", "course": "ch2", "unit": "적정-d", "tier": "C", "mis": ["H⁺ 1몰 = OH⁻ 1몰이다.", "OH⁻ 몰수를 맞춰야 한다.", "가수를 반영한다."], "dx": "중화 양론이 H⁺ 몰수와 OH⁻ 몰수를 같게 맞추는 것이고 다가 산·염기는 가수를 반영해야 한다는 점을 놓친 경우다. 가수를 빼먹으면 중화량 계산이 어긋난다.", "fix": "중화 양론을 'H⁺ 몰수와 OH⁻ 몰수를 같게 맞춤, 다가 산·염기는 가수를 반영'으로 못 박는다. 가수를 빼먹지 말고 중화량을 계산하라.", "cite": ""}, "CH2-316": {"name": "완전 중화 조건", "course": "ch2", "unit": "적정-d", "tier": "C", "mis": ["몰수가 같아야 한다."], "dx": "완전 중화가 산과 염기의 몰수가 같아 남는 것이 없는 상태라는 점을 놓친 경우다. 이 조건이 약하면 당량점을 잘못 잡는다.", "fix": "완전 중화를 '산과 염기의 몰수가 같아 남는 것이 없는 상태'로 못 박는다. 이 조건으로 당량점을 잡아라.", "cite": ""}, "CH2-317": {"name": "당량점 위치", "course": "ch2", "unit": "적정-d", "tier": "C", "mis": ["급변 구간이다.", "도약 구간 중간이다."], "dx": "당량점이 적정 곡선에서 pH가 급변하는 도약 구간의 중간에 있다는 점을 놓친 경우다. 위치를 잘못 잡으면 당량점 pH와 지시약 선택이 어긋난다.", "fix": "당량점을 '적정 곡선에서 pH가 급변하는 도약 구간의 중간'으로 못 박는다. 위치를 바로 잡아 당량점 pH와 지시약 선택을 맞춰라.", "cite": ""}, "CH2-318": {"name": "완충 영역", "course": "ch2", "unit": "적정-d", "tier": "C", "mis": ["완충 작용을 한다.", "약산과 짝염기가 공존한다.", "약산과 짝염기가 필요하다."], "dx": "적정 곡선에서 당량점 전, 약산과 짝염기가 함께 있는 완충 영역이 있어 pH가 천천히 변한다는 점을 놓친 경우다. 이 영역이 약하면 적정 곡선의 완만한 구간을 설명하지 못한다.", "fix": "'적정 곡선에서 당량점 전, 약산과 짝염기가 함께 있는 완충 영역이 있어 pH가 천천히 변함'을 못 박는다. 이 영역으로 적정 곡선의 완만한 구간을 설명하라.", "cite": ""}, "CH2-319": {"name": "종말점과 당량점", "course": "ch2", "unit": "적정-d", "tier": "C", "mis": ["가까우면 충분하다.", "가까워야 한다."], "dx": "종말점(지시약이 변하는 점)이 당량점과 가까워야 적정 오차가 작다는 점을 놓친 경우다. 둘의 차이가 크면 측정 농도가 어긋난다는 점이 약하면 지시약 선택의 중요성을 못 짚는다.", "fix": "'종말점(지시약이 변하는 점)이 당량점과 가까워야 적정 오차가 작음'을 못 박는다. 둘의 차이가 크면 측정 농도가 어긋남을 잡아 지시약 선택의 중요성을 짚어라.", "cite": ""}, "GC-136": {"name": "브뢴스테드-라우리", "course": "gc", "unit": "산염기평형-1", "tier": "B", "mis": ["받는 것은 염기이다.", "주는 것은 산이다.", "전자 이동은 산화환원이다.", "OH⁻ 방출은 아레니우스 염기 개념이다."], "dx": "브뢴스테드-라우리 정의에서 산은 양성자(H⁺)를 주고 염기는 받는다는 대응을 헷갈린 경우다. 전자를 주고받는 산화환원과 혼동한 점이 보인다.", "fix": "브뢴스테드-라우리를 '산은 양성자(H⁺)를 주고 염기는 받음'으로 못 박는다. 전자를 주고받는 산화환원과 혼동 말고 양성자 이동으로 보라.", "cite": ""}, "GC-137": {"name": "짝산-짝염기", "course": "gc", "unit": "산염기평형-1", "tier": "C", "mis": ["받는 것이 아니라 잃는 것이다.", "양성자 하나 차이이다.", "세기는 반대로 대응한다."], "dx": "짝산·짝염기가 양성자 하나 차이로 이어지고(산이 H⁺를 잃으면 짝염기), 세기는 반대로 대응한다(강산의 짝염기는 약함)는 점을 놓친 경우다.", "fix": "짝산·짝염기를 '양성자 하나 차이로 이어지고(산이 H⁺를 잃으면 짝염기) 세기는 반대(강산의 짝염기는 약함)'로 못 박는다. 세기 반비례를 잡아라.", "cite": ""}, "GC-138": {"name": "양쪽성", "course": "gc", "unit": "산염기평형-1", "tier": "C", "mis": ["두 역할을 모두 할 수 있다.", "염기로도 작용한다.", "산으로도 작용한다."], "dx": "양쪽성 물질이 조건에 따라 산으로도 염기로도 작용한다는 점을 놓친 경우다. 물·HCO₃⁻처럼 양성자를 주기도 받기도 한다는 그림이 약하다.", "fix": "양쪽성 물질을 '조건에 따라 산으로도 염기로도 작용'으로 못 박는다. 물·HCO₃⁻처럼 양성자를 주기도 받기도 함을 그려라.", "cite": ""}, "GC-139": {"name": "pH·pOH 정의", "course": "gc", "unit": "산염기평형-1", "tier": "C", "mis": ["두 정의가 뒤바뀌었다.", "음의 부호가 빠졌다.", "음의 로그 관계이다."], "dx": "pH = -log[H⁺], pOH = -log[OH⁻]라는 정의를 헷갈린 경우다. 음의 로그라는 부호와 두 정의의 대상이 뒤섞였다.", "fix": "pH·pOH를 'pH = -log[H⁺], pOH = -log[OH⁻]'로 못 박는다. 음의 로그라는 부호와 두 정의의 대상을 갈라라.", "cite": ""}, "GC-140": {"name": "pH+pOH", "course": "gc", "unit": "산염기평형-1", "tier": "C", "mis": ["합은 14이다.", "Kw가 온도에 따라 변한다.", "합이 14가 되어야 한다."], "dx": "25°C에서 pH + pOH = 14가 물 이온곱에서 나온다는 점을 놓친 경우다. 이 14는 온도에 따라 변한다(물 이온곱이 온도 의존)는 점이 약하다.", "fix": "'25°C에서 pH + pOH = 14가 물 이온곱에서 나옴'을 못 박는다. 이 14는 온도에 따라 변함(물 이온곱이 온도 의존)을 잡아라.", "cite": ""}, "GC-141": {"name": "물 이온곱", "course": "gc", "unit": "산염기평형-1", "tier": "C", "mis": ["Kw는 10^-14이다.", "합이 아니라 곱이다.", "중성에서는 10^-7이다."], "dx": "물 이온곱이 [H⁺]와 [OH⁻]의 곱(25°C에서 10⁻¹⁴)이고 합이 아니라는 점을 놓친 경우다. 중성에서 각 농도가 10⁻⁷이라는 점이 흔들린다.", "fix": "물 이온곱을 '[H⁺]와 [OH⁻]의 곱(25°C에서 10⁻¹⁴), 합이 아님'으로 못 박는다. 중성에서 각 농도가 10⁻⁷임을 잡아라.", "cite": ""}, "GC-142": {"name": "중성 pH", "course": "gc", "unit": "산염기평형-1", "tier": "C", "mis": ["두 농도가 같아야 중성이다.", "Kw가 온도에 의존한다.", "중성은 pH 7이다."], "dx": "중성이 [H⁺]=[OH⁻]인 상태라는 정의를 놓친 경우다. pH 7은 25°C에서만 중성이고, 물 이온곱이 온도에 의존해 중성 pH가 달라진다는 점이 약하다.", "fix": "중성을 '[H⁺]=[OH⁻]인 상태'로 못 박는다. pH 7은 25°C에서만 중성이고 물 이온곱이 온도에 의존해 중성 pH가 달라짐을 잡아라.", "cite": ""}, "GC-143": {"name": "산성 pH", "course": "gc", "unit": "산염기평형-1", "tier": "C", "mis": ["산성은 pH 7 미만이다.", "염기성은 pH 7 초과이다.", "수소 이온이 더 많다."], "dx": "산성·염기성의 pH 기준을 헷갈린 경우다. 25°C에서 pH<7이 산성([H⁺]가 더 많음), pH>7이 염기성이라는 대응이 흔들린다.", "fix": "'25°C에서 pH<7이 산성([H⁺]가 더 많음), pH>7이 염기성'임을 못 박는다. pH 기준으로 액성을 가려라.", "cite": ""}, "GC-144": {"name": "이온화 상수", "course": "gc", "unit": "산염기평형-1", "tier": "C", "mis": ["염기는 Kb로 나타낸다.", "산은 Ka로 나타낸다.", "온도에 의존한다."], "dx": "산의 세기는 산 이온화 상수 Kₐ로, 염기의 세기는 염기 이온화 상수로 나타내며 온도에 의존한다는 점을 놓친 경우다.", "fix": "'산의 세기는 Kₐ로, 염기의 세기는 염기 이온화 상수로 나타내며 온도에 의존'함을 못 박는다. 세기를 이온화 상수로 정량화하라.", "cite": ""}, "GC-145": {"name": "Ka와 세기", "course": "gc", "unit": "산염기평형-1", "tier": "C", "mis": ["Ka가 크면 강하다.", "Ka가 작으면 약하다.", "이온화가 덜 된다."], "dx": "Kₐ가 클수록 더 많이 이온화하는 강한 산이라는 대응을 놓친 경우다. Kₐ가 작으면 약산(이온화가 덜 됨)이라는 방향이 흔들린다.", "fix": "'Kₐ가 클수록 더 많이 이온화하는 강한 산, 작으면 약산(이온화 덜 됨)'임을 못 박는다. Kₐ 크기로 산 세기를 가려라.", "cite": ""}, "GC-146": {"name": "강산 pH", "course": "gc", "unit": "산염기평형-1", "tier": "C", "mis": ["부분 이온화는 약산이다.", "강산은 이온화도가 크다.", "완전 이온화 때문이다."], "dx": "강산이 물에서 거의 완전히 이온화한다는 점을 놓친 경우다. 부분 이온화는 약산이라는 구분이 흔들려 강산 pH 계산이 막힌다.", "fix": "강산을 '물에서 거의 완전히 이온화'로 못 박는다. 부분 이온화는 약산임을 갈라 강산 pH를 계산하라.", "cite": ""}, "GC-147": {"name": "약산 근사", "course": "gc", "unit": "산염기평형-1", "tier": "C", "mis": ["완전 이온화는 강산이다.", "일부만 이온화한다.", "이온화가 덜 된다."], "dx": "약산이 일부만 이온화해 평형을 이룬다는 점, 그래서 근사(이온화 적음)를 쓴다는 점을 놓친 경우다. 완전 이온화는 강산이라는 구분이 약하다.", "fix": "약산을 '일부만 이온화해 평형을 이루고, 그래서 이온화 적음 근사를 씀'으로 못 박는다. 완전 이온화는 강산임을 갈라라.", "cite": ""}, "GC-148": {"name": "Ka·Kb 관계", "course": "gc", "unit": "산염기평형-2", "tier": "A", "mis": ["곱은 Kw이다.", "곱이 Kw로 일정하다.", "합은 14이다.", "세기가 반대로 대응한다.", "곱이 아니라 나눗셈이다.", "짝 관계여야 한다."], "dx": "짝산·짝염기의 이온화 상수 곱이 물 이온곱(=[H⁺][OH⁻])으로 일정하다는 관계(Kₐ × 짝염기 상수 = 물 이온곱)를 놓친 경우다. 합이 14인 것과 혼동했다.", "fix": "'짝산·짝염기의 이온화 상수 곱이 물 이온곱(=[H⁺][OH⁻])으로 일정(Kₐ × 짝염기 상수 = 물 이온곱)'임을 못 박는다. 합이 14인 것과 혼동 말고 곱으로 잡아라.", "cite": ""}, "GC-149": {"name": "pKa", "course": "gc", "unit": "산염기평형-2", "tier": "C", "mis": ["강산은 pKa가 작다.", "음의 부호가 빠졌다.", "pKa가 작으면 강하다."], "dx": "pKₐ = -log Kₐ라 강산일수록 pKₐ가 작다는 대응을 놓친 경우다. 음의 로그라는 부호 때문에 Kₐ와 pKₐ의 크기 방향이 반대라는 점이 흔들린다.", "fix": "pKₐ를 'pKₐ = -log Kₐ라 강산일수록 pKₐ가 작음'으로 못 박는다. 음의 로그라 Kₐ와 pKₐ의 크기 방향이 반대임을 잡아라.", "cite": ""}, "GC-150": {"name": "완충 용액", "course": "gc", "unit": "산염기평형-2", "tier": "C", "mis": ["강산·강염기로는 완충이 안 된다.", "짝염기 성분도 필요하다.", "양쪽 성분이 함께 있어야 한다."], "dx": "완충 용액이 약산과 그 짝염기(또는 약염기와 짝산)가 함께 있어야 만들어진다는 점을 놓친 경우다. 강산·강염기만으로는 완충이 안 된다는 점이 약하다.", "fix": "완충 용액을 '약산과 그 짝염기(또는 약염기와 짝산)가 함께 있어야 만들어짐'으로 못 박는다. 강산·강염기만으로는 완충이 안 됨을 잡아라.", "cite": ""}, "GC-151": {"name": "완충 작용", "course": "gc", "unit": "산염기평형-2", "tier": "C", "mis": ["변화를 흡수하기 때문이다.", "짝염기가 H⁺를 흡수한다.", "완충 능력에는 한계가 있다."], "dx": "완충이 외부에서 들어온 H⁺를 짝염기가, OH⁻를 약산이 흡수해 pH 변화를 줄인다는 메커니즘을 놓친 경우다. 완충 능력에 한계가 있다는 점도 약하다.", "fix": "완충 작용을 '외부에서 들어온 H⁺를 짝염기가, OH⁻를 약산이 흡수해 pH 변화를 줄임'으로 못 박는다. 완충 능력에 한계가 있음도 잡아라.", "cite": ""}, "GC-152": {"name": "헨더슨-하셀바흐", "course": "gc", "unit": "산염기평형-2", "tier": "C", "mis": ["pKa이지 7이 아니다.", "분자와 분모가 뒤바뀌었다.", "로그 항이 양수이다."], "dx": "헨더슨-하셀바흐 식에서 pH = pKₐ + log([짝염기]/[산])이라는 구조를 헷갈린 경우다. 기준이 7이 아니라 pKₐ이고 분자·분모(짝염기/산)가 뒤바뀌기 쉽다.", "fix": "헨더슨-하셀바흐를 'pH = pKₐ + log([짝염기]/[산])'로 못 박는다. 기준이 7이 아니라 pKₐ임을 잡고 분자·분모(짝염기/산)를 뒤바꾸지 마라.", "cite": ""}, "GC-154": {"name": "염 가수분해", "course": "gc", "unit": "산염기평형-2", "tier": "A", "mis": ["아세트산 이온이 가수분해해 염기성이다.", "NH₄+가 가수분해해 산성이다.", "NH₄+의 가수분해 때문이다.", "두 이온 모두 가수분해하지 않는다.", "아세트산 이온이 가수분해한다.", "H⁺를 내놓아 산성이 된다."], "dx": "염을 이루는 이온의 가수분해로 액성이 갈린다는 점을 놓친 경우다. 아세트산 이온은 가수분해해 염기성, NH₄⁺는 가수분해해 산성이 된다는 대응이 흔들린다.", "fix": "'염을 이루는 이온의 가수분해로 액성이 갈림'을 못 박는다. 아세트산 이온은 가수분해해 염기성, NH₄⁺는 가수분해해 산성이 됨을 잡아라.", "cite": ""}, "GC-155": {"name": "중화 반응", "course": "gc", "unit": "산염기평형-2", "tier": "C", "mis": ["물이 생성되는 반응이다.", "H⁺ + OH⁻ → H₂O이다.", "산 + 염기 → 염 + 물이다."], "dx": "중화 반응의 알짜 변화가 H⁺ + OH⁻ → H₂O이고 산+염기 → 염+물이라는 틀을 놓친 경우다.", "fix": "중화 반응을 '알짜 변화가 H⁺ + OH⁻ → H₂O, 산+염기 → 염+물'로 못 박는다. 이 틀로 중화 반응식을 잡아라.", "cite": ""}, "GC-156": {"name": "적정 곡선", "course": "gc", "unit": "산염기평형-2", "tier": "C", "mis": ["짝염기가 가수분해해 염기성이다.", "생성된 염이 중성이다.", "생성된 염이 산성이다."], "dx": "적정 당량점의 액성이 생성된 염의 가수분해로 정해진다는 점을 놓친 경우다. 약산+강염기 적정은 짝염기 가수분해로 당량점이 염기성이 된다는 대응이 흔들린다.", "fix": "'적정 당량점의 액성은 생성된 염의 가수분해로 정해짐'을 못 박는다. 약산+강염기 적정은 짝염기 가수분해로 당량점이 염기성이 됨을 잡아라.", "cite": ""}, "GC-157": {"name": "pH 정의", "course": "gc", "unit": "산염기평형-2", "tier": "C", "mis": ["[OH⁻] 기준은 pOH이다.", "음의 로그 관계이다.", "정비례가 아니라 로그 관계이다."], "dx": "pH가 [H⁺] 기준의 음의 로그이고 [OH⁻] 기준은 pOH라는 구분을 놓친 경우다. 정비례가 아니라 로그 관계라는 점이 약하다.", "fix": "pH를 '[H⁺] 기준의 음의 로그이고 [OH⁻] 기준은 pOH'로 못 박는다. 정비례가 아니라 로그 관계임을 잡아라.", "cite": ""}, "GC-011": {"name": "원자 구성", "course": "gc", "unit": "원자", "tier": "C", "mis": ["전자는 핵 바깥에 있다.", "전자 질량은 무시할 만큼 작다.", "전자는 핵 주위에 있다."], "dx": "원자의 구성 입자 배치를 헷갈린 경우다. 전자는 핵 바깥, 질량은 핵(양성자·중성자)에 거의 다 있다는 그림이 흐리다.", "fix": "원자 구성을 '전자는 핵 바깥, 질량은 핵(양성자·중성자)에 거의 다'로 못 박는다. 이 배치로 질량과 전하가 어디에 있는지 그려라.", "cite": ""}, "GC-012": {"name": "원자 번호", "course": "gc", "unit": "원자", "tier": "B", "mis": ["중성자 수와는 무관하다.", "질량수는 양성자+중성자이다.", "양성자 수가 같으면 같은 원소이다.", "중성자 수가 달라도 같은 원소일 수 있다."], "dx": "원자번호=양성자 수라는 정의와 질량수(양성자+중성자)를 섞은 경우다. 원자번호가 원소를 결정한다는 점이 빠지면 동위원소에서 막힌다.", "fix": "원자번호를 '양성자 수(원소를 결정), 질량수(양성자+중성자)와 별개'로 못 박는다. 원자번호가 원소 정체임을 잡아 동위원소를 다뤄라.", "cite": ""}, "GC-013": {"name": "질량수", "course": "gc", "unit": "원자", "tier": "A", "mis": ["전자는 질량수에 포함되지 않는다.", "중성자 수가 빠졌다.", "양성자 수가 빠졌다.", "질량수는 핵자 수만으로 정해진다.", "중성자=질량수-양성자(원자 번호)이다.", "원자량은 존재비 가중 평균이다."], "dx": "질량수에 전자를 포함하거나 중성자를 빠뜨린 경우다. 질량수=양성자+중성자(전자 제외)라는 셈이 흔들린다.", "fix": "질량수를 '양성자 + 중성자(전자 제외)'로 못 박는다. 전자를 넣거나 중성자를 빼지 말고 두 핵 입자만 더하라.", "cite": ""}, "GC-014": {"name": "동위원소", "course": "gc", "unit": "원자", "tier": "B", "mis": ["전자 배치가 같아 성질이 비슷하다.", "양성자 수가 다르면 다른 원소이다.", "중성자 수 차이가 동위원소를 만든다.", "중성자 수가 달라 질량수도 다르다."], "dx": "동위원소를 양성자 수가 다른 것으로 오해하거나, 질량수만 다를 뿐 전자 배치·화학적 성질은 같다는 점을 놓친 경우다.", "fix": "동위원소를 '양성자 수는 같고 질량수(중성자)만 다름, 전자 배치·화학적 성질은 같음'으로 못 박는다. 양성자가 다른 것으로 오해 마라.", "cite": ""}, "GC-015": {"name": "원자량", "course": "gc", "unit": "원자", "tier": "C", "mis": ["한 동위원소가 아니라 평균이다.", "존재비 가중 평균은 소수가 된다.", "흔한 동위원소가 더 큰 비중을 가진다."], "dx": "원자량을 한 동위원소의 질량으로 본 경우다. 존재비로 가중평균한 값이라 보통 소수가 된다는 점이 빠졌다.", "fix": "원자량을 '존재비로 가중평균한 값이라 보통 소수'로 못 박는다. 한 동위원소의 질량으로 보지 말고 존재비를 곱해 평균하라.", "cite": ""}, "GC-016": {"name": "전하 균형", "course": "gc", "unit": "원자", "tier": "C", "mis": ["중성자 수와는 무관하다.", "양성자 수는 변하지 않는다.", "전자를 얻어 -전하를 띤다."], "dx": "중성 원자에서 양성자 수=전자 수라는 균형을 놓친 경우다. 이온이 될 때 변하는 건 전자 수이지 양성자 수가 아니라는 점이 흔들린다.", "fix": "'중성 원자는 양성자 수 = 전자 수, 이온이 될 때 변하는 건 전자 수(양성자 불변)'임을 못 박는다. 이온식·산화수의 토대로 삼아라.", "cite": ""}, "GC-017": {"name": "입자 질량", "course": "gc", "unit": "원자", "tier": "B", "mis": ["전자는 양성자보다 매우 가볍다.", "전자 질량은 약 1/1836이다.", "전자는 매우 가볍다.", "둘의 질량은 거의 같다."], "dx": "전자 질량을 양성자·중성자와 비슷하게 본 경우다. 전자는 약 1/1836로 매우 가벼워 원자 질량에 사실상 기여하지 않는다.", "fix": "'전자는 양성자·중성자의 약 1/1836로 매우 가벼워 원자 질량에 사실상 기여 안 함'을 못 박는다. 질량은 핵 입자로만 셈하라.", "cite": ""}, "GC-018": {"name": "입자 전하", "course": "gc", "unit": "원자", "tier": "C", "mis": ["중성자는 전기적으로 중성이다.", "전자는 음전하 입자이다.", "양성자는 +, 전자는 -이다."], "dx": "구성 입자의 전하를 헷갈린 경우다. 양성자(+)·전자(-)·중성자(0)의 부호가 정리되지 않았다.", "fix": "구성 입자 전하를 '양성자(+)·전자(−)·중성자(0)'로 못 박는다. 세 부호를 적어 두고 전하 계산에 써라.", "cite": ""}, "GC-001": {"name": "SI 단위", "course": "gc", "unit": "기초지식", "tier": "C", "mis": ["질량의 SI 기본 단위는 g이 아니라 kg이다.", "SI 온도 기본 단위는 K이다.", "cm는 기본 단위가 아니라 유도된 단위이다."], "dx": "SI 기본 단위를 혼동한 경우다. 질량은 g이 아니라 kg, 온도는 ℃가 아니라 K가 기본 단위라는 점이 흔들린다.", "fix": "SI 기본 단위를 '질량은 kg(g 아님), 온도는 K(℃ 아님)'로 못 박는다. 기본 단위 목록을 적어 두고 계산 전 단위를 기본형으로 맞춰라.", "cite": ""}, "GC-002": {"name": "물질량 단위", "course": "gc", "unit": "기초지식", "tier": "A", "mis": ["질량 단위 g과 물질량 단위 mol을 혼동하면 안 된다.", "kg은 질량의 단위이다.", "아보가드로 수는 약 6.022×10^23이다.", "n = 질량/몰질량이다.", "표준 상태 몰부피는 22.4 L이다.", "몰수는 몰질량에 따라 달라진다."], "dx": "질량(g)과 물질량(mol)을 같은 '양'으로 뭉뚱그린 경우다. mol은 입자 수를 세는 단위라는 정체가 빠지면 이후 양적관계 전체가 흔들린다.", "fix": "mol을 '입자 수를 세는 단위(질량 g과 다른 양)'로 못 박는다. 질량·물질량을 갈라 두고 모든 양적관계를 mol을 축으로 세워라.", "cite": ""}, "GC-003": {"name": "접두사", "course": "gc", "unit": "기초지식", "tier": "B", "mis": ["10^-3은 milli이고 micro는 10^-6이다.", "10^-6은 micro이고 nano는 10^-9이다.", "kilo는 10^3이다.", "centi는 10^-2이다."], "dx": "SI 접두사의 지수를 헷갈린 경우다. milli(10⁻³)·micro(10⁻⁶)·nano(10⁻⁹)의 자릿수 간격이 정리되지 않았다.", "fix": "SI 접두사를 'milli(10⁻³)·micro(10⁻⁶)·nano(10⁻⁹)'로 자릿수까지 못 박는다. 세 칸 간격을 외워 두고 단위 환산에서 지수를 맞춰라.", "cite": ""}, "GC-004": {"name": "유효숫자", "course": "gc", "unit": "기초지식", "tier": "C", "mis": ["자릿값만 나타내므로 유효하지 않다.", "표기만으로는 측정 정밀도를 알 수 없다.", "두 개념은 별개이다."], "dx": "유효숫자를 '자릿값 표시'로만 보고 측정의 정밀도를 담는다는 의미를 놓친 경우다. 어떤 0이 유효한지의 판단이 흔들린다.", "fix": "유효숫자를 '측정의 정밀도를 담는 자리(단순 자릿값 표시가 아님)'로 못 박는다. 앞의 0은 무효·중간과 뒤의 0은 유효라는 판단 규칙으로 어떤 0이 유효한지 가려라.", "cite": ""}, "GC-005": {"name": "유효숫자 연산", "course": "gc", "unit": "기초지식", "tier": "C", "mis": ["가장 적은 자릿수가 결과를 제한한다.", "가장 적은 유효숫자가 기준이다.", "소수 자릿수 기준은 덧·뺄셈이다."], "dx": "곱셈·나눗셈은 가장 적은 유효숫자, 덧셈·뺄셈은 가장 적은 소수 자릿수가 결과를 제한한다는 두 규칙을 섞은 경우다.", "fix": "'곱셈·나눗셈은 가장 적은 유효숫자, 덧셈·뺄셈은 가장 적은 소수 자릿수'로 두 규칙을 갈라 못 박는다. 연산 종류를 먼저 보고 맞는 규칙을 적용하라.", "cite": ""}, "GC-006": {"name": "정확한 수", "course": "gc", "unit": "기초지식", "tier": "C", "mis": ["정확한 수는 결과를 제한하지 않는다.", "정의값은 측정값이 아니다.", "무한대 유효숫자로 취급된다."], "dx": "정의값·셈값 같은 정확한 수는 유효숫자 제한을 받지 않는다는 점을 놓친 경우다. 측정값과 정확한 수를 같이 취급하면 자릿수가 틀린다.", "fix": "'정의값·셈값 같은 정확한 수는 유효숫자 제한을 받지 않음'을 못 박는다. 측정값과 정확한 수를 갈라 자릿수 제한은 측정값에만 걸어라.", "cite": ""}, "GC-007": {"name": "정확도·정밀도", "course": "gc", "unit": "기초지식", "tier": "A", "mis": ["계통 오차가 있으면 정밀해도 부정확하다.", "참값 근접성과 재현성은 별개이다.", "치우침은 정확도 문제이다.", "흩어짐은 정밀도 문제이다.", "치우침은 반복 평균으로 사라지지 않는다.", "서로 일치하는 정도는 정밀도이다."], "dx": "정확도(참값 근접)와 정밀도(재현성)를 한 덩어리로 본 경우다. 계통 오차가 있으면 정밀해도 부정확할 수 있다는 구분이 빠졌다.", "fix": "'정확도 = 참값 근접, 정밀도 = 재현성'으로 갈라 못 박는다. 계통 오차가 있으면 정밀해도 부정확할 수 있음을 잡아 둘을 따로 평가하라.", "cite": ""}, "GC-008": {"name": "밀도", "course": "gc", "unit": "기초지식", "tier": "C", "mis": ["분자·분모를 바꾸면 안 된다.", "질량과 부피가 비례해 밀도는 일정하다.", "밀도가 크면 가라앉는다."], "dx": "밀도를 질량/부피의 고정된 비로 다루지 못한 경우다. 분자·분모를 뒤집거나 단위 처리에서 막힌다.", "fix": "밀도를 '질량 ÷ 부피의 고정된 비'로 못 박는다. 분자·분모를 뒤집지 말고 단위를 약분해 따라가며 밀도를 다뤄라.", "cite": ""}, "GC-009": {"name": "온도 환산", "course": "gc", "unit": "기초지식", "tier": "B", "mis": ["부호가 반대이다.", "0℃는 약 273 K이다.", "간격이 같고 기준점만 다르다.", "0 K보다 낮은 온도는 없다."], "dx": "℃와 K 환산에서 막힌 경우다. 둘은 눈금 간격이 같고 0점만 273.15 차이라는 점이 흔들린다.", "fix": "'℃와 K는 눈금 간격이 같고 0점만 273.15 차이'임을 못 박는다. K = ℃ + 273.15로 더하거나 빼 환산하라.", "cite": ""}, "GC-010": {"name": "차원 분석", "course": "gc", "unit": "기초지식", "tier": "C", "mis": ["더하는 것이 아니라 곱한다.", "같은 양의 다른 표현이라 값이 1이다.", "단위 연산이 차원 분석의 핵심이다."], "dx": "단위환산을 더하기로 처리하거나, 환산인자가 값 1인 같은 양의 다른 표현임을 놓친 경우다. 단위를 약분해 따라가는 습관이 안 잡혔다.", "fix": "차원 분석을 '환산인자는 값이 1인 같은 양의 다른 표현, 단위를 약분해 따라감'으로 못 박는다. 더하기로 처리 말고 곱해 단위를 약분하라.", "cite": ""}, "GC-200": {"name": "배위 착물", "course": "gc", "unit": "배위화학-1", "tier": "C", "mis": ["중심 금속이 있어야 한다.", "금속이 중심이 된다.", "리간드가 결합한다."], "dx": "배위 착물이 중심 금속에 리간드가 배위 결합한 화합물이라는 구조를 놓친 경우다. 금속이 중심, 리간드가 둘러싼다는 골격이 약하다.", "fix": "배위 착물을 '중심 금속에 리간드가 배위 결합한 화합물'로 못 박는다. 금속이 중심, 리간드가 둘러싼다는 골격을 잡아라.", "cite": ""}, "GC-201": {"name": "중심 금속", "course": "gc", "unit": "배위화학-1", "tier": "C", "mis": ["전자쌍을 받는다.", "받는 쪽이다.", "전이 금속이 중심이 된다."], "dx": "중심 금속(주로 전이 금속)이 리간드의 전자쌍을 받는 쪽(루이스 산)이라는 점을 놓친 경우다. 받는 역할이라는 점이 흔들린다.", "fix": "중심 금속을 '주로 전이 금속, 리간드의 전자쌍을 받는 쪽(루이스 산)'으로 못 박는다. 받는 역할임을 잡아라.", "cite": ""}, "GC-202": {"name": "리간드", "course": "gc", "unit": "배위화학-1", "tier": "C", "mis": ["전자쌍을 주는 쪽이다.", "배위 결합은 전자쌍 제공이다.", "그 전자쌍으로 배위한다."], "dx": "리간드가 전자쌍을 주는 쪽(루이스 염기)이고 그 전자쌍으로 배위한다는 점을 놓친 경우다. 주개 원자가 비공유 전자쌍을 낸다는 그림이 약하다.", "fix": "리간드를 '전자쌍을 주는 쪽(루이스 염기)이고 그 전자쌍으로 배위'로 못 박는다. 주개 원자가 비공유 전자쌍을 냄을 그려라.", "cite": ""}, "GC-203": {"name": "배위 결합", "course": "gc", "unit": "배위화학-1", "tier": "C", "mis": ["전자쌍을 한쪽이 모두 낸다.", "리간드가 전자쌍을 준다.", "전자를 공유한다."], "dx": "배위 결합이 한쪽(리간드)이 전자쌍을 모두 내어 공유하는 결합이라는 점을 놓친 경우다. 일반 공유 결합과 전자쌍 출처가 다르다는 점이 흔들린다.", "fix": "배위 결합을 '한쪽(리간드)이 전자쌍을 모두 내어 공유하는 결합'으로 못 박는다. 일반 공유 결합과 전자쌍 출처가 다름을 잡아라.", "cite": ""}, "GC-204": {"name": "배위수", "course": "gc", "unit": "배위화학-1", "tier": "C", "mis": ["4와 6이 가장 흔하다.", "한 분자가 여러 자리를 차지할 수 있다.", "팔면체로 배열된다."], "dx": "배위수가 중심 금속에 직접 결합한 주개 원자 수이고 4·6이 흔하다는 점을 놓친 경우다. 한 리간드가 여러 자리를 차지할 수 있다는 점이 약하다.", "fix": "배위수를 '중심 금속에 직접 결합한 주개 원자 수, 4·6이 흔함'으로 못 박는다. 한 리간드가 여러 자리를 차지할 수 있음을 잡아라.", "cite": ""}, "GC-205": {"name": "한자리 리간드", "course": "gc", "unit": "배위화학-1", "tier": "C", "mis": ["결합점이 하나이다.", "주개 원자가 질소 하나이다."], "dx": "한자리 리간드가 결합점(주개 원자) 하나로 배위한다는 점을 놓친 경우다. 결합점 수가 리간드 분류 기준이라는 점이 흔들린다.", "fix": "한자리 리간드를 '결합점(주개 원자) 하나로 배위'로 못 박는다. 결합점 수가 리간드 분류 기준임을 잡아라.", "cite": ""}, "GC-206": {"name": "여러자리 리간드", "course": "gc", "unit": "배위화학-1", "tier": "C", "mis": ["여러 자리에서 배위한다.", "여러 결합점을 가진다.", "결합점 수가 다르다."], "dx": "여러자리 리간드가 한 분자에 결합점이 여럿이라 여러 자리에서 동시에 배위한다는 점을 놓친 경우다.", "fix": "여러자리 리간드를 '한 분자에 결합점이 여럿이라 여러 자리에서 동시에 배위'로 못 박는다. 결합점 수로 한자리와 갈라라.", "cite": ""}, "GC-207": {"name": "킬레이트 효과", "course": "gc", "unit": "배위화학-1", "tier": "C", "mis": ["킬레이트 효과로 안정해진다.", "여러 점 결합이 안정성을 높인다.", "더 안정하기 때문이다."], "dx": "여러자리 리간드가 금속을 집게처럼 무는(킬레이트) 착물이 한자리 여럿보다 더 안정하다는 킬레이트 효과를 놓친 경우다. 엔트로피 이득이 안정성의 뿌리라는 점이 약하다.", "fix": "킬레이트 효과를 '여러자리 리간드가 금속을 집게처럼 무는 착물이 한자리 여럿보다 더 안정'으로 못 박는다. 엔트로피 이득이 안정성의 뿌리임을 잡아라.", "cite": ""}, "GC-208": {"name": "이성질체", "course": "gc", "unit": "배위화학-1", "tier": "C", "mis": ["구조·입체 이성질이 가능하다.", "배열이 다를 수 있다.", "결합 방식 차이와 배열 차이로 구분된다."], "dx": "배위 착물의 이성질이 구조 이성질(결합 방식 차이)과 입체 이성질(공간 배열 차이)로 나뉜다는 점을 놓친 경우다.", "fix": "배위 착물의 이성질을 '구조 이성질(결합 방식 차이)과 입체 이성질(공간 배열 차이)'로 나눠 못 박는다. 두 갈래로 이성질을 분류하라.", "cite": ""}, "GC-209": {"name": "기하 이성질체", "course": "gc", "unit": "배위화학-1", "tier": "C", "mis": ["정의가 뒤바뀌었다.", "결합 순서는 같다.", "배열 차이가 성질을 바꾼다."], "dx": "기하 이성질이 결합 순서는 같고 리간드의 공간 배열(cis·trans)이 달라 성질이 바뀌는 것이라는 점을 놓친 경우다. 정의가 광학 이성질과 뒤섞였다.", "fix": "기하 이성질을 '결합 순서는 같고 리간드의 공간 배열(cis·trans)이 달라 성질이 바뀜'으로 못 박는다. 광학 이성질과 갈라 정의하라.", "cite": ""}, "GC-210": {"name": "광학 이성질체", "course": "gc", "unit": "배위화학-1", "tier": "C", "mis": ["포개지면 같은 분자이다.", "입체 배열의 차이이다.", "순서가 아니라 공간 배열의 차이이다."], "dx": "광학 이성질이 거울상이 겹쳐지지 않는 입체 배열 차이라는 점을 놓친 경우다. 결합 순서가 아니라 공간 배열(손대칭성)의 차이라는 점이 흔들린다.", "fix": "광학 이성질을 '거울상이 겹쳐지지 않는 입체 배열 차이'로 못 박는다. 결합 순서가 아니라 공간 배열(손대칭성)의 차이임을 잡아라.", "cite": ""}, "GC-211": {"name": "평면 사각", "course": "gc", "unit": "배위화학-1", "tier": "C", "mis": ["리간드 배치가 갈린다.", "배위수 6은 팔면체이다.", "평면 배열이 정의이다."], "dx": "배위수 4가 평면 사각형 또는 정사면체로, 배위수 6은 팔면체로 배열된다는 대응을 놓친 경우다. 같은 배위수라도 구조가 갈릴 수 있다는 점이 약하다.", "fix": "'배위수 4는 평면 사각형 또는 정사면체, 배위수 6은 팔면체'로 못 박는다. 같은 배위수라도 구조가 갈릴 수 있음을 잡아라.", "cite": ""}, "GC-212": {"name": "팔면체", "course": "gc", "unit": "배위화학-2", "tier": "C", "mis": ["배위수가 6이다.", "배위수 4는 평면 사각·정사면체이다.", "리간드 배치가 여러 가지이다."], "dx": "배위수 6이 팔면체, 배위수 4가 평면 사각·정사면체라는 구조 대응을 헷갈린 경우다. 배위수와 기하 구조의 짝이 흔들린다.", "fix": "'배위수 6은 팔면체, 배위수 4는 평면 사각·정사면체'로 못 박는다. 배위수와 기하 구조의 짝을 맞춰라.", "cite": ""}, "GC-213": {"name": "결정장 이론", "course": "gc", "unit": "배위화학-2", "tier": "C", "mis": ["리간드가 에너지를 갈라놓는다.", "리간드가 d 오비탈을 분리시킨다.", "정전기적 모형이다."], "dx": "결정장 이론이 리간드를 점전하로 보고 그 정전기적 영향으로 금속 d 오비탈 에너지가 갈라진다고 설명한다는 점을 놓친 경우다.", "fix": "결정장 이론을 '리간드를 점전하로 보고 그 정전기적 영향으로 금속 d 오비탈 에너지가 갈라짐'으로 못 박는다. 이 그림으로 d 오비탈 분리를 설명하라.", "cite": ""}, "GC-214": {"name": "d 오비탈 분리", "course": "gc", "unit": "배위화학-2", "tier": "C", "mis": ["리간드가 에너지를 분리시킨다.", "리간드를 향한 두 개가 높다.", "가까울수록 반발이 크다."], "dx": "팔면체장에서 리간드를 향한 d 오비탈이 더 큰 반발로 높아지고 그 사이를 향한 것은 낮아져, 낮은 세 개·높은 두 개로 갈라진다는 점을 놓친 경우다.", "fix": "'팔면체장에서 리간드를 향한 d 오비탈이 더 큰 반발로 높아지고 그 사이를 향한 것은 낮아져, 낮은 세 개·높은 두 개로 갈라짐'을 못 박는다. 방향으로 분리를 잡아라.", "cite": ""}, "GC-215": {"name": "분리 에너지", "course": "gc", "unit": "배위화학-2", "tier": "C", "mis": ["같음이 아니라 차이이다.", "장의 세기에 의존한다.", "조건마다 달라진다."], "dx": "갈라짐 에너지 Δ가 두 d 오비탈 무리의 에너지 차이이고 리간드 장 세기에 따라 달라진다는 점을 놓친 경우다. '같음'이 아니라 '차이'라는 점이 흔들린다.", "fix": "갈라짐 에너지 Δ를 '두 d 오비탈 무리의 에너지 차이이고 리간드 장 세기에 따라 달라짐'으로 못 박는다. '같음'이 아니라 '차이'임을 잡아라.", "cite": ""}, "GC-216": {"name": "강한 장", "course": "gc", "unit": "배위화학-2", "tier": "C", "mis": ["장이 강할수록 Δ가 크다.", "장이 약해 분리가 작다.", "Δ를 크게 만든다."], "dx": "강한 장 리간드일수록 갈라짐 Δ를 크게 만든다는 대응을 놓친 경우다. 장이 약하면 Δ가 작다는 방향이 흔들린다.", "fix": "'강한 장 리간드일수록 갈라짐 Δ를 크게 만듦'을 못 박는다. 장이 약하면 Δ가 작은 방향을 잡아라.", "cite": ""}, "GC-217": {"name": "저스핀", "course": "gc", "unit": "배위화학-2", "tier": "C", "mis": ["작으면 고스핀이 된다.", "전자가 짝을 짓는다.", "높은 오비탈로 올라가지 않는다."], "dx": "Δ가 짝짓기 에너지보다 크면(강한 장) 전자가 낮은 오비탈에서 짝을 지어 저스핀이 된다는 점을 놓친 경우다.", "fix": "'Δ가 짝짓기 에너지보다 크면(강한 장) 전자가 낮은 오비탈에서 짝을 지어 저스핀'임을 못 박는다. Δ와 짝짓기 에너지의 크기 비교로 스핀을 정하라.", "cite": ""}, "GC-218": {"name": "고스핀", "course": "gc", "unit": "배위화학-2", "tier": "C", "mis": ["크면 저스핀이 된다.", "전자가 퍼져 채워진다.", "짝짓기보다 퍼지는 편이 유리하다."], "dx": "Δ가 작으면(약한 장) 짝짓기보다 높은 오비탈로 퍼져 들어가는 편이 유리해 고스핀이 된다는 점을 놓친 경우다.", "fix": "'Δ가 작으면(약한 장) 짝짓기보다 높은 오비탈로 퍼져 들어가는 편이 유리해 고스핀'임을 못 박는다. 약한 장에서 전자가 퍼짐을 잡아라.", "cite": ""}, "GC-219": {"name": "강한 장과 스핀", "course": "gc", "unit": "배위화학-2", "tier": "C", "mis": ["Δ가 커서 저스핀이 된다.", "Δ가 작아 고스핀이 된다.", "강한 장은 Δ가 크다."], "dx": "강한 장은 Δ가 커서 저스핀, 약한 장은 Δ가 작아 고스핀이라는 연결을 놓친 경우다. Δ와 짝짓기 에너지의 크기 비교가 스핀을 정한다는 점이 약하다.", "fix": "'강한 장은 Δ가 커서 저스핀, 약한 장은 Δ가 작아 고스핀'임을 못 박는다. Δ와 짝짓기 에너지의 크기 비교가 스핀을 정함을 잡아라.", "cite": ""}, "GC-220": {"name": "분광화학 계열", "course": "gc", "unit": "배위화학-2", "tier": "C", "mis": ["분자량이 아니라 장 세기이다.", "리간드 기준의 배열이다.", "장 세기가 다르기 때문이다."], "dx": "분광화학 계열이 리간드를 장 세기(Δ 크기) 순으로 배열한 것이고 분자량 순이 아니라는 점을 놓친 경우다.", "fix": "분광화학 계열을 '리간드를 장 세기(Δ 크기) 순으로 배열한 것'으로 못 박는다. 분자량 순이 아님을 잡아라.", "cite": ""}, "GC-221": {"name": "착물의 색", "course": "gc", "unit": "배위화학-2", "tier": "C", "mis": ["흡수한 색이 아니라 보색이 보인다.", "d 오비탈 전이가 원인이다.", "Δ만큼의 에너지를 흡수한다."], "dx": "착물의 색이 d 오비탈 전이로 Δ만큼의 빛을 흡수하고 그 보색이 보이는 것이라는 점을 놓친 경우다. 흡수한 색 자체가 보이는 게 아니라는 점이 흔들린다.", "fix": "착물의 색을 'd 오비탈 전이로 Δ만큼의 빛을 흡수하고 그 보색이 보임'으로 못 박는다. 흡수한 색 자체가 보이는 게 아님을 잡아라.", "cite": ""}, "GC-222": {"name": "착물 자기성", "course": "gc", "unit": "배위화학-2", "tier": "C", "mis": ["질량이 아니라 홀전자가 정한다.", "색이 아니라 홀전자가 정한다.", "반자기성은 홀전자가 없을 때이다."], "dx": "착물의 자기성이 홀전자 유무로 정해진다는 점을 놓친 경우다. 홀전자가 있으면 상자기성, 없으면 반자기성이라는 대응이 흔들린다(고스핀·저스핀과 직결).", "fix": "착물의 자기성을 '홀전자가 있으면 상자기성, 없으면 반자기성'으로 못 박는다. 고스핀·저스핀이 홀전자 수를 정함과 직결로 잡아라.", "cite": ""}, "GC-223": {"name": "배위수와 구조", "course": "gc", "unit": "배위화학-2", "tier": "C", "mis": ["평면 사각은 배위수 4이다.", "직선형은 배위수 2이다.", "배위수에 따라 구조가 정해진다."], "dx": "배위수가 기하 구조를 정한다는 대응을 놓친 경우다. 2는 직선형, 4는 평면 사각·정사면체, 6은 팔면체라는 짝이 흔들린다.", "fix": "배위수가 기하 구조를 정함을 '2는 직선형, 4는 평면 사각·정사면체, 6은 팔면체'로 못 박는다. 배위수에서 구조를 바로 옮겨라.", "cite": ""}, "GC-027": {"name": "파울리 원리", "course": "gc", "unit": "전자배치", "tier": "B", "mis": ["같으면 배타 원리에 어긋난다.", "스핀이 두 종류뿐이다.", "모두 같을 수 없다는 원리이다.", "오비탈 3개에 각 2개씩이다."], "dx": "파울리 원리를 '스핀은 두 종류'로만 외우고, 네 양자수가 모두 같은 전자는 존재할 수 없다는 핵심을 놓친 경우다. 한 오비탈에 전자가 반대 스핀 2개까지만 들어가는 이유가 여기서 나온다.", "fix": "파울리 원리를 '네 양자수가 모두 같은 전자는 존재 불가'로 못 박는다. 여기서 한 오비탈에 반대 스핀 2개까지만 들어감이 나옴을 잡아라.", "cite": ""}, "GC-028": {"name": "훈트 규칙", "course": "gc", "unit": "전자배치", "tier": "C", "mis": ["짝짓기는 모두 하나씩 채운 뒤이다.", "평행 스핀이 안정하다.", "흩어져 들어가 반발을 낮춘다."], "dx": "같은 에너지의 오비탈은 먼저 하나씩 평행 스핀으로 채운 뒤 짝짓는다는 순서를, 결과만 외우고 이유(전자 반발 최소·교환 안정화)를 놓친 경우다. p·d 오비탈 채움에서 바로 틀린다.", "fix": "훈트 규칙을 '같은 에너지의 오비탈은 먼저 하나씩 평행 스핀으로 채운 뒤 짝지음(전자 반발 최소·교환 안정화)'으로 못 박는다. p·d 채움을 이 순서로 그려라.", "cite": ""}, "GC-029": {"name": "쌓음 원리", "course": "gc", "unit": "전자배치", "tier": "B", "mis": ["낮은 에너지부터 채운다.", "가장 낮은 에너지 배치가 바닥상태이다.", "바깥이 아니라 에너지 기준이다.", "1s의 에너지가 더 낮다."], "dx": "쌓음 원리를 '안쪽 껍질부터'라는 공간 순서로 오해한 경우다. 기준은 위치가 아니라 에너지이며, 바닥상태는 에너지가 가장 낮은 배치라는 정의가 흔들린다(4s가 3d보다 먼저 차는 이유와 직결).", "fix": "쌓음 원리를 '기준은 위치가 아니라 에너지, 바닥상태는 에너지가 가장 낮은 배치'로 못 박는다. 4s가 3d보다 먼저 차는 이유를 에너지 순서로 설명하라.", "cite": ""}, "GC-030": {"name": "배치 순서", "course": "gc", "unit": "전자배치", "tier": "C", "mis": ["낮은 에너지부터 채운다.", "1s의 에너지가 더 낮다.", "산소는 전자가 8개라 2p에 4개가 들어간다."], "dx": "주어진 원자의 전자를 부껍질에 실제로 배분하는 단계에서 막히는 경우다. 전자 수 세기, 에너지 순서대로 채우기, 각 부껍질 최대 수(s²·p⁶·d¹⁰) 적용이 한 흐름으로 이어지지 않는다.", "fix": "전자 배치를 '전자 수를 세고, 에너지 순서대로 채우고, 각 부껍질 최대 수(s²·p⁶·d¹⁰)를 적용하는 한 흐름'으로 못 박는다. 이 순서로 주어진 원자를 채워라.", "cite": ""}, "GC-031": {"name": "에너지 순서", "course": "gc", "unit": "전자배치", "tier": "C", "mis": ["4s의 에너지가 더 낮다.", "가려막기 효과로 l에도 의존한다.", "6s의 에너지가 더 낮다."], "dx": "오비탈 에너지를 주양자수 n만으로 판단해 4s와 3d, 6s와 4f 순서에서 틀리는 경우다. 다전자 원자에서는 가려막기·침투 때문에 같은 n 안에서도 l에 따라 에너지가 갈린다는 점이 빠졌다.", "fix": "'오비탈 에너지를 n만으로 판단하면 안 되고, 다전자 원자에선 가려막기·침투로 같은 n 안에서도 l에 따라 에너지가 갈림'을 못 박는다. 4s<3d, 6s<4f를 이로 잡아라.", "cite": ""}, "GC-032": {"name": "안정 배치", "course": "gc", "unit": "전자배치", "tier": "C", "mis": ["반쪽 채움은 안정성을 준다.", "반쪽 채움·가득 참을 선호한다.", "닫힌 부껍질이 안정성을 준다."], "dx": "반쪽 채움(d⁵)·가득 참(d¹⁰)이 주는 추가 안정성을 모르고, Cr·Cu 같은 예외 배치를 단순 규칙 위반으로 보는 경우다. 4s 전자 하나가 3d로 옮겨 가는 이유가 여기 있다.", "fix": "'반쪽 채움(d⁵)·가득 참(d¹⁰)이 주는 추가 안정성'을 못 박는다. 4s 전자 하나가 3d로 옮겨 가는 Cr·Cu 예외를 단순 위반이 아니라 안정화로 설명하라.", "cite": ""}, "GC-033": {"name": "바닥상태", "course": "gc", "unit": "전자배치", "tier": "C", "mis": ["가장 낮은 에너지가 바닥상태이다.", "세 원칙을 따른다.", "에너지가 가장 낮다."], "dx": "바닥상태를 '세 원칙을 지킨 배치'로만 외우고, 본질이 에너지가 가장 낮은 상태라는 정의와 분리된 경우다. 전자 하나라도 더 높은 자리에 있으면 들뜬상태라는 대비가 약하다.", "fix": "바닥상태를 '본질이 에너지가 가장 낮은 상태'로 못 박는다. 세 원칙을 지킨 배치로만 외우지 말고, 전자 하나라도 더 높은 자리면 들뜬상태임을 대비하라.", "cite": ""}, "GC-034": {"name": "들뜬상태", "course": "gc", "unit": "전자배치", "tier": "C", "mis": ["에너지가 더 높아 불안정하다.", "흡수해야 전자가 올라간다.", "떨어지며 에너지를 내놓는다."], "dx": "들뜬상태가 에너지를 흡수해 전자가 올라간 불안정한 상태이고, 떨어질 때 그 차이를 빛으로 내놓는다는 흡수·방출 방향을 헷갈리는 경우다. 선 스펙트럼·바닥상태와 한 묶음으로 봐야 한다.", "fix": "들뜬상태를 '에너지를 흡수해 전자가 올라간 불안정한 상태, 떨어질 때 그 차이를 빛으로 방출'로 못 박는다. 흡수·방출 방향을 선 스펙트럼과 한 묶음으로 잡아라.", "cite": ""}, "GC-035": {"name": "원자가 전자", "course": "gc", "unit": "전자배치", "tier": "C", "mis": ["바깥 전자가 결합에 참여한다.", "안쪽 전자는 결합에 거의 안 쓰인다.", "같은 주기는 서로 다르다."], "dx": "결합에 참여하는 건 가장 바깥 껍질의 원자가 전자이고 안쪽 전자는 거의 관여하지 않는다는 구분이 흐린 경우다. 원자가 전자 수가 족·반응성으로 이어지는 다음 단원(주기성·결합)의 토대가 흔들린다.", "fix": "원자가 전자를 '가장 바깥 껍질의 전자로 결합에 참여, 안쪽 전자는 거의 관여 안 함'으로 못 박는다. 원자가 전자 수를 족·반응성으로 잇는 다음 단원의 토대로 삼아라.", "cite": ""}, "GC-116": {"name": "동적 평형", "course": "gc", "unit": "화학평형-1", "tier": "B", "mis": ["동적 평형은 반응이 멈추지 않는다.", "일정한 것과 같은 것은 다르다.", "두 반응이 같은 속도로 진행된다.", "미시적으로 반응이 진행된다."], "dx": "동적 평형이 반응이 멈춘 게 아니라 정·역반응이 같은 속도로 계속되어 농도가 일정한 상태라는 점을 놓친 경우다. '일정함'과 '멈춤'을 같게 본 것이 오류다.", "fix": "동적 평형을 '반응이 멈춘 게 아니라 정·역반응이 같은 속도로 계속되어 농도가 일정'으로 못 박는다. '일정함'과 '멈춤'을 갈라라.", "cite": ""}, "GC-117": {"name": "평형 상수", "course": "gc", "unit": "화학평형-1", "tier": "C", "mis": ["분자와 분모가 뒤바뀌었다.", "계수를 반영해야 한다.", "처음 농도가 아니라 평형 농도이다."], "dx": "평형 상수 식에서 생성물을 분자, 반응물을 분모에 두고 계수를 지수로, 처음 농도가 아니라 평형 농도를 넣는다는 규칙을 헷갈린 경우다.", "fix": "평형 상수 식을 '생성물을 분자·반응물을 분모, 계수를 지수, 처음이 아니라 평형 농도를 넣음'으로 못 박는다. 평형 농도를 써서 K를 세워라.", "cite": ""}, "GC-118": {"name": "Kp", "course": "gc", "unit": "화학평형-1", "tier": "C", "mis": ["농도로 나타낸 것은 Kc이다.", "순수 고체는 제외한다.", "Δn = 0일 때만 같다."], "dx": "압력 평형 상수 Kₚ가 부분 압력으로, 농도 평형 상수가 농도로 표현된다는 구분을 놓친 경우다. 순수 고체·액체는 식에서 빠지고 Δn=0일 때만 둘이 같다는 점이 흔들린다.", "fix": "'Kₚ는 부분 압력으로, 농도 평형 상수는 농도로 표현, 순수 고체·액체는 제외, Δn=0일 때만 둘이 같음'을 못 박는다. 무엇으로 표현하는지 갈라라.", "cite": ""}, "GC-119": {"name": "Kc-Kp 관계", "course": "gc", "unit": "화학평형-1", "tier": "A", "mis": ["켈빈을 사용한다.", "고체·액체는 제외한다.", "Δn이 0이 아니면 다르다.", "생성물에서 반응물을 뺀다.", "더하기가 아니라 곱과 거듭제곱이다.", "(RT)^0 = 1이다."], "dx": "압력 기준 Kₚ와 농도 기준 K가 기체 몰수 변화 Δn에 따라 달라진다는 점(Δn=0이면 같음)을 놓친 경우다. 관계식에서 온도는 켈빈을 쓴다는 점도 흔들린다.", "fix": "'Kₚ와 농도 기준 K는 기체 몰수 변화 Δn에 따라 달라짐(Δn=0이면 같음)'을 못 박는다. 관계식에서 온도는 켈빈을 씀을 잡아라.", "cite": ""}, "GC-120": {"name": "평형 상수 식", "course": "gc", "unit": "화학평형-1", "tier": "C", "mis": ["활동도를 1로 본다.", "고체의 활동도는 1이다.", "고체·액체는 빠진다."], "dx": "평형 상수 식에서 순수 고체·액체는 활동도를 1로 보아 제외한다는 규칙을 놓친 경우다. 고체 농도를 식에 넣는 실수로 이어진다.", "fix": "평형 상수 식에서 '순수 고체·액체는 활동도를 1로 보아 제외'함을 못 박는다. 고체 농도를 식에 넣는 실수를 피하라.", "cite": ""}, "GC-121": {"name": "평형 상수 의미", "course": "gc", "unit": "화학평형-1", "tier": "A", "mis": ["K가 크면 생성물이 많다.", "K가 작으면 반응물이 많다.", "생성물로 거의 전환된다.", "속도가 아니라 위치이다.", "K가 작으면 반응물 우세이다.", "속도가 아니라 진행 정도이다."], "dx": "K 크기의 의미를 놓친 경우다. K가 크면 생성물이, 작으면 반응물이 우세하다는 해석이 흔들린다.", "fix": "'K가 크면 생성물이, 작으면 반응물이 우세'함을 못 박는다. K 크기로 평형이 어느 쪽으로 치우쳤는지 읽어라.", "cite": ""}, "GC-122": {"name": "평형 상수 의존성", "course": "gc", "unit": "화학평형-1", "tier": "C", "mis": ["농도는 K를 바꾸지 않는다.", "촉매는 K에 영향이 없다.", "압력은 K를 바꾸지 않는다."], "dx": "K가 온도에만 의존하고 농도·압력·촉매로는 변하지 않는다는 점을 놓친 경우다. 농도를 바꾸면 평형 위치는 이동해도 K 값은 그대로라는 구분이 약하다.", "fix": "'K는 온도에만 의존하고 농도·압력·촉매로는 변하지 않음'을 못 박는다. 농도를 바꾸면 평형 위치는 이동해도 K 값은 그대로임을 갈라라.", "cite": ""}, "GC-123": {"name": "반응지수", "course": "gc", "unit": "화학평형-1", "tier": "C", "mis": ["Q > K이면 역반응이다.", "Q < K이면 정반응이다.", "정·역 속도가 같다."], "dx": "반응지수 Q와 K를 비교해 방향을 판단한다는 점을 헷갈린 경우다. Q<K면 정반응, Q>K면 역반응, Q=K면 평형이라는 대응이 흔들린다.", "fix": "반응지수를 'Q와 K를 비교해 방향 판단: Q<K면 정반응, Q>K면 역반응, Q=K면 평형'으로 못 박는다. Q-K 비교로 이동 방향을 정하라.", "cite": ""}, "GC-124": {"name": "르샤틀리에", "course": "gc", "unit": "화학평형-1", "tier": "C", "mis": ["변화를 완화하는 방향이다.", "르샤틀리에 원리에 따라 이동한다.", "속도가 아니라 평형 이동이다."], "dx": "르샤틀리에 원리(가해진 변화를 완화하는 방향으로 평형 이동)를 놓친 경우다. 속도 변화가 아니라 평형 위치 이동이라는 점이 약하다.", "fix": "르샤틀리에 원리를 '가해진 변화를 완화하는 방향으로 평형이 이동'으로 못 박는다. 속도 변화가 아니라 평형 위치 이동임을 잡아라.", "cite": ""}, "GC-125": {"name": "농도 변화", "course": "gc", "unit": "화학평형-1", "tier": "C", "mis": ["늘어난 생성물을 줄이려 한다.", "줄어든 반응물을 보충한다.", "줄어든 생성물을 보충한다."], "dx": "농도를 바꿨을 때 이동 방향을 헷갈린 경우다. 반응물을 넣으면 정반응, 생성물을 넣으면 역반응으로 그 변화를 완화한다는 방향이 흔들린다.", "fix": "'반응물을 넣으면 정반응, 생성물을 넣으면 역반응으로 그 변화를 완화'함을 못 박는다. 농도 변화에서 이동 방향을 바로 잡아라.", "cite": ""}, "GC-126": {"name": "압력 변화", "course": "gc", "unit": "화학평형-2", "tier": "A", "mis": ["분자 수를 줄여 압력을 낮춘다.", "분자 수를 늘려 압력을 높인다.", "완화 효과가 없다.", "압력 증가를 완화한다.", "K는 온도에만 의존한다.", "양쪽이 같으면 이동하지 않는다."], "dx": "압력(부피)을 바꿨을 때 기체 몰수가 적은 쪽으로 이동해 변화를 완화한다는 점을 놓친 경우다. 압축하면 분자 수가 줄어드는 쪽으로 이동한다는 방향이 흔들린다.", "fix": "'압력(부피)을 바꾸면 기체 몰수가 적은 쪽으로 이동해 변화를 완화'함을 못 박는다. 압축하면 분자 수가 줄어드는 쪽으로 이동함을 잡아라.", "cite": ""}, "GC-127": {"name": "온도 변화", "course": "gc", "unit": "화학평형-2", "tier": "C", "mis": ["열을 흡수하는 역반응 쪽이다.", "역반응 쪽으로 이동한다.", "열을 내는 역반응 쪽이다."], "dx": "온도 변화 시 이동 방향을 헷갈린 경우다. 온도를 올리면 흡열 반응 쪽으로 이동한다(열을 흡수해 완화)는 대응이 흔들린다.", "fix": "'온도를 올리면 흡열 반응 쪽으로 이동(열을 흡수해 완화)'함을 못 박는다. 온도 변화에서 이동 방향을 흡열·발열로 갈라라.", "cite": ""}, "GC-128": {"name": "촉매와 평형", "course": "gc", "unit": "화학평형-2", "tier": "B", "mis": ["정·역 속도를 똑같이 높일 뿐이다.", "평형 위치가 바뀌지 않는다.", "K는 온도에만 의존한다.", "평형 위치가 변하지 않는다."], "dx": "촉매가 정·역반응 속도를 똑같이 높여 평형에 빨리 도달시킬 뿐 평형 위치(K)는 바꾸지 않는다는 점을 놓친 경우다.", "fix": "'촉매는 정·역반응 속도를 똑같이 높여 평형에 빨리 도달시킬 뿐 평형 위치(K)는 안 바꿈'을 못 박는다. 도달 속도와 위치를 갈라라.", "cite": ""}, "GC-129": {"name": "불활성 기체", "course": "gc", "unit": "화학평형-2", "tier": "C", "mis": ["부분 압력이 변하지 않는다.", "농도가 변하지 않는다."], "dx": "일정 부피에서 불활성 기체를 넣어도 각 반응 성분의 부분 압력·농도가 그대로라 평형이 이동하지 않는다는 점을 놓친 경우다.", "fix": "'일정 부피에서 불활성 기체를 넣어도 각 반응 성분의 부분 압력·농도가 그대로라 평형이 이동하지 않음'을 못 박는다. 전체 압력만 오를 뿐임을 잡아라.", "cite": ""}, "GC-130": {"name": "온도와 K", "course": "gc", "unit": "화학평형-2", "tier": "C", "mis": ["K는 온도에 의존한다.", "온도만 K를 바꾼다.", "역반응 쪽으로 이동한다."], "dx": "K를 바꾸는 유일한 요인이 온도라는 점을 놓친 경우다. 농도·압력·촉매는 K를 안 바꾸고 온도만 K 값 자체를 바꾼다는 구분이 흔들린다.", "fix": "'K를 바꾸는 유일한 요인이 온도'임을 못 박는다. 농도·압력·촉매는 K를 안 바꾸고 온도만 K 값 자체를 바꿈을 갈라라.", "cite": ""}, "GC-131": {"name": "용해도곱", "course": "gc", "unit": "화학평형-2", "tier": "C", "mis": ["이온이 더 많이 녹는다.", "평형 상수이기 때문이다.", "용해도가 매우 작은 염을 다룬다."], "dx": "용해도곱 Kₛₚ가 잘 녹지 않는 염의 용해 평형 상수라는 점을 놓친 경우다. 평형 상수의 일종이라 온도에만 의존한다는 점이 약하다.", "fix": "용해도곱 Kₛₚ를 '잘 녹지 않는 염의 용해 평형 상수'로 못 박는다. 평형 상수의 일종이라 온도에만 의존함을 잡아라.", "cite": ""}, "GC-132": {"name": "공통 이온 효과", "course": "gc", "unit": "화학평형-2", "tier": "A", "mis": ["평형이 침전 쪽으로 이동한다.", "늘어난 이온을 줄이려 한다.", "Ksp는 온도에만 의존한다.", "평형이 침전 쪽으로 더 치우친다.", "공통 이온 효과로 용해도가 감소한다.", "용해 평형을 억제한다."], "dx": "공통 이온을 넣으면 평형이 침전 쪽으로 이동해 용해도가 줄어든다(공통 이온 효과)는 점을 놓친 경우다. Kₛₚ는 온도에만 의존해 그대로라는 점과 헷갈린다.", "fix": "'공통 이온을 넣으면 평형이 침전 쪽으로 이동해 용해도가 줆(공통 이온 효과)'을 못 박는다. Kₛₚ는 온도에만 의존해 그대로임과 갈라라.", "cite": ""}, "GC-133": {"name": "침전 조건", "course": "gc", "unit": "화학평형-2", "tier": "C", "mis": ["불포화라 더 녹을 수 있다.", "용해와 침전이 균형이다.", "과포화 상태이다."], "dx": "이온곱 Q와 Kₛₚ 비교로 침전 여부를 판단한다는 점을 놓친 경우다. Q>Kₛₚ면 과포화라 침전, Q<Kₛₚ면 불포화라 더 녹는다는 대응이 흔들린다.", "fix": "침전 여부를 '이온곱 Q와 Kₛₚ 비교: Q>Kₛₚ면 과포화라 침전, Q<Kₛₚ면 불포화라 더 녹음'으로 못 박는다. Q-Kₛₚ 비교로 판단하라.", "cite": ""}, "GC-134": {"name": "Ksp 식", "course": "gc", "unit": "화학평형-2", "tier": "C", "mis": ["고체의 활동도는 1이다.", "계수가 지수로 들어간다.", "평형 상수는 곱의 형태이다."], "dx": "Kₛₚ 식에서 고체 활동도를 1로 빼고, 각 이온 농도에 계수를 지수로 넣어 곱한다는 규칙을 놓친 경우다.", "fix": "Kₛₚ 식을 '고체 활동도를 1로 빼고, 각 이온 농도에 계수를 지수로 넣어 곱함'으로 못 박는다. 화학식의 이온 계수를 지수로 옮겨라.", "cite": ""}, "GC-135": {"name": "촉매와 K", "course": "gc", "unit": "화학평형-2", "tier": "C", "mis": ["K는 온도에만 의존한다.", "촉매는 K에 영향이 없다.", "평형 위치가 그대로이다."], "dx": "촉매가 K에 영향을 주지 않는다(평형 위치 불변)는 점을 놓친 경우다. K는 온도에만 의존한다는 원칙이 흔들린다.", "fix": "'촉매는 K에 영향을 주지 않음(평형 위치 불변)'을 못 박는다. K는 온도에만 의존한다는 원칙을 지켜라.", "cite": ""}, "GC-180": {"name": "반응 속도", "course": "gc", "unit": "반응속도론-1", "tier": "C", "mis": ["반응물 농도가 줄어든다.", "농도가 변하기 때문이다.", "농도 변화율이 곧 속도이다."], "dx": "반응 속도가 단위 시간당 농도 변화율이라는 정의를 놓친 경우다. 반응물은 줄고 생성물은 느는 변화의 '율'이 속도라는 점이 약하다.", "fix": "반응 속도를 '단위 시간당 농도 변화율'로 못 박는다. 반응물은 줄고 생성물은 느는 변화의 '율'임을 잡아 속도를 정량화하라.", "cite": ""}, "GC-181": {"name": "속도식", "course": "gc", "unit": "반응속도론-1", "tier": "C", "mis": ["계수와 일치한다는 보장이 없다.", "반응물 농도가 속도를 정한다.", "실험 데이터가 필요하다."], "dx": "속도식의 차수가 반응식 계수와 일치한다는 보장이 없고 실험으로 정해진다는 점을 놓친 경우다. 계수=차수로 단정한 것이 오류다.", "fix": "'속도식의 차수가 반응식 계수와 일치한다는 보장이 없고 실험으로 정함'을 못 박는다. 계수=차수로 단정 말고 실험 데이터로 차수를 잡아라.", "cite": ""}, "GC-182": {"name": "반응 차수", "course": "gc", "unit": "반응속도론-1", "tier": "C", "mis": ["계수와 일치한다는 보장이 없다.", "정수로 제한되지 않는다.", "반응식만으로는 알 수 없다."], "dx": "반응 차수가 반응식만으로는 알 수 없고 정수로 제한되지도 않으며 실험 데이터로 정한다는 점을 놓친 경우다.", "fix": "반응 차수를 '반응식만으로는 알 수 없고 정수로 제한되지도 않으며 실험 데이터로 정함'으로 못 박는다. 차수를 짐작 말고 데이터로 구하라.", "cite": ""}, "GC-183": {"name": "전체 차수", "course": "gc", "unit": "반응속도론-1", "tier": "C", "mis": ["더하는 것이다.", "하나만 보는 것이 아니다.", "1 + 2 = 3이다."], "dx": "전체 차수가 각 반응물 차수의 합이라는 점을 놓친 경우다. 1차와 2차가 함께면 전체 3차라는 셈이 흔들린다.", "fix": "전체 차수를 '각 반응물 차수의 합'으로 못 박는다. 1차와 2차가 함께면 전체 3차임을 잡아 전체 차수를 셈하라.", "cite": ""}, "GC-184": {"name": "속도 상수", "course": "gc", "unit": "반응속도론-1", "tier": "C", "mis": ["k는 온도에만 의존한다.", "온도가 오르면 커진다.", "농도가 바뀌어도 k는 일정하다."], "dx": "속도 상수 k가 온도(와 활성화 에너지)에만 의존하고 농도로는 변하지 않는다는 점을 놓친 경우다. 온도가 오르면 k가 커진다는 방향이 약하다.", "fix": "속도 상수 k를 '온도(와 활성화 에너지)에만 의존하고 농도로는 변하지 않음'으로 못 박는다. 온도가 오르면 k가 커지는 방향을 잡아라.", "cite": ""}, "GC-185": {"name": "0차 반응", "course": "gc", "unit": "반응속도론-1", "tier": "C", "mis": ["농도에 의존하지 않는다.", "v = k이다."], "dx": "0차 반응이 농도와 무관하게 일정한 속도(v=k)로 진행된다는 점을 놓친 경우다. 농도가 줄어도 속도가 유지된다는 점이 흔들린다.", "fix": "0차 반응을 'v=k라 농도와 무관하게 일정한 속도로 진행'으로 못 박는다. 농도가 줄어도 속도가 유지됨을 잡아라.", "cite": ""}, "GC-186": {"name": "1차 반응", "course": "gc", "unit": "반응속도론-1", "tier": "C", "mis": ["v = k[A]이다.", "t½ = ln2/k이다."], "dx": "1차 반응이 v=k[A]이고 반감기 t½=ln2/k로 농도와 무관하게 일정하다는 점을 놓친 경우다.", "fix": "1차 반응을 'v=k[A]이고 반감기 t½=ln2/k로 농도와 무관하게 일정'으로 못 박는다. 1차 반감기의 농도 독립성을 잡아라.", "cite": ""}, "GC-187": {"name": "2차 반응", "course": "gc", "unit": "반응속도론-1", "tier": "C", "mis": ["v = k[A]^2이다.", "ln 직선은 1차 반응이다."], "dx": "2차 반응이 v=k[A]²이고, ln[A]-t 직선은 1차의 특징이라는 구분을 놓친 경우다. 차수별 그래프 형태가 흔들린다.", "fix": "2차 반응을 'v=k[A]²'로 못 박는다. ln[A]-t 직선은 1차의 특징임을 갈라, 차수별 그래프 형태를 구분하라.", "cite": ""}, "GC-188": {"name": "적분 속도식", "course": "gc", "unit": "반응속도론-1", "tier": "C", "mis": ["[A]-t 직선은 0차이다.", "ln 직선은 1차이다."], "dx": "적분 속도식의 직선 형태로 차수를 구별한다는 점을 놓친 경우다. [A]-t 직선은 0차, ln[A]-t 직선은 1차, 1/[A]-t 직선은 2차라는 대응이 흔들린다.", "fix": "적분 속도식의 차수 구별을 '[A]-t 직선은 0차, ln[A]-t 직선은 1차, 1/[A]-t 직선은 2차'로 못 박는다. 어느 그래프가 직선인지로 차수를 정하라.", "cite": ""}, "GC-189": {"name": "반감기", "course": "gc", "unit": "반응속도론-1", "tier": "A", "mis": ["t½ = ln2/k이다.", "0차·2차는 초기 농도에 의존한다.", "농도가 클수록 길다.", "농도가 클수록 짧다.", "농도와 무관한 상수이다.", "1차는 무관, 2차는 반비례이다."], "dx": "1차 반응만 반감기 t½=ln2/k가 농도와 무관하게 일정하고, 0차·2차는 초기 농도에 의존한다는 점을 놓친 경우다.", "fix": "'1차 반응만 반감기 t½=ln2/k가 농도와 무관하게 일정, 0차·2차는 초기 농도에 의존'함을 못 박는다. 차수별 반감기 거동을 갈라라.", "cite": ""}, "GC-190": {"name": "충돌 이론", "course": "gc", "unit": "반응속도론-2", "tier": "C", "mis": ["대부분의 충돌은 반응하지 않는다.", "배향도 조건이다.", "방향이 맞아야 반응한다."], "dx": "반응이 일어나려면 충분한 에너지와 올바른 배향(방향)을 갖춘 충돌이어야 한다는 점을 놓친 경우다. 대부분의 충돌은 반응으로 이어지지 않는다는 점이 약하다.", "fix": "충돌 이론을 '반응이 일어나려면 충분한 에너지와 올바른 배향(방향)을 갖춘 충돌'로 못 박는다. 대부분의 충돌은 반응으로 이어지지 않음을 잡아라.", "cite": ""}, "GC-191": {"name": "활성화 에너지", "course": "gc", "unit": "반응속도론-2", "tier": "C", "mis": ["장벽이 높아 넘기 어렵다.", "장벽이 낮아 넘기 쉽다.", "장벽 높이가 속도를 정한다."], "dx": "활성화 에너지가 반응이 넘어야 할 에너지 장벽이고, 장벽이 높을수록 넘기 어려워 반응이 느리다는 점을 놓친 경우다.", "fix": "활성화 에너지를 '반응이 넘어야 할 에너지 장벽, 높을수록 넘기 어려워 반응이 느림'으로 못 박는다. 장벽 개념으로 속도를 가늠하라.", "cite": ""}, "GC-192": {"name": "아레니우스", "course": "gc", "unit": "반응속도론-2", "tier": "C", "mis": ["장벽이 높아 k가 작아진다.", "온도가 오르면 k가 커진다.", "지수항에 Ea가 들어간다."], "dx": "아레니우스 식에서 온도가 오르면 k가 커지고 활성화 에너지 Eₐ가 클수록 k가 작아진다는 관계를 놓친 경우다. Eₐ가 지수항에 들어간다는 점이 약하다.", "fix": "아레니우스 식을 '온도가 오르면 k가 커지고 활성화 에너지 Eₐ가 클수록 k가 작아짐(Eₐ가 지수항에 들어감)'으로 못 박는다. 두 인자로 k 변화를 따져라.", "cite": ""}, "GC-193": {"name": "빈도 인자", "course": "gc", "unit": "반응속도론-2", "tier": "C", "mis": ["활성화 에너지는 지수항에 따로 있다.", "배향 인자를 포함한다.", "k가 A에 비례한다."], "dx": "빈도 인자 A가 충돌 빈도와 배향 인자를 담고, 활성화 에너지는 지수항에 따로 들어간다는 점을 놓친 경우다. k가 A에 비례한다는 점이 흔들린다.", "fix": "빈도 인자 A를 '충돌 빈도와 배향 인자를 담고, 활성화 에너지는 지수항에 따로 들어감'으로 못 박는다. k가 A에 비례함을 잡아라.", "cite": ""}, "GC-194": {"name": "온도와 충돌", "course": "gc", "unit": "반응속도론-2", "tier": "C", "mis": ["에너지 분포가 이동한다.", "Ea 자체는 변하지 않는다.", "Ea는 반응의 고유 장벽이다."], "dx": "온도가 오르면 분자 에너지 분포가 이동해 장벽을 넘는 분자 비율이 늘어 속도가 커진다는 점을 놓친 경우다. 활성화 에너지 자체는 변하지 않는다는 점이 약하다.", "fix": "'온도가 오르면 분자 에너지 분포가 이동해 장벽을 넘는 분자 비율이 늘어 속도가 커짐'을 못 박는다. 활성화 에너지 자체는 변하지 않음을 잡아라.", "cite": ""}, "GC-195": {"name": "메커니즘", "course": "gc", "unit": "반응속도론-2", "tier": "C", "mis": ["계수로 바로 쓰면 틀린다.", "소반응은 계수가 곧 차수이다.", "중간 단계까지 포함한다."], "dx": "전체 반응식의 계수를 바로 차수로 쓰면 틀리고, 소반응(단일 단계)에서만 계수가 곧 차수라는 점을 놓친 경우다. 메커니즘이 여러 단계로 이뤄진다는 점이 약하다.", "fix": "'전체 반응식의 계수를 바로 차수로 쓰면 틀리고, 소반응(단일 단계)에서만 계수가 곧 차수'임을 못 박는다. 메커니즘이 여러 단계로 이뤄짐을 잡아라.", "cite": ""}, "GC-196": {"name": "속도 결정 단계", "course": "gc", "unit": "반응속도론-2", "tier": "C", "mis": ["느린 단계가 병목이다.", "느린 단계가 속도를 제한한다.", "합이 아니라 병목 단계이다."], "dx": "여러 단계 중 가장 느린 단계가 전체 속도를 제한한다(병목)는 점을 놓친 경우다. 전체 속도가 단계들의 합이 아니라 병목 단계로 정해진다는 점이 흔들린다.", "fix": "'여러 단계 중 가장 느린 단계가 전체 속도를 제한함(병목)'을 못 박는다. 전체 속도가 단계들의 합이 아니라 병목 단계로 정해짐을 잡아라.", "cite": ""}, "GC-197": {"name": "중간체", "course": "gc", "unit": "반응속도론-2", "tier": "C", "mis": ["이후 단계에서 소비된다.", "처음부터 있는 것이 아니다.", "생성과 소비가 상쇄된다."], "dx": "중간체가 한 단계에서 생겼다가 다음 단계에서 소비되어 전체 반응식에는 나타나지 않는다는 점을 놓친 경우다. 처음부터 있는 반응물과 다르다는 구분이 약하다.", "fix": "중간체를 '한 단계에서 생겼다가 다음 단계에서 소비되어 전체 반응식에는 나타나지 않음'으로 못 박는다. 처음부터 있는 반응물과 갈라라.", "cite": ""}, "GC-198": {"name": "촉매", "course": "gc", "unit": "반응속도론-2", "tier": "B", "mis": ["장벽을 낮춰야 빨라진다.", "ΔH는 변하지 않는다.", "소모되지 않는다.", "양방향을 함께 가속한다."], "dx": "촉매가 활성화 에너지를 낮춰 속도를 높이되 자신은 소모되지 않고 반응엔탈피 ΔH(평형)는 바꾸지 않는다는 점을 놓친 경우다.", "fix": "촉매를 '활성화 에너지를 낮춰 속도를 높이되 자신은 소모되지 않고 반응엔탈피 ΔH(평형)는 안 바꿈'으로 못 박는다. 속도와 평형을 갈라라.", "cite": ""}, "GC-043": {"name": "이온 결합", "course": "gc", "unit": "분자-1", "tier": "A", "mis": ["전자를 공유하는 것은 공유 결합이다.", "두 비금속 사이는 공유 결합이다.", "강한 인력 때문에 녹는점이 높다.", "고체에서는 이온이 고정되어 있다.", "정전기력이 전하 곱에 비례한다.", "개별 분자가 아니라 격자이다."], "dx": "이온 결합(전자 이동, 금속+비금속)과 공유 결합(전자 공유)을 섞은 경우다. 강한 정전 인력으로 녹는점이 높다는 성질 연결도 흐리다.", "fix": "이온 결합을 '전자 이동(금속+비금속)으로 강한 정전 인력, 그래서 녹는점 높음'으로 못 박는다. 공유 결합(전자 공유)과 갈라 성질까지 이어라.", "cite": ""}, "GC-044": {"name": "공유 결합", "course": "gc", "unit": "분자-1", "tier": "C", "mis": ["완전히 넘기면 이온 결합이다.", "금속끼리는 금속 결합이다.", "전자쌍을 2, 3쌍 공유할 수 있다."], "dx": "공유 결합(전자쌍 공유)과 이온 결합(완전 이동)의 경계를 헷갈린 경우다. 전자쌍을 2·3쌍 공유해 이중·삼중 결합이 된다는 점이 약하다.", "fix": "공유 결합을 '전자쌍 공유, 2·3쌍 공유면 이중·삼중 결합'으로 못 박는다. 이온 결합(완전 이동)과 경계를 갈라 결합 차수를 잡아라.", "cite": ""}, "GC-045": {"name": "결합 길이", "course": "gc", "unit": "분자-1", "tier": "A", "mis": ["결합 차수가 클수록 짧다.", "전자쌍이 많을수록 가까워진다.", "가까울수록 인력이 크다.", "삼중 결합의 차수가 가장 크다.", "차수가 클수록 짧아진다.", "큰 원자끼리는 핵 사이가 멀다."], "dx": "결합 길이를 결합 차수와 연결하지 못한 경우다. 차수가 클수록(공유 전자쌍 많을수록) 더 짧아진다는 관계가 흔들린다.", "fix": "결합 길이를 '결합 차수가 클수록(공유 전자쌍 많을수록) 짧음'으로 못 박는다. 차수-길이의 반비례로 단일·이중·삼중을 비교하라.", "cite": ""}, "GC-046": {"name": "결합 세기", "course": "gc", "unit": "분자-1", "tier": "C", "mis": ["삼중 결합의 전자쌍이 더 많다.", "짧을수록 인력이 크다.", "끊는 데 큰 에너지가 들면 강하다."], "dx": "결합 세기를 결합 차수·길이와 묶지 못한 경우다. 차수가 크고 짧을수록 강하며, 끊는 데 큰 에너지가 든다는 정의가 정리되지 않았다.", "fix": "결합 세기를 '차수가 크고 짧을수록 강하며, 끊는 데 큰 에너지가 듦'으로 못 박는다. 차수·길이·세기를 한 묶음으로 잡아라.", "cite": ""}, "GC-047": {"name": "루이스 구조", "course": "gc", "unit": "분자-1", "tier": "C", "mis": ["코어 전자가 아니라 최외각 전자이다.", "비공유 전자쌍도 구조에 포함된다.", "양성자가 아니라 전자를 그린다."], "dx": "루이스 구조에서 최외각 전자(코어 제외)와 비공유 전자쌍까지 그린다는 규칙을 놓친 경우다. 전자를 점으로 배분하는 절차가 흔들린다.", "fix": "루이스 구조를 '최외각 전자(코어 제외)와 비공유 전자쌍까지 점으로 배분'으로 못 박는다. 전체 원자가 전자를 세고 결합·비공유로 나눠 그려라.", "cite": ""}, "GC-048": {"name": "옥텟 규칙", "course": "gc", "unit": "분자-1", "tier": "A", "mis": ["8개를 채우려 한다.", "수소는 헬륨 배치를 닮는다.", "붕소, 확장 옥텟, 홀수 전자 분자 등 예외가 있다.", "옥텟은 8개를 뜻한다.", "바깥 껍질을 8개로 채운다.", "닫힌 껍질이 안정하다."], "dx": "옥텟(최외각 8개) 지향과 그 한계를 같이 잡지 못한 경우다. 수소는 2개(He 배치), 붕소·확장 옥텟·홀수 전자 분자 같은 예외가 빠졌다.", "fix": "옥텟 규칙을 '최외각 8개 지향, 단 수소는 2개(He 배치)·붕소·확장 옥텟·홀수 전자 분자는 예외'로 못 박는다. 지향과 한계를 함께 잡아라.", "cite": ""}, "GC-049": {"name": "옥텟 예외", "course": "gc", "unit": "분자-1", "tier": "C", "mis": ["붕소, 확장 옥텟, 홀수 전자 등이 예외이다.", "확장 옥텟이 가능하다.", "BF₃는 전자 6개로 안정하다."], "dx": "옥텟 예외를 인식하지 못한 경우다. 붕소(6개)·확장 옥텟(3주기 이하)·홀수 전자 분자가 안정하게 존재한다는 점이 흔들린다.", "fix": "옥텟 예외를 '붕소(6개)·확장 옥텟(3주기 이하)·홀수 전자 분자가 안정하게 존재'로 못 박는다. 옥텟을 절대 규칙으로 보지 말고 예외를 인식하라.", "cite": ""}, "GC-050": {"name": "형식 전하", "course": "gc", "unit": "분자-1", "tier": "A", "mis": ["더하는 것이 아니라 빼는 식이다.", "이온이면 0이 아니다.", "전하 분리가 적어야 안정하다.", "공유 전자를 균등 분배한다.", "전자를 잘 끄는 원자가 음전하를 감당한다.", "형식적으로 매긴 값이다."], "dx": "형식 전하 계산(원자가 전자 - 비공유 - 결합쌍/2)을 헷갈린 경우다. 전하 분리가 적은 구조가 더 안정하다는 판단으로 이어지지 않는다.", "fix": "형식 전하를 '원자가 전자 − 비공유 − 결합쌍/2'로 못 박는다. 전하 분리가 적은 구조가 더 안정함을 잡아 여러 루이스 구조를 가려라.", "cite": ""}, "GC-051": {"name": "공명", "course": "gc", "unit": "분자-1", "tier": "C", "mis": ["실제로 오가는 것이 아니다.", "원자는 그대로이다.", "전자 비편재화로 안정해진다."], "dx": "공명을 실제로 구조가 오가는 것으로 오해한 경우다. 원자는 고정이고 전자만 비편재화되어 안정해진다는 핵심이 빠졌다.", "fix": "공명을 '구조가 오가는 게 아니라 원자는 고정이고 전자만 비편재화되어 안정해짐'으로 못 박는다. 실제로 오간다는 오해를 버리고 평균 구조로 보라.", "cite": ""}, "GC-052": {"name": "결합 극성", "course": "gc", "unit": "분자-1", "tier": "B", "mis": ["전기음성도 차이가 없다.", "전자쌍이 더 치우친다.", "전자를 더 끄는 원자가 음전하를 띤다.", "전기음성도 차이가 핵심이다."], "dx": "결합 극성을 전기음성도 차이로 잡지 못한 경우다. 차이가 클수록 전자쌍이 치우치고, 더 끄는 원자가 부분 음전하를 띤다는 그림이 흐리다.", "fix": "결합 극성을 '전기음성도 차이가 클수록 전자쌍이 치우치고, 더 끄는 원자가 부분 음전하'로 못 박는다. 전기음성도 차로 극성 방향을 잡아라.", "cite": ""}, "GC-053": {"name": "분자 극성", "course": "gc", "unit": "분자-2", "tier": "C", "mis": ["CO₂처럼 쌍극자가 상쇄될 수 있다.", "모양에 따라 상쇄될 수 있다.", "쌍극자가 상쇄되기 때문이다."], "dx": "결합이 극성이어도 분자가 무극성일 수 있다는 점(CO₂처럼 쌍극자 상쇄)을 놓친 경우다. 결합 극성과 분자 극성은 모양이 매개한다는 연결이 약하다.", "fix": "'결합이 극성이어도 분자가 무극성일 수 있음(CO₂처럼 쌍극자 상쇄)'을 못 박는다. 결합 극성과 분자 극성을 모양이 매개함을 잡아 대칭을 따져라.", "cite": ""}, "GC-054": {"name": "VSEPR", "course": "gc", "unit": "분자-2", "tier": "C", "mis": ["반발을 최소화한다.", "비공유 전자쌍도 반발한다.", "다중 결합은 한 영역으로 취급한다."], "dx": "VSEPR의 핵심(전자쌍 반발 최소화)을 놓친 경우다. 비공유 전자쌍도 반발하고 다중 결합은 한 영역으로 센다는 규칙이 흔들린다.", "fix": "VSEPR를 '전자쌍 반발을 최소화하는 배치, 비공유 전자쌍도 반발하고 다중 결합은 한 영역으로 셈'으로 못 박는다. 전자 영역 수를 세어 골격을 잡아라.", "cite": ""}, "GC-055": {"name": "VSEPR 구조", "course": "gc", "unit": "분자-2", "tier": "C", "mis": ["정사면체가 반발이 최소이다.", "두 영역은 180°로 직선이다.", "세 영역은 평면 삼각형이다."], "dx": "전자 영역 수와 기본 골격의 대응을 헷갈린 경우다. 2영역 직선(180°)·3영역 평면삼각형·4영역 정사면체라는 짝이 안 잡혔다.", "fix": "전자 영역과 골격을 '2영역 직선(180°)·3영역 평면삼각형·4영역 정사면체'로 짝지어 못 박는다. 영역 수에서 기본 골격을 바로 옮겨라.", "cite": ""}, "GC-056": {"name": "비공유 전자쌍", "course": "gc", "unit": "분자-2", "tier": "C", "mis": ["비공유 전자쌍의 반발이 더 크다.", "강한 반발로 결합각을 좁힌다.", "한 원자에만 묶여 더 퍼진다."], "dx": "비공유 전자쌍이 결합쌍보다 반발이 커서 결합각을 좁힌다는 점을 놓친 경우다. 한 원자에만 묶여 더 퍼진다는 이유가 빠졌다.", "fix": "'비공유 전자쌍은 결합쌍보다 반발이 커서 결합각을 좁힘(한 원자에만 묶여 더 퍼짐)'을 못 박는다. 비공유쌍 수만큼 결합각이 줄어듦을 잡아라.", "cite": ""}, "GC-057": {"name": "분자 구조", "course": "gc", "unit": "분자-2", "tier": "A", "mis": ["네 결합쌍이 정사면체로 배치된다.", "비공유 전자쌍이 평면에서 벗어나게 한다.", "비공유 전자쌍 두 개 때문에 굽는다.", "중심에 비공유 전자쌍이 없다.", "비공유 전자쌍이 없어 평면이다.", "전자 영역이 4이고 비공유가 하나이다."], "dx": "전자쌍 배치(정사면체)와 실제 분자 모양(비공유쌍 때문에 굽음)을 구분하지 못한 경우다. 물·암모니아가 사면체 골격에서 굽은형·피라미드형이 되는 흐름이 흔들린다.", "fix": "'전자쌍 배치(정사면체)와 실제 분자 모양(비공유쌍 때문에 굽음)을 구분'함을 못 박는다. 물·암모니아가 사면체 골격에서 굽은형·피라미드형이 되는 흐름을 그려라.", "cite": ""}, "GC-058": {"name": "혼성 오비탈", "course": "gc", "unit": "분자-2", "tier": "C", "mis": ["정사면체는 sp^3이다.", "평면 삼각형은 sp^2이다.", "파이 결합 두 개를 위해 p 오비탈 둘이 남는다."], "dx": "혼성을 전자 영역 수와 연결하지 못한 경우다. 정사면체 sp³·평면삼각형 sp²·직선 sp, 그리고 남는 p 오비탈이 파이 결합을 만든다는 대응이 약하다.", "fix": "혼성을 '전자 영역 수와 짝: 정사면체 sp³·평면삼각형 sp²·직선 sp, 남는 p 오비탈이 파이 결합'으로 못 박는다. 영역 수에서 혼성을 바로 정하라.", "cite": ""}, "GC-059": {"name": "시그마·파이", "course": "gc", "unit": "분자-2", "tier": "A", "mis": ["첫 결합만 시그마이다.", "단일 결합은 시그마이다.", "첫 결합은 시그마이다.", "정면 겹침이 더 강하다.", "옆 겹침은 파이 결합이다.", "회전하면 옆 겹침이 깨진다."], "dx": "단일 결합은 시그마, 다중 결합의 첫 결합만 시그마이고 나머지가 파이라는 구분을 놓친 경우다. 결합 차수와 시그마·파이 개수의 관계가 흔들린다.", "fix": "'단일 결합은 시그마, 다중 결합은 첫 결합만 시그마이고 나머지가 파이'를 못 박는다. 결합 차수에서 시그마·파이 개수를 셈하라.", "cite": ""}, "GC-060": {"name": "분자 오비탈", "course": "gc", "unit": "분자-2", "tier": "C", "mis": ["결합 차수를 낮춘다.", "보강 겹침이 안정화한다.", "결합성과 반결합성 둘이 생긴다."], "dx": "분자 오비탈에서 보강 겹침(결합성)과 상쇄 겹침(반결합성)이 함께 생긴다는 점을 놓친 경우다. 원자 오비탈 수만큼 분자 오비탈이 나온다는 보존이 빠졌다.", "fix": "분자 오비탈을 '보강 겹침(결합성)과 상쇄 겹침(반결합성)이 함께 생기고, 원자 오비탈 수만큼 분자 오비탈이 나옴'으로 못 박는다. 둘을 짝으로 그려라.", "cite": ""}, "GC-061": {"name": "결합 차수", "course": "gc", "unit": "분자-2", "tier": "A", "mis": ["반결합성은 빼야 한다.", "알짜 결합이 없다.", "결합이 강해 가까워진다.", "결합성에서 반결합성을 뺀다.", "전자 수 차이가 홀수일 수 있다.", "강한 결합일수록 에너지가 크다."], "dx": "결합 차수=(결합성-반결합성)/2에서 반결합성 전자를 빼야 한다는 점을 놓친 경우다. 차수가 0이면 결합이 없다는 판단으로 이어지지 않는다.", "fix": "결합 차수를 '(결합성 − 반결합성)/2'로 못 박는다. 반결합성 전자를 빼야 함을 잡고, 차수가 0이면 결합이 없다고 판단하라.", "cite": ""}, "GC-062": {"name": "자기성", "course": "gc", "unit": "분자-2", "tier": "C", "mis": ["짝지은 스핀은 상쇄된다.", "홀전자가 자기성을 만든다.", "홀전자가 없어 자기성이 약하다."], "dx": "홀전자 유무로 자기성을 판단하는 연결을 놓친 경우다. 홀전자가 있으면 상자기성, 모두 짝지으면 반자기성이라는 대응이 흔들린다(MO로 O₂ 상자기성 설명).", "fix": "자기성을 '홀전자가 있으면 상자기성, 모두 짝지으면 반자기성'으로 못 박는다. MO로 O₂에 홀전자가 있어 상자기성임을 설명하라.", "cite": ""}, "GC-224": {"name": "방사성 붕괴", "course": "gc", "unit": "핵화학-1", "tier": "C", "mis": ["화학 반응이 아니라 핵 변화이다.", "불안정한 핵이 붕괴한다.", "양성자 수가 변할 수 있다."], "dx": "방사성 붕괴가 전자만 관여하는 화학 반응이 아니라 핵 자체가 변하는 변화라는 점을 놓친 경우다. 양성자 수가 바뀌어 다른 원소가 될 수 있다는 점이 약하다.", "fix": "방사성 붕괴를 '전자만 관여하는 화학 반응이 아니라 핵 자체가 변하는 변화'로 못 박는다. 양성자 수가 바뀌어 다른 원소가 될 수 있음을 잡아라.", "cite": ""}, "GC-225": {"name": "알파 붕괴", "course": "gc", "unit": "핵화학-1", "tier": "C", "mis": ["양성자 2개가 빠진다.", "질량수 4인 헬륨 핵이 방출된다.", "헬륨 핵이다."], "dx": "알파 붕괴가 헬륨 핵(⁴He, 양성자 2·중성자 2)을 방출해 질량수 4·원자번호 2가 줄어든다는 점을 놓친 경우다.", "fix": "알파 붕괴를 '헬륨 핵(⁴He, 양성자 2·중성자 2)을 방출해 질량수 4·원자번호 2가 줄어듦'으로 못 박는다. 방출 입자로 질량수·원자번호 변화를 셈하라.", "cite": ""}, "GC-226": {"name": "베타 붕괴", "course": "gc", "unit": "핵화학-1", "tier": "C", "mis": ["핵자 수가 유지된다.", "양성자가 하나 늘어난다.", "방향이 반대이다."], "dx": "베타(β⁻) 붕괴가 중성자 하나가 양성자로 바뀌며 전자를 방출해, 질량수는 그대로이고 원자번호가 1 늘어난다는 점을 놓친 경우다.", "fix": "베타(β⁻) 붕괴를 '중성자 하나가 양성자로 바뀌며 전자를 방출, 질량수는 그대로이고 원자번호가 1 늚'으로 못 박는다. 이 변화를 핵반응식에 반영하라.", "cite": ""}, "GC-227": {"name": "감마 붕괴", "course": "gc", "unit": "핵화학-1", "tier": "C", "mis": ["에너지만 방출한다.", "핵자 수가 유지된다.", "입자가 아니다."], "dx": "감마 붕괴가 입자가 아니라 에너지(전자기파)만 방출해 질량수·원자번호가 변하지 않는다는 점을 놓친 경우다. 들뜬 핵이 에너지를 내려놓는 과정이라는 점이 약하다.", "fix": "감마 붕괴를 '입자가 아니라 에너지(전자기파)만 방출해 질량수·원자번호가 변하지 않음'으로 못 박는다. 들뜬 핵이 에너지를 내려놓는 과정임을 잡아라.", "cite": ""}, "GC-228": {"name": "양전자 방출", "course": "gc", "unit": "핵화학-1", "tier": "C", "mis": ["양성자가 줄어든다.", "방향이 반대이다(β-와 반대).", "핵자 수가 유지된다."], "dx": "양전자(β⁺) 방출이 양성자 하나가 중성자로 바뀌며 양전자를 내보내, 질량수는 그대로이고 원자번호가 1 줄어든다는 점(β⁻와 반대)을 놓친 경우다.", "fix": "양전자(β⁺) 방출을 '양성자 하나가 중성자로 바뀌며 양전자를 내보내, 질량수는 그대로이고 원자번호가 1 줆(β⁻와 반대)'으로 못 박는다. 두 베타의 반대 방향을 잡아라.", "cite": ""}, "GC-229": {"name": "Z-N 그래프", "course": "gc", "unit": "핵화학-1", "tier": "C", "mis": ["전자가 아니라 핵자 분포이다.", "띠 형태로 분포한다.", "불안정한 핵이다."], "dx": "안정성 그래프의 축이 양성자 수(Z)와 중성자 수(N)이고, 안정한 핵이 띠(안정대) 형태로 분포한다는 점을 놓친 경우다. 전자 분포가 아니라는 점이 흔들린다.", "fix": "안정성 그래프를 '축이 양성자 수(Z)와 중성자 수(N), 안정한 핵이 띠(안정대) 형태로 분포'로 못 박는다. 전자 분포가 아님을 잡아라.", "cite": ""}, "GC-230": {"name": "안정성 비", "course": "gc", "unit": "핵화학-1", "tier": "C", "mis": ["비가 약 1:1이다.", "중성자가 더 많아야 안정하다.", "비가 거의 1:1이다."], "dx": "가벼운 핵은 중성자:양성자 비가 약 1:1에서 안정하고, 무거워질수록 중성자가 더 많아야 안정하다는 점을 놓친 경우다.", "fix": "'가벼운 핵은 중성자:양성자 비가 약 1:1에서 안정하고, 무거워질수록 중성자가 더 많아야 안정'함을 못 박는다. 이 비로 안정대의 휘어짐을 잡아라.", "cite": ""}, "GC-231": {"name": "붕괴 속도", "course": "gc", "unit": "핵화학-1", "tier": "C", "mis": ["남은 핵 수에 비례한다.", "1차 반응이다.", "1차 반응이라 일정하다."], "dx": "방사성 붕괴가 1차 반응이라 붕괴 속도가 남은 핵 수에 비례한다는 점을 놓친 경우다. 그래서 반감기가 일정하다는 점이 흔들린다.", "fix": "방사성 붕괴를 '1차 반응이라 붕괴 속도가 남은 핵 수에 비례'로 못 박는다. 그래서 반감기가 일정함을 잡아라.", "cite": ""}, "GC-232": {"name": "방사성 반감기", "course": "gc", "unit": "핵화학-1", "tier": "C", "mis": ["완전히가 아니라 절반이다.", "핵 고유의 값이다.", "1차 반응이라 양과 무관하다."], "dx": "반감기가 핵 수가 절반으로 줄어드는 데 걸리는 시간이고, 1차 반응이라 처음 양과 무관하게 핵 고유값이라는 점을 놓친 경우다. '완전히 사라짐'이 아니라 '절반'이라는 점이 흔들린다.", "fix": "반감기를 '핵 수가 절반으로 줄어드는 데 걸리는 시간, 1차 반응이라 처음 양과 무관한 핵 고유값'으로 못 박는다. '완전히 사라짐'이 아니라 '절반'임을 잡아라.", "cite": ""}, "GC-233": {"name": "반감기 계산", "course": "gc", "unit": "핵화학-1", "tier": "C", "mis": ["절반의 절반이다.", "곱이 아니라 거듭제곱이다.", "여전히 일부가 남는다."], "dx": "반감기가 지날 때마다 양이 절반씩 거듭 줄어(절반의 절반…) 거듭제곱으로 감소한다는 점을 놓친 경우다. 곱이 아니라 거듭제곱이고 여전히 일부가 남는다는 점이 약하다.", "fix": "반감기 계산을 '반감기가 지날 때마다 절반씩 거듭 줄어 거듭제곱으로 감소'로 못 박는다. 곱이 아니라 거듭제곱이고 여전히 일부가 남음을 잡아라.", "cite": ""}, "GC-234": {"name": "연대 측정", "course": "gc", "unit": "핵화학-2", "tier": "C", "mis": ["색이 아니라 붕괴를 이용한다.", "일정한 반감기가 시간 척도이다.", "붕괴하기 때문에 시간을 잴 수 있다."], "dx": "연대 측정이 일정한 반감기를 시간 척도로 삼아, 남은 방사성 동위원소 양으로 시간을 잰다는 원리를 놓친 경우다.", "fix": "연대 측정을 '일정한 반감기를 시간 척도로 삼아, 남은 방사성 동위원소 양으로 시간을 잼'으로 못 박는다. 반감기의 일정함이 시계가 됨을 잡아라.", "cite": ""}, "GC-235": {"name": "질량 결손", "course": "gc", "unit": "핵화학-2", "tier": "C", "mis": ["핵이 더 가볍다.", "질량이 줄어든다.", "질량이 생기는 것이 아니다."], "dx": "핵이 핵자들의 질량 합보다 가볍고(질량 결손), 그 줄어든 질량이 핵을 묶는 에너지로 바뀌었다는 점을 놓친 경우다. 질량이 생기는 게 아니라 줄어든다는 방향이 흔들린다.", "fix": "질량 결손을 '핵이 핵자들의 질량 합보다 가볍고, 그 줄어든 질량이 핵을 묶는 에너지로 바뀜'으로 못 박는다. 질량이 생기는 게 아니라 줆을 잡아라.", "cite": ""}, "GC-236": {"name": "질량-에너지", "course": "gc", "unit": "핵화학-2", "tier": "C", "mis": ["c의 제곱이 들어간다.", "질량-에너지 등가성 때문이다.", "c는 빛의 속도이다."], "dx": "질량과 에너지가 E=mc²로 등가이고 c(빛의 속도)의 제곱이 곱해져 작은 질량 변화도 큰 에너지가 된다는 점을 놓친 경우다.", "fix": "질량-에너지를 'E=mc²로 등가, c(빛의 속도)의 제곱이 곱해져 작은 질량 변화도 큰 에너지'로 못 박는다. c²의 크기로 핵에너지의 규모를 잡아라.", "cite": ""}, "GC-237": {"name": "핵 결합 에너지", "course": "gc", "unit": "핵화학-2", "tier": "C", "mis": ["형성 시 방출, 분리 시 필요하다.", "질량 결손이 에너지원이다.", "클수록 안정하다."], "dx": "핵 결합 에너지가 핵을 핵자로 분리하는 데 필요한(형성 시 방출되는) 에너지이고, 질량 결손이 그 에너지원이라는 점을 놓친 경우다. 클수록 안정하다는 방향이 약하다.", "fix": "핵 결합 에너지를 '핵을 핵자로 분리하는 데 필요한(형성 시 방출되는) 에너지, 질량 결손이 그 에너지원'으로 못 박는다. 클수록 안정함을 잡아라.", "cite": ""}, "GC-238": {"name": "핵자당 결합 에너지", "course": "gc", "unit": "핵화학-2", "tier": "C", "mis": ["클수록 안정하다.", "철 부근이 최대이다.", "단조 증가가 아니다."], "dx": "핵자당 결합 에너지가 클수록 안정하고 철(Fe) 부근에서 최대라는 점을 놓친 경우다. 질량수에 따라 단조 증가가 아니라 봉우리 형태라는 점이 흔들린다.", "fix": "핵자당 결합 에너지를 '클수록 안정하고 철(Fe) 부근에서 최대'로 못 박는다. 질량수에 따라 단조 증가가 아니라 봉우리 형태임을 잡아라.", "cite": ""}, "GC-239": {"name": "핵분열", "course": "gc", "unit": "핵화학-2", "tier": "C", "mis": ["합쳐지는 것은 핵융합이다.", "더 안정한 핵으로 가며 에너지를 낸다.", "질량 결손이 에너지로 바뀐다."], "dx": "핵분열이 무거운 핵이 더 안정한(핵자당 결합 에너지가 큰) 핵들로 쪼개지며 질량 결손만큼 에너지를 낸다는 점을 놓친 경우다. 합쳐지는 핵융합과 방향이 반대다.", "fix": "핵분열을 '무거운 핵이 더 안정한(핵자당 결합 에너지가 큰) 핵들로 쪼개지며 질량 결손만큼 에너지를 냄'으로 못 박는다. 합쳐지는 핵융합과 방향이 반대임을 잡아라.", "cite": ""}, "GC-240": {"name": "핵융합", "course": "gc", "unit": "핵화학-2", "tier": "C", "mis": ["쪼개지는 것은 핵분열이다.", "더 안정한 핵으로 가며 에너지를 낸다."], "dx": "핵융합이 가벼운 핵들이 더 안정한 핵으로 합쳐지며 에너지를 낸다는 점을 놓친 경우다. 쪼개지는 핵분열과 방향이 반대라는 구분이 흔들린다.", "fix": "핵융합을 '가벼운 핵들이 더 안정한 핵으로 합쳐지며 에너지를 냄'으로 못 박는다. 쪼개지는 핵분열과 방향이 반대임을 잡아라.", "cite": ""}, "GC-241": {"name": "핵에너지", "course": "gc", "unit": "핵화학-2", "tier": "C", "mis": ["질량-에너지 전환 때문이다.", "화학 결합이 아니라 핵 변화이다.", "질량 변화가 훨씬 크다."], "dx": "핵에너지가 화학 결합이 아니라 핵 변화의 질량-에너지 전환에서 나오고, 질량 변화가 화학 반응보다 훨씬 커 에너지도 훨씬 크다는 점을 놓친 경우다.", "fix": "핵에너지를 '화학 결합이 아니라 핵 변화의 질량-에너지 전환에서 나옴'으로 못 박는다. 질량 변화가 화학 반응보다 훨씬 커 에너지도 훨씬 큼을 잡아라.", "cite": ""}, "GC-242": {"name": "안정화 경향", "course": "gc", "unit": "핵화학-2", "tier": "C", "mis": ["방향이 뒤바뀌었다.", "가벼운 핵은 융합한다.", "핵자당 결합 에너지가 큰 쪽으로 간다."], "dx": "핵 반응이 핵자당 결합 에너지가 큰(더 안정한) 쪽으로 진행한다는 방향을 놓친 경우다. 가벼운 핵은 융합으로, 무거운 핵은 분열로 철 부근의 안정점에 가까워진다는 점이 흔들린다.", "fix": "핵 반응을 '핵자당 결합 에너지가 큰(더 안정한) 쪽으로 진행'으로 못 박는다. 가벼운 핵은 융합으로, 무거운 핵은 분열로 철 부근의 안정점에 가까워짐을 잡아라.", "cite": ""}, "GC-036": {"name": "족과 원자가 전자", "course": "gc", "unit": "주기성", "tier": "C", "mis": ["같은 족은 원자가 전자 수가 같아서 성질이 비슷하다.", "원자가 전자 수가 같은 것은 같은 족이다.", "주기는 전자 껍질 수, 족이 원자가 전자 수와 관련된다."], "dx": "같은 족=원자가 전자 수가 같아 성질이 비슷하다는 연결과, 주기는 껍질 수·족은 원자가 전자 수라는 대응이 흔들린 경우다. 주기율표 위치와 전자 배치의 다리가 약하다.", "fix": "'같은 족 = 원자가 전자 수가 같아 성질 비슷, 주기는 껍질 수·족은 원자가 전자 수'를 못 박는다. 주기율표 위치와 전자 배치를 이 대응으로 이으라.", "cite": ""}, "GC-037": {"name": "전자 배치와 위치", "course": "gc", "unit": "주기성", "tier": "C", "mis": ["원자가 전자 수는 족과 관련된다.", "원자가 전자 배치가 족을 결정한다.", "주기가 같으면 최외각 껍질 번호가 같다."], "dx": "원자가 전자 배치가 족을, 최외각 껍질 번호가 주기를 정한다는 대응을 놓친 경우다. 전자 배치로 주기율표 위치를 역추적하지 못한다.", "fix": "'원자가 전자 배치가 족을, 최외각 껍질 번호가 주기를 정함'을 못 박는다. 전자 배치로 주기율표 위치를 역추적하라.", "cite": ""}, "GC-038": {"name": "원자 반지름", "course": "gc", "unit": "주기성", "tier": "B", "mis": ["유효 핵전하가 커져 반지름이 줄어든다.", "전자 껍질 수가 늘어 반지름이 커진다.", "전자를 잃어 반지름이 작아진다.", "전자 수가 늘어 반발로 반지름이 커진다."], "dx": "원자 반지름 경향을 두 인자로 분리하지 못한 경우다. 같은 주기는 유효 핵전하 증가로 감소, 같은 족은 껍질 수 증가로 증가라는 두 축이 섞였다.", "fix": "원자 반지름을 '같은 주기는 유효 핵전하 증가로 감소, 같은 족은 껍질 수 증가로 증가'의 두 축으로 못 박는다. 두 인자를 갈라 위치별 반지름을 잡아라.", "cite": ""}, "GC-039": {"name": "이온화 에너지", "course": "gc", "unit": "주기성", "tier": "A", "mis": ["바깥 전자가 핵에서 멀어 떼기 쉬워진다.", "오른쪽으로 갈수록 유효 핵전하가 커진다.", "Be의 꽉 찬 2s 배치가 더 안정하다.", "N의 반쪽 채워진 2p 배치가 더 안정하다.", "기체 상태 바닥상태 원자에서 전자를 뗀다.", "전자를 떼는 데 큰 에너지가 들면 양이온이 되기 어렵다."], "dx": "이온화 에너지 경향에서 유효 핵전하 효과를 놓친 경우다. 오른쪽·위로 갈수록 커지며, Be·N 같은 안정 배치에서의 예외적 꺾임이 빠졌다.", "fix": "이온화 에너지를 '유효 핵전하 때문에 오른쪽·위로 갈수록 커짐, Be·N 같은 안정 배치에서 예외적 꺾임'으로 못 박는다. 유효 핵전하를 축으로 잡고 예외를 따로 새겨라.", "cite": ""}, "GC-040": {"name": "순차 이온화 에너지", "course": "gc", "unit": "주기성", "tier": "C", "mis": ["양전하가 커져 전자를 떼기 더 어렵다.", "남은 전자에 대한 인력이 점점 커진다.", "안정한 안쪽 껍질 전자를 떼야 해서 급증한다."], "dx": "순차 이온화에서 전자를 뗄수록 남은 전자 인력이 커져 에너지가 점증하고, 안쪽 껍질로 넘어갈 때 급증한다는 점을 놓친 경우다. 이 급증 위치가 원자가 전자 수를 알려준다.", "fix": "순차 이온화 에너지를 '전자를 뗄수록 점증하고, 안쪽 껍질로 넘어갈 때 급증'으로 못 박는다. 이 급증 위치가 원자가 전자 수를 알려줌을 잡아라.", "cite": ""}, "GC-041": {"name": "전기음성도", "course": "gc", "unit": "주기성", "tier": "A", "mis": ["최외각 전자가 멀어져 당기는 힘이 약해진다.", "오른쪽으로 갈수록 유효 핵전하가 커진다.", "플루오린이 가장 강하게 전자를 당긴다.", "전자쌍이 치우치지 않아 무극성이다.", "금속은 전자를 잃기 쉬워 전기음성도가 작다.", "전자쌍이 한쪽으로 더 치우쳐 극성이 커진다."], "dx": "전기음성도를 결합에서 전자를 당기는 힘으로 잡되, 유효 핵전하·반지름과의 관계와 F가 최대라는 점이 흔들린 경우다.", "fix": "전기음성도를 '결합에서 전자를 당기는 힘, 유효 핵전하가 크고 반지름이 작을수록 커짐(F가 최대)'으로 못 박는다. 유효 핵전하·반지름과 묶어 경향을 잡아라.", "cite": ""}, "GC-042": {"name": "등전자 이온", "course": "gc", "unit": "주기성", "tier": "C", "mis": ["핵전하가 크면 전자를 더 세게 당겨 작아진다.", "전자 수가 같아야 등전자 관계이다.", "양성자 수가 많을수록 반지름이 작다."], "dx": "등전자 이온(전자 수 동일) 비교에서 핵전하가 클수록 더 세게 당겨 반지름이 작아진다는 점을 놓친 경우다. 전자 수가 같아야 등전자 관계라는 전제도 흔들린다.", "fix": "등전자 이온을 '전자 수가 같으면 핵전하가 클수록 더 세게 당겨 반지름이 작아짐'으로 못 박는다. 전자 수가 같아야 등전자 관계임을 전제로 핵전하로 반지름을 비교하라.", "cite": ""}, "GC-019": {"name": "주양자수", "course": "gc", "unit": "양자수", "tier": "C", "mis": ["n의 최솟값은 1이다.", "바깥 껍질일수록 에너지가 크다.", "모양은 방위 양자수 l이 결정한다."], "dx": "주양자수 n의 의미(껍질·에너지 크기)와 범위(최솟값 1)를 놓친 경우다. n이 클수록 에너지가 높고 핵에서 멀다는 연결이 약하다.", "fix": "주양자수 n을 '껍질·에너지 크기를 정함, 최솟값 1, n이 클수록 에너지 높고 핵에서 멂'으로 못 박는다. n으로 껍질과 에너지 규모를 잡아라.", "cite": ""}, "GC-020": {"name": "방위양자수", "course": "gc", "unit": "양자수", "tier": "C", "mis": ["방향은 자기 양자수 ml이 나타낸다.", "l은 0에서 시작해 n-1에서 끝난다.", "껍질은 주양자수 n이 나타낸다."], "dx": "방위양자수 l이 오비탈 모양을 정하고 0부터 n-1까지라는 점을 놓친 경우다. 방향을 정하는 mₗ과 역할을 섞었다.", "fix": "방위양자수 l을 '오비탈 모양을 정함, 0부터 n-1까지'로 못 박는다. 방향을 정하는 mₗ과 갈라 모양은 l로 잡아라.", "cite": ""}, "GC-021": {"name": "자기양자수", "course": "gc", "unit": "양자수", "tier": "C", "mis": ["모양은 방위 양자수 l이 정한다.", "음수 값도 포함한다.", "스핀은 스핀 양자수 ms이다."], "dx": "자기양자수 mₗ이 오비탈의 공간 방향을 정하고 -l부터 +l까지(0·음수 포함)라는 점이 흔들린 경우다. 모양을 정하는 l과 혼동했다.", "fix": "자기양자수 mₗ을 '오비탈의 공간 방향을 정함, -l부터 +l까지(0·음수 포함)'로 못 박는다. 모양을 정하는 l과 혼동 말고 방향은 mₗ로 잡아라.", "cite": ""}, "GC-022": {"name": "스핀양자수", "course": "gc", "unit": "양자수", "tier": "A", "mis": ["전자 스핀은 ±1/2이다.", "정수가 아니라 ±1/2이다.", "같은 스핀이면 배타 원리에 어긋난다.", "스핀이 두 가지뿐이다.", "파울리 배타 원리에 따라 모두 같을 수 없다.", "방향은 자기 양자수 ml이다."], "dx": "전자 스핀을 정수로 보거나 값을 헷갈린 경우다. mₛ는 +1/2·-1/2 두 값뿐이라는 점이 빠졌다.", "fix": "스핀양자수 mₛ을 '+1/2와 -1/2 두 값뿐'으로 못 박는다. 정수로 보지 말고 두 반정수 값만 써라.", "cite": ""}, "GC-023": {"name": "양자수 범위", "course": "gc", "unit": "양자수", "tier": "A", "mis": ["최댓값은 n이 아니라 n-1이다.", "음수 방향도 포함한다.", "n=0은 존재하지 않는다.", "l은 0부터 n-1=0까지이다.", "ml이 -l부터 +l까지라 (2l+1)개이다.", "오비탈 수는 n^2이다."], "dx": "양자수 간 종속 범위를 놓친 경우다. l의 최댓값은 n이 아니라 n-1, mₗ은 -l부터 +l까지라는 제약이 정리되지 않았다.", "fix": "양자수 종속 범위를 'l의 최댓값은 n이 아니라 n-1, mₗ은 -l부터 +l까지'로 못 박는다. n, l, mₗ 순으로 제약을 따라 가능한 양자수 조합을 가려라.", "cite": ""}, "GC-024": {"name": "오비탈 기호", "course": "gc", "unit": "양자수", "tier": "C", "mis": ["s는 l=0이고 p가 l=1이다.", "p는 l=1, d가 l=2이다.", "l=2는 d, l=3이 f이다."], "dx": "오비탈 기호와 l 값의 대응을 헷갈린 경우다. s=0·p=1·d=2·f=3이라는 짝이 흔들린다.", "fix": "오비탈 기호와 l을 's=0·p=1·d=2·f=3'으로 짝지어 못 박는다. 이 대응으로 기호에서 l을, l에서 기호를 옮겨라.", "cite": ""}, "GC-025": {"name": "오비탈 수", "course": "gc", "unit": "양자수", "tier": "B", "mis": ["p는 3개, d는 5개이다.", "l=0이라 오비탈이 1개이다.", "l=2이라 (2l+1)=5이다.", "l=3이라 (2l+1)=7이다."], "dx": "부껍질별 오비탈 수를 놓친 경우다. s 1·p 3·d 5·f 7(=2l+1)이라는 셈이 안 잡혔다.", "fix": "부껍질별 오비탈 수를 's 1·p 3·d 5·f 7(=2l+1)'로 못 박는다. 2l+1로 오비탈 수를, 그 두 배로 최대 전자 수를 셈하라.", "cite": ""}, "GC-026": {"name": "오비탈 모양", "course": "gc", "unit": "양자수", "tier": "C", "mis": ["아령형은 p 오비탈이다.", "구형은 s 오비탈이다.", "고정된 궤도가 아니다."], "dx": "오비탈 모양과 종류의 대응을 헷갈린 경우다. s는 구형, p는 아령형이라는 기본 그림이 흐리다.", "fix": "오비탈 모양을 's는 구형, p는 아령형'으로 못 박는다. 기본 그림을 잡아 모양과 종류를 짝지어라.", "cite": ""}, "GC-158": {"name": "산화·환원 정의", "course": "gc", "unit": "산화환원평형-1", "tier": "C", "mis": ["전자를 얻는 것은 환원이다.", "전자를 잃는 것은 산화이다.", "산화수가 커지는 것이 산화이다."], "dx": "산화(전자 잃음·산화수 증가)와 환원(전자 얻음·산화수 감소)의 대응을 헷갈린 경우다. 전자 이동 방향과 산화수 변화가 한 묶음이라는 점이 약하다.", "fix": "'산화 = 전자 잃음·산화수 증가, 환원 = 전자 얻음·산화수 감소'로 못 박는다. 전자 이동 방향과 산화수 변화를 한 묶음으로 잡아라.", "cite": ""}, "GC-159": {"name": "산화 정의", "course": "gc", "unit": "산화환원평형-1", "tier": "C", "mis": ["전자를 얻는 것은 환원이다.", "산화수가 커진다.", "전자 손실이 산화이다."], "dx": "산화가 전자를 잃고 산화수가 커지는 것이라는 정의를 놓친 경우다. 전자 손실=산화라는 핵심이 흔들린다.", "fix": "산화를 '전자를 잃고 산화수가 커지는 것'으로 못 박는다. 전자 손실=산화라는 핵심을 잡아라.", "cite": ""}, "GC-160": {"name": "동시성", "course": "gc", "unit": "산화환원평형-1", "tier": "C", "mis": ["전자를 주고받아야 한다.", "전자를 주는 쪽이 있어야 한다.", "전자 이동으로 연결된다."], "dx": "산화와 환원이 항상 짝으로(전자를 주는 쪽과 받는 쪽이 동시에) 일어난다는 점을 놓친 경우다. 한쪽만 단독으로 일어날 수 없다는 점이 약하다.", "fix": "'산화와 환원은 항상 짝으로(전자를 주는 쪽과 받는 쪽이 동시에) 일어남'을 못 박는다. 한쪽만 단독으로 일어날 수 없음을 잡아라.", "cite": ""}, "GC-161": {"name": "산화수 규칙", "course": "gc", "unit": "산화환원평형-1", "tier": "C", "mis": ["부호가 뒤바뀌었다.", "홑원소는 0이다.", "전하가 0이다."], "dx": "산화수 규칙을 헷갈린 경우다. 홑원소 0, 단원자 이온은 그 전하, 화합물 전체 합은 0(이온은 전하)이라는 기준이 흔들린다.", "fix": "산화수 규칙을 '홑원소 0, 단원자 이온은 그 전하, 화합물 전체 합은 0(이온은 전하)'으로 못 박는다. 이 기준으로 모르는 원자의 산화수를 역산하라.", "cite": ""}, "GC-162": {"name": "산화제·환원제", "course": "gc", "unit": "산화환원평형-1", "tier": "C", "mis": ["환원제는 자신이 산화된다.", "역할이 뒤바뀌었다.", "전자를 받아야 상대를 산화시킨다."], "dx": "산화제(자신은 환원되며 상대를 산화)와 환원제(자신은 산화되며 상대를 환원)의 역할을 뒤바꾼 경우다. 전자를 받는 쪽이 산화제라는 점이 약하다.", "fix": "'산화제는 자신이 환원되며 상대를 산화, 환원제는 자신이 산화되며 상대를 환원'으로 못 박는다. 전자를 받는 쪽이 산화제임을 잡아 역할을 뒤바꾸지 마라.", "cite": ""}, "GC-163": {"name": "전자 보존", "course": "gc", "unit": "산화환원평형-1", "tier": "C", "mis": ["전자는 보존된다.", "사라지지 않는다.", "잃은 전자 = 얻은 전자이다."], "dx": "산화환원에서 잃은 전자 수=얻은 전자 수로 전자가 보존된다는 점을 놓친 경우다. 반쪽 반응 균형의 근거가 흔들린다.", "fix": "'산화환원에서 잃은 전자 수 = 얻은 전자 수로 전자가 보존'됨을 못 박는다. 이를 반쪽 반응 균형의 근거로 삼아라.", "cite": ""}, "GC-164": {"name": "갈바니 전지", "course": "gc", "unit": "산화환원평형-1", "tier": "C", "mis": ["자발 반응을 이용한다.", "방향이 반대이며, 그 반대는 전기분해이다.", "외부 전원은 전기분해에 필요하다."], "dx": "갈바니(볼타) 전지가 자발 반응으로 전기를 만든다는 점을 놓친 경우다. 외부 전원으로 비자발 반응을 강제하는 전기분해와 방향이 반대라는 구분이 약하다.", "fix": "갈바니(볼타) 전지를 '자발 반응으로 전기를 만듦'으로 못 박는다. 외부 전원으로 비자발 반응을 강제하는 전기분해와 방향이 반대임을 잡아라.", "cite": ""}, "GC-165": {"name": "전극 극성", "course": "gc", "unit": "산화환원평형-1", "tier": "C", "mis": ["산화는 (-)극에서 일어난다.", "환원은 (+)극에서 일어난다.", "환원전극이 (+)극이다."], "dx": "갈바니 전지에서 산화전극(-)·환원전극(+)이라는 극성 대응을 헷갈린 경우다. 산화는 (-)극, 환원은 (+)극에서 일어난다는 점이 흔들린다.", "fix": "갈바니 전지에서 '산화전극 (-)·환원전극 (+)'를 못 박는다. 산화는 (-)극, 환원은 (+)극에서 일어남을 잡아라.", "cite": ""}, "GC-166": {"name": "전자 흐름", "course": "gc", "unit": "산화환원평형-1", "tier": "C", "mis": ["방향이 반대이다.", "전류는 양전하 흐름으로 정의된다.", "산화전극에서 환원전극으로 간다."], "dx": "전자가 산화전극에서 환원전극으로 도선을 따라 흐른다는 방향을 놓친 경우다. 전류는 그 반대(양전하 흐름)로 정의된다는 점도 흔들린다.", "fix": "'전자가 산화전극에서 환원전극으로 도선을 따라 흐름'을 못 박는다. 전류는 그 반대(양전하 흐름)로 정의됨도 잡아라.", "cite": ""}, "GC-167": {"name": "염다리", "course": "gc", "unit": "산화환원평형-1", "tier": "C", "mis": ["전자는 도선으로 흐른다.", "용액을 섞는 것이 아니다.", "전하가 쌓이기 때문이다."], "dx": "염다리가 전하 쏠림을 막아 회로를 유지한다는 역할을 놓친 경우다. 전자는 도선으로 흐르고 염다리는 이온으로 전기적 중성을 지킨다는 구분이 약하다.", "fix": "염다리를 '전하 쏠림을 막아 회로를 유지'로 못 박는다. 전자는 도선으로 흐르고 염다리는 이온으로 전기적 중성을 지킴을 갈라라.", "cite": ""}, "GC-168": {"name": "표준 수소 전극", "course": "gc", "unit": "산화환원평형-1", "tier": "C", "mis": ["기준값은 0 V이다.", "표준 수소 전극 기준의 값이다."], "dx": "표준 수소 전극을 0 V 기준으로 삼아 다른 전극 전위를 정한다는 점을 놓친 경우다. 절대값이 아니라 기준 대비 상대값이라는 점이 흔들린다.", "fix": "표준 수소 전극을 '0 V 기준으로 삼아 다른 전극 전위를 정함'으로 못 박는다. 절대값이 아니라 기준 대비 상대값임을 잡아라.", "cite": ""}, "GC-169": {"name": "전지 전위", "course": "gc", "unit": "산화환원평형-1", "tier": "C", "mis": ["환원극에서 산화극을 뺀다.", "양수일 때 자발적이다.", "더하는 것이 아니라 뺀다."], "dx": "표준 전지 전위 = (환원전극 전위) - (산화전극 전위)로 빼서 구하고, 값이 양수면 자발적이라는 점을 놓친 경우다.", "fix": "표준 전지 전위를 '(환원전극 전위) − (산화전극 전위)로 빼서 구함, 값이 양수면 자발'로 못 박는다. 빼는 순서를 맞춰 자발성을 잡아라.", "cite": ""}, "GC-170": {"name": "자발성", "course": "gc", "unit": "산화환원평형-2", "tier": "C", "mis": ["양수일 때 자발적이다.", "음수면 비자발적이다.", "양수면 자발, 음수면 비자발이다."], "dx": "전지 전위가 양수면 자발, 음수면 비자발이라는 대응을 놓친 경우다. E°의 부호가 반응 방향을 알려준다는 점이 흔들린다.", "fix": "'전지 전위가 양수면 자발, 음수면 비자발'임을 못 박는다. E°의 부호가 반응 방향을 알려줌을 잡아라.", "cite": ""}, "GC-171": {"name": "표준 환원 전위", "course": "gc", "unit": "산화환원평형-2", "tier": "C", "mis": ["전자를 잘 받아 산화제로 작용한다.", "전위가 클수록 환원 경향이 크다.", "환원이 잘 일어나는 쪽이다."], "dx": "표준 환원 전위가 클수록 환원이 잘 일어나(전자를 잘 받아 산화제로 작용)는 경향이 크다는 점을 놓친 경우다. 전위 크기와 환원 경향의 방향이 흔들린다.", "fix": "'표준 환원 전위가 클수록 환원이 잘 일어나(전자를 잘 받아 산화제로 작용)는 경향이 큼'을 못 박는다. 전위 크기로 환원 경향·산화제 세기를 잡아라.", "cite": ""}, "GC-172": {"name": "자유 에너지와 전위", "course": "gc", "unit": "산화환원평형-2", "tier": "A", "mis": ["음의 부호가 붙는다.", "음의 부호 때문이다.", "ΔG° = -nFE°이다.", "음의 부호로 연결된다.", "n은 전자 몰수이다.", "음의 부호로 부호가 뒤집힌다."], "dx": "ΔG° = -nFE°에서 음의 부호 때문에 E°>0이면 ΔG°<0(자발)이라는 연결을 놓친 경우다. n은 이동 전자 몰수, F는 패러데이 상수라는 점이 약하다.", "fix": "'ΔG° = -nFE°라 음의 부호 때문에 E°>0이면 ΔG°<0(자발)'임을 못 박는다. n은 이동 전자 몰수, F는 패러데이 상수임을 잡아라.", "cite": ""}, "GC-173": {"name": "네른스트 식", "course": "gc", "unit": "산화환원평형-2", "tier": "C", "mis": ["평형에서 전위가 0이다.", "농도가 표준과 다를 때 쓴다.", "평형을 향해 줄어든다."], "dx": "네른스트 식이 농도가 표준과 다를 때 전위를 보정하고, 평형에서 전위가 0이 된다는 점을 놓친 경우다. 반응이 평형을 향하며 전위가 줄어든다는 흐름이 약하다.", "fix": "네른스트 식을 '농도가 표준과 다를 때 전위를 보정하고, 평형에서 전위가 0이 됨'으로 못 박는다. 반응이 평형을 향하며 전위가 줄어드는 흐름을 잡아라.", "cite": ""}, "GC-174": {"name": "전기분해", "course": "gc", "unit": "산화환원평형-2", "tier": "C", "mis": ["전기를 만드는 것은 갈바니 전지이다.", "방향이 반대이다.", "비자발 반응을 강제해야 한다."], "dx": "전기분해가 외부 전원으로 비자발 반응을 강제하는 것이라는 점을 놓친 경우다. 전기를 만드는 갈바니 전지와 방향이 반대라는 구분이 흔들린다.", "fix": "전기분해를 '외부 전원으로 비자발 반응을 강제'로 못 박는다. 전기를 만드는 갈바니 전지와 방향이 반대임을 잡아라.", "cite": ""}, "GC-175": {"name": "전기분해 전극", "course": "gc", "unit": "산화환원평형-2", "tier": "C", "mis": ["(-)극 연결 전극은 환원전극이다.", "(+)극 연결 전극은 산화전극이다.", "산화와 환원이 짝으로 일어난다."], "dx": "전기분해에서 (-)극 연결 전극이 환원, (+)극 연결 전극이 산화라는 대응을 놓친 경우다. 산화·환원이 두 전극에서 짝으로 일어난다는 점이 약하다.", "fix": "전기분해에서 '(-)극에 연결된 전극이 환원, (+)극에 연결된 전극이 산화'임을 못 박는다. 산화·환원이 두 전극에서 짝으로 일어남을 잡아라.", "cite": ""}, "GC-176": {"name": "패러데이 법칙", "course": "gc", "unit": "산화환원평형-2", "tier": "C", "mis": ["전하량이 석출량을 정한다.", "전류가 전하량을 정한다.", "석출량이 전하량에 비례한다."], "dx": "석출량이 흘려준 전하량에 비례한다는 패러데이 법칙을 놓친 경우다. 전하량=전류×시간(Q=It)이라는 연결이 흔들린다.", "fix": "패러데이 법칙을 '석출량이 흘려준 전하량에 비례'로 못 박는다. 전하량 = 전류 × 시간(Q=It)으로 전하량을 구하라.", "cite": ""}, "GC-177": {"name": "패러데이 상수", "course": "gc", "unit": "산화환원평형-2", "tier": "C", "mis": ["1개가 아니라 1몰이다.", "Q = It이다.", "값은 96500 C/mol이다."], "dx": "패러데이 상수가 전자 1몰의 전하(약 96500 C/mol)라는 점을 놓친 경우다. 전자 1개가 아니라 1몰 기준이고, Q=It로 전하량을 구한다는 점이 약하다.", "fix": "패러데이 상수를 '전자 1몰의 전하(약 96500 C/mol)'로 못 박는다. 전자 1개가 아니라 1몰 기준이고, Q=It로 전하량을 구함을 잡아라.", "cite": ""}, "GC-178": {"name": "패러데이 계산", "course": "gc", "unit": "산화환원평형-2", "tier": "C", "mis": ["+2가는 전자가 두 배 필요하다.", "전하수가 2이기 때문이다.", "전하수로 나누어 정해진다."], "dx": "석출량 계산에서 이온의 전하수만큼 전자가 필요하다는 점을 놓친 경우다. +2가 이온은 같은 몰을 석출하는 데 전자가 두 배 든다는 비례가 흔들린다.", "fix": "'석출에 이온의 전하수만큼 전자가 필요'함을 못 박는다. +2가 이온은 같은 몰을 석출하는 데 전자가 두 배 듦을 잡아라.", "cite": ""}, "GC-179": {"name": "환원제", "course": "gc", "unit": "산화환원평형-2", "tier": "C", "mis": ["환원제는 자신이 산화된다.", "전자를 주어 상대를 환원시킨다.", "전자를 잃어 산화수가 커진다."], "dx": "환원제가 전자를 주어 상대를 환원시키고 자신은 산화(산화수 증가)된다는 점을 놓친 경우다. 역할과 자기 변화 방향이 뒤섞였다.", "fix": "환원제를 '전자를 주어 상대를 환원시키고 자신은 산화(산화수 증가)됨'으로 못 박는다. 역할과 자기 변화 방향을 갈라 잡아라.", "cite": ""}, "GC-199": {"name": "산화제", "course": "gc", "unit": "산화환원평형-2", "tier": "C", "mis": ["역할이 뒤바뀌었다.", "전자를 받아 상대를 산화시킨다.", "전자를 얻어 산화수가 작아진다."], "dx": "산화제가 전자를 받아 상대를 산화시키고 자신은 환원(산화수 감소)된다는 점을 놓친 경우다. 환원제와 역할이 뒤바뀌었다.", "fix": "산화제를 '전자를 받아 상대를 산화시키고 자신은 환원(산화수 감소)됨'으로 못 박는다. 환원제와 역할을 뒤바꾸지 마라.", "cite": ""}, "GC-084": {"name": "끓는점 오름·어는점 내림", "course": "gc", "unit": "물질의상태-총괄성", "tier": "C", "mis": ["끓는점 오름이 일어난다.", "ΔTf = Kf·m이다.", "농도에 비례한다."], "dx": "끓는점 오름·어는점 내림이 몰랄 농도에 비례한다(ΔT = K·m)는 점을 놓친 경우다. 상수 K가 용매 고유값이고 두 현상의 방향(오름 대 내림)이 흔들린다.", "fix": "끓는점 오름·어는점 내림을 'ΔT = K·m, K는 용매 고유값'으로 못 박는다. 끓는점은 오르고 어는점은 내리는 방향을 갈라 잡아라.", "cite": ""}, "GC-085": {"name": "삼투압", "course": "gc", "unit": "물질의상태-총괄성", "tier": "A", "mis": ["농도를 맞추는 방향이다.", "π = MRT이다.", "R와 T는 곱해진다.", "종류가 아니라 입자 수이다.", "몰 농도가 클수록 크다."], "dx": "삼투압 π = MRT(M은 몰 농도)에서 R·T가 곱해진다는 점, 그리고 농도를 맞추는(묽은 쪽에서 진한 쪽으로) 방향을 놓친 경우다.", "fix": "삼투압을 'π = MRT, M은 몰 농도'로 못 박는다. R·T가 곱해짐을 잡고 용매가 묽은 쪽에서 진한 쪽으로 가는 방향을 새겨라.", "cite": ""}, "GC-086": {"name": "반트호프 인자", "course": "gc", "unit": "물질의상태-총괄성", "tier": "C", "mis": ["입자가 나뉘지 않는다.", "입자 수가 많아진다.", "이온으로 나뉘기 때문이다."], "dx": "반트호프 인자 i가 용질 1몰이 내놓는 입자 수라는 점을 놓친 경우다. 비전해질은 i=1, 전해질은 이온 수만큼 커져 총괄성이 배가된다는 연결이 약하다.", "fix": "반트호프 인자 i를 '용질 1몰이 내놓는 입자 수'로 못 박는다. 비전해질은 i=1, 전해질은 이온 수만큼 커져 총괄성이 배가됨을 잡아라.", "cite": ""}, "GC-087": {"name": "증기압 내림", "course": "gc", "unit": "물질의상태-총괄성", "tier": "B", "mis": ["용매 몰분율이 줄어든다.", "용질이 많을수록 더 내려간다.", "표면 용매 분자가 감소한다.", "총괄성은 입자 수에 비례한다."], "dx": "증기압 내림이 표면의 용매 분자 비율(용매 몰분율)이 줄어 생긴다는 메커니즘을 놓친 경우다. 용질이 많을수록 더 내려간다는 방향이 흔들린다.", "fix": "증기압 내림을 '표면의 용매 분자 비율(용매 몰분율)이 줄어 생김'으로 못 박는다. 용질이 많을수록 더 내려가는 방향을 잡아라.", "cite": ""}, "GC-088": {"name": "몰랄 상수", "course": "gc", "unit": "물질의상태-총괄성", "tier": "C", "mis": ["용질이 아니라 용매의 값이다.", "용매 고유의 상수이다.", "용매의 성질이다."], "dx": "끓는점 오름·어는점 내림 상수가 용질이 아니라 용매의 고유 성질이라는 점을 놓친 경우다. 같은 용매면 어떤 용질이든 같은 상수를 쓴다는 점이 빠졌다.", "fix": "끓는점 오름·어는점 내림 상수를 '용질이 아니라 용매의 고유 성질'로 못 박는다. 같은 용매면 어떤 용질이든 같은 상수를 씀을 잡아라.", "cite": ""}, "GC-089": {"name": "전해질 비교", "course": "gc", "unit": "물질의상태-총괄성", "tier": "C", "mis": ["NaCl이 이온으로 나뉘어 입자 수가 많다.", "전해질이 이온으로 나뉜다.", "NaCl의 입자 수가 더 많다."], "dx": "같은 농도라도 전해질(예: NaCl)은 이온으로 나뉘어 입자 수가 더 많아 총괄성이 크다는 점을 놓친 경우다. 반트호프 인자로 비교해야 한다는 연결이 약하다.", "fix": "'같은 농도라도 전해질(NaCl)은 이온으로 나뉘어 입자 수가 더 많아 총괄성이 큼'을 못 박는다. 반트호프 인자로 비교해야 함을 잡아라.", "cite": ""}, "GC-090": {"name": "용해성 규칙", "course": "gc", "unit": "물질의상태-총괄성", "tier": "C", "mis": ["성질이 비슷한 것끼리 잘 녹는다.", "무극성끼리 잘 섞인다.", "무극성과 극성은 섞이지 않는다."], "dx": "'비슷한 것끼리 잘 녹는다'(극성끼리·무극성끼리)는 규칙을 놓친 경우다. 극성과 무극성은 잘 섞이지 않는다는 방향이 흔들린다.", "fix": "용해성을 '비슷한 것끼리 잘 녹음(극성끼리·무극성끼리)'으로 못 박는다. 극성과 무극성은 잘 섞이지 않는 방향을 잡아라.", "cite": ""}, "GC-091": {"name": "어는점 내림", "course": "gc", "unit": "물질의상태-총괄성", "tier": "C", "mis": ["총괄성이기 때문이다.", "어는점 내림이 일어난다.", "농도에 비례한다."], "dx": "어는점 내림이 총괄성이라 용질 입자 수(몰랄 농도)에 비례한다는 점을 놓친 경우다. 왜 총괄성인지(용매 화학퍼텐셜 낮춤)의 뿌리가 약하다.", "fix": "어는점 내림을 '총괄성이라 용질 입자 수(몰랄 농도)에 비례'로 못 박는다. 용매의 화학퍼텐셜을 낮춰 총괄성이 됨을 뿌리로 잡아라.", "cite": ""}, "GC-063": {"name": "이상 기체", "course": "gc", "unit": "물질의상태-기체", "tier": "A", "mis": ["온도는 제곱이 아니라 일차이다.", "보일 법칙은 반비례이다.", "샤를 법칙은 정비례이다.", "이상 기체 가정에 어긋난다.", "섭씨를 넣으면 결과가 틀린다.", "몰부피는 22.4 L이다."], "dx": "이상 기체 상태방정식(PV=nRT)에서 변수 관계를 헷갈린 경우다. 부피는 압력에 반비례(보일)·절대온도에 정비례(샤를, 일차)라는 비례 구조가 흔들린다.", "fix": "이상 기체를 'PV=nRT, 부피는 압력에 반비례(보일)·절대온도에 정비례(샤를)'로 못 박는다. 비례 구조를 잡아 변수 변화를 따져라.", "cite": ""}, "GC-064": {"name": "돌턴 분압", "course": "gc", "unit": "물질의상태-기체", "tier": "C", "mis": ["곱이 아니라 합이다.", "몰분율에 비례한다.", "몰수가 많을수록 분압이 크다."], "dx": "전체 압력이 각 성분 분압의 합이고, 각 분압이 몰분율에 비례한다는 점을 놓친 경우다. 합을 곱으로 다루거나 몰수·분압 관계가 흐리다.", "fix": "돌턴 분압을 '전체 압력은 각 성분 분압의 합, 각 분압은 몰분율에 비례'로 못 박는다. 합을 곱으로 다루지 말고 몰분율로 분압을 구하라.", "cite": ""}, "GC-065": {"name": "운동론", "course": "gc", "unit": "물질의상태-기체", "tier": "C", "mis": ["온도가 운동 에너지를 정한다.", "이상 기체는 탄성 충돌로 가정한다.", "온도가 0 K가 아닌 한 운동한다."], "dx": "기체 분자 운동론의 가정(온도가 평균 운동 에너지를 정함, 탄성 충돌)을 놓친 경우다. 0 K가 아니면 분자는 늘 운동한다는 점이 약하다.", "fix": "기체 운동론을 '온도가 평균 운동 에너지를 정하고 충돌은 탄성, 0 K가 아니면 분자는 늘 운동'으로 못 박는다. 이 가정을 속력·압력 해석의 토대로 삼아라.", "cite": ""}, "GC-066": {"name": "vrms", "course": "gc", "unit": "물질의상태-기체", "tier": "A", "mis": ["분모는 M의 일차이다.", "M의 제곱근에 반비례한다.", "√T에 비례한다.", "제곱근에 비례하기 때문이다.", "M이 작을수록 빠르다.", "M이 클수록 느려진다."], "dx": "제곱평균제곱근 속력(vᵣₘₛ)이 √T에 비례하고 √M(몰질량)에 반비례한다는 관계를 헷갈린 경우다. 분모가 M의 제곱근이라는 점이 흔들린다.", "fix": "제곱평균제곱근 속력을 'vᵣₘₛ는 √T에 비례하고 √M(몰질량)에 반비례'로 못 박는다. 분모가 M의 제곱근임을 잡아 속력을 정량 비교하라.", "cite": ""}, "GC-067": {"name": "분자량과 속력", "course": "gc", "unit": "물질의상태-기체", "tier": "A", "mis": ["가벼운 분자가 빠르다.", "온도가 같으면 평균 운동 에너지도 같다.", "무거우면 느리다.", "분자량이 속력을 좌우한다.", "운동 에너지가 증가한다.", "고온일수록 분포가 빠른 쪽으로 넓어진다."], "dx": "같은 온도면 평균 운동 에너지가 같아 무거운 분자가 더 느리다는 결론을 놓친 경우다. (1/2)mv²이 같으니 M이 크면 v가 작다는 흐름이 약하다.", "fix": "'같은 온도면 평균 운동 에너지가 같아 무거운 분자가 더 느림'을 못 박는다. (1/2)mv²이 같으니 M이 크면 v가 작음을 잡아라.", "cite": ""}, "GC-068": {"name": "그레이엄", "course": "gc", "unit": "물질의상태-기체", "tier": "C", "mis": ["가벼운 기체가 빠르다.", "몰질량이 작을수록 빠르다.", "무거울수록 느리다."], "dx": "확산·분출 속도가 몰질량의 제곱근에 반비례한다는 그레이엄 법칙을 놓친 경우다. 가벼운 기체일수록 빠르다는 결론이 vᵣₘₛ와 같은 뿌리임을 못 본다.", "fix": "그레이엄 법칙을 '확산·분출 속도가 몰질량의 제곱근에 반비례'로 못 박는다. 가벼운 기체일수록 빠름이 vᵣₘₛ와 같은 뿌리임을 잡아라.", "cite": ""}, "GC-069": {"name": "실제 기체", "course": "gc", "unit": "물질의상태-기체", "tier": "C", "mis": ["부피와 힘이 없는 것은 이상 기체 가정이다.", "이 조건에서 비이상성이 커진다.", "고압·저온에서 특히 벗어난다."], "dx": "이상 기체 가정(분자 부피 0, 분자 간 힘 0)이 깨지는 조건을 놓친 경우다. 고압·저온에서 비이상성이 커진다는 점이 흔들린다.", "fix": "실제 기체를 '이상 가정(분자 부피 0, 분자 간 힘 0)이 고압·저온에서 깨짐'으로 못 박는다. 어느 조건에서 비이상성이 커지는지 잡아라.", "cite": ""}, "GC-070": {"name": "압축 인자", "course": "gc", "unit": "물질의상태-기체", "tier": "C", "mis": ["Z = 1이 이상 기체이다.", "분자와 분모가 뒤바뀌었다."], "dx": "압축 인자 Z=PV/nRT에서 Z=1이 이상 기체 기준이라는 점을 놓친 경우다. 분자·분모를 뒤집어 1보다 큰지 작은지 해석이 흔들린다.", "fix": "압축 인자를 'Z=PV/nRT, Z=1이 이상 기체 기준'으로 못 박는다. 1보다 큰지 작은지로 분자 부피·인력 중 무엇이 우세한지 해석하라.", "cite": ""}, "GC-071": {"name": "이상 기체 근접", "course": "gc", "unit": "물질의상태-기체", "tier": "C", "mis": ["고압·저온에서는 오히려 벗어난다.", "인력이 크면 비이상성이 커진다.", "부피가 크면 가정에서 벗어난다."], "dx": "이상 기체에 가까워지는 조건(저압·고온)을 거꾸로 잡은 경우다. 인력이 작고 분자 부피가 무시될 때 이상성에 가까워진다는 점이 빠졌다.", "fix": "'이상 기체에 가까워지는 조건은 저압·고온(인력이 작고 분자 부피가 무시될 때)'임을 못 박는다. 조건을 거꾸로 잡지 마라.", "cite": ""}, "GC-072": {"name": "반데르발스", "course": "gc", "unit": "물질의상태-기체", "tier": "C", "mis": ["부피 보정은 b 항이다.", "인력 보정은 a 항이다.", "실제 기체의 비이상성을 다룬다."], "dx": "반데르발스 식의 두 보정 항을 헷갈린 경우다. a는 분자 간 인력, b는 분자 자체 부피 보정이라는 대응이 흔들린다.", "fix": "반데르발스 식을 'a는 분자 간 인력, b는 분자 자체 부피 보정'으로 못 박는다. 두 항의 역할을 바꾸지 말고 실제 기체를 해석하라.", "cite": ""}, "GC-073": {"name": "증기압", "course": "gc", "unit": "물질의상태-액체고체용액", "tier": "C", "mis": ["고온에서 증발이 활발하다.", "증발이 어려워 증기압이 낮다.", "온도와 물질 종류로 정해진다."], "dx": "증기압이 온도와 분자 간 힘으로 정해진다는 점을 놓친 경우다. 고온일수록·인력이 약할수록 증기압이 크다는 방향이 흔들린다.", "fix": "증기압을 '온도와 분자 간 힘으로 정해짐, 고온일수록·인력이 약할수록 큼'으로 못 박는다. 두 인자로 증기압 방향을 잡아라.", "cite": ""}, "GC-074": {"name": "끓는점", "course": "gc", "unit": "물질의상태-액체고체용액", "tier": "C", "mis": ["더 높은 증기압이 필요하다.", "강한 힘일수록 끓는점이 높다.", "압력이 낮으면 끓는점도 낮아진다."], "dx": "끓는점이 증기압=외부 압력이 되는 온도라는 정의를 놓친 경우다. 인력이 강할수록 끓는점이 높고, 외압이 낮으면 끓는점도 낮아진다는 연결이 약하다.", "fix": "끓는점을 '증기압이 외부 압력과 같아지는 온도'로 못 박는다. 인력이 강할수록 끓는점이 높고 외압이 낮으면 끓는점도 낮아짐을 이으라.", "cite": ""}, "GC-075": {"name": "점도·표면장력", "course": "gc", "unit": "물질의상태-액체고체용액", "tier": "C", "mis": ["강한 힘이 흐름을 방해한다.", "분자가 더 잘 미끄러진다.", "분자 간 인력이 표면장력을 만든다."], "dx": "점도·표면장력이 모두 분자 간 인력에서 나온다는 공통 뿌리를 놓친 경우다. 인력이 강할수록 흐름 저항·표면장력이 크다는 방향이 흔들린다.", "fix": "'점도·표면장력은 모두 분자 간 인력에서 나옴, 인력이 강할수록 흐름 저항·표면장력이 큼'을 못 박는다. 공통 뿌리를 잡아 함께 설명하라.", "cite": ""}, "GC-076": {"name": "점도", "course": "gc", "unit": "물질의상태-액체고체용액", "tier": "C", "mis": ["강한 힘이 흐름을 막는다.", "점도는 흐름에 대한 저항이다.", "분자가 더 쉽게 미끄러진다."], "dx": "점도가 흐름에 대한 저항이고 분자 간 인력이 클수록 커진다는 점을 놓친 경우다. 인력과 미끄러짐의 방향이 뒤집혔다.", "fix": "점도를 '흐름에 대한 저항이고 분자 간 인력이 클수록 큼'으로 못 박는다. 인력과 미끄러짐의 방향을 뒤집지 마라.", "cite": ""}, "GC-077": {"name": "이온 결정", "course": "gc", "unit": "물질의상태-액체고체용액", "tier": "C", "mis": ["강한 정전기적 인력 때문이다.", "이온이 움직일 수 없다.", "전하 반발로 쪼개진다."], "dx": "이온 결정의 단단함·높은 녹는점이 강한 정전 인력에서 온다는 점, 그리고 층이 밀릴 때 같은 전하끼리 만나 쪼개진다는 점을 놓친 경우다.", "fix": "이온 결정을 '강한 정전 인력으로 단단하고 녹는점 높음, 층이 밀리면 같은 전하끼리 만나 쪼개짐(취성)'으로 못 박는다. 두 성질을 한 그림으로 잡아라.", "cite": ""}, "GC-078": {"name": "단위 세포", "course": "gc", "unit": "물질의상태-액체고체용액", "tier": "C", "mis": ["FCC는 4개이다.", "BCC는 2개이다.", "SC는 1개이다."], "dx": "단위 세포당 입자 수를 헷갈린 경우다. 단순입방(SC) 1·체심입방(BCC) 2·면심입방(FCC) 4라는 셈(꼭짓점 1/8·면 1/2·체심 1)이 안 잡혔다.", "fix": "단위 세포당 입자 수를 '단순입방(SC) 1·체심입방(BCC) 2·면심입방(FCC) 4'로 못 박는다. 꼭짓점 1/8·면 1/2·체심 1로 직접 세어 확인하라.", "cite": ""}, "GC-079": {"name": "상평형 그림", "course": "gc", "unit": "물질의상태-액체고체용액", "tier": "C", "mis": ["고체·액체·기체가 함께 존재한다.", "임계점은 액체-기체 경계의 끝이다.", "축은 온도와 압력이다."], "dx": "상평형 그림의 축(온도·압력)과 삼중점·임계점의 의미를 놓친 경우다. 삼중점은 세 상 공존, 임계점은 액체-기체 경계의 끝이라는 점이 흔들린다.", "fix": "상평형 그림을 '축은 온도·압력, 삼중점은 세 상 공존, 임계점은 액체-기체 경계의 끝'으로 못 박는다. 두 특이점의 의미를 잡아 그림을 읽어라.", "cite": ""}, "GC-080": {"name": "몰랄 농도", "course": "gc", "unit": "물질의상태-액체고체용액", "tier": "C", "mis": ["용액 1 L 기준은 몰 농도이다.", "질량 기준이라 온도에 안 변한다.", "질량이 아니라 몰수이다."], "dx": "몰랄 농도(용매 1 kg당 용질 mol)와 몰 농도(용액 1 L당 mol)를 섞은 경우다. 질량 기준이라 온도에 안 변한다는 몰랄의 장점이 빠졌다.", "fix": "몰랄 농도를 '용매 1 kg당 용질 mol이라 온도에 안 변함, 몰 농도(용액 1 L당 mol)와 별개'로 못 박는다. 질량 기준이라는 장점을 총괄성에 써라.", "cite": ""}, "GC-081": {"name": "헨리 법칙", "course": "gc", "unit": "물질의상태-액체고체용액", "tier": "A", "mis": ["압력이 클수록 더 녹는다.", "압력에 비례한다.", "고온에서 기체가 덜 녹는다.", "기체-압력 관계이다.", "압력이 내려야 용해도가 줄어든다.", "헨리 법칙의 핵심이다."], "dx": "기체의 용해도가 그 기체의 부분 압력에 비례한다는 헨리 법칙을 놓친 경우다. 압력이 클수록·저온일수록 더 녹는다는 방향이 흔들린다.", "fix": "헨리 법칙을 '기체의 용해도가 그 기체의 부분 압력에 비례'로 못 박는다. 압력이 클수록·저온일수록 더 녹는 방향을 잡아라.", "cite": ""}, "GC-082": {"name": "총괄성", "course": "gc", "unit": "물질의상태-액체고체용액", "tier": "A", "mis": ["종류가 아니라 개수이다.", "입자 수에 비례한다.", "전해질은 이온으로 나뉜다.", "총괄성이다.", "용매 몰분율이 줄어든다.", "용매에 따라 상수가 다르다."], "dx": "총괄성이 용질 입자의 종류가 아니라 개수에 의존한다는 핵심을 놓친 경우다. 전해질은 이온으로 나뉘어 입자 수가 늘어난다는 점이 빠졌다.", "fix": "총괄성을 '용질 입자의 종류가 아니라 개수에 의존'으로 못 박는다. 전해질은 이온으로 나뉘어 입자 수가 늚을 잡아 반트호프 인자를 반영하라.", "cite": ""}, "GC-083": {"name": "라울 법칙", "course": "gc", "unit": "물질의상태-액체고체용액", "tier": "C", "mis": ["용매 몰분율이 1보다 작다.", "용매 몰분율이 줄어든다.", "라울 법칙의 핵심이다."], "dx": "용액의 증기압이 용매 몰분율에 비례한다(라울)는 점을 놓친 경우다. 용질이 늘면 용매 몰분율이 1보다 작아져 증기압이 내려간다는 흐름이 약하다.", "fix": "라울 법칙을 '용액의 증기압이 용매 몰분율에 비례'로 못 박는다. 용질이 늘면 용매 몰분율이 1보다 작아져 증기압이 내려감을 잡아라.", "cite": ""}, "GC-100": {"name": "ΔH 부호", "course": "gc", "unit": "열역학-엔탈피엔트로피", "tier": "C", "mis": ["발열은 엔탈피가 감소한다.", "흡열은 엔탈피가 증가한다.", "발열은 열을 내보낸다."], "dx": "ΔH 부호와 발열·흡열의 대응을 헷갈린 경우다. 발열은 ΔH<0(엔탈피 감소), 흡열은 ΔH>0이라는 약속이 흔들린다.", "fix": "'발열은 ΔH<0(엔탈피 감소), 흡열은 ΔH>0'을 못 박는다. 열 출입 방향과 부호를 짝지어 열화학식의 부호를 맞춰라.", "cite": ""}, "GC-101": {"name": "표준 생성 엔탈피", "course": "gc", "unit": "열역학-엔탈피엔트로피", "tier": "C", "mis": ["화합물은 0이 아니다.", "기준값은 0이다.", "분해가 아니라 생성이다."], "dx": "표준 생성 엔탈피에서 기준(가장 안정한 홑원소 물질=0)을 놓친 경우다. 화합물은 0이 아니며, 생성(분해 아님) 반응 기준이라는 점이 약하다.", "fix": "표준 생성 엔탈피를 '가장 안정한 홑원소 물질 = 0, 화합물은 0이 아니고 생성(분해 아님) 반응 기준'으로 못 박는다. 홑원소 0을 기준점으로 반응엔탈피를 구하라.", "cite": ""}, "GC-102": {"name": "반응엔탈피 계산", "course": "gc", "unit": "열역학-엔탈피엔트로피", "tier": "C", "mis": ["생성물에서 반응물을 빼야 한다.", "더하는 것이 아니라 빼는 것이다.", "몰수를 반영해야 한다."], "dx": "반응엔탈피를 (생성물 생성엔탈피 합) - (반응물 생성엔탈피 합)으로 계산하고, 각 항에 계수(몰수)를 곱한다는 절차를 놓친 경우다.", "fix": "반응엔탈피를 '(생성물 생성엔탈피 합) − (반응물 생성엔탈피 합), 각 항에 계수 곱'으로 못 박는다. 계수 반영을 빼먹지 말고 계산하라.", "cite": ""}, "GC-103": {"name": "헤스 법칙", "course": "gc", "unit": "열역학-엔탈피엔트로피", "tier": "C", "mis": ["상태 함수라 경로와 무관하다.", "역반응은 부호가 반대이다."], "dx": "엔탈피가 상태 함수라 경로와 무관하다는 헤스 법칙을 놓친 경우다. 반응을 더하거나 뒤집으면 ΔH도 같이 더해지고 부호가 바뀐다는 점이 흔들린다.", "fix": "헤스 법칙을 '엔탈피가 상태 함수라 경로와 무관, 반응을 더하면 ΔH도 더해지고 뒤집으면 부호가 바뀜'으로 못 박는다. 이 조합 규칙으로 다단계 ΔH를 구하라.", "cite": ""}, "GC-104": {"name": "결합 에너지", "course": "gc", "unit": "열역학-엔탈피엔트로피", "tier": "C", "mis": ["끊기는 에너지를 흡수한다.", "형성은 발열이다.", "끊기는 흡열이다."], "dx": "결합을 끊는 데 에너지를 흡수(흡열)하고 만들 때 방출(발열)한다는 방향을 놓친 경우다. 반응엔탈피를 (끊은 결합 합) - (만든 결합 합)으로 보는 틀이 약하다.", "fix": "'결합을 끊는 데 에너지를 흡수(흡열), 만들 때 방출(발열)'을 못 박는다. 반응엔탈피를 (끊은 결합 합) − (만든 결합 합)으로 구하라.", "cite": ""}, "GC-105": {"name": "엔트로피", "course": "gc", "unit": "열역학-엔탈피엔트로피", "tier": "C", "mis": ["기체가 가장 무질서하다.", "무질서도와 같은 방향이다.", "상태 함수이다."], "dx": "엔트로피가 무질서도(미시 상태 수)와 같은 방향이고 기체에서 가장 크다는 점을 놓친 경우다. 상태 함수라는 점도 흔들린다.", "fix": "엔트로피를 '무질서도(미시 상태 수)와 같은 방향이고 기체에서 가장 큰 상태 함수'로 못 박는다. 상태별 크기 비교의 토대로 삼아라.", "cite": ""}, "GC-106": {"name": "제2법칙", "course": "gc", "unit": "열역학-엔탈피엔트로피", "tier": "C", "mis": ["감소가 아니라 증가이다.", "전체 무질서도가 늘어난다.", "주위 변화까지 합쳐 판단한다."], "dx": "고립계(또는 계+주위)의 전체 엔트로피가 자발 과정에서 증가한다는 제2법칙을 놓친 경우다. 계만 보지 않고 주위 변화까지 합쳐 판단해야 한다는 점이 약하다.", "fix": "제2법칙을 '고립계(또는 계+주위)의 전체 엔트로피가 자발 과정에서 증가'로 못 박는다. 계만 보지 말고 주위 변화까지 합쳐 판단하라.", "cite": ""}, "GC-107": {"name": "제3법칙", "course": "gc", "unit": "열역학-엔탈피엔트로피", "tier": "C", "mis": ["최대가 아니라 0이다.", "배열이 하나뿐이라 0이다.", "무질서도가 0이다."], "dx": "완전한 결정이 0 K에서 엔트로피 0(배열이 하나뿐)이라는 제3법칙을 놓친 경우다. 0 K에서 최대가 아니라 0이라는 방향이 흔들린다.", "fix": "제3법칙을 '완전한 결정은 0 K에서 엔트로피 0(배열이 하나뿐)'으로 못 박는다. 0 K에서 최대가 아니라 0임을 새겨라.", "cite": ""}, "GC-108": {"name": "엔트로피 변화", "course": "gc", "unit": "열역학-엔탈피엔트로피", "tier": "C", "mis": ["무질서도가 커진다.", "입자 운동이 활발해진다.", "기체가 더 무질서하다."], "dx": "상태 변화에서 엔트로피 방향(고체<액체<기체, 입자 운동·무질서 증가)을 놓친 경우다. 기체화·용해처럼 배열 수가 느는 쪽이 ΔS>0이라는 감이 약하다.", "fix": "엔트로피 변화 방향을 '고체<액체<기체, 입자 운동·무질서가 늘수록 큼'으로 못 박는다. 기체화·용해처럼 배열 수가 느는 쪽이 ΔS>0임을 잡아라.", "cite": ""}, "GC-092": {"name": "내부 에너지", "course": "gc", "unit": "열역학-1법칙", "tier": "C", "mis": ["상태 함수는 경로에 의존하지 않는다.", "상태 함수이기 때문이다.", "경로에 따라 값이 달라진다."], "dx": "내부 에너지 U가 상태 함수라 경로가 아니라 처음·끝 상태로만 정해진다는 점을 놓친 경우다. 경로에 따라 값이 달라진다고 본 것이 오류다.", "fix": "내부 에너지 U를 '상태 함수라 경로가 아니라 처음·끝 상태로만 정해짐'으로 못 박는다. 경로에 따라 값이 달라진다고 보지 마라.", "cite": ""}, "GC-093": {"name": "제1법칙", "course": "gc", "unit": "열역학-1법칙", "tier": "B", "mis": ["에너지는 보존된다.", "계가 받는 일을 양으로 두는 규약이다.", "제1법칙에 어긋난다.", "일도 함께 고려해야 한다."], "dx": "ΔU = q + w(에너지 보존)에서 부호 규약(계가 받는 열·일을 양으로)을 놓친 경우다. 열과 일을 통한 에너지 출입의 총합이 내부 에너지 변화라는 틀이 흔들린다.", "fix": "제1법칙을 'ΔU = q + w(에너지 보존), 계가 받는 열·일을 양으로'로 못 박는다. 열과 일을 통한 에너지 출입의 총합이 내부 에너지 변화임을 잡아라.", "cite": ""}, "GC-094": {"name": "부호 규약", "course": "gc", "unit": "열역학-1법칙", "tier": "C", "mis": ["흡수는 양수이다.", "방출은 음수이다.", "받은 일은 양수이다."], "dx": "열의 부호 규약을 헷갈린 경우다. 계가 흡수하면 q>0, 방출하면 q<0이라는 약속이 정리되지 않았다.", "fix": "열의 부호 규약을 '계가 흡수하면 q>0, 방출하면 q<0'으로 못 박는다. 흡수·방출 방향을 부호로 옮겨라.", "cite": ""}, "GC-095": {"name": "일의 부호", "course": "gc", "unit": "열역학-1법칙", "tier": "C", "mis": ["해준 일은 음수이다.", "받은 일은 양수이다.", "에너지가 일로 빠져나간다."], "dx": "일의 부호 규약을 헷갈린 경우다. 계가 일을 받으면 w>0, 계가 일을 하면(팽창) w<0이라는 약속이 흔들린다.", "fix": "일의 부호 규약을 '계가 일을 받으면 w>0, 계가 일을 하면(팽창) w<0'으로 못 박는다. 팽창이 일을 내보냄을 부호로 잡아라.", "cite": ""}, "GC-096": {"name": "정적 과정", "course": "gc", "unit": "열역학-1법칙", "tier": "C", "mis": ["엔탈피 변화는 정압 과정에서 q와 같다.", "부피 변화가 없다.", "정적 과정의 열은 내부 에너지 변화이다."], "dx": "정적 과정(ΔV=0)에서 한 일이 0이라 q가 곧 ΔU라는 점을 놓친 경우다. 정압의 q=ΔH와 정적의 q=ΔU를 뒤섞었다.", "fix": "정적 과정을 'ΔV=0이라 한 일이 0이라 q가 곧 ΔU'로 못 박는다. 정압의 q=ΔH와 정적의 q=ΔU를 뒤섞지 마라.", "cite": ""}, "GC-097": {"name": "정압 과정", "course": "gc", "unit": "열역학-1법칙", "tier": "C", "mis": ["내부 에너지 변화는 정적 과정의 열이다.", "압력이 일정해도 부피는 변한다.", "정압 과정의 열은 엔탈피 변화이다."], "dx": "정압 과정의 열이 엔탈피 변화 ΔH와 같다는 점을 놓친 경우다. 압력이 일정해도 부피는 변해 팽창 일이 생긴다는 점이 흔들린다.", "fix": "정압 과정의 열을 '엔탈피 변화 ΔH와 같음'으로 못 박는다. 압력이 일정해도 부피는 변해 팽창 일이 생김을 잡아라.", "cite": ""}, "GC-098": {"name": "팽창과 일", "course": "gc", "unit": "열역학-1법칙", "tier": "C", "mis": ["팽창은 계가 일을 하는 것이다.", "P · ΔV이다.", "부피가 늘며 일을 한다."], "dx": "기체가 팽창할 때 계가 외부에 일을 한다(w<0, 크기 P·ΔV)는 점을 놓친 경우다. 부피가 늘며 에너지가 일로 빠져나간다는 방향이 약하다.", "fix": "'기체가 팽창할 때 계가 외부에 일을 함(w<0, 크기 P·ΔV)'을 못 박는다. 부피가 늘며 에너지가 일로 빠져나가는 방향을 잡아라.", "cite": ""}, "GC-099": {"name": "엔탈피 정의", "course": "gc", "unit": "열역학-1법칙", "tier": "A", "mis": ["PV를 더한다.", "경로와 무관하다.", "열을 방출한다.", "열을 흡수한다.", "P와 V는 곱한다.", "상태 함수이다."], "dx": "엔탈피 H = U + PV의 정의를 놓친 경우다. PV를 더한 상태 함수라는 점, 정압에서 q와 같아지는 이유가 흔들린다.", "fix": "엔탈피를 'H = U + PV'로 못 박는다. PV를 더한 상태 함수임을 잡아 정압에서 q와 같아지는 이유로 이어라.", "cite": ""}, "GC-109": {"name": "자유 에너지", "course": "gc", "unit": "열역학-자유에너지", "tier": "C", "mis": ["TS를 더하는 것이 아니라 뺀다.", "상태 함수이다.", "음수일 때 자발적이다."], "dx": "깁스 자유 에너지 G = H - TS에서 TS를 빼는(더하지 않는) 정의를 놓친 경우다. ΔG<0일 때 자발적이라는 판단 기준이 흔들린다.", "fix": "깁스 자유 에너지를 'G = H − TS(TS를 더하지 않고 뺌)'로 못 박는다. ΔG<0일 때 자발적이라는 판단 기준을 잡아라.", "cite": ""}, "GC-110": {"name": "ΔG 식", "course": "gc", "unit": "열역학-자유에너지", "tier": "A", "mis": ["TΔS를 빼야 한다.", "켈빈을 사용한다.", "-TΔS가 음수가 된다.", "ΔG를 양수 쪽으로 민다.", "T가 ΔS에 곱해진다.", "항을 뒤바꾸면 안 된다."], "dx": "ΔG = ΔH - TΔS에서 T를 켈빈으로 쓰고 TΔS를 빼야 한다는 점을 놓친 경우다. -TΔS 항의 부호가 엔트로피 증가를 자발성으로 잇는다는 흐름이 약하다.", "fix": "깁스 식을 'ΔG = ΔH − TΔS, T는 켈빈, TΔS를 뺌'으로 못 박는다. −TΔS 항이 엔트로피 증가를 자발성으로 잇는 흐름을 잡아라.", "cite": ""}, "GC-111": {"name": "자발성 판단", "course": "gc", "unit": "열역학-자유에너지", "tier": "C", "mis": ["음수일 때 자발적이다.", "자발도 비자발도 아니다.", "음수면 자발적이다."], "dx": "ΔG<0이면 자발, ΔG>0이면 비자발, ΔG=0이면 평형이라는 기준을 놓친 경우다. ΔG의 부호 하나로 방향이 결정된다는 점이 흔들린다.", "fix": "'ΔG<0이면 자발, ΔG>0이면 비자발, ΔG=0이면 평형'을 못 박는다. ΔG 부호 하나로 방향이 결정됨을 잡아라.", "cite": ""}, "GC-112": {"name": "부호 조합", "course": "gc", "unit": "열역학-자유에너지", "tier": "C", "mis": ["고온에서 TΔS가 우세하다.", "저온에서 ΔH 항이 우세하다.", "두 항 모두 비자발 쪽이다."], "dx": "ΔH·ΔS 부호 조합과 온도 의존을 헷갈린 경우다. 고온에서는 -TΔS 항이, 저온에서는 ΔH 항이 우세해진다는 온도 갈림이 약하다.", "fix": "'ΔH·ΔS 부호 조합과 온도 의존: 고온에서는 −TΔS 항이, 저온에서는 ΔH 항이 우세'함을 못 박는다. 온도 갈림으로 자발성 전환을 따져라.", "cite": ""}, "GC-113": {"name": "발열과 자발성", "course": "gc", "unit": "열역학-자유에너지", "tier": "B", "mis": ["엔트로피와 온도가 영향을 준다.", "ΔG가 최종 기준이다.", "고온에서 자발적일 수 있다.", "ΔG = ΔH - TΔS이다."], "dx": "발열이 곧 자발성은 아니고 ΔG가 최종 기준이라는 점을 놓친 경우다. 엔트로피와 온도에 따라 흡열도 고온에서 자발일 수 있다는 점이 약하다.", "fix": "'발열이 곧 자발은 아니고 ΔG가 최종 기준'임을 못 박는다. 엔트로피와 온도에 따라 흡열도 고온에서 자발일 수 있음을 잡아라.", "cite": ""}, "GC-114": {"name": "자유 에너지와 평형", "course": "gc", "unit": "열역학-자유에너지", "tier": "A", "mis": ["ln K가 양수라 ΔG°가 음수이다.", "ln K가 음수이다.", "ln 1 = 0이다.", "음의 부호가 붙는다.", "K가 크다는 뜻이다.", "ln K가 커진다."], "dx": "ΔG° = -RT ln K에서 K와 ΔG°의 부호 관계를 놓친 경우다. K>1이면 ln K>0이라 ΔG°<0, K=1이면 ln 1=0이라 ΔG°=0이라는 연결이 흔들린다.", "fix": "'ΔG° = -RT ln K'를 못 박는다. K>1이면 ln K>0이라 ΔG°<0, K=1이면 ln 1=0이라 ΔG°=0인 부호 관계를 잡아라.", "cite": ""}, "GC-115": {"name": "비열", "course": "gc", "unit": "열역학-자유에너지", "tier": "C", "mis": ["온도를 올리기 어렵다.", "양과 무관한 물질 고유의 값이다.", "비열이 작을수록 잘 데워진다."], "dx": "비열이 단위 질량을 1 K 올리는 데 드는 열이고 물질 고유값이라는 점을 놓친 경우다. 비열이 클수록 데우기 어렵다는 방향이 뒤집혔다.", "fix": "비열을 '단위 질량을 1 K 올리는 데 드는 열, 물질 고유값'으로 못 박는다. 비열이 클수록 데우기 어려움을 방향으로 잡아라.", "cite": ""}};
